--
-- Name: build_where_condition(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.build_where_condition(p_column_name text, p_operator text, p_value text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_condition TEXT := '';
    v_temp_text TEXT := '';
    v_temp_value TEXT;
    v_operator_upper TEXT;
    v_array_values TEXT[];
    v_value1 TEXT;
    v_value2 TEXT;
    i INTEGER;
    v_json_array json;
    v_is_json_array BOOLEAN := FALSE;
BEGIN
    -- Normalize operator to uppercase for case-insensitive matching
    v_operator_upper := UPPER(TRIM(p_operator));
    
    -- Debug logging (uncomment for debugging)
    -- RAISE NOTICE 'build_where_condition: column=%, operator=%, value=%, upper_operator=%', 
    --               p_column_name, p_operator, p_value, v_operator_upper;
    
    -- Handle NULL value cases first
    IF p_value IS NULL OR p_value = 'null' OR p_value = 'NULL' OR p_value = '' THEN
        CASE v_operator_upper
            WHEN 'IS NULL', 'IS_NULL', 'NULL' THEN
                v_condition := ' AND ' || p_column_name || ' IS NULL';
            WHEN 'IS NOT NULL', 'IS_NOT_NULL', 'NOT NULL', 'NOT_NULL' THEN
                v_condition := ' AND ' || p_column_name || ' IS NOT NULL';
            ELSE
                -- For other operators with NULL value, handle appropriately
                IF v_operator_upper IN ('=', 'EQUALS') THEN
                    v_condition := ' AND ' || p_column_name || ' IS NULL';
                ELSIF v_operator_upper IN ('!=', '<>', 'NOT EQUALS', 'NOT_EQUALS') THEN
                    v_condition := ' AND ' || p_column_name || ' IS NOT NULL';
                ELSE
                    v_condition := ' AND ' || p_column_name || ' IS NULL';
                END IF;
        END CASE;
        RETURN v_condition;
    END IF;
    
    -- Check if value is a JSON array (for IN/NOT IN operators)
    IF (v_operator_upper = 'IN' OR v_operator_upper = 'NOT IN') THEN
        BEGIN
            -- Try to parse as JSON array
            v_json_array := p_value::json;
            IF json_typeof(v_json_array) = 'array' THEN
                v_is_json_array := TRUE;
                v_temp_text := '';
                FOR v_temp_value IN SELECT json_array_elements_text(v_json_array)
                LOOP
                    IF v_temp_text != '' THEN
                        v_temp_text := v_temp_text || ', ';
                    END IF;
                    v_temp_text := v_temp_text || quote_literal(v_temp_value);
                END LOOP;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- Not a valid JSON, will handle as comma-separated string below
            v_is_json_array := FALSE;
        END;
    END IF;
    
    -- Main operator handling
    CASE v_operator_upper
        -- EQUALITY OPERATORS
        WHEN '=', 'EQUALS' THEN
            v_condition := ' AND ' || p_column_name || ' = ' || quote_literal(p_value);
        
        -- INEQUALITY OPERATORS (THIS WAS THE BUG - "!=" was not handled!)
        WHEN '!=', '<>', 'NOT_EQUALS', 'NOT EQUALS' THEN
            v_condition := ' AND ' || p_column_name || ' != ' || quote_literal(p_value);
        
        -- COMPARISON OPERATORS
        WHEN '>', 'GREATER_THAN', 'GREATER THAN' THEN
            v_condition := ' AND ' || p_column_name || ' > ' || quote_literal(p_value);
        
        WHEN '<', 'LESS_THAN', 'LESS THAN' THEN
            v_condition := ' AND ' || p_column_name || ' < ' || quote_literal(p_value);
        
        WHEN '>=', 'GREATER_THAN_EQUALS', 'GREATER THAN EQUALS', 'GREATER OR EQUAL' THEN
            v_condition := ' AND ' || p_column_name || ' >= ' || quote_literal(p_value);
        
        WHEN '<=', 'LESS_THAN_EQUALS', 'LESS THAN EQUALS', 'LESS OR EQUAL' THEN
            v_condition := ' AND ' || p_column_name || ' <= ' || quote_literal(p_value);
        
        -- TEXT OPERATORS
        WHEN 'LIKE' THEN
            v_condition := ' AND ' || p_column_name || ' ILIKE ' || quote_literal('%' || p_value || '%');
        
        WHEN 'NOT LIKE', 'NOT_LIKE' THEN
            v_condition := ' AND ' || p_column_name || ' NOT ILIKE ' || quote_literal('%' || p_value || '%');
        
        -- IN / NOT IN OPERATORS
        WHEN 'IN' THEN
            IF v_is_json_array AND v_temp_text != '' THEN
                -- Use JSON array
                v_condition := ' AND ' || p_column_name || ' IN (' || v_temp_text || ')';
            ELSE
                -- Try comma-separated values
                BEGIN
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) > 0 THEN
                        v_temp_text := '';
                        FOR i IN 1..array_length(v_array_values, 1) LOOP
                            IF v_temp_text != '' THEN
                                v_temp_text := v_temp_text || ', ';
                            END IF;
                            v_temp_text := v_temp_text || quote_literal(TRIM(v_array_values[i]));
                        END LOOP;
                        v_condition := ' AND ' || p_column_name || ' IN (' || v_temp_text || ')';
                    ELSE
                        -- Single value
                        v_condition := ' AND ' || p_column_name || ' = ' || quote_literal(p_value);
                    END IF;
                EXCEPTION WHEN OTHERS THEN
                    -- Single value
                    v_condition := ' AND ' || p_column_name || ' = ' || quote_literal(p_value);
                END;
            END IF;
        
        WHEN 'NOT IN', 'NOT_IN' THEN
            IF v_is_json_array AND v_temp_text != '' THEN
                -- Use JSON array
                v_condition := ' AND ' || p_column_name || ' NOT IN (' || v_temp_text || ')';
            ELSE
                -- Try comma-separated values
                BEGIN
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) > 0 THEN
                        v_temp_text := '';
                        FOR i IN 1..array_length(v_array_values, 1) LOOP
                            IF v_temp_text != '' THEN
                                v_temp_text := v_temp_text || ', ';
                            END IF;
                            v_temp_text := v_temp_text || quote_literal(TRIM(v_array_values[i]));
                        END LOOP;
                        v_condition := ' AND ' || p_column_name || ' NOT IN (' || v_temp_text || ')';
                    ELSE
                        -- Single value
                        v_condition := ' AND ' || p_column_name || ' != ' || quote_literal(p_value);
                    END IF;
                EXCEPTION WHEN OTHERS THEN
                    -- Single value
                    v_condition := ' AND ' || p_column_name || ' != ' || quote_literal(p_value);
                END;
            END IF;
        
        -- NULL OPERATORS
        WHEN 'IS NULL', 'IS_NULL' THEN
            v_condition := ' AND ' || p_column_name || ' IS NULL';
        
        WHEN 'IS NOT NULL', 'IS_NOT_NULL' THEN
            v_condition := ' AND ' || p_column_name || ' IS NOT NULL';
        
        -- "BY AGE" SPECIAL OPERATOR (assuming this is for date differences)
     	
        WHEN 'CONTAINS' THEN
            v_condition := ' AND ' || p_column_name || ' ILIKE ' || quote_literal('%' || p_value || '%');
        
        WHEN 'NOT_CONTAINS' THEN
            v_condition := ' AND ' || p_column_name || ' NOT ILIKE ' || quote_literal('%' || p_value || '%');
        
        WHEN 'STARTS_WITH' THEN
            v_condition := ' AND ' || p_column_name || ' ILIKE ' || quote_literal(p_value || '%');
        
        WHEN 'ENDS_WITH' THEN
            v_condition := ' AND ' || p_column_name || ' ILIKE ' || quote_literal('%' || p_value);
        
        WHEN 'BETWEEN' THEN
            BEGIN
                v_condition := ' AND ' || p_column_name || 
                    ' BETWEEN ' || quote_literal(split_part(replace(replace(p_value, '[', ''), ']', ''), ',', 1)) ||
                    ' AND ' || quote_literal(split_part(replace(replace(p_value, '[', ''), ']', ''), ',', 2));
            EXCEPTION WHEN OTHERS THEN
                v_condition := '';
            END;
        
        WHEN 'IN_LIST' THEN
            BEGIN
                v_temp_text := '';
                FOR v_temp_value IN SELECT value::text FROM json_array_elements_text(p_value::json)
                LOOP
                    IF v_temp_text != '' THEN
                        v_temp_text := v_temp_text || ', ';
                    END IF;
                    v_temp_text := v_temp_text || quote_literal(v_temp_value);
                END LOOP;
                v_condition := ' AND ' || p_column_name || ' IN (' || v_temp_text || ')';
            EXCEPTION WHEN OTHERS THEN
                v_condition := '';
            END;
        
        WHEN 'NOT_IN_LIST' THEN
            BEGIN
                v_temp_text := '';
                FOR v_temp_value IN SELECT value::text FROM json_array_elements_text(p_value::json)
                LOOP
                    IF v_temp_text != '' THEN
                        v_temp_text := v_temp_text || ', ';
                    END IF;
                    v_temp_text := v_temp_text || quote_literal(v_temp_value);
                END LOOP;
                v_condition := ' AND ' || p_column_name || ' NOT IN (' || v_temp_text || ')';
            EXCEPTION WHEN OTHERS THEN
                v_condition := '';
            END;
        WHEN 'AGE=>' THEN
            BEGIN
                -- Validate that value is a number
                IF p_value ~ '^\d+$' THEN
                    v_condition := ' AND EXTRACT(YEAR FROM age(CURRENT_DATE, ' || p_column_name || ')) >= ' || p_value;
                ELSE
                    -- Invalid age value
                    RAISE NOTICE 'Invalid age value for AGE=>: %', p_value;
                    v_condition := '';
                END IF;
                
                RETURN v_condition;
        END;
	        -- "AGE<=" OPERATOR - Age less than or equal to value
	    WHEN 'AGE<=' THEN
	            BEGIN
	                -- Validate that value is a number
	                IF p_value ~ '^\d+$' THEN
	                    v_condition := ' AND EXTRACT(YEAR FROM age(CURRENT_DATE, ' || p_column_name || ')) <= ' || p_value;
	                ELSE
	                    -- Invalid age value
	                    RAISE NOTICE 'Invalid age value for AGE<=: %', p_value;
	                    v_condition := '';
	                END IF;
	                
	                RETURN v_condition;
	     END;
        -- DEFAULT CASE
        ELSE
            -- If operator not recognized, default to equals
            v_condition := ' AND ' || p_column_name || ' = ' || quote_literal(p_value);
    END CASE;
    
    RETURN v_condition;
END;
$_$;


ALTER FUNCTION public.build_where_condition(p_column_name text, p_operator text, p_value text) OWNER TO postgres;

--
-- Name: cancel_duplicate_annual_charges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_duplicate_annual_charges() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    duplicate_count INTEGER := 0;
    current_year INTEGER := EXTRACT(YEAR FROM CURRENT_DATE);
BEGIN
    WITH duplicates AS (
        SELECT 
            cardid,
            charge_type,
            charge_year,
            COUNT(*) as charge_count,
            ARRAY_AGG(charge_id ORDER BY created_at DESC) as charge_ids
        FROM card_charges
        WHERE charge_type = 'ANNUAL_FEE' 
          AND charge_year = current_year
          AND status = 'APPLIED'
        GROUP BY cardid, charge_type, charge_year
        HAVING COUNT(*) > 1
    ),
    cancelled AS (
        UPDATE card_charges 
        SET status = 'CANCELLED',
            description = CONCAT(description, ' - Duplicate cancelled on ', CURRENT_DATE)
        WHERE charge_id IN (
            SELECT unnest(charge_ids[2:]) -- Keep first, cancel rest
            FROM duplicates
        )
        RETURNING 1
    )
    SELECT COUNT(*) INTO duplicate_count FROM cancelled;

    RETURN json_build_object(
        'cancelled_duplicates', duplicate_count,
        'status', 'COMPLETED',
        'execution_time', CURRENT_TIMESTAMP
    );

EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object(
        'cancelled_duplicates', 0,
        'status', 'ERROR',
        'error_message', SQLERRM
    );
END;
$$;


ALTER FUNCTION public.cancel_duplicate_annual_charges() OWNER TO postgres;

--
-- Name: check_annual_fees_status(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_annual_fees_status(current_year integer DEFAULT NULL::integer) RETURNS TABLE(card_id character varying, card_number character varying, annual_fee_applied boolean, fee_amount numeric, charge_date date, status character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF current_year IS NULL THEN
        current_year := EXTRACT(YEAR FROM CURRENT_DATE);
    END IF;

    RETURN QUERY
    SELECT 
        c.cardid,
        c.cardnumber,
        (cc.charge_id IS NOT NULL) as annual_fee_applied,
        COALESCE(cc.amount, 0) as fee_amount,
        cc.charge_date,
        COALESCE(cc.status, 'NOT_APPLIED')
    FROM card c
    LEFT JOIN card_charges cc ON c.cardid = cc.cardid 
        AND cc.charge_type = 'ANNUAL_FEE' 
        AND cc.charge_year = current_year
        AND cc.status != 'CANCELLED'
    WHERE c.issuedate + INTERVAL '1 year' BETWEEN CURRENT_DATE - INTERVAL '30 days' AND CURRENT_DATE
    ORDER BY c.cardid;
END;
$$;


ALTER FUNCTION public.check_annual_fees_status(current_year integer) OWNER TO postgres;

--
-- Name: customer_action_handler(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.customer_action_handler(action character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_customercode character varying DEFAULT NULL::character varying, p_accountnumber character varying DEFAULT NULL::character varying, p_cardnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(customercode character varying, fname character varying, lname character varying, middlename character varying, mobileno character varying, accountid character varying, accountnumber character varying, accounttype character varying, balance numeric, cardid character varying, cardnumber character varying, cardtype character varying, schemetype character varying, status character)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
BEGIN
    IF action = 'ALL_SEARCH' THEN
        dyn_sql := 'SELECT 
                        c.customercode,
                        c.fname,
                        c.lname,
                        c.middlename,
                        c.mobileno,
                        a.accountid,
                        a.accountnumber,
                        a.accounttype,
                        a.balance,
                        d.cardid,
                        d.cardnumber,
                        d.cardtype,
                        d.schemetype,
                        d.status
                    FROM customer c
                    LEFT JOIN account a ON c.customercode = a.customercode
                    LEFT JOIN card d ON a.accountid = d.accountid
                    WHERE 1=1';

        -- Dynamically add filters if parameters are provided
        IF p_mobileno IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.mobileno = %L', p_mobileno);
        END IF;

        IF p_fname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.fname ILIKE %L', p_fname || '%');
        END IF;

        IF p_lname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.lname ILIKE %L', p_lname || '%');
        END IF;

        IF p_middlename IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.middlename ILIKE %L', p_middlename || '%');
        END IF;

        IF p_cardnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND d.cardnumber = %L', p_cardnumber);
        END IF;

        IF p_accountnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', p_accountnumber);
        END IF;

        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;

        -- Optional: Show the generated SQL (for debugging)
        RAISE NOTICE 'Dynamic query executing: %', dyn_sql;

        -- Execute and return the query results
        RETURN QUERY EXECUTE dyn_sql;
    ELSE
        RAISE NOTICE 'No matching action found for: %', action;
    END IF;
END;
$$;


ALTER FUNCTION public.customer_action_handler(action character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_customercode character varying, p_accountnumber character varying, p_cardnumber character varying) OWNER TO postgres;

