--
-- Name: evaluate_card_condition(character varying, character varying, character varying, character varying, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.evaluate_card_condition(p_cardid character varying, p_productid character varying, p_field_name character varying, p_operator character varying, p_value text, p_data_type character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_card_record RECORD;
    v_result BOOLEAN := false;
    v_json_array TEXT[];
BEGIN
    -- Get card data
    SELECT c.cardtype, c.schemetype, c.status, c.expirydate
    INTO v_card_record
    FROM card c
    WHERE c.cardid = p_cardid;
    
    -- Evaluate based on field name and operator
    IF p_field_name = 'card_status' AND p_operator = 'EQUALS' THEN
        v_result := v_card_record.status = p_value;
        
    ELSIF p_field_name = 'cardtype' AND p_operator = 'IN' THEN
        -- Parse JSON array
        SELECT ARRAY(SELECT jsonb_array_elements_text(p_value::jsonb))
        INTO v_json_array;
        v_result := v_card_record.cardtype = ANY(v_json_array);
        
    ELSIF p_field_name = 'schemetype' AND p_operator = 'IN' THEN
        -- Parse JSON array
        SELECT ARRAY(SELECT jsonb_array_elements_text(p_value::jsonb))
        INTO v_json_array;
        v_result := v_card_record.schemetype = ANY(v_json_array);
        
    ELSIF p_field_name = 'years_until_expiry' AND p_operator = 'GREATER_THAN' THEN
        v_result := (EXTRACT(YEAR FROM v_card_record.expirydate) - EXTRACT(YEAR FROM CURRENT_DATE)) > p_value::integer;
        
    ELSE
        v_result := true;  -- Default to true for unknown conditions
    END IF;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.evaluate_card_condition(p_cardid character varying, p_productid character varying, p_field_name character varying, p_operator character varying, p_value text, p_data_type character varying) OWNER TO postgres;

--
-- Name: fbulk_uploadinstant_cards(character varying, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fbulk_uploadinstant_cards(p_batchid character varying, p_records_json jsonb, p_debuglevel integer DEFAULT 0, OUT p_result_code integer, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_success_count INTEGER := 0;
    v_error_count INTEGER := 0;
    v_errors JSONB := '[]'::JSONB;
    v_success_ids JSONB := '[]'::JSONB;
    v_total_records INTEGER;
    v_inserted_uploadid VARCHAR(12);
    v_record JSONB;
    v_cardnumber VARCHAR(20);
    v_status VARCHAR(20);
    v_field_name TEXT;
    v_field_value TEXT;
    v_field_length INTEGER;
	v_isgreenpinenable VARCHAR(1);--FOR POOLING STATUS FROM INSTANTCARDCYLCE-TABLE
	v_requestid VARCHAR(12);
	v_accountnumber VARCHAR(20);
BEGIN
    -- Initialize result
    p_result_code := 0;
    p_result_message := 'Bulk insert completed';
    p_result_data := NULL;
    v_total_records := jsonb_array_length(p_records_json);
    
    -- SIMPLE DEBUGGING: Print what we receive
    RAISE NOTICE '=== DEBUG START ===';
    RAISE NOTICE 'Batch ID: % (Length: %)', p_batchid, LENGTH(p_batchid);
    RAISE NOTICE 'Total records received: %', v_total_records;

			
	
    -- Check first record fields and lengths
    IF v_total_records > 0 THEN
        v_record := p_records_json -> 0;
        RAISE NOTICE 'First record fields:';
        
        -- Loop through all fields in the first record
        FOR v_field_name IN SELECT jsonb_object_keys(v_record)
        LOOP
            v_field_value := v_record ->> v_field_name;
            v_field_length := LENGTH(v_field_value);
            RAISE NOTICE '  %: "%" (Length: %)', 
                         v_field_name, 
                         v_field_value,
                         v_field_length;
            
            -- Warning for fields >12 characters
            IF v_field_length > 12 THEN
                RAISE NOTICE '  WARNING: Field "%" has % characters (>12!)', 
                            v_field_name, v_field_length;
            END IF;
        END LOOP;
    END IF;
    RAISE NOTICE '=== DEBUG END ===';
    
    -- Validate input
    IF v_total_records = 0 THEN
        p_result_code := 1;
        p_result_message := 'No valid records provided';
        RETURN;
    END IF;
    
    -- Log start
    IF p_debuglevel >= 1 THEN
        PERFORM public.flog_audit_trail(
            'instantcardstock',
            'BULK_INSERT_START',
            'Starting bulk insert for batch: ' || p_batchid,
            jsonb_build_object(
                'batchid', p_batchid,
                'total_records', v_total_records
            )
        );
    END IF;
    
    -- Use transaction for atomic operation
    BEGIN
        -- Process each record
        FOR i IN 0..v_total_records - 1 LOOP
            v_record := p_records_json -> i;
            v_cardnumber := v_record ->> 'cardnumber';
            v_status := v_record ->> 'status';
            
            -- Validate required fields
            IF v_cardnumber IS NOT NULL AND v_status IS NOT NULL 
               AND v_cardnumber != '' AND v_status != '' THEN
                BEGIN
                    -- Check for duplicate before insert
                    IF EXISTS (SELECT 1 FROM instantcardstock 
                              WHERE cardnumber = v_cardnumber) THEN
                        v_error_count := v_error_count + 1;
                        v_errors := v_errors || jsonb_build_object(
                            'row', i + 1,
                            'cardnumber', v_cardnumber,
                            'error', 'Duplicate card number exists'
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'instantcardstock',
                                'DUPLICATE_SKIPPED',
                                'Skipping duplicate card number: ' || v_cardnumber,
                                jsonb_build_object(
                                    'row', i + 1,
                                    'cardnumber', v_cardnumber
                                )
                            );
                        END IF;
                    ELSE
					--getting requestid from the  instant_card_applications based on accountno
					v_accountnumber =COALESCE(v_record ->> 'accountnumber', '');
					SELECT SPLIT_PART(dap_iden, '_', 1)INTO v_requestid
    				FROM instant_card_applications WHERE dap_requ_acc_numb =COALESCE(v_record ->> 'accountnumber', '');
					RAISE NOTICE 'Account number: %, Request ID: %', COALESCE(v_record ->> 'accountnumber', ''),  v_requestid;
					--Inserted by ST:jan20-2026 
					SELECT CASE WHEN pintype = 'GREEN-PIN' THEN 'Y' ELSE 'N' END
    				INTO v_isgreenpinenable FROM instantcardcycle WHERE  requestid=v_requestid;
						IF p_debuglevel >= 1000 THEN--ONLY CHECKING IF REQUESTID NOT FOUND FOR GREENPIN CEHCK
						    PERFORM public.flog_audit_trail(
						        'instantcardstock',
						        'RECORD_INSERTED',
						        'Inserted card: ' || v_cardnumber || 
						        ' | Green-PIN: ' || v_isgreenpinenable ||
						        ' | Account: ' || COALESCE(v_accountnumber, 'NULL'),
						        jsonb_build_object(
						            'row', 2000,
						            'uploadid', v_inserted_uploadid,
						            'cardnumber', v_cardnumber,
						            'accountnumber', v_accountnumber,
						            'requestid', v_requestid,
						            'isgreenpin', v_isgreenpinenable,
						            'batchid', p_batchid
						        )
						    );
						END IF;
                        -- Insert the record
                        INSERT INTO instantcardstock (
                            batchid,
                            uploaddate,
                            cardnumber,
                            clientcode,
                            bankcode,
                            requestbranch,
                            allocatedbranch,
                            assingtocustomer,
                            status,
                            embossedname,
                            opendingdate,
                            expirydate,
                            lastbatchprodnum,
                            accountnumber,
                            createddate,
                            createdby,
                            lastupdateddate,
                            lastupdatedby,
							isgreenpin
                        ) VALUES (
                            p_batchid,
                            CURRENT_TIMESTAMP,
                            v_cardnumber,
                            COALESCE(v_record ->> 'clientcode', ''),
                            COALESCE(v_record ->> 'bankcode', ''),
                            COALESCE(v_record ->> 'requestbranch', '999'),
                            COALESCE(v_record ->> 'allocatedbranch', v_record ->> 'requestbranch', '999'),
                            COALESCE(v_record ->> 'assingtocustomer', 'N'),
                            v_status,
                            COALESCE(v_record ->> 'embossedname', ''),
                            NULLIF(v_record ->> 'opendingdate', '')::DATE,
                            NULLIF(v_record ->> 'expirydate', '')::DATE,
                            COALESCE(v_record ->> 'lastbatchprodnum', ''),
                            COALESCE(v_record ->> 'accountnumber', ''),
                            CURRENT_TIMESTAMP,
                            'BULK_UPLOAD',
                            CURRENT_TIMESTAMP,
                            'BULK_UPLOAD',
							v_isgreenpinenable
                        )
                        RETURNING uploadid INTO v_inserted_uploadid;
                        
                        v_success_count := v_success_count + 1;
                        v_success_ids := v_success_ids || jsonb_build_object(
                            'row', i + 1,
                            'uploadid', v_inserted_uploadid,
                            'cardnumber', v_cardnumber
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'instantcardstock',
                                'RECORD_INSERTED',
                                'Inserted card: ' || v_cardnumber,
                                jsonb_build_object(
                                    'row', i + 1,
                                    'uploadid', v_inserted_uploadid,
                                    'cardnumber', v_cardnumber
                                )
                            );
                        END IF;
                    END IF;
                    
                EXCEPTION WHEN OTHERS THEN
                    v_error_count := v_error_count + 1;
                    v_errors := v_errors || jsonb_build_object(
                        'row', i + 1,
                        'cardnumber', v_cardnumber,
                        'error', SQLERRM
                    );
                    
                    -- Log detailed error for debugging
                    IF p_debuglevel >= 1 THEN
                        PERFORM public.flog_audit_trail(
                            'instantcardstock',
                            'INSERT_ERROR',
                            'Error inserting record: ' || SQLERRM,
                            jsonb_build_object(
                                'row', i + 1,
                                'cardnumber', v_cardnumber,
                                'error', SQLERRM,
                                'record_data', v_record
                            )
                        );
                    END IF;
                END;
            ELSE
                v_error_count := v_error_count + 1;
                v_errors := v_errors || jsonb_build_object(
                    'row', i + 1,
                    'cardnumber', v_cardnumber,
                    'error', 'Missing required fields (cardnumber or status)'
                );
            END IF;
        END LOOP;
        
        -- Prepare result
        p_result_data := jsonb_build_object(
            'batchid', p_batchid,
            'total_records', v_total_records,
            'successful', v_success_count,
            'failed', v_error_count,
            'successful_ids', v_success_ids,
            'errors', v_errors
        );
        
        p_result_message := format('Inserted %s of %s records', 
                                  v_success_count, v_total_records);
        
        IF p_debuglevel >= 1 THEN
            PERFORM public.flog_audit_trail(
                'instantcardstock',
                'BULK_INSERT_SUMMARY',
                p_result_message,
                p_result_data
            );
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        p_result_code := 99;
        p_result_message := 'Bulk insert failed: ' || SQLERRM;
        
        -- Log the transaction error
        IF p_debuglevel >= 1 THEN
            PERFORM public.flog_audit_trail(
                'instantcardstock',
                'BULK_INSERT_FAILED',
                'Transaction failed: ' || SQLERRM,
                jsonb_build_object(
                    'batchid', p_batchid,
                    'error', SQLERRM
                )
            );
        END IF;
    END;
    
    -- Log completion
    IF p_debuglevel >= 1 THEN
        PERFORM public.flog_audit_trail(
            'instantcardstock',
            'BULK_INSERT_COMPLETE',
            p_result_message,
            p_result_data
        );
    END IF;
END;
$$;


ALTER FUNCTION public.fbulk_uploadinstant_cards(p_batchid character varying, p_records_json jsonb, p_debuglevel integer, OUT p_result_code integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- Name: fcard_request_cycle(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcard_request_cycle(action character varying, p_request_id character varying DEFAULT NULL::character varying, p_full_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_account_no character varying DEFAULT NULL::character varying, p_request_type character varying DEFAULT NULL::character varying, p_card_type character varying DEFAULT NULL::character varying, p_currency_type character varying DEFAULT NULL::character varying, p_card_scheme character varying DEFAULT NULL::character varying, p_request_branch_id character varying DEFAULT NULL::character varying, p_delivery_branch_id character varying DEFAULT NULL::character varying, p_remarks text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer, p_pintype character varying DEFAULT NULL::character varying) RETURNS TABLE(request_id character varying, full_name character varying, mobile character varying, account_no character varying, request_type character varying, card_type character varying, currency_type character varying, card_scheme character varying, request_branch_id character varying, delivery_branch_id character varying, customer_branch_id character varying, customer_branch_code character varying, account_type character varying, instcode character varying, remarks text, status character varying, created_at timestamp without time zone, updated_at timestamp without time zone, requstor_branch_code character varying, receiver_branch_code character varying, pintype character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_request_id  VARCHAR(11);
    v_branchcode  VARCHAR(10);
    v_instcode    VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname  VARCHAR(100);
    v_old_status  VARCHAR(20);
    v_log_result  JSON;
    v_log_id      INTEGER;
    v_customer_branch_name VARCHAR(100);
    v_account_type VARCHAR(100);
    v_customer_branch_code VARCHAR(10);
    v_customer_branch_name_full VARCHAR(100);
    v_username  VARCHAR(30);
    v_delivery_branch_code VARCHAR(4);
    v_delivery_branch_name VARCHAR(100);
    v_request_branch_code VARCHAR(4);  -- For requestor_branch_code
    v_branch_id INTEGER;  -- To store the branch ID from users table
BEGIN
    -- Logging at entry
    RAISE LOG 'fcard_request_cycle called: action=%, user=% , full_name=%, mobile=%, account_no=%',
              action, p_userid, p_full_name, p_mobile, p_account_no;

    -- Get user branch info - FIXED with proper join to branch table
    IF p_userid IS NOT NULL THEN
        -- DEBUG: First check if user exists
        RAISE LOG 'DEBUG: Looking for user ID = % in users table', p_userid;
        
        -- Check if user exists
        IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_userid) THEN
            RAISE EXCEPTION 'User with ID % not found in users table. Please check users table.', p_userid;
        END IF;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT,4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- Check if we got data
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Failed to retrieve user data for ID %. Query returned no rows.', p_userid;
        END IF;
        
        RAISE LOG 'DEBUG: Retrieved - v_branch_id=%, v_branchcode="%", v_instcode="%", v_crossbranch=%, v_branchname="%"', 
                  v_branch_id, v_branchcode, v_instcode, v_crossbranch, v_branchname;
        
        -- Validate branch code
        IF v_branchcode IS NULL OR TRIM(v_branchcode) = '' THEN
            RAISE EXCEPTION 'User % has NULL or empty branch code. Current branchid: %. Please update user branch information.', 
                            p_userid, v_branch_id;
        END IF;
        
        -- Clean branch code (remove any whitespace)
        v_branchcode := TRIM(v_branchcode);
        
        IF v_branchname IS NULL THEN
            -- Try to get branch name separately if join didn't work
            SELECT branch_name
              INTO v_branchname
            FROM branch
            WHERE branch_no = v_branchcode
            LIMIT 1;
            
            IF v_branchname IS NULL THEN
                -- Get list of available branches for error message
                DECLARE
                    v_available_branches TEXT;
                BEGIN
                    SELECT string_agg(branch_no || '=' || branch_name, ', ') 
                    INTO v_available_branches
                    FROM branch 
                    LIMIT 5;
                    
                    RAISE EXCEPTION 'Branch not found for branch code: "%" (from user %). Available branches: %', 
                                    v_branchcode, p_userid, v_available_branches;
                END;
            END IF;
        END IF;
        
        RAISE LOG 'DEBUG: Found branch: % (code: %)', v_branchname, v_branchcode;
    END IF;
    
    -- Get requestor branch code from branch table based on request_branch_id
    IF p_request_branch_id IS NOT NULL THEN
        -- First try to match by branch name
        SELECT branch_no INTO v_request_branch_code
        FROM branch
        WHERE branch_name = p_request_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_request_branch_code IS NULL THEN
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_no = p_request_branch_id
            LIMIT 1;
        END IF;
    ELSE
        v_request_branch_code := v_branchcode;  -- Default to user's branch code
    END IF;
    
    -- For INSERT action, get customer branch info from account table
    IF UPPER(action) = 'INSERT' AND p_account_no IS NOT NULL THEN
        -- Get account type and branch code from account table
        SELECT a.accounttype, a.branchcode
          INTO v_account_type, v_customer_branch_code
        FROM account a
        WHERE a.accountnumber = p_account_no
        LIMIT 1;
    
        IF v_account_type IS NULL THEN
            RAISE EXCEPTION 'Account not found with account number: %', p_account_no;
        END IF;

        -- Get branch name from branch table using the branch code
        SELECT branch_name
          INTO v_customer_branch_name_full
        FROM branch
        WHERE branch_no = v_customer_branch_code
        LIMIT 1;

        IF v_customer_branch_name_full IS NULL THEN
            RAISE EXCEPTION 'Customer branch not found for branch code: %', v_customer_branch_code;
        END IF;
    END IF;
    
    -- Get delivery branch info if provided
    IF p_delivery_branch_id IS NOT NULL THEN
        -- Try to get branch code and name from branch table
        -- First try by branch name
        SELECT branch_no, branch_name
          INTO v_delivery_branch_code, v_delivery_branch_name
        FROM branch
        WHERE branch_name = p_delivery_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_delivery_branch_code IS NULL THEN
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_no = p_delivery_branch_id
            LIMIT 1;
        END IF;
        
        -- If still not found, try to get from authlogin table by username
        IF v_delivery_branch_code IS NULL THEN
            SELECT b.branch_no, b.branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM users u
            JOIN branch b ON b.id = u.branchid
            JOIN authlogin al ON al.userid = u.id
            WHERE al.username = p_delivery_branch_id
            LIMIT 1;
        END IF;
    END IF;
    
    -- for fetching username
    SELECT username INTO v_username FROM authlogin WHERE userid = p_userid;
    
    -- INSERT logic
    IF UPPER(action) = 'INSERT' THEN
        v_request_id := COALESCE(p_request_id, fCreateCardCycleCode());

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => v_request_id,
            p_user_id => v_username,
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_new => COALESCE(p_status, 'Pending')
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log INSERT action: %', v_log_result->>'message';
        END IF;

        INSERT INTO card_request_cycle (
            request_id, full_name, mobile, account_no,
            request_type, card_type, currency_type, card_scheme,
            request_branch_id, delivery_branch_id, 
            customer_branch_id, customer_branch_code, account_type,
            requstor_branch_code, receiver_branch_code,  -- NEW COLUMNS
            remarks, status,
            instcode, created_at, updated_at,
            pintype  -- NEW COLUMN
        ) VALUES (
            v_request_id, p_full_name, p_mobile, p_account_no,
            p_request_type, p_card_type, p_currency_type, p_card_scheme,
            COALESCE(p_request_branch_id, v_branchname), 
            COALESCE(v_delivery_branch_name, p_delivery_branch_id),
            v_customer_branch_name_full, v_customer_branch_code, v_account_type,
            v_request_branch_code, v_delivery_branch_code,  -- NEW VALUES
            p_remarks, COALESCE(p_status, 'Pending'),
            v_instcode,
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
            COALESCE(p_pintype, 'DefaultPIN')  -- DEFAULT VALUE IF NOT PROVIDED
        );

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype  -- NEW COLUMN
          FROM card_request_cycle crc
         WHERE crc.request_id = v_request_id;

    -- UPDATE logic
    ELSIF UPPER(action) = 'UPDATE' THEN
        -- For UPDATE, also get customer branch info if account_no is being updated
        IF p_account_no IS NOT NULL THEN
            SELECT a.accounttype, a.branchcode
              INTO v_account_type, v_customer_branch_code
            FROM account a
            WHERE a.accountnumber = p_account_no
            LIMIT 1;

            IF v_account_type IS NOT NULL THEN
                SELECT branch_name
                  INTO v_customer_branch_name_full
                FROM branch
                WHERE branch_no = v_customer_branch_code
                LIMIT 1;
            END IF;
        END IF;
        
        -- Get requestor branch code for UPDATE if request_branch_id provided
        IF p_request_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_name = p_request_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_request_branch_code IS NULL THEN
                SELECT branch_no INTO v_request_branch_code
                FROM branch
                WHERE branch_no = p_request_branch_id
                LIMIT 1;
            END IF;
        ELSE
            -- Keep existing requestor_branch_code if not changing
            SELECT requstor_branch_code INTO v_request_branch_code
            FROM card_request_cycle
            WHERE request_id = p_request_id
            LIMIT 1;
        END IF;
        
        -- Get delivery branch info if provided for UPDATE
        IF p_delivery_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_name = p_delivery_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_delivery_branch_code IS NULL THEN
                SELECT branch_no, branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM branch
                WHERE branch_no = p_delivery_branch_id
                LIMIT 1;
            END IF;
            
            -- If still not found, try to get from authlogin table by username
            IF v_delivery_branch_code IS NULL THEN
                SELECT b.branch_no, b.branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM users u
                JOIN branch b ON b.id = u.branchid
                JOIN authlogin al ON al.userid = u.id
                WHERE al.username = p_delivery_branch_id
                LIMIT 1;
            END IF;
        END IF;

        -- Get old status for logging
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => COALESCE(p_status, v_old_status)
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log UPDATE action: %', v_log_result->>'message';
        END IF;

        -- Update the main record
        UPDATE card_request_cycle crc
           SET full_name          = COALESCE(p_full_name,          crc.full_name),
               mobile             = COALESCE(p_mobile,             crc.mobile),
               account_no         = COALESCE(p_account_no,         crc.account_no),
               request_type       = COALESCE(p_request_type,       crc.request_type),
               card_type          = COALESCE(p_card_type,          crc.card_type),
               currency_type      = COALESCE(p_currency_type,      crc.currency_type),
               card_scheme        = COALESCE(p_card_scheme,        crc.card_scheme),
               request_branch_id  = COALESCE(p_request_branch_id,  crc.request_branch_id),
               delivery_branch_id = CASE 
                                       WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_name IS NOT NULL 
                                       THEN v_delivery_branch_name 
                                       ELSE COALESCE(p_delivery_branch_id, crc.delivery_branch_id) 
                                    END,
               remarks           = COALESCE(p_remarks,             crc.remarks),
               status             = COALESCE(p_status,             crc.status),
               customer_branch_id = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_name_full IS NOT NULL 
                                       THEN v_customer_branch_name_full 
                                       ELSE crc.customer_branch_id 
                                    END,
               customer_branch_code = CASE  -- Changed from branch_code
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_code IS NOT NULL 
                                       THEN v_customer_branch_code 
                                       ELSE crc.customer_branch_code 
                                     END,
               account_type       = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_account_type IS NOT NULL 
                                       THEN v_account_type 
                                       ELSE crc.account_type 
                                    END,
               requstor_branch_code = CASE  -- NEW: Update requestor branch code
                                        WHEN p_request_branch_id IS NOT NULL AND v_request_branch_code IS NOT NULL 
                                        THEN v_request_branch_code 
                                        ELSE crc.requstor_branch_code 
                                     END,
               receiver_branch_code = CASE  -- NEW: Update receiver branch code
                                        WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_code IS NOT NULL 
                                        THEN v_delivery_branch_code 
                                        ELSE crc.receiver_branch_code 
                                     END,
               pintype            = COALESCE(p_pintype,            crc.pintype),  -- NEW: Update pintype
               updated_at         = CURRENT_TIMESTAMP
         WHERE crc.request_id = p_request_id;

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype  -- NEW COLUMN
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

    -- DELETE logic
    ELSIF UPPER(action) = 'DELETE' THEN
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => NULL
        ) INTO v_log_result;

        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log DELETE action: %', v_log_result->>'message';
        END IF;

        DELETE FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

        RETURN;

    -- LIST logic
    ELSIF UPPER(action) = 'LIST' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for LIST action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- CHECKER logic
    ELSIF UPPER(action) = 'CHECKER' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for CHECKER action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- OPERATOR logic
    ELSIF UPPER(action) = 'OPERATOR' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for OPERATOR action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    ELSE
        RAISE EXCEPTION 'Invalid action: %, must be INSERT, UPDATE, DELETE, LIST, CHECKER or OPERATOR', action;
    END IF;
END;
$$;


ALTER FUNCTION public.fcard_request_cycle(action character varying, p_request_id character varying, p_full_name character varying, p_mobile character varying, p_account_no character varying, p_request_type character varying, p_card_type character varying, p_currency_type character varying, p_card_scheme character varying, p_request_branch_id character varying, p_delivery_branch_id character varying, p_remarks text, p_status character varying, p_userid integer, p_pintype character varying) OWNER TO postgres;

--
-- Name: fcard_request_cycle(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, integer, character varying, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcard_request_cycle(action character varying, p_request_id character varying DEFAULT NULL::character varying, p_full_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_account_no character varying DEFAULT NULL::character varying, p_request_type character varying DEFAULT NULL::character varying, p_card_type character varying DEFAULT NULL::character varying, p_currency_type character varying DEFAULT NULL::character varying, p_card_scheme character varying DEFAULT NULL::character varying, p_request_branch_id character varying DEFAULT NULL::character varying, p_delivery_branch_id character varying DEFAULT NULL::character varying, p_remarks text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer, p_pintype character varying DEFAULT NULL::character varying, p_filelocation text DEFAULT NULL::text) RETURNS TABLE(request_id character varying, full_name character varying, mobile character varying, account_no character varying, request_type character varying, card_type character varying, currency_type character varying, card_scheme character varying, request_branch_id character varying, delivery_branch_id character varying, customer_branch_id character varying, customer_branch_code character varying, account_type character varying, instcode character varying, remarks text, status character varying, created_at timestamp without time zone, updated_at timestamp without time zone, requstor_branch_code character varying, receiver_branch_code character varying, pintype character varying, file_location text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_request_id  VARCHAR(11);
    v_branchcode  VARCHAR(10);
    v_instcode    VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname  VARCHAR(100);
    v_old_status  VARCHAR(20);
    v_log_result  JSON;
    v_log_id      INTEGER;
    v_customer_branch_name VARCHAR(100);
    v_account_type VARCHAR(100);
    v_customer_branch_code VARCHAR(10);
    v_customer_branch_name_full VARCHAR(100);
    v_username  VARCHAR(30);
    v_delivery_branch_code VARCHAR(4);
    v_delivery_branch_name VARCHAR(100);
    v_request_branch_code VARCHAR(4);  -- For requestor_branch_code
    v_branch_id INTEGER;  -- To store the branch ID from users table
BEGIN
    -- Logging at entry
    RAISE LOG 'fcard_request_cycle called: action=%, user=% , full_name=%, mobile=%, account_no=%',
              action, p_userid, p_full_name, p_mobile, p_account_no;

    -- Get user branch info - FIXED with proper join to branch table
    IF p_userid IS NOT NULL THEN
        -- DEBUG: First check if user exists
        RAISE LOG 'DEBUG: Looking for user ID = % in users table', p_userid;
        
        -- Check if user exists
        IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_userid) THEN
            RAISE EXCEPTION 'User with ID % not found in users table. Please check users table.', p_userid;
        END IF;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT,4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- Check if we got data
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Failed to retrieve user data for ID %. Query returned no rows.', p_userid;
        END IF;
        
        RAISE LOG 'DEBUG: Retrieved - v_branch_id=%, v_branchcode="%", v_instcode="%", v_crossbranch=%, v_branchname="%"', 
                  v_branch_id, v_branchcode, v_instcode, v_crossbranch, v_branchname;
        
        -- Validate branch code
        IF v_branchcode IS NULL OR TRIM(v_branchcode) = '' THEN
            RAISE EXCEPTION 'User % has NULL or empty branch code. Current branchid: %. Please update user branch information.', 
                            p_userid, v_branch_id;
        END IF;
        
        -- Clean branch code (remove any whitespace)
        v_branchcode := TRIM(v_branchcode);
        
        IF v_branchname IS NULL THEN
            -- Try to get branch name separately if join didn't work
            SELECT branch_name
              INTO v_branchname
            FROM branch
            WHERE branch_no = v_branchcode
            LIMIT 1;
            
            IF v_branchname IS NULL THEN
                -- Get list of available branches for error message
                DECLARE
                    v_available_branches TEXT;
                BEGIN
                    SELECT string_agg(branch_no || '=' || branch_name, ', ') 
                    INTO v_available_branches
                    FROM branch 
                    LIMIT 5;
                    
                    RAISE EXCEPTION 'Branch not found for branch code: "%" (from user %). Available branches: %', 
                                    v_branchcode, p_userid, v_available_branches;
                END;
            END IF;
        END IF;
        
        RAISE LOG 'DEBUG: Found branch: % (code: %)', v_branchname, v_branchcode;
    END IF;
    
    -- Get requestor branch code from branch table based on request_branch_id
    IF p_request_branch_id IS NOT NULL THEN
        -- First try to match by branch name
        SELECT branch_no INTO v_request_branch_code
        FROM branch
        WHERE branch_name = p_request_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_request_branch_code IS NULL THEN
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_no = p_request_branch_id
            LIMIT 1;
        END IF;
    ELSE
        v_request_branch_code := v_branchcode;  -- Default to user's branch code
    END IF;
    
    -- For INSERT action, get customer branch info from account table
    IF UPPER(action) = 'INSERT' AND p_account_no IS NOT NULL THEN
        -- Get account type and branch code from account table
        SELECT a.accounttype, a.branchcode
          INTO v_account_type, v_customer_branch_code
        FROM account a
        WHERE a.accountnumber = p_account_no
        LIMIT 1;
    
        IF v_account_type IS NULL THEN
            RAISE EXCEPTION 'Account not found with account number: %', p_account_no;
        END IF;

        -- Get branch name from branch table using the branch code
        SELECT branch_name
          INTO v_customer_branch_name_full
        FROM branch
        WHERE branch_no = v_customer_branch_code
        LIMIT 1;

        IF v_customer_branch_name_full IS NULL THEN
            RAISE EXCEPTION 'Customer branch not found for branch code: %', v_customer_branch_code;
        END IF;
    END IF;
    
    -- Get delivery branch info if provided
    IF p_delivery_branch_id IS NOT NULL THEN
        -- Try to get branch code and name from branch table
        -- First try by branch name
        SELECT branch_no, branch_name
          INTO v_delivery_branch_code, v_delivery_branch_name
        FROM branch
        WHERE branch_name = p_delivery_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_delivery_branch_code IS NULL THEN
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_no = p_delivery_branch_id
            LIMIT 1;
        END IF;
        
        -- If still not found, try to get from authlogin table by username
        IF v_delivery_branch_code IS NULL THEN
            SELECT b.branch_no, b.branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM users u
            JOIN branch b ON b.id = u.branchid
            JOIN authlogin al ON al.userid = u.id
            WHERE al.username = p_delivery_branch_id
            LIMIT 1;
        END IF;
    END IF;
    
    -- for fetching username
    SELECT username INTO v_username FROM authlogin WHERE userid = p_userid;
    
    -- INSERT logic
    IF UPPER(action) = 'INSERT' THEN
        v_request_id := COALESCE(p_request_id, fCreateCardCycleCode());

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => v_request_id,
            p_user_id => v_username,
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_new => COALESCE(p_status, 'Pending')
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log INSERT action: %', v_log_result->>'message';
        END IF;

        INSERT INTO card_request_cycle (
            request_id, full_name, mobile, account_no,
            request_type, card_type, currency_type, card_scheme,
            request_branch_id, delivery_branch_id, 
            customer_branch_id, customer_branch_code, account_type,
            requstor_branch_code, receiver_branch_code,  -- NEW COLUMNS
            remarks, status,
            instcode, created_at, updated_at,
            pintype,  -- NEW COLUMN
			filelocation --added on feb-24-2026
        ) VALUES (
            v_request_id, p_full_name, p_mobile, p_account_no,
            p_request_type, p_card_type, p_currency_type, p_card_scheme,
            COALESCE(p_request_branch_id, v_branchname), 
            COALESCE(v_delivery_branch_name, p_delivery_branch_id),
            v_customer_branch_name_full, v_customer_branch_code, v_account_type,
            v_request_branch_code, v_delivery_branch_code,  -- NEW VALUES
            p_remarks, COALESCE(p_status, 'Pending'),
            v_instcode,
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
            COALESCE(p_pintype, 'DefaultPIN'),  -- DEFAULT VALUE IF NOT PROVIDED
			p_filelocation  
        );

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype,  -- NEW COLUMN
			   crc.filelocation
          FROM card_request_cycle crc
         WHERE crc.request_id = v_request_id;

    -- UPDATE logic
    ELSIF UPPER(action) = 'UPDATE' THEN
        -- For UPDATE, also get customer branch info if account_no is being updated
        IF p_account_no IS NOT NULL THEN
            SELECT a.accounttype, a.branchcode
              INTO v_account_type, v_customer_branch_code
            FROM account a
            WHERE a.accountnumber = p_account_no
            LIMIT 1;

            IF v_account_type IS NOT NULL THEN
                SELECT branch_name
                  INTO v_customer_branch_name_full
                FROM branch
                WHERE branch_no = v_customer_branch_code
                LIMIT 1;
            END IF;
        END IF;
        
        -- Get requestor branch code for UPDATE if request_branch_id provided
        IF p_request_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_name = p_request_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_request_branch_code IS NULL THEN
                SELECT branch_no INTO v_request_branch_code
                FROM branch
                WHERE branch_no = p_request_branch_id
                LIMIT 1;
            END IF;
        ELSE
            -- Keep existing requestor_branch_code if not changing
            SELECT requstor_branch_code INTO v_request_branch_code
            FROM card_request_cycle
            WHERE request_id = p_request_id
            LIMIT 1;
        END IF;
        
        -- Get delivery branch info if provided for UPDATE
        IF p_delivery_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_name = p_delivery_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_delivery_branch_code IS NULL THEN
                SELECT branch_no, branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM branch
                WHERE branch_no = p_delivery_branch_id
                LIMIT 1;
            END IF;
            
            -- If still not found, try to get from authlogin table by username
            IF v_delivery_branch_code IS NULL THEN
                SELECT b.branch_no, b.branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM users u
                JOIN branch b ON b.id = u.branchid
                JOIN authlogin al ON al.userid = u.id
                WHERE al.username = p_delivery_branch_id
                LIMIT 1;
            END IF;
        END IF;

        -- Get old status for logging
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => COALESCE(p_status, v_old_status)
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log UPDATE action: %', v_log_result->>'message';
        END IF;

        -- Update the main record
        UPDATE card_request_cycle crc
           SET full_name          = COALESCE(p_full_name,          crc.full_name),
               mobile             = COALESCE(p_mobile,             crc.mobile),
               account_no         = COALESCE(p_account_no,         crc.account_no),
               request_type       = COALESCE(p_request_type,       crc.request_type),
               card_type          = COALESCE(p_card_type,          crc.card_type),
               currency_type      = COALESCE(p_currency_type,      crc.currency_type),
               card_scheme        = COALESCE(p_card_scheme,        crc.card_scheme),
               request_branch_id  = COALESCE(p_request_branch_id,  crc.request_branch_id),
               delivery_branch_id = CASE 
                                       WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_name IS NOT NULL 
                                       THEN v_delivery_branch_name 
                                       ELSE COALESCE(p_delivery_branch_id, crc.delivery_branch_id) 
                                    END,
               remarks           = COALESCE(p_remarks,             crc.remarks),
               status             = COALESCE(p_status,             crc.status),
               customer_branch_id = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_name_full IS NOT NULL 
                                       THEN v_customer_branch_name_full 
                                       ELSE crc.customer_branch_id 
                                    END,
               customer_branch_code = CASE  -- Changed from branch_code
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_code IS NOT NULL 
                                       THEN v_customer_branch_code 
                                       ELSE crc.customer_branch_code 
                                     END,
               account_type       = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_account_type IS NOT NULL 
                                       THEN v_account_type 
                                       ELSE crc.account_type 
                                    END,
               requstor_branch_code = CASE  -- NEW: Update requestor branch code
                                        WHEN p_request_branch_id IS NOT NULL AND v_request_branch_code IS NOT NULL 
                                        THEN v_request_branch_code 
                                        ELSE crc.requstor_branch_code 
                                     END,
               receiver_branch_code = CASE  -- NEW: Update receiver branch code
                                        WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_code IS NOT NULL 
                                        THEN v_delivery_branch_code 
                                        ELSE crc.receiver_branch_code 
                                     END,
               pintype            = COALESCE(p_pintype,            crc.pintype),  -- NEW: Update pintype\
			   filelocation		  =COALESCE(p_filelocation,			crc.filelocation),
               updated_at         = CURRENT_TIMESTAMP
         WHERE crc.request_id = p_request_id;

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype,  -- NEW COLUMN
			   crc.filelocation
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

    -- DELETE logic
    ELSIF UPPER(action) = 'DELETE' THEN
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => NULL
        ) INTO v_log_result;

        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log DELETE action: %', v_log_result->>'message';
        END IF;

        DELETE FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

        RETURN;

    -- LIST logic
    ELSIF UPPER(action) = 'LIST' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for LIST action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- CHECKER logic
    ELSIF UPPER(action) = 'CHECKER' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for CHECKER action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- OPERATOR logic
    ELSIF UPPER(action) = 'OPERATOR' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for OPERATOR action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype,  -- NEW COLUMN
				   crc.filelocation
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    ELSE
        RAISE EXCEPTION 'Invalid action: %, must be INSERT, UPDATE, DELETE, LIST, CHECKER or OPERATOR', action;
    END IF;
END;
$$;


ALTER FUNCTION public.fcard_request_cycle(action character varying, p_request_id character varying, p_full_name character varying, p_mobile character varying, p_account_no character varying, p_request_type character varying, p_card_type character varying, p_currency_type character varying, p_card_scheme character varying, p_request_branch_id character varying, p_delivery_branch_id character varying, p_remarks text, p_status character varying, p_userid integer, p_pintype character varying, p_filelocation text) OWNER TO postgres;

--
-- Name: fcard_request_cycle_feb242026(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcard_request_cycle_feb242026(action character varying, p_request_id character varying DEFAULT NULL::character varying, p_full_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_account_no character varying DEFAULT NULL::character varying, p_request_type character varying DEFAULT NULL::character varying, p_card_type character varying DEFAULT NULL::character varying, p_currency_type character varying DEFAULT NULL::character varying, p_card_scheme character varying DEFAULT NULL::character varying, p_request_branch_id character varying DEFAULT NULL::character varying, p_delivery_branch_id character varying DEFAULT NULL::character varying, p_remarks text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer, p_pintype character varying DEFAULT NULL::character varying) RETURNS TABLE(request_id character varying, full_name character varying, mobile character varying, account_no character varying, request_type character varying, card_type character varying, currency_type character varying, card_scheme character varying, request_branch_id character varying, delivery_branch_id character varying, customer_branch_id character varying, customer_branch_code character varying, account_type character varying, instcode character varying, remarks text, status character varying, created_at timestamp without time zone, updated_at timestamp without time zone, requstor_branch_code character varying, receiver_branch_code character varying, pintype character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_request_id  VARCHAR(11);
    v_branchcode  VARCHAR(10);
    v_instcode    VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname  VARCHAR(100);
    v_old_status  VARCHAR(20);
    v_log_result  JSON;
    v_log_id      INTEGER;
    v_customer_branch_name VARCHAR(100);
    v_account_type VARCHAR(100);
    v_customer_branch_code VARCHAR(10);
    v_customer_branch_name_full VARCHAR(100);
    v_username  VARCHAR(30);
    v_delivery_branch_code VARCHAR(4);
    v_delivery_branch_name VARCHAR(100);
    v_request_branch_code VARCHAR(4);  -- For requestor_branch_code
    v_branch_id INTEGER;  -- To store the branch ID from users table
BEGIN
    -- Logging at entry
    RAISE LOG 'fcard_request_cycle called: action=%, user=% , full_name=%, mobile=%, account_no=%',
              action, p_userid, p_full_name, p_mobile, p_account_no;

    -- Get user branch info - FIXED with proper join to branch table
    IF p_userid IS NOT NULL THEN
        -- DEBUG: First check if user exists
        RAISE LOG 'DEBUG: Looking for user ID = % in users table', p_userid;
        
        -- Check if user exists
        IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_userid) THEN
            RAISE EXCEPTION 'User with ID % not found in users table. Please check users table.', p_userid;
        END IF;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT,4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- Check if we got data
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Failed to retrieve user data for ID %. Query returned no rows.', p_userid;
        END IF;
        
        RAISE LOG 'DEBUG: Retrieved - v_branch_id=%, v_branchcode="%", v_instcode="%", v_crossbranch=%, v_branchname="%"', 
                  v_branch_id, v_branchcode, v_instcode, v_crossbranch, v_branchname;
        
        -- Validate branch code
        IF v_branchcode IS NULL OR TRIM(v_branchcode) = '' THEN
            RAISE EXCEPTION 'User % has NULL or empty branch code. Current branchid: %. Please update user branch information.', 
                            p_userid, v_branch_id;
        END IF;
        
        -- Clean branch code (remove any whitespace)
        v_branchcode := TRIM(v_branchcode);
        
        IF v_branchname IS NULL THEN
            -- Try to get branch name separately if join didn't work
            SELECT branch_name
              INTO v_branchname
            FROM branch
            WHERE branch_no = v_branchcode
            LIMIT 1;
            
            IF v_branchname IS NULL THEN
                -- Get list of available branches for error message
                DECLARE
                    v_available_branches TEXT;
                BEGIN
                    SELECT string_agg(branch_no || '=' || branch_name, ', ') 
                    INTO v_available_branches
                    FROM branch 
                    LIMIT 5;
                    
                    RAISE EXCEPTION 'Branch not found for branch code: "%" (from user %). Available branches: %', 
                                    v_branchcode, p_userid, v_available_branches;
                END;
            END IF;
        END IF;
        
        RAISE LOG 'DEBUG: Found branch: % (code: %)', v_branchname, v_branchcode;
    END IF;
    
    -- Get requestor branch code from branch table based on request_branch_id
    IF p_request_branch_id IS NOT NULL THEN
        -- First try to match by branch name
        SELECT branch_no INTO v_request_branch_code
        FROM branch
        WHERE branch_name = p_request_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_request_branch_code IS NULL THEN
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_no = p_request_branch_id
            LIMIT 1;
        END IF;
    ELSE
        v_request_branch_code := v_branchcode;  -- Default to user's branch code
    END IF;
    
    -- For INSERT action, get customer branch info from account table
    IF UPPER(action) = 'INSERT' AND p_account_no IS NOT NULL THEN
        -- Get account type and branch code from account table
        SELECT a.accounttype, a.branchcode
          INTO v_account_type, v_customer_branch_code
        FROM account a
        WHERE a.accountnumber = p_account_no
        LIMIT 1;
    
        IF v_account_type IS NULL THEN
            RAISE EXCEPTION 'Account not found with account number: %', p_account_no;
        END IF;

        -- Get branch name from branch table using the branch code
        SELECT branch_name
          INTO v_customer_branch_name_full
        FROM branch
        WHERE branch_no = v_customer_branch_code
        LIMIT 1;

        IF v_customer_branch_name_full IS NULL THEN
            RAISE EXCEPTION 'Customer branch not found for branch code: %', v_customer_branch_code;
        END IF;
    END IF;
    
    -- Get delivery branch info if provided
    IF p_delivery_branch_id IS NOT NULL THEN
        -- Try to get branch code and name from branch table
        -- First try by branch name
        SELECT branch_no, branch_name
          INTO v_delivery_branch_code, v_delivery_branch_name
        FROM branch
        WHERE branch_name = p_delivery_branch_id
        LIMIT 1;
        
        -- If not found by name, try by branch code
        IF v_delivery_branch_code IS NULL THEN
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_no = p_delivery_branch_id
            LIMIT 1;
        END IF;
        
        -- If still not found, try to get from authlogin table by username
        IF v_delivery_branch_code IS NULL THEN
            SELECT b.branch_no, b.branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM users u
            JOIN branch b ON b.id = u.branchid
            JOIN authlogin al ON al.userid = u.id
            WHERE al.username = p_delivery_branch_id
            LIMIT 1;
        END IF;
    END IF;
    
    -- for fetching username
    SELECT username INTO v_username FROM authlogin WHERE userid = p_userid;
    
    -- INSERT logic
    IF UPPER(action) = 'INSERT' THEN
        v_request_id := COALESCE(p_request_id, fCreateCardCycleCode());

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => v_request_id,
            p_user_id => v_username,
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_new => COALESCE(p_status, 'Pending')
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log INSERT action: %', v_log_result->>'message';
        END IF;

        INSERT INTO card_request_cycle (
            request_id, full_name, mobile, account_no,
            request_type, card_type, currency_type, card_scheme,
            request_branch_id, delivery_branch_id, 
            customer_branch_id, customer_branch_code, account_type,
            requstor_branch_code, receiver_branch_code,  -- NEW COLUMNS
            remarks, status,
            instcode, created_at, updated_at,
            pintype  -- NEW COLUMN
        ) VALUES (
            v_request_id, p_full_name, p_mobile, p_account_no,
            p_request_type, p_card_type, p_currency_type, p_card_scheme,
            COALESCE(p_request_branch_id, v_branchname), 
            COALESCE(v_delivery_branch_name, p_delivery_branch_id),
            v_customer_branch_name_full, v_customer_branch_code, v_account_type,
            v_request_branch_code, v_delivery_branch_code,  -- NEW VALUES
            p_remarks, COALESCE(p_status, 'Pending'),
            v_instcode,
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP,
            COALESCE(p_pintype, 'DefaultPIN')  -- DEFAULT VALUE IF NOT PROVIDED
        );

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype  -- NEW COLUMN
          FROM card_request_cycle crc
         WHERE crc.request_id = v_request_id;

    -- UPDATE logic
    ELSIF UPPER(action) = 'UPDATE' THEN
        -- For UPDATE, also get customer branch info if account_no is being updated
        IF p_account_no IS NOT NULL THEN
            SELECT a.accounttype, a.branchcode
              INTO v_account_type, v_customer_branch_code
            FROM account a
            WHERE a.accountnumber = p_account_no
            LIMIT 1;

            IF v_account_type IS NOT NULL THEN
                SELECT branch_name
                  INTO v_customer_branch_name_full
                FROM branch
                WHERE branch_no = v_customer_branch_code
                LIMIT 1;
            END IF;
        END IF;
        
        -- Get requestor branch code for UPDATE if request_branch_id provided
        IF p_request_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no INTO v_request_branch_code
            FROM branch
            WHERE branch_name = p_request_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_request_branch_code IS NULL THEN
                SELECT branch_no INTO v_request_branch_code
                FROM branch
                WHERE branch_no = p_request_branch_id
                LIMIT 1;
            END IF;
        ELSE
            -- Keep existing requestor_branch_code if not changing
            SELECT requstor_branch_code INTO v_request_branch_code
            FROM card_request_cycle
            WHERE request_id = p_request_id
            LIMIT 1;
        END IF;
        
        -- Get delivery branch info if provided for UPDATE
        IF p_delivery_branch_id IS NOT NULL THEN
            -- First try by branch name
            SELECT branch_no, branch_name
              INTO v_delivery_branch_code, v_delivery_branch_name
            FROM branch
            WHERE branch_name = p_delivery_branch_id
            LIMIT 1;
            
            -- If not found by name, try by branch code
            IF v_delivery_branch_code IS NULL THEN
                SELECT branch_no, branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM branch
                WHERE branch_no = p_delivery_branch_id
                LIMIT 1;
            END IF;
            
            -- If still not found, try to get from authlogin table by username
            IF v_delivery_branch_code IS NULL THEN
                SELECT b.branch_no, b.branch_name
                  INTO v_delivery_branch_code, v_delivery_branch_name
                FROM users u
                JOIN branch b ON b.id = u.branchid
                JOIN authlogin al ON al.userid = u.id
                WHERE al.username = p_delivery_branch_id
                LIMIT 1;
            END IF;
        END IF;

        -- Get old status for logging
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        -- Log the action using fcrud_card_cycle_log
        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_full_name => p_full_name,
            p_mobile => p_mobile,
            p_account_no => p_account_no,
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => COALESCE(p_status, v_old_status)
        ) INTO v_log_result;

        -- Check if log was successful
        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log UPDATE action: %', v_log_result->>'message';
        END IF;

        -- Update the main record
        UPDATE card_request_cycle crc
           SET full_name          = COALESCE(p_full_name,          crc.full_name),
               mobile             = COALESCE(p_mobile,             crc.mobile),
               account_no         = COALESCE(p_account_no,         crc.account_no),
               request_type       = COALESCE(p_request_type,       crc.request_type),
               card_type          = COALESCE(p_card_type,          crc.card_type),
               currency_type      = COALESCE(p_currency_type,      crc.currency_type),
               card_scheme        = COALESCE(p_card_scheme,        crc.card_scheme),
               request_branch_id  = COALESCE(p_request_branch_id,  crc.request_branch_id),
               delivery_branch_id = CASE 
                                       WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_name IS NOT NULL 
                                       THEN v_delivery_branch_name 
                                       ELSE COALESCE(p_delivery_branch_id, crc.delivery_branch_id) 
                                    END,
               remarks           = COALESCE(p_remarks,             crc.remarks),
               status             = COALESCE(p_status,             crc.status),
               customer_branch_id = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_name_full IS NOT NULL 
                                       THEN v_customer_branch_name_full 
                                       ELSE crc.customer_branch_id 
                                    END,
               customer_branch_code = CASE  -- Changed from branch_code
                                       WHEN p_account_no IS NOT NULL AND v_customer_branch_code IS NOT NULL 
                                       THEN v_customer_branch_code 
                                       ELSE crc.customer_branch_code 
                                     END,
               account_type       = CASE 
                                       WHEN p_account_no IS NOT NULL AND v_account_type IS NOT NULL 
                                       THEN v_account_type 
                                       ELSE crc.account_type 
                                    END,
               requstor_branch_code = CASE  -- NEW: Update requestor branch code
                                        WHEN p_request_branch_id IS NOT NULL AND v_request_branch_code IS NOT NULL 
                                        THEN v_request_branch_code 
                                        ELSE crc.requstor_branch_code 
                                     END,
               receiver_branch_code = CASE  -- NEW: Update receiver branch code
                                        WHEN p_delivery_branch_id IS NOT NULL AND v_delivery_branch_code IS NOT NULL 
                                        THEN v_delivery_branch_code 
                                        ELSE crc.receiver_branch_code 
                                     END,
               pintype            = COALESCE(p_pintype,            crc.pintype),  -- NEW: Update pintype
               updated_at         = CURRENT_TIMESTAMP
         WHERE crc.request_id = p_request_id;

        RETURN QUERY
        SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
               crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
               crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
               crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
               crc.created_at, crc.updated_at,
               crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
               crc.pintype  -- NEW COLUMN
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

    -- DELETE logic
    ELSIF UPPER(action) = 'DELETE' THEN
        SELECT crc.status INTO v_old_status
          FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id
         LIMIT 1;

        IF v_old_status IS NULL THEN
            RAISE EXCEPTION 'Record not found with request_id: %', p_request_id;
        END IF;

        SELECT fcrud_card_cycle_log(
            'INSERT',
            p_request_id => p_request_id,
            p_user_id => v_username,  -- Use v_username instead of p_userid
            p_branch_code => v_branchcode,
            p_status_old => v_old_status,
            p_status_new => NULL
        ) INTO v_log_result;

        IF NOT (v_log_result->>'success')::BOOLEAN THEN
            RAISE EXCEPTION 'Failed to log DELETE action: %', v_log_result->>'message';
        END IF;

        DELETE FROM card_request_cycle crc
         WHERE crc.request_id = p_request_id;

        RETURN;

    -- LIST logic
    ELSIF UPPER(action) = 'LIST' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for LIST action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE (p_status IS NULL OR crc.status = p_status)
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- CHECKER logic
    ELSIF UPPER(action) = 'CHECKER' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for CHECKER action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = 'Pending'
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    -- OPERATOR logic
    ELSIF UPPER(action) = 'OPERATOR' THEN
        IF p_userid IS NULL THEN
            RAISE EXCEPTION 'User ID is required for OPERATOR action.';
        END IF;

        IF v_crossbranch THEN
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        ELSE
            RETURN QUERY
            SELECT crc.request_id, crc.full_name, crc.mobile, crc.account_no,
                   crc.request_type, crc.card_type, crc.currency_type, crc.card_scheme,
                   crc.request_branch_id, crc.delivery_branch_id, crc.customer_branch_id,
                   crc.customer_branch_code, crc.account_type, crc.instcode, crc.remarks, crc.status,
                   crc.created_at, crc.updated_at,
                   crc.requstor_branch_code, crc.receiver_branch_code,  -- NEW COLUMNS
                   crc.pintype  -- NEW COLUMN
              FROM card_request_cycle crc
             WHERE crc.status = p_status
               AND crc.customer_branch_code = v_branchcode  -- Changed from branch_code to customer_branch_code
               AND (p_full_name IS NULL OR crc.full_name ILIKE '%' || p_full_name || '%')
               AND (p_mobile    IS NULL OR crc.mobile    = p_mobile)
               AND (p_account_no IS NULL OR crc.account_no = p_account_no)
             ORDER BY crc.created_at DESC;
        END IF;

    ELSE
        RAISE EXCEPTION 'Invalid action: %, must be INSERT, UPDATE, DELETE, LIST, CHECKER or OPERATOR', action;
    END IF;
END;
$$;


ALTER FUNCTION public.fcard_request_cycle_feb242026(action character varying, p_request_id character varying, p_full_name character varying, p_mobile character varying, p_account_no character varying, p_request_type character varying, p_card_type character varying, p_currency_type character varying, p_card_scheme character varying, p_request_branch_id character varying, p_delivery_branch_id character varying, p_remarks text, p_status character varying, p_userid integer, p_pintype character varying) OWNER TO postgres;

--
-- Name: fcardprofilemappingcrud(character varying, character varying, character varying, character varying, character varying, date, date, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcardprofilemappingcrud(p_action character varying, p_card_profile_id character varying DEFAULT NULL::character varying, p_cardid character varying DEFAULT NULL::character varying, p_profileid character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_effective_date date DEFAULT NULL::date, p_expiry_date date DEFAULT NULL::date, p_assigned_by character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_count INTEGER;
    v_new_id VARCHAR(12);
    v_affected_rows INTEGER;
BEGIN
    -- Input validation
    IF p_action IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Action parameter is required');
    END IF;
    RAISE NOTICE 'befor insert cardid:%',p_cardid;
    -- INSERT action
    IF UPPER(p_action) = 'INSERT' THEN
        -- Check for required parameters
        IF p_cardid IS NULL OR p_profileid IS NULL OR p_effective_date IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid, profileid, and effective_date are required for INSERT');
        END IF;
        
        -- Check for duplicate active mapping
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid 
          AND profileid = p_profileid 
          AND status = 'ACTIVE';
        
        IF v_count > 0 THEN
            RETURN json_build_object('success', false, 'message', 'Active mapping already exists for this card and profile');
        END IF;
        
        -- Insert new record
        INSERT INTO public.cardprofilemapping (
            cardid,
            profileid,
            status,
            effective_date,
            expiry_date,
            assigned_by
        ) VALUES (
            p_cardid,
            p_profileid,
            COALESCE(p_status, 'ACTIVE'),
            p_effective_date,
            p_expiry_date,
            p_assigned_by
        ) RETURNING card_profile_id INTO v_new_id;
        
        RETURN json_build_object(
            'success', true,
            'message', 'Record inserted successfully',
            'card_profile_id', v_new_id
        );
    
    -- UPDATE action - Updates all fields EXCEPT cardid for given cardid
    ELSIF UPPER(p_action) = 'UPDATE' THEN
        -- UPDATE based on cardid
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for UPDATE');
        END IF;
        
        -- Check if any records exist for this cardid
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid;
        RAISE NOTICE 'select cardid:%',p_cardid;
        IF v_count = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for given cardid: ' || p_cardid);
        END IF;
        
        -- Update ALL records for this cardid (EXCLUDING cardid itself)
        UPDATE public.cardprofilemapping
        SET 
            -- DO NOT update: cardid (keep original)
            profileid = COALESCE(p_profileid, profileid),  -- Can update profileid if provided
            status = COALESCE(p_status, status),
            effective_date = COALESCE(p_effective_date, effective_date),
            expiry_date = p_expiry_date,  -- Can be set to NULL if provided
            assigned_by = COALESCE(p_assigned_by, assigned_by)
        WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        
        RETURN json_build_object(
            'success', true,
            'message', v_affected_rows || ' record(s) updated successfully for cardid: ' || p_cardid,
            'affected_rows', v_affected_rows,
            'cardid', p_cardid,
            'updated_fields', json_build_object(
                'profileid_updated', p_profileid IS NOT NULL,
                'status_updated', p_status IS NOT NULL,
                'effective_date_updated', p_effective_date IS NOT NULL,
                'expiry_date_updated', TRUE,  -- Always considered (can be NULL)
                'assigned_by_updated', p_assigned_by IS NOT NULL
            )
        );
    
    -- DELETE action (HARD DELETE) - Uses cardid only
    ELSIF UPPER(p_action) = 'DELETE' THEN
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for DELETE');
        END IF;
        
        -- Check if any records exist for this cardid
        SELECT COUNT(*) INTO v_count 
        FROM public.cardprofilemapping 
        WHERE cardid = p_cardid;
        
        IF v_count = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for this cardid: ' || p_cardid);
        END IF;
        
        -- HARD DELETE (permanent removal)
        DELETE FROM public.cardprofilemapping
        WHERE cardid = p_cardid;
          
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        
        RETURN json_build_object(
            'success', true,
            'message', v_affected_rows || ' record(s) permanently removed for cardid: ' || p_cardid,
            'affected_rows', v_affected_rows,
            'cardid', p_cardid,
            'delete_type', 'HARD_DELETE'
        );
    
    -- GET action - Uses cardid only
    ELSIF UPPER(p_action) = 'GET' THEN
        IF p_cardid IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'cardid is required for GET');
        END IF;
        
        -- Get ALL mappings for the cardid
        SELECT json_build_object(
            'success', true,
            'data', COALESCE(json_agg(row_to_json(t)), '[]'::json),
            'count', COUNT(*),
            'cardid', p_cardid
        ) INTO v_result
        FROM (
            SELECT 
                card_profile_id,
                cardid,
                profileid,
                status,
                effective_date,
                expiry_date,
                assigned_by,
                assigned_at
            FROM public.cardprofilemapping
            WHERE cardid = p_cardid
            ORDER BY assigned_at DESC
        ) t;
        
        IF v_result IS NULL OR (v_result->>'count')::INTEGER = 0 THEN
            RETURN json_build_object('success', false, 'message', 'No records found for this cardid: ' || p_cardid, 'cardid', p_cardid);
        END IF;
        
        RETURN v_result;
    
    -- LIST action (multiple records with filters)
    ELSIF UPPER(p_action) = 'LIST' THEN
        SELECT json_build_object(
            'success', true,
            'data', COALESCE(json_agg(row_to_json(t)), '[]'::json),
            'count', COUNT(*),
            'filters', json_build_object(
                'cardid', p_cardid,
                'profileid', p_profileid,
                'status', p_status,
                'effective_date', p_effective_date
            )
        ) INTO v_result
        FROM (
            SELECT 
                card_profile_id,
                cardid,
                profileid,
                status,
                effective_date,
                expiry_date,
                assigned_by,
                assigned_at
            FROM public.cardprofilemapping
            WHERE 
                (p_cardid IS NULL OR cardid = p_cardid)
                AND (p_profileid IS NULL OR profileid = p_profileid)
                AND (p_status IS NULL OR status = p_status)
                AND (p_effective_date IS NULL OR effective_date = p_effective_date)
            ORDER BY assigned_at DESC
        ) t;
        
        RETURN v_result;
    
    ELSE
        RETURN json_build_object('success', false, 'message', 'Invalid action. Use INSERT, UPDATE, DELETE, GET, or LIST');
    END IF;
    
EXCEPTION
    WHEN unique_violation THEN
        RETURN json_build_object('success', false, 'message', 'Duplicate card-profile mapping');
    WHEN foreign_key_violation THEN
        RETURN json_build_object('success', false, 'message', 'Invalid profileid - does not exist in profilemaster');
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION public.fcardprofilemappingcrud(p_action character varying, p_card_profile_id character varying, p_cardid character varying, p_profileid character varying, p_status character varying, p_effective_date date, p_expiry_date date, p_assigned_by character varying) OWNER TO postgres;

--
-- Name: fchargeconfigcrud(character varying, character varying, character varying, character varying, character varying, double precision, numeric, character varying, character varying, character varying, integer, character varying, text, boolean, boolean, date, date, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fchargeconfigcrud(p_action character varying, p_chargeid character varying DEFAULT NULL::character varying, p_chargename character varying DEFAULT NULL::character varying, p_charge_type character varying DEFAULT NULL::character varying, p_productid character varying DEFAULT NULL::character varying, p_percentage double precision DEFAULT NULL::double precision, p_amount numeric DEFAULT NULL::numeric, p_currency character varying DEFAULT 'NPR'::character varying, p_status character varying DEFAULT NULL::character varying, p_paymentmethod character varying DEFAULT NULL::character varying, p_graceperiod integer DEFAULT NULL::integer, p_applies_to character varying DEFAULT NULL::character varying, p_calculation_rule text DEFAULT NULL::text, p_istaxable boolean DEFAULT NULL::boolean, p_isactive boolean DEFAULT NULL::boolean, p_effectivedate date DEFAULT NULL::date, p_expirydate date DEFAULT NULL::date, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_chargeid VARCHAR(5);
    v_charge_count INTEGER;
    v_product_count INTEGER;
    v_return_message TEXT;
    v_validation_error TEXT;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_chargeid := TRIM(p_chargeid);
    p_chargename := TRIM(p_chargename);
    p_charge_type := UPPER(TRIM(p_charge_type));
    p_productid := TRIM(p_productid);
    p_currency := UPPER(TRIM(p_currency));
    p_status := UPPER(TRIM(p_status));
    p_paymentmethod := TRIM(p_paymentmethod);
    p_applies_to := TRIM(p_applies_to);
    p_calculation_rule := TRIM(p_calculation_rule);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'fchargeconfigCRUD called with action: ' || p_action,
        jsonb_build_object(
            'chargeid', p_chargeid,
            'chargename', p_chargename,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, SELECT, LIST_BY_PRODUCT, or LIST_ACTIVE';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_chargename IS NULL OR p_chargename = '' THEN
                RAISE EXCEPTION 'chargename is required for INSERT';
            END IF;
            
            IF p_charge_type IS NULL OR p_charge_type = '' THEN
                RAISE EXCEPTION 'charge_type is required for INSERT';
            END IF;
            
            -- Check if parent product exists (if provided)
            IF p_productid IS NOT NULL AND p_productid != '' THEN
                SELECT COUNT(*) INTO v_product_count
                FROM public.products
                WHERE productid = p_productid;
                
                IF v_product_count = 0 THEN
                    RAISE EXCEPTION 'Parent product with productid "%" does not exist', p_productid;
                END IF;
            END IF;
            
            -- Validate charge_type against allowed values
            IF p_charge_type NOT IN ('PER', 'FLAT', 'BOTH') THEN
                RAISE EXCEPTION 'Invalid charge_type. Must be PER, FLAT, or BOTH';
            END IF;
            
            -- Validate status if provided
            IF p_status IS NOT NULL AND p_status != '' THEN
                IF p_status NOT IN ('A', 'I') THEN
                    RAISE EXCEPTION 'Invalid status. Must be A (Active) or I (Inactive)';
                END IF;
            ELSE
                p_status := 'A'; -- Default to Active
            END IF;
            
            -- Validate business rules
            IF p_charge_type = 'PER' AND p_percentage IS NULL THEN
                RAISE EXCEPTION 'percentage is required for charge_type = PER';
            END IF;
            
            IF p_charge_type = 'FLAT' AND p_amount IS NULL THEN
                RAISE EXCEPTION 'amount is required for charge_type = FLAT';
            END IF;
            
            IF p_charge_type = 'BOTH' AND (p_percentage IS NULL OR p_amount IS NULL) THEN
                RAISE EXCEPTION 'Both percentage and amount are required for charge_type = BOTH';
            END IF;
            
            -- Validate dates
            IF p_effectivedate IS NOT NULL AND p_expirydate IS NOT NULL THEN
                IF p_effectivedate > p_expirydate THEN
                    RAISE EXCEPTION 'effectivedate cannot be after expirydate';
                END IF;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_charge_count
            FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            IF v_charge_count = 0 THEN
                RAISE EXCEPTION 'chargeid "%" not found', p_chargeid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(cc) INTO v_old_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            -- Check if new product exists (if provided)
            IF p_productid IS NOT NULL AND p_productid != '' THEN
                SELECT COUNT(*) INTO v_product_count
                FROM public.products
                WHERE productid = p_productid;
                
                IF v_product_count = 0 THEN
                    RAISE EXCEPTION 'Parent product with productid "%" does not exist', p_productid;
                END IF;
            END IF;
            
            -- Validate charge_type if provided
            IF p_charge_type IS NOT NULL AND p_charge_type != '' THEN
                IF p_charge_type NOT IN ('PER', 'FLAT', 'BOTH') THEN
                    RAISE EXCEPTION 'Invalid charge_type. Must be PER, FLAT, or BOTH';
                END IF;
            END IF;
            
            -- Validate status if provided
            IF p_status IS NOT NULL AND p_status != '' THEN
                IF p_status NOT IN ('A', 'I') THEN
                    RAISE EXCEPTION 'Invalid status. Must be A (Active) or I (Inactive)';
                END IF;
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_charge_count
            FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            IF v_charge_count = 0 THEN
                RAISE EXCEPTION 'chargeid "%" not found', p_chargeid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(cc) INTO v_old_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_chargeid IS NULL OR p_chargeid = '' THEN
                RAISE EXCEPTION 'chargeid is required for SELECT';
            END IF;
            
        WHEN 'LIST_BY_PRODUCT' THEN
            -- Validate LIST_BY_PRODUCT parameters
            IF p_productid IS NULL OR p_productid = '' THEN
                RAISE EXCEPTION 'productid is required for LIST_BY_PRODUCT';
            END IF;
            
            -- Check if product exists
            SELECT COUNT(*) INTO v_product_count
            FROM public.products
            WHERE productid = p_productid;
            
            IF v_product_count = 0 THEN
                RAISE EXCEPTION 'Product with productid "%" does not exist', p_productid;
            END IF;
            
        WHEN 'LIST_ACTIVE' THEN
            -- No specific validation needed
            NULL;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new charge config (DO NOT include chargeid - it will be auto-generated)
            INSERT INTO public.chargeconfig (
                chargename,
                charge_type,
                productid,
                percentage,
                amount,
                currency,
                status,
                paymentmethod,
                graceperiod,
                applies_to,
                calculation_rule,
                istaxable,
                isactive,
                effectivedate,
                expirydate
            ) VALUES (
                p_chargename,
                p_charge_type,
                NULLIF(p_productid, ''),
                p_percentage,
                p_amount,
                p_currency,
                p_status,
                NULLIF(p_paymentmethod, ''),
                p_graceperiod,
                NULLIF(p_applies_to, ''),
                NULLIF(p_calculation_rule, ''),
                COALESCE(p_istaxable, false),
                COALESCE(p_isactive, true),
                p_effectivedate,
                p_expirydate
            )
            RETURNING chargeid INTO v_existing_chargeid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = v_existing_chargeid;
            
            v_return_message := 'Charge configuration created successfully';
            v_audit_description := 'Created new charge: ' || p_chargename;
            
        WHEN 'UPDATE' THEN
            -- Update existing charge config
            UPDATE public.chargeconfig
            SET 
                chargename = COALESCE(NULLIF(p_chargename, ''), chargename),
                charge_type = COALESCE(NULLIF(p_charge_type, ''), charge_type),
                productid = COALESCE(NULLIF(p_productid, ''), productid),
                percentage = COALESCE(p_percentage, percentage),
                amount = COALESCE(p_amount, amount),
                currency = COALESCE(NULLIF(p_currency, ''), currency),
                status = COALESCE(NULLIF(p_status, ''), status),
                paymentmethod = COALESCE(NULLIF(p_paymentmethod, ''), paymentmethod),
                graceperiod = COALESCE(p_graceperiod, graceperiod),
                applies_to = COALESCE(NULLIF(p_applies_to, ''), applies_to),
                calculation_rule = COALESCE(NULLIF(p_calculation_rule, ''), calculation_rule),
                istaxable = COALESCE(p_istaxable, istaxable),
                isactive = COALESCE(p_isactive, isactive),
                effectivedate = COALESCE(p_effectivedate, effectivedate),
                expirydate = COALESCE(p_expirydate, expirydate),
                updated_date = CURRENT_TIMESTAMP
            WHERE chargeid = p_chargeid
            RETURNING chargeid INTO v_existing_chargeid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            v_return_message := 'Charge configuration updated successfully';
            v_audit_description := 'Updated charge: ' || p_chargeid || ' - ' || p_chargename;
            
        WHEN 'DELETE' THEN
            -- Delete charge config
            DELETE FROM public.chargeconfig
            WHERE chargeid = p_chargeid;
            
            v_return_message := 'Charge configuration deleted successfully';
            v_audit_description := 'Deleted charge: ' || p_chargeid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific charge config
            SELECT jsonb_build_object(
                'chargeid', cc.chargeid,
                'chargename', cc.chargename,
                'charge_type', cc.charge_type,
                'productid', cc.productid,
                'percentage', cc.percentage,
                'amount', cc.amount,
                'currency', cc.currency,
                'status', cc.status,
                'paymentmethod', cc.paymentmethod,
                'graceperiod', cc.graceperiod,
                'applies_to', cc.applies_to,
                'calculation_rule', cc.calculation_rule,
                'istaxable', cc.istaxable,
                'isactive', cc.isactive,
                'effectivedate', cc.effectivedate,
                'expirydate', cc.expirydate,
                'created_date', cc.created_date,
                'updated_date', cc.updated_date
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE chargeid = p_chargeid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Charge configuration with ID "%" not found', p_chargeid;
            END IF;
            
            v_return_message := 'Charge configuration retrieved successfully';
            v_audit_description := 'Retrieved charge: ' || p_chargeid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all charge configs
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE (p_isactive IS NULL OR cc.isactive = p_isactive)
            ORDER BY cc.chargename, cc.created_date DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Charge configurations listed successfully';
            v_audit_description := 'Listed all charge configurations';
            v_old_record := NULL;
            
        WHEN 'LIST_BY_PRODUCT' THEN
            -- Get all charges for a specific product
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE cc.productid = p_productid
            AND (p_isactive IS NULL OR cc.isactive = p_isactive)
            ORDER BY cc.charge_type, cc.chargename;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Charge configurations listed for product: ' || p_productid;
            v_audit_description := 'Listed charges for product: ' || p_productid;
            v_old_record := NULL;
            
        WHEN 'LIST_ACTIVE' THEN
            -- Get all active charge configs
            SELECT jsonb_agg(
                jsonb_build_object(
                    'chargeid', cc.chargeid,
                    'chargename', cc.chargename,
                    'charge_type', cc.charge_type,
                    'productid', cc.productid,
                    'percentage', cc.percentage,
                    'amount', cc.amount,
                    'currency', cc.currency,
                    'status', cc.status,
                    'paymentmethod', cc.paymentmethod,
                    'graceperiod', cc.graceperiod,
                    'applies_to', cc.applies_to,
                    'calculation_rule', cc.calculation_rule,
                    'istaxable', cc.istaxable,
                    'isactive', cc.isactive,
                    'effectivedate', cc.effectivedate,
                    'expirydate', cc.expirydate,
                    'created_date', cc.created_date,
                    'updated_date', cc.updated_date
                )
            ) INTO v_new_record
            FROM public.chargeconfig cc
            WHERE cc.isactive = true
            AND (cc.status IS NULL OR cc.status = 'A')
            AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
            AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            ORDER BY cc.chargename;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Active charge configurations listed successfully';
            v_audit_description := 'Listed active charges';
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST operations)
    IF p_action NOT IN ('LIST', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'CHARGECONFIG',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'chargeid', COALESCE(p_chargeid, v_existing_chargeid),
                'chargename', p_chargename
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action IN ('LIST', 'LIST_BY_PRODUCT', 'LIST_ACTIVE') THEN v_new_record
            ELSE jsonb_build_object('charge', v_new_record)
        END,
        'chargeid', COALESCE(p_chargeid, v_existing_chargeid)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN foreign_key_violation THEN
        v_error_message := 'Foreign key violation. The referenced product does not exist.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Ensure the productid exists in products table.';
        
    WHEN check_violation THEN
        v_error_message := 'Check constraint violation. Invalid charge_type or status.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Check allowed values for charge_type (PER, FLAT, BOTH) and status (A, I).';
        
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
    -- Log error to audit trail
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'CHARGECONFIG',
        'ERROR',
        'Error in fchargeconfigCRUD: ' || v_error_message,
        jsonb_build_object(
            'action', p_action,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'chargeid', p_chargeid,
            'chargename', p_chargename
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Build error response
    v_result := jsonb_build_object(
        'success', false,
        'message', 'Operation failed: ' || v_error_message,
        'error_detail', v_error_detail,
        'error_hint', v_error_hint,
        'data', null
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fchargeconfigcrud(p_action character varying, p_chargeid character varying, p_chargename character varying, p_charge_type character varying, p_productid character varying, p_percentage double precision, p_amount numeric, p_currency character varying, p_status character varying, p_paymentmethod character varying, p_graceperiod integer, p_applies_to character varying, p_calculation_rule text, p_istaxable boolean, p_isactive boolean, p_effectivedate date, p_expirydate date, p_user_id character varying, p_ip_address inet, p_user_agent text) OWNER TO postgres;

