CREATE FUNCTION public.fcreateaccountcode() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    next_val BIGINT;
    padded_val TEXT;
BEGIN
    -- Get the next value from the sequence
    next_val := nextval('s_accountcode_id_seq');

    -- Pad the numeric value to 7 digits with leading zeros and prefix with 'CUST'
    padded_val := 'ACC' || LPAD(next_val::TEXT, 8, '0');

    RETURN padded_val;
END;
$$;


