--
-- Name: fcredit_get_score_calculation_log(character varying, date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcredit_get_score_calculation_log(p_request_id character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_min_score integer DEFAULT NULL::integer, p_max_score integer DEFAULT NULL::integer) RETURNS TABLE(log_id integer, request_id character varying, assessment_id character varying, calculation_timestamp timestamp without time zone, final_score integer, dbr_percentage numeric, monthly_income numeric, suggested_limit numeric, score_breakdown jsonb, calculations jsonb, remarks text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        csc.log_id,
        csc.request_id,
        csc.assessment_id,
        csc.calculation_timestamp,
        csc.final_score,
        csc.dbr_percentage,
        csc.monthly_income,
        (csc.calculations_json->'suggested_limit_calculation'->>'base_income')::NUMERIC * 
        CASE 
            WHEN csc.final_score >= 80 THEN 0.6
            WHEN csc.final_score >= 70 THEN 0.5
            WHEN csc.final_score >= 60 THEN 0.4
            WHEN csc.final_score >= 50 THEN 0.3
            ELSE 0.2
        END as suggested_limit,
        jsonb_build_object(
            'income_score', csc.income_score,
            'employment_score', csc.employment_score,
            'debt_score', csc.debt_score,
            'education_score', csc.education_score,
            'residence_score', csc.residence_score,
            'risk_score', csc.risk_score
        ) as score_breakdown,
        csc.calculations_json as calculations,
        csc.remarks
    FROM credit_score_calculation_log csc
    WHERE (p_request_id IS NULL OR csc.request_id = p_request_id)
      AND (p_start_date IS NULL OR csc.calculation_timestamp >= p_start_date)
      AND (p_end_date IS NULL OR csc.calculation_timestamp <= p_end_date + INTERVAL '1 day')
      AND (p_min_score IS NULL OR csc.final_score >= p_min_score)
      AND (p_max_score IS NULL OR csc.final_score <= p_max_score)
    ORDER BY csc.calculation_timestamp DESC;
END;
$$;


ALTER FUNCTION public.fcredit_get_score_calculation_log(p_request_id character varying, p_start_date date, p_end_date date, p_min_score integer, p_max_score integer) OWNER TO postgres;

--
-- Name: fcredit_getrequestdetailsbybatchidforswitch(character varying, character varying[], character varying, character varying, json, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcredit_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying DEFAULT NULL::character varying, p_search_criteria json DEFAULT NULL::json, p_debug_level integer DEFAULT 0, p_page_number integer DEFAULT 1, p_page_size integer DEFAULT 100, p_include_data boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_batch_id VARCHAR(12);
    v_timestamp VARCHAR(50);
    v_record RECORD;
    v_counter INTEGER;
    v_total_records INTEGER;
    v_query TEXT;
    v_count_query TEXT;
    v_where_conditions TEXT;
    v_criteria JSON;
    v_column_name VARCHAR(100);
    v_column_value TEXT;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_result JSONB;
    v_batch_results JSONB[];
    v_batch_result JSONB;
    v_offset INTEGER;
    v_data JSONB[];
    v_row JSONB;
    v_error_context TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_execution_time_ms NUMERIC;
    v_function_name TEXT := 'fdebit_getRequestDetailsByBatchidforSwitch';
    v_json_record JSONB;
BEGIN
    -- Initialize result
    v_result := jsonb_build_object(
        'success', false,
        'timestamp', CURRENT_TIMESTAMP,
        'function_name', v_function_name,
        'action', p_action,
        'user', p_user,
        'debug_level', p_debug_level,
        'total_batches_processed', 0,
        'total_records_affected', 0,
        'execution_time_ms', 0,
        'error', NULL,
        'batches', '[]'::jsonb
    );
    
    -- Start timing
    v_start_time := clock_timestamp();
    
    -- Create timestamp for audit
    v_timestamp := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD_HH24MISS');
    
    -- Log function start at debug level 1
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'CREDIT_CARD_APPLICATIONS',
                'FUNCTION_START',
                v_function_name || ' started',
                jsonb_build_object(
                    'action', p_action,
                    'batch_ids', p_batch_ids,
                    'user', p_user,
                    'debug_level', p_debug_level,
                    'search_criteria', p_search_criteria,
                    'new_status', p_new_status,
                    'page_number', p_page_number,
                    'page_size', p_page_size,
                    'include_data', p_include_data
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    -- Calculate offset for pagination
    v_offset := (p_page_number - 1) * p_page_size;
    
    -- Initialize batch results array
    v_batch_results := ARRAY[]::JSONB[];
    
    -- Validate input parameters with error handling
    BEGIN
        IF p_action NOT IN ('SEARCH', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'Invalid action: %. Use SEARCH, UPDATE, or DELETE', p_action
            USING ERRCODE = '22000';
        END IF;
        
        IF p_batch_ids IS NULL OR array_length(p_batch_ids, 1) = 0 THEN
            RAISE EXCEPTION 'No batch IDs provided'
            USING ERRCODE = '22001';
        END IF;
        
        IF p_action = 'UPDATE' AND (p_new_status IS NULL OR p_new_status = '') THEN
            RAISE EXCEPTION 'New status is required for UPDATE action'
            USING ERRCODE = '22002';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'DEBIT_CARD_APPLICATIONS',
                'VALIDATION_ERROR',
                'Input validation failed',
                jsonb_build_object(
                    'function', v_function_name,
                    'error_message', v_error_message,
                    'error_detail', v_error_detail,
                    'error_hint', v_error_hint,
                    'sql_state', SQLSTATE
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
        
        -- Calculate execution time
        v_end_time := clock_timestamp();
        v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
        
        -- Return error result
        v_result := v_result || jsonb_build_object(
            'success', false,
            'execution_time_ms', v_execution_time_ms,
            'error', jsonb_build_object(
                'message', v_error_message,
                'detail', v_error_detail,
                'hint', v_error_hint,
                'sql_state', SQLSTATE
            )
        );
        
        RETURN v_result;
    END;
    
    -- Process each batch ID
    FOR i IN 1..array_length(p_batch_ids, 1)
    LOOP
        v_batch_id := p_batch_ids[i];
        v_counter := 0;
        v_total_records := 0;
        v_data := ARRAY[]::JSONB[];
        v_where_conditions := 'WHERE batch_id = ' || quote_literal(v_batch_id);
        
        -- Initialize batch result
        v_batch_result := jsonb_build_object(
            'batch_id', v_batch_id,
            'success', false,
            'records_affected', 0,
            'error', NULL
        );
        
        -- Log batch processing start
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'DEBIT_CARD_APPLICATIONS',
                    'BATCH_START',
                    'Processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'sequence', i
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
        
        -- Process based on action
        BEGIN
            IF p_action = 'SEARCH' THEN
                -- Build WHERE conditions for search
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        -- Handle numeric fields from debit_card_application
                        IF v_column_name IN ('dap_gros_sal1', 'dap_net_sal1', 'dap_gros_sal2', 'dap_net_sal2', 'dap_empl_age1', 'dap_empl_age2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || v_column_value;
                        -- Handle date fields
                        ELSIF v_column_name IN ('dap_date', 'dap_birt_dat1', 'dap_birt_dat2', 'dap_deci_date', 'dap_requ_effe_date', 'dap_requ_expi_date') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle boolean/character fields
                        ELSIF v_column_name IN ('dap_cus_type', 'dap_cus_old_new', 'dap_gend1', 'dap_gend2', 'dap_tit1', 'dap_tit2', 'dap_old_new_acct', 'dap_pan_gene_manu_auto', 'dap_prim_seco_card', 'dap_gree_pin_flag') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle specific identification fields
                        ELSIF v_column_name IN ('dap_cus_iden', 'dap_firs_ide1', 'dap_firs_ide2', 'dap_seco_ide1', 'dap_seco_ide2', 'dap_requ_acc_numb', 'dap_requ_card_numb') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle other text fields with case-insensitive search
                        ELSIF v_column_name IN ('dap_firs_nam1', 'dap_last_nam1', 'dap_midd_nam1', 'dap_firs_nam2', 'dap_last_nam2', 'dap_midd_nam2', 'dap_empl_nam1', 'dap_empl_nam2', 'dap_birt_loc1', 'dap_birt_loc2', 'dap_email_adr') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' ILIKE ' || quote_literal('%' || v_column_value || '%');
                        -- Handle exact match for other fields
                        ELSE
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Get total count for pagination
                v_count_query := 'SELECT COUNT(*) FROM public.credit_card_application ' || v_where_conditions;
                EXECUTE v_count_query INTO v_total_records;
                
                -- Build search query with pagination
                v_query := 'SELECT row_to_json(dca) as row_data 
                            FROM public.credit_card_application dca ' || 
                            v_where_conditions || 
                            ' ORDER BY created_at DESC ' ||
                            ' LIMIT ' || p_page_size || 
                            ' OFFSET ' || v_offset;
                
                -- Execute query and collect data
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add to data array
                    v_data := array_append(v_data, v_json_record);
                END LOOP;
                
                -- Update batch result for SEARCH
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'SEARCH',
                    'records_found', v_counter,
                    'total_records', v_total_records,
                    'pagination', jsonb_build_object(
                        'page_number', p_page_number,
                        'page_size', p_page_size,
                        'total_pages', CASE WHEN p_page_size > 0 THEN CEIL(v_total_records::NUMERIC / p_page_size) ELSE 1 END
                    )
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'data', v_data
                    );
                END IF;
                
                -- Log successful search
                IF p_debug_level >= 1 AND v_counter > 0 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'CREDIT_CARD_APPLICATIONS',
                            'SEARCH_COMPLETED',
                            'Search completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_found', v_counter,
                                'total_records', v_total_records
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'UPDATE' THEN
                -- For UPDATE, we need to update the status-related fields
                -- Since there's no statusflag column in debit_card_application,
                -- we'll update dap_deci_auth and dap_deci_date as status indicators
                
                -- Build WHERE conditions for update
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_firs_ide1' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_firs_ide1 = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_requ_acc_numb' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_requ_acc_numb = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_deci_auth' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_deci_auth = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Execute update with RETURNING clause
                v_query := 'UPDATE public.CREDIT_card_application 
                            SET dap_deci_auth = ' || quote_literal(p_new_status) || 
                           ', dap_deci_date = CURRENT_DATE' ||
                           ', updated_at = CURRENT_TIMESTAMP ' ||
                           v_where_conditions || 
                           ' RETURNING row_to_json(CREDIT_card_application.*) as row_data';
                
                -- Execute update and count affected rows
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add minimal info to data array
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'dap_firs_nam1', v_json_record->>'dap_firs_nam1',
                        'dap_last_nam1', v_json_record->>'dap_last_nam1',
                        'old_decision_auth', v_json_record->>'dap_deci_auth',
                        'new_decision_auth', p_new_status,
                        'decision_date', v_json_record->>'dap_deci_date'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Update batch result for UPDATE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'UPDATE',
                    'records_affected', v_counter,
                    'new_decision_auth', p_new_status,
                    'updated_by', p_user
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'updated_records', v_data
                    );
                END IF;
                
                -- Log successful update
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'CREDIT_CARD_APPLICATIONS',
                            'UPDATE_COMPLETED',
                            'Decision update completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_updated', v_counter,
                                'new_decision_auth', p_new_status
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'DELETE' THEN
                -- Build WHERE conditions for deletion
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_deci_auth' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_deci_auth = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- First, select records to be deleted
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT dap_iden, dap_cus_iden, dap_firs_nam1, dap_last_nam1, dap_deci_auth, dap_deci_date 
                                FROM public.CREDIT_card_application ' || 
                                v_where_conditions || 
                            ') t';
                
                FOR v_record IN EXECUTE v_query
                LOOP
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Store record info before deletion
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'dap_firs_nam1', v_json_record->>'dap_firs_nam1',
                        'dap_last_nam1', v_json_record->>'dap_last_nam1',
                        'decision_auth', v_json_record->>'dap_deci_auth',
                        'decision_date', v_json_record->>'dap_deci_date'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Execute deletion
                v_query := 'DELETE FROM public.CREDIT_card_application ' || v_where_conditions;
                EXECUTE v_query;
                GET DIAGNOSTICS v_counter = ROW_COUNT;
                
                -- Update batch result for DELETE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'DELETE',
                    'records_deleted', v_counter
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'deleted_records', v_data
                    );
                END IF;
                
                -- Log successful deletion
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'CREDIT_CARD_APPLICATIONS',
                            'DELETE_COMPLETED',
                            'Deletion completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_deleted', v_counter
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
            END IF;
            
            -- Update batch result with success
            v_batch_result := v_batch_result || jsonb_build_object(
                'records_affected', v_counter,
                'processed_at', CURRENT_TIMESTAMP
            );
            
            -- Add to batch results array
            v_batch_results := array_append(v_batch_results, v_batch_result);
            
            -- Update total records
            v_result := v_result || jsonb_build_object(
                'total_records_affected', (v_result->>'total_records_affected')::INTEGER + v_counter
            );
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS 
                v_error_message = MESSAGE_TEXT,
                v_error_detail = PG_EXCEPTION_DETAIL,
                v_error_hint = PG_EXCEPTION_HINT,
                v_error_context = PG_EXCEPTION_CONTEXT;
            
            -- Log batch error
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'CREDIT_CARD_APPLICATIONS',
                    'BATCH_ERROR',
                    'Error processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'error_message', v_error_message,
                        'error_detail', v_error_detail,
                        'error_hint', v_error_hint,
                        'error_context', v_error_context,
                        'sql_state', SQLSTATE
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            
            -- Update batch result with error
            v_batch_result := v_batch_result || jsonb_build_object(
                'success', false,
                'error', jsonb_build_object(
                    'message', v_error_message,
                    'detail', v_error_detail,
                    'hint', v_error_hint,
                    'sql_state', SQLSTATE
                )
            );
            
            v_batch_results := array_append(v_batch_results, v_batch_result);
        END;
        
        -- Log batch completion
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'DEBIT_CARD_APPLICATIONS',
                    'BATCH_COMPLETE',
                    'Completed processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'records_affected', v_counter,
                        'success', v_batch_result->>'success'
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Prepare final result
    v_result := v_result || jsonb_build_object(
        'success', true,
        'execution_time_ms', v_execution_time_ms,
        'total_batches_processed', array_length(p_batch_ids, 1),
        'batches', to_jsonb(v_batch_results)
    );
    
    -- Log function completion
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'CREDIT_CARD_APPLICATIONS',
                'FUNCTION_COMPLETE',
                v_function_name || ' completed successfully',
                jsonb_build_object(
                    'execution_time_ms', v_execution_time_ms,
                    'total_batches', array_length(p_batch_ids, 1),
                    'total_records', v_result->>'total_records_affected'
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Global exception handler
    GET STACKED DIAGNOSTICS 
        v_error_message = MESSAGE_TEXT,
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT,
        v_error_context = PG_EXCEPTION_CONTEXT;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Log global error
    BEGIN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            created_at
        ) VALUES (
            'CREDIT_CARD_APPLICATIONS',
            'FUNCTION_ERROR',
            v_function_name || ' failed',
            jsonb_build_object(
                'error_message', v_error_message,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'error_context', v_error_context,
                'sql_state', SQLSTATE,
                'execution_time_ms', v_execution_time_ms
            ),
            p_user,
            CURRENT_TIMESTAMP
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    
    -- Return error result
    v_result := v_result || jsonb_build_object(
        'success', false,
        'execution_time_ms', v_execution_time_ms,
        'error', jsonb_build_object(
            'message', v_error_message,
            'detail', v_error_detail,
            'hint', v_error_hint,
            'context', v_error_context,
            'sql_state', SQLSTATE
        )
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fcredit_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying, p_search_criteria json, p_debug_level integer, p_page_number integer, p_page_size integer, p_include_data boolean) OWNER TO postgres;

--
-- Name: fcreditcard_calculate_credit_assessment(character varying, numeric, character varying, character varying, character varying, numeric, numeric, numeric, character varying, integer, character varying, integer, character varying, character varying, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcreditcard_calculate_credit_assessment(p_request_id character varying, p_request_limit_amount numeric, p_vehicle_type character varying, p_residential_status character varying, p_occupation_type character varying, p_monthly_income numeric, p_monthly_expenditure numeric, p_existing_emi numeric, p_education_level character varying, p_other_loan_count integer, p_risk_category character varying, p_employment_years integer, p_organization_type character varying, p_calculated_by character varying, p_debug_level integer DEFAULT 0, p_limit_justification text DEFAULT NULL::text) RETURNS TABLE(assessment_id character varying, final_score integer, dbr_percentage numeric, suggested_limit numeric, status character varying, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_assessment_id VARCHAR(10);
    v_final_score INTEGER := 0;
    v_dbr_percentage NUMERIC(5,2) := 0;
    v_suggested_limit NUMERIC(15,2) := 0;
    v_net_monthly_income NUMERIC(15,2);
    v_total_monthly_obligations NUMERIC(15,2);
    
    -- Score components
    v_income_score INTEGER := 0;
    v_employment_score INTEGER := 0;
    v_debt_score INTEGER := 0;
    v_education_score INTEGER := 0;
    v_residence_score INTEGER := 0;
    v_risk_score INTEGER := 0;
    
    v_calculations_json JSONB;
    v_log_data JSONB;
    v_status VARCHAR(20) := 'Success';
    v_message TEXT := 'Credit assessment completed successfully';
    
BEGIN
    -- Log entry with debug level 1
    IF p_debug_level >= 1 THEN
        PERFORM public.flog_audit_trail(
            'CreditAssessment',
            'Start',
            'Starting credit assessment for request: ' || p_request_id,
            jsonb_build_object(
                'request_id', p_request_id,
                'debug_level', p_debug_level,
                'income', p_monthly_income,
                'requested_limit', p_request_limit_amount
            )
        );
    END IF;
    
    -- Validate required parameters
    IF p_request_id IS NULL OR p_request_id = '' THEN
        RAISE EXCEPTION 'Request ID cannot be empty';
    END IF;
    
    -- Check if request exists in creditcardcycle
    IF NOT EXISTS (SELECT 1 FROM creditcardcycle WHERE request_id = p_request_id) THEN
        RAISE EXCEPTION 'Request ID % does not exist in creditcardcycle table', p_request_id;
    END IF;
    
    -- Check if assessment already exists
    IF EXISTS (SELECT 1 FROM creditcard_credit_assessment WHERE request_id = p_request_id) THEN
        RAISE EXCEPTION 'Credit assessment already exists for request ID: %', p_request_id;
    END IF;
    
    -- ============================================
    -- CREDIT SCORING LOGIC
    -- ============================================
    
    -- 1. INCOME SCORE (Max: 25 points)
    IF p_monthly_income >= 100000 THEN
        v_income_score := 25;
    ELSIF p_monthly_income >= 75000 THEN
        v_income_score := 20;
    ELSIF p_monthly_income >= 50000 THEN
        v_income_score := 15;
    ELSIF p_monthly_income >= 30000 THEN
        v_income_score := 10;
    ELSIF p_monthly_income >= 20000 THEN
        v_income_score := 5;
    ELSE
        v_income_score := 0;
    END IF;
    
    -- 2. EMPLOYMENT SCORE (Max: 20 points)
    v_employment_score := LEAST(p_employment_years * 2, 20);  -- 2 points per year, max 20
    
    -- Add points for organization type
    CASE p_organization_type
        WHEN 'Government' THEN v_employment_score := v_employment_score + 5;
        WHEN 'MNC' THEN v_employment_score := v_employment_score + 4;
        WHEN 'Public Listed' THEN v_employment_score := v_employment_score + 3;
        WHEN 'Private Limited' THEN v_employment_score := v_employment_score + 2;
        WHEN 'Proprietorship' THEN v_employment_score := v_employment_score + 1;
        ELSE NULL;
    END CASE;
    
    v_employment_score := LEAST(v_employment_score, 25);  -- Cap at 25
    
    -- 3. DEBT SCORE (Max: 20 points) - Calculate DBR first
    -- Calculate total monthly obligations
    v_total_monthly_obligations := p_existing_emi + p_monthly_expenditure + (COALESCE(p_other_loan_count, 0) * 5000);
    
    -- Calculate DBR (Debt Burden Ratio)
    IF p_monthly_income > 0 THEN
        v_dbr_percentage := (v_total_monthly_obligations / p_monthly_income) * 100;
    ELSE
        v_dbr_percentage := 100;
    END IF;
    
    -- Assign debt score based on DBR
    IF v_dbr_percentage < 30 THEN
        v_debt_score := 20;
    ELSIF v_dbr_percentage < 40 THEN
        v_debt_score := 15;
    ELSIF v_dbr_percentage < 50 THEN
        v_debt_score := 10;
    ELSIF v_dbr_percentage < 60 THEN
        v_debt_score := 5;
    ELSE
        v_debt_score := 0;
    END IF;
    
    -- 4. EDUCATION SCORE (Max: 15 points)
    CASE p_education_level
        WHEN 'Doctorate' THEN v_education_score := 15;
        WHEN 'Post Graduate' THEN v_education_score := 12;
        WHEN 'Graduate' THEN v_education_score := 10;
        WHEN 'Diploma' THEN v_education_score := 7;
        WHEN 'Higher Secondary' THEN v_education_score := 5;
        WHEN 'Secondary' THEN v_education_score := 3;
        ELSE v_education_score := 0;
    END CASE;
    
    -- 5. RESIDENCE SCORE (Max: 10 points)
    CASE p_residential_status
        WHEN 'Own House' THEN v_residence_score := 10;
        WHEN 'Parents House' THEN v_residence_score := 8;
        WHEN 'Rented - Long Term' THEN v_residence_score := 6;
        WHEN 'Rented - Short Term' THEN v_residence_score := 4;
        WHEN 'Company Provided' THEN v_residence_score := 7;
        WHEN 'Owned' THEN v_residence_score := 10;  -- Added for your case
        ELSE v_residence_score := 3;
    END CASE;
    
    -- 6. RISK SCORE (Max: 10 points)
    CASE p_risk_category
        WHEN 'Low Risk' THEN v_risk_score := 10;
        WHEN 'Medium Risk' THEN v_risk_score := 6;
        WHEN 'High Risk' THEN v_risk_score := 2;
        WHEN 'Low' THEN v_risk_score := 10;  -- Added for your case
        ELSE v_risk_score := 0;
    END CASE;
    
    -- Deduct points for multiple loans
    IF p_other_loan_count > 0 THEN
        v_risk_score := GREATEST(v_risk_score - (p_other_loan_count * 1), 0);
    END IF;
    
    -- Add vehicle type points
    CASE p_vehicle_type
        WHEN 'Car' THEN v_risk_score := v_risk_score + 2;
        WHEN 'Two Wheeler' THEN v_risk_score := v_risk_score + 1;
        ELSE NULL;
    END CASE;
    
    v_risk_score := LEAST(v_risk_score, 10);
    
    -- ============================================
    -- CALCULATE FINAL SCORE
    -- ============================================
    v_final_score := v_income_score + v_employment_score + v_debt_score + 
                     v_education_score + v_residence_score + v_risk_score;
    
    -- Cap score between 0 and 100
    v_final_score := GREATEST(LEAST(v_final_score, 100), 0);
    
    -- ============================================
    -- CALCULATE SUGGESTED CREDIT LIMIT (FIXED)
    -- ============================================
    -- FIX: Credit limit should be based on GROSS income, not net income
    -- Standard banking practice: Credit limit = X months of gross income
    
    IF p_monthly_income > 0 THEN
        IF v_final_score >= 80 THEN
            v_suggested_limit := p_monthly_income * 6.0;  -- 6 months income for excellent score
        ELSIF v_final_score >= 70 THEN
            v_suggested_limit := p_monthly_income * 5.0;  -- 5 months income for very good
        ELSIF v_final_score >= 60 THEN
            v_suggested_limit := p_monthly_income * 4.0;  -- 4 months income for good
        ELSIF v_final_score >= 50 THEN
            v_suggested_limit := p_monthly_income * 3.0;  -- 3 months income for fair
        ELSIF v_final_score >= 40 THEN
            v_suggested_limit := p_monthly_income * 2.0;  -- 2 months income for poor
        ELSE
            v_suggested_limit := p_monthly_income * 1.0;  -- 1 month income for very poor
        END IF;
    ELSE
        v_suggested_limit := 0;
    END IF;
    
    -- Don't exceed requested limit if specified
    IF p_request_limit_amount > 0 AND p_request_limit_amount < v_suggested_limit THEN
        v_suggested_limit := p_request_limit_amount;
    END IF;
    
    -- Ensure minimum limit of ₹5,000 for any approved application
    IF v_final_score >= 40 AND v_suggested_limit < 5000 THEN
        v_suggested_limit := 5000;
    END IF;
    
    -- ============================================
    -- PREPARE CALCULATION JSON
    -- ============================================
    v_calculations_json := jsonb_build_object(
        'income_score', v_income_score,
        'employment_score', v_employment_score,
        'debt_score', v_debt_score,
        'education_score', v_education_score,
        'residence_score', v_residence_score,
        'risk_score', v_risk_score,
        'raw_score', v_final_score,
        'dbr_percentage', v_dbr_percentage,
        'net_monthly_income', p_monthly_income - v_total_monthly_obligations,
        'total_monthly_obligations', v_total_monthly_obligations,
        'suggested_limit_calculation', jsonb_build_object(
            'base_income', p_monthly_income,
            'score_based_multiplier', CASE 
                WHEN v_final_score >= 80 THEN '6.0'
                WHEN v_final_score >= 70 THEN '5.0'
                WHEN v_final_score >= 60 THEN '4.0'
                WHEN v_final_score >= 50 THEN '3.0'
                WHEN v_final_score >= 40 THEN '2.0'
                ELSE '1.0'
            END,
            'requested_limit', p_request_limit_amount,
            'calculated_limit_before_cap', CASE 
                WHEN v_final_score >= 80 THEN p_monthly_income * 6.0
                WHEN v_final_score >= 70 THEN p_monthly_income * 5.0
                WHEN v_final_score >= 60 THEN p_monthly_income * 4.0
                WHEN v_final_score >= 50 THEN p_monthly_income * 3.0
                WHEN v_final_score >= 40 THEN p_monthly_income * 2.0
                ELSE p_monthly_income * 1.0
            END
        )
    );
    v_assessment_id := fCreateAssessmentCode();
    -- ============================================
    -- LOG CALCULATION DETAILS
    -- ============================================
    INSERT INTO credit_score_calculation_log (
        request_id,
        debug_level,
        request_limit_amount,
        vehicle_type,
        residential_status,
        occupation_type,
        monthly_income,
        monthly_expenditure,
        existing_emi,
        education_level,
        other_loan_count,
        risk_category,
        employment_years,
        organization_type,
        raw_score,
        adjusted_score,
        final_score,
        dbr_percentage,
        income_score,
        employment_score,
        debt_score,
        education_score,
        residence_score,
        risk_score,
        calculations_json,
        remarks,
		assessment_id
    ) VALUES (
        p_request_id,
        p_debug_level,
        p_request_limit_amount,
        p_vehicle_type,
        p_residential_status,
        p_occupation_type,
        p_monthly_income,
        p_monthly_expenditure,
        p_existing_emi,
        p_education_level,
        p_other_loan_count,
        p_risk_category,
        p_employment_years,
        p_organization_type,
        v_final_score,
        v_final_score,  -- For now, same as raw score
        v_final_score,
        v_dbr_percentage,
        v_income_score,
        v_employment_score,
        v_debt_score,
        v_education_score,
        v_residence_score,
        v_risk_score,
        v_calculations_json,
        COALESCE(p_limit_justification, 'Auto-calculated by credit assessment function'),
		v_assessment_id
    );
    -- RETURNING log_id INTO v_log_data;
    
    -- ============================================
    -- INSERT INTO CREDIT ASSESSMENT TABLE
    -- ============================================
    -- Generate assessment ID using existing function
    
    
    INSERT INTO creditcard_credit_assessment (
        assessment_id,
        request_id,
        applicant_score,
        dbr_percentage,
        monthly_income,
        monthly_expenditure,
        existing_monthly_emi,
        suggested_limit, 
        limit_justification,
        calculated_by,
        requested_limit
    ) VALUES (
        v_assessment_id,
        p_request_id,
        v_final_score,
        v_dbr_percentage,
        p_monthly_income,
        p_monthly_expenditure,
        p_existing_emi,
        v_suggested_limit, 
        COALESCE(p_limit_justification, 
            'Score: ' || v_final_score || 
            ', DBR: ' || ROUND(v_dbr_percentage, 2) || '%' ||
            ', Income Multiplier: ' || CASE 
                WHEN v_final_score >= 80 THEN '6.0'
                WHEN v_final_score >= 70 THEN '5.0'
                WHEN v_final_score >= 60 THEN '4.0'
                WHEN v_final_score >= 50 THEN '3.0'
                WHEN v_final_score >= 40 THEN '2.0'
                ELSE '1.0'
            END || ' months' ||
            ', Suggested Limit: ₹' || ROUND(v_suggested_limit, 2)),
        p_calculated_by,
        p_request_limit_amount
    );
    
    -- ============================================
    -- AUDIT LOGGING
    -- ============================================
    IF p_debug_level >= 2 THEN
        PERFORM public.flog_audit_trail(
            'CreditAssessment',
            'Calculation',
            'Credit score calculated for request: ' || p_request_id,
            jsonb_build_object(
                'request_id', p_request_id,
                'assessment_id', v_assessment_id,
                'final_score', v_final_score,
                'dbr_percentage', v_dbr_percentage,
                'suggested_limit', v_suggested_limit,
                'score_breakdown', jsonb_build_object(
                    'income', v_income_score,
                    'employment', v_employment_score,
                    'debt', v_debt_score,
                    'education', v_education_score,
                    'residence', v_residence_score,
                    'risk', v_risk_score
                )
            )
        );
    END IF;
    
    IF p_debug_level >= 3 THEN
        PERFORM public.flog_audit_trail(
            'CreditAssessment',
            'Details',
            'Detailed calculation for request: ' || p_request_id,
            v_calculations_json
        );
    END IF;
    
    IF p_debug_level >= 1 THEN
        PERFORM public.flog_audit_trail(
            'CreditAssessment',
            'Complete',
            'Credit assessment completed for request: ' || p_request_id,
            jsonb_build_object(
                'request_id', p_request_id,
                'assessment_id', v_assessment_id,
                'status', 'SUCCESS',
                'final_score', v_final_score,
                'suggested_limit', v_suggested_limit,
                'income_multiplier', CASE 
                    WHEN v_final_score >= 80 THEN '6.0'
                    WHEN v_final_score >= 70 THEN '5.0'
                    WHEN v_final_score >= 60 THEN '4.0'
                    WHEN v_final_score >= 50 THEN '3.0'
                    WHEN v_final_score >= 40 THEN '2.0'
                    ELSE '1.0'
                END
            )
        );
    END IF;
    
    -- ============================================
    -- RETURN RESULTS
    -- ============================================
    RETURN QUERY SELECT 
        v_assessment_id,
        v_final_score,
        v_dbr_percentage,
        v_suggested_limit,
        v_status,
        v_message;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Log error
        v_status := 'Error';
        v_message := SQLERRM;
        
        IF p_debug_level >= 0 THEN
            PERFORM public.flog_audit_trail(
                'CreditAssessment',
                'Error',
                'Error in credit assessment for request: ' || p_request_id || ' - ' || SQLERRM,
                jsonb_build_object(
                    'request_id', p_request_id,
                    'error_message', SQLERRM,
                    'error_state', SQLSTATE
                )
            );
        END IF;
        
        -- Insert error log
        INSERT INTO credit_score_calculation_log (
            request_id,
            debug_level,
            final_score,
            dbr_percentage,
            calculations_json,
            remarks
        ) VALUES (
            p_request_id,
            p_debug_level,
            0,
            0,
            jsonb_build_object('error', SQLERRM, 'state', SQLSTATE),
            'ERROR: ' || SQLERRM
        );
        
        -- Return error
        RETURN QUERY SELECT 
            NULL::VARCHAR(10),
            0,
            0.0,
            0.0,
            v_status,
            v_message;
END;
$$;


ALTER FUNCTION public.fcreditcard_calculate_credit_assessment(p_request_id character varying, p_request_limit_amount numeric, p_vehicle_type character varying, p_residential_status character varying, p_occupation_type character varying, p_monthly_income numeric, p_monthly_expenditure numeric, p_existing_emi numeric, p_education_level character varying, p_other_loan_count integer, p_risk_category character varying, p_employment_years integer, p_organization_type character varying, p_calculated_by character varying, p_debug_level integer, p_limit_justification text) OWNER TO postgres;

--
-- Name: fcreditcard_cycle(character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, bit, bit, numeric, character varying, character varying, character varying, numeric, numeric, numeric, character varying, integer, character varying, integer, character varying, character varying, text, jsonb, character varying, jsonb, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcreditcard_cycle(p_action character varying, p_debug_level integer DEFAULT 0, p_full_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_account_no character varying DEFAULT NULL::character varying, p_request_type character varying DEFAULT NULL::character varying, p_card_type character varying DEFAULT NULL::character varying, p_currency_type character varying DEFAULT NULL::character varying, p_card_scheme character varying DEFAULT NULL::character varying, p_request_branch_id character varying DEFAULT NULL::character varying, p_delivery_branch_id character varying DEFAULT NULL::character varying, p_customer_branch_id character varying DEFAULT NULL::character varying, p_customer_branch_code character varying DEFAULT NULL::character varying, p_account_type character varying DEFAULT NULL::character varying, p_instcode character varying DEFAULT NULL::character varying, p_remarks text DEFAULT NULL::text, p_requstor_branch_code character varying DEFAULT NULL::character varying, p_receiver_branch_code character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_document_remarks character varying DEFAULT NULL::character varying, p_limitapproval_remarks character varying DEFAULT NULL::character varying, p_forwarddoc bit DEFAULT NULL::"bit", p_forwardapproval bit DEFAULT NULL::"bit", p_request_limit_amount numeric DEFAULT NULL::numeric, p_vehicle_type character varying DEFAULT NULL::character varying, p_residential_status character varying DEFAULT NULL::character varying, p_occupation_type character varying DEFAULT NULL::character varying, p_monthly_income numeric DEFAULT NULL::numeric, p_monthly_expenditure numeric DEFAULT NULL::numeric, p_existing_emi numeric DEFAULT NULL::numeric, p_education_level character varying DEFAULT NULL::character varying, p_other_loan_count integer DEFAULT NULL::integer, p_risk_category character varying DEFAULT NULL::character varying, p_employment_years integer DEFAULT NULL::integer, p_organization_type character varying DEFAULT NULL::character varying, p_calculated_by character varying DEFAULT NULL::character varying, p_limit_justification text DEFAULT NULL::text, p_documents jsonb DEFAULT NULL::jsonb, p_request_id character varying DEFAULT NULL::character varying, p_search_criteria jsonb DEFAULT NULL::jsonb, p_userid integer DEFAULT NULL::integer, p_status character varying DEFAULT NULL::character varying, OUT result_status character varying, OUT result_message text, OUT result_data jsonb) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_request_id VARCHAR(12);
    v_assessment_id VARCHAR(10);
    v_final_score INTEGER;
    v_dbr_percentage NUMERIC;
    v_suggested_limit NUMERIC;
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTEGER;
    v_document_count INTEGER := 0;
    v_old_data JSONB;
    v_new_data JSONB;
    v_rows_affected INTEGER := 0;
    v_log_id BIGINT;
    
    -- SIMPLE STATUS VARIABLES
    v_current_status VARCHAR(100);
    v_new_composed_status VARCHAR(100);
    v_forwarddoc_current BIT;
    v_forwardapproval_current BIT;
    v_current_parts TEXT[];
    v_result_parts TEXT[];
    v_initial_status VARCHAR(100);
    v_has_docs_verified BOOLEAN := FALSE;
    v_has_assess_verified BOOLEAN := FALSE;
    v_has_docs_pending BOOLEAN := FALSE;
    v_has_assess_pending BOOLEAN := FALSE;
    v_temp_part VARCHAR(100);
    v_current_status_upper VARCHAR(100);
    
    -- CROSS-BRANCH ACCESS VARIABLES
    v_user_branchcode VARCHAR(10);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_access_message TEXT;
    v_app_branch_code VARCHAR(10);
    v_has_access BOOLEAN := FALSE;
    v_username VARCHAR(100);  -- For storing username internally
    
    -- Variables for card/PIN status composition
    v_new_status VARCHAR(30);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    v_pintype_from_db VARCHAR(15);
BEGIN
    -- Initialize result
    result_status := 'ERROR';
    result_message := 'Action not completed';
    result_data := '{}'::JSONB;
    
    -- ============================================
    -- GET USER BRANCH ACCESS INFORMATION
    -- ============================================
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        BEGIN
            -- Get user branch info (using p_userid as INTEGER)
            SELECT 
                b.branch_no,
                COALESCE(u.crossbranch, FALSE),
                al.username
            INTO 
                v_user_branchcode,
                v_user_crossbranch,
                v_username
            FROM users u
            LEFT JOIN branch b ON b.id = u.branchid
            LEFT JOIN authlogin al ON al.userid = u.id
            WHERE u.id = p_userid  -- Using integer comparison
            LIMIT 1;
            
            -- If user not found, set defaults
            IF NOT FOUND THEN
                v_user_branchcode := NULL;
                v_user_crossbranch := FALSE;
                v_username := 'Unknown_User_' || p_userid::text;
            END IF;
            
            -- Set access message
            IF v_user_crossbranch THEN
                v_user_access_message := 'Cross-branch access: FULL';
            ELSE
                v_user_access_message := 'Branch-restricted access: ' || COALESCE(v_user_branchcode, 'Not assigned');
            END IF;
            
            IF p_debug_level >= 2 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'USER_ACCESS_INFO',
                    'User access determined',
                    jsonb_build_object(
                        'user_id', p_userid,
                        'username', v_username,
                        'user_branch', v_user_branchcode,
                        'crossbranch', v_user_crossbranch,
                        'access_message', v_user_access_message,
                        'action', p_action
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            -- If error getting user info, set defaults
            v_user_branchcode := NULL;
            v_user_crossbranch := FALSE;
            v_username := 'Error_User_' || p_userid::text;
            v_user_access_message := 'Access info unavailable: ' || SQLERRM;
            
            IF p_debug_level >= 1 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'USER_INFO_ERROR',
                    'Error getting user branch info',
                    jsonb_build_object(
                        'error', SQLERRM,
                        'user_id', p_userid,
                        'action', p_action
                    )
                );
            END IF;
        END;
    ELSE
        -- No user ID provided
        v_user_branchcode := NULL;
        v_user_crossbranch := FALSE;
        v_username := 'Anonymous_User';
        v_user_access_message := 'No user ID provided - restricted access';
    END IF;
    
    -- Log start of operation
    IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
        PERFORM public.flog_audit_trail(
            'CREDITCARD_MAIN',
            'START_' || p_action,
            'Starting ' || p_action || ' operation',
            jsonb_build_object(
                'action', p_action,
                'debug_level', p_debug_level,
                'has_request_id', p_request_id IS NOT NULL,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'access_message', v_user_access_message
            )
        );
    END IF;
    
    -- Validate action
    IF p_action NOT IN ('INSERT', 'UPDATE', 'SEARCH', 'DELETE') THEN
        result_message := 'Invalid action specified. Must be INSERT, UPDATE, SEARCH, or DELETE';
        RETURN;
    END IF;
    
    -- ============================================
    -- HANDLE INSERT ACTION (NO BRANCH RESTRICTION)
    -- ============================================
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Debug: Log all incoming parameters
            IF p_debug_level >= 2 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'DEBUG_PARAMS',
                    'Checking assessment parameters',
                    jsonb_build_object(
                        'p_monthly_income', p_monthly_income,
                        'p_calculated_by', p_calculated_by,
                        'income_is_null', p_monthly_income IS NULL,
                        'calculated_by_is_null', p_calculated_by IS NULL,
                        'assessment_condition', (p_monthly_income IS NOT NULL AND p_calculated_by IS NOT NULL),
                        'user_id', p_userid,
                        'username', v_username,
                        'user_branch', v_user_branchcode
                    )
                );
            END IF;
            
            -- Validate required parameters for INSERT
            IF p_full_name IS NULL OR p_request_type IS NULL OR 
               p_card_type IS NULL OR p_currency_type IS NULL OR 
               p_card_scheme IS NULL OR p_request_branch_id IS NULL OR
               p_delivery_branch_id IS NULL OR p_customer_branch_id IS NULL OR
               p_customer_branch_code IS NULL OR p_account_type IS NULL OR
               p_instcode IS NULL OR p_pintype IS NULL THEN
                
                result_message := 'Missing required parameters for credit card application';
                RETURN;
            END IF;
            
            -- DETERMINE INITIAL STATUS BASED ON FLAGS
            v_initial_status := CASE 
                WHEN p_forwarddoc = '1' AND p_forwardapproval = '1' THEN 
                    'DOCS & ASSESS PENDING'
                WHEN p_forwarddoc = '1' THEN 
                    'DOCS PENDING'
                WHEN p_forwardapproval = '1' THEN 
                    'ASSESS PENDING'
                ELSE 
                    'PENDING'
            END;
            
            -- ============================================
            -- 1. INSERT INTO CREDITCARDCYCLE (MAIN TABLE)
            -- ============================================
            INSERT INTO public.creditcardcycle (
                full_name,
                mobile,
                account_no,
                request_type,
                card_type,
                currency_type,
                card_scheme,
                request_branch_id,
                delivery_branch_id,
                customer_branch_id,
                customer_branch_code,
                account_type,
                instcode,
                remarks,
                requstor_branch_code,
                receiver_branch_code,
                pintype,
                document_remarks,
                limitapproval_remarks,
                forwarddoc,
                forwardapproval,
                status,
                requested_limit
            ) VALUES (
                p_full_name,
                p_mobile,
                p_account_no,
                p_request_type,
                p_card_type,
                p_currency_type,
                p_card_scheme,
                p_request_branch_id,
                p_delivery_branch_id,
                p_customer_branch_id,
                p_customer_branch_code,
                p_account_type,
                p_instcode,
                p_remarks,
                p_requstor_branch_code,
                p_receiver_branch_code,
                p_pintype,
                p_document_remarks,
                p_limitapproval_remarks,
                p_forwarddoc,
                p_forwardapproval,
                v_initial_status,
                p_request_limit_amount
            )
            RETURNING request_id INTO v_request_id;
            
            v_rows_affected := v_rows_affected + 1;
            
            IF p_debug_level >= 2 and p_action != 'SEARCH' THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'INSERT_CYCLE',
                    'Inserted into creditcardcycle',
                    jsonb_build_object(
                        'request_id', v_request_id,
                        'full_name', p_full_name,
                        'card_type', p_card_type,
                        'initial_status', v_initial_status,
                        'forwarddoc', p_forwarddoc,
                        'forwardapproval', p_forwardapproval,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_branch', v_user_branchcode
                    )
                );
            END IF;
            
            -- ============================================
            -- 2. INSERT DOCUMENTS (IF PROVIDED)
            -- ============================================
            IF p_documents IS NOT NULL AND jsonb_array_length(p_documents) > 0 THEN
                INSERT INTO public.creditcard_documents (
                    request_id,
                    document_type,
                    url_file_name,
                    uploaded_by,
                    status
                )
                SELECT 
                    v_request_id,
                    doc->>'document_type',
                    doc->>'url_file_name',
                    COALESCE(doc->>'uploaded_by', v_username),  -- Use v_username instead of p_userid
                    COALESCE(doc->>'status', 'Pending')
                FROM jsonb_array_elements(p_documents) AS doc;
                
                GET DIAGNOSTICS v_document_count = ROW_COUNT;
                v_rows_affected := v_rows_affected + v_document_count;
                
                IF p_debug_level >= 2 and p_action != 'SEARCH' THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'INSERT_DOCUMENTS',
                        'Inserted documents for request',
                        jsonb_build_object(
                            'request_id', v_request_id,
                            'document_count', v_document_count,
                            'user_id', p_userid,
                            'username', v_username
                        )
                    );
                END IF;
            END IF;
            
            -- ============================================
            -- 3. PERFORM CREDIT ASSESSMENT (IF PARAMETERS PROVIDED)
            -- ============================================
            -- Check if BOTH required assessment parameters are provided
            IF p_monthly_income IS NOT NULL AND p_calculated_by IS NOT NULL THEN
                
                IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'ASSESSMENT_CONDITION_MET',
                        'Assessment parameters provided - proceeding',
                        jsonb_build_object(
                            'request_id', v_request_id,
                            'monthly_income', p_monthly_income,
                            'calculated_by', p_calculated_by,
                            'user_id', p_userid,
                            'username', v_username
                        )
                    );
                END IF;
                
                -- Call the credit assessment function
                SELECT assessment_id, final_score, dbr_percentage, suggested_limit
                INTO v_assessment_id, v_final_score, v_dbr_percentage, v_suggested_limit
                FROM fcreditcard_calculate_credit_assessment(
                    p_request_id := v_request_id,
                    p_request_limit_amount := COALESCE(p_request_limit_amount, 0),
                    p_vehicle_type := p_vehicle_type,
                    p_residential_status := p_residential_status,
                    p_occupation_type := p_occupation_type,
                    p_monthly_income := p_monthly_income,
                    p_monthly_expenditure := COALESCE(p_monthly_expenditure, 0),
                    p_existing_emi := COALESCE(p_existing_emi, 0),
                    p_education_level := p_education_level,
                    p_other_loan_count := COALESCE(p_other_loan_count, 0),
                    p_risk_category := p_risk_category,
                    p_employment_years := COALESCE(p_employment_years, 0),
                    p_organization_type := p_organization_type,
                    p_calculated_by := p_calculated_by,
                    p_debug_level := p_debug_level,
                    p_limit_justification := p_limit_justification
                );
                
                IF v_assessment_id IS NOT NULL THEN
                    v_rows_affected := v_rows_affected + 1;
                    
                    IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                        PERFORM public.flog_audit_trail(
                            'CREDITCARD_MAIN',
                            'ASSESSMENT_CREATED',
                            'Credit assessment created successfully',
                            jsonb_build_object(
                                'request_id', v_request_id,
                                'assessment_id', v_assessment_id,
                                'final_score', v_final_score,
                                'dbr_percentage', v_dbr_percentage,
                                'suggested_limit', v_suggested_limit,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        );
                    END IF;
                ELSE
                    IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                        PERFORM public.flog_audit_trail(
                            'CREDITCARD_MAIN',
                            'ASSESSMENT_NULL',
                            'Assessment function returned NULL',
                            jsonb_build_object(
                                'request_id', v_request_id,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        );
                    END IF;
                END IF;
                
            ELSE
                -- Log why assessment wasn't performed
                IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'NO_ASSESSMENT_REASON',
                        'Assessment not performed - missing parameters',
                        jsonb_build_object(
                            'request_id', v_request_id,
                            'missing_monthly_income', p_monthly_income IS NULL,
                            'missing_calculated_by', p_calculated_by IS NULL,
                            'monthly_income_value', p_monthly_income,
                            'calculated_by_value', p_calculated_by,
                            'user_id', p_userid,
                            'username', v_username
                        )
                    );
                END IF;
            END IF;
            
            -- ============================================
            -- PREPARE SUCCESS RESPONSE
            -- ============================================
            result_status := 'SUCCESS';
            result_message := 'Credit card application created successfully';
            result_data := jsonb_build_object(
                'request_id', v_request_id,
                'assessment_id', v_assessment_id,
                'assessment_details', CASE 
                    WHEN v_assessment_id IS NOT NULL THEN
                        jsonb_build_object(
                            'final_score', v_final_score,
                            'dbr_percentage', v_dbr_percentage,
                            'suggested_limit', v_suggested_limit
                        )
                    ELSE NULL
                END,
                'document_count', v_document_count,
                'application_status', v_initial_status,
                'created_at', (SELECT created_at FROM creditcardcycle WHERE request_id = v_request_id),
                'assessment_performed', v_assessment_id IS NOT NULL,
                'assessment_params_provided', (p_monthly_income IS NOT NULL AND p_calculated_by IS NOT NULL),
                'next_steps', CASE 
                    WHEN v_document_count = 0 THEN 'Upload supporting documents'
                    WHEN v_assessment_id IS NULL THEN 'Complete credit assessment'
                    ELSE 'Application is ready for review'
                END,
                'user_access_info', v_user_access_message,
                'created_by', jsonb_build_object(
                    'user_id', p_userid,
                    'username', v_username,
                    'branch', v_user_branchcode
                )
            );
            
            IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'INSERT_SUCCESS',
                    'Application created successfully',
                    jsonb_build_object(
                        'request_id', v_request_id,
                        'status', result_status,
                        'assessment_id', v_assessment_id,
                        'assessment_performed', v_assessment_id IS NOT NULL,
                        'initial_application_status', v_initial_status,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_access', v_user_access_message
                    )
                );
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                result_message := 'Failed to create application: ' || SQLERRM;
                
                IF p_debug_level >= 0 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'INSERT_ERROR',
                        'Error creating application: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'error_state', SQLSTATE,
                            'parameters', jsonb_build_object(
                                'full_name', p_full_name,
                                'request_type', p_request_type,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        )
                    );
                END IF;
                
                RETURN;
        END;
    
    -- ============================================
    -- HANDLE UPDATE ACTION (WITH BRANCH ACCESS CHECK)
    -- ============================================
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            -- Validate required parameters for UPDATE
            IF p_request_id IS NULL THEN
                result_message := 'Request ID is required for UPDATE action';
                RETURN;
            END IF;
            
            -- Check if application exists
            IF NOT EXISTS (SELECT 1 FROM creditcardcycle WHERE request_id = p_request_id) THEN
                result_message := 'Application not found for update. Request ID: ' || p_request_id;
                RETURN;
            END IF;
            
            -- ============================================
            -- CROSS-BRANCH ACCESS CHECK FOR UPDATE
            -- ============================================
            -- Get the application's branch code
            SELECT customer_branch_code INTO v_app_branch_code
            FROM creditcardcycle 
            WHERE request_id = p_request_id;
            
            -- Check if user has access to this application
            v_has_access := FALSE;
            
            IF v_user_crossbranch THEN
                -- User has cross-branch access, allow update
                v_has_access := TRUE;
            ELSIF v_user_branchcode IS NOT NULL AND v_app_branch_code IS NOT NULL 
                  AND v_user_branchcode = v_app_branch_code THEN
                -- User is from the same branch as the application
                v_has_access := TRUE;
            ELSE
                -- User doesn't have access
                v_has_access := FALSE;
                result_message := 'Access denied. You do not have permission to update this application. ' ||
                                'Application belongs to branch: ' || COALESCE(v_app_branch_code, 'Unknown') ||
                                ', Your branch: ' || COALESCE(v_user_branchcode, 'Not assigned');
                result_status := 'ACCESS_DENIED';
                
                IF p_debug_level >= 1 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'UPDATE_ACCESS_DENIED',
                        'User denied access to update application',
                        jsonb_build_object(
                            'request_id', p_request_id,
                            'user_id', p_userid,
                            'username', v_username,
                            'user_branch', v_user_branchcode,
                            'app_branch', v_app_branch_code,
                            'crossbranch_access', v_user_crossbranch,
                            'access_message', v_user_access_message,
                            'reason', 'Branch access mismatch'
                        )
                    );
                END IF;
                
                RETURN;
            END IF;
            
            -- Log access granted
            IF p_debug_level >= 2 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'UPDATE_ACCESS_GRANTED',
                    'User granted access to update application',
                    jsonb_build_object(
                        'request_id', p_request_id,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_branch', v_user_branchcode,
                        'app_branch', v_app_branch_code,
                        'crossbranch_access', v_user_crossbranch,
                        'access_message', v_user_access_message
                    )
                );
            END IF;
            
            -- Get old data for logging
            SELECT to_jsonb(cc.*) INTO v_old_data
            FROM creditcardcycle cc
            WHERE cc.request_id = p_request_id;
            
            -- Get current status, flags, and pintype
            SELECT status, forwarddoc, forwardapproval, pintype 
            INTO v_current_status, v_forwarddoc_current, v_forwardapproval_current, v_pintype_from_db
            FROM creditcardcycle 
            WHERE request_id = p_request_id;
            
            -- ============================================
            -- ENHANCED STATUS COMPOSITION LOGIC
            -- ============================================
            v_new_composed_status := v_current_status;
            
            -- Only process if new status is provided and different
            IF p_status IS NOT NULL AND TRIM(p_status) != TRIM(v_current_status) THEN
                
                -- Convert current status to uppercase for consistent checking
                v_current_status_upper := UPPER(v_current_status);
                
                -- Check for various pending and verified states (using LIKE for pattern matching)
                -- Check DOCS status
                v_has_docs_pending := 
                    v_current_status_upper LIKE '%DOCS%PENDING%' OR
                    v_current_status_upper = 'DOCS PENDING' OR
                    v_current_status_upper = 'DOCS & ASSESS PENDING' OR
                    v_current_status_upper = 'DOCS PENDING & ASSESS VERIFIED';
                
                v_has_docs_verified := 
                    v_current_status_upper LIKE '%DOCS%VERIFIED%' OR
                    v_current_status_upper = 'DOCS VERIFIED' OR
                    v_current_status_upper = 'DOCS & ASSESS VERIFIED' OR
                    v_current_status_upper = 'DOCS VERIFIED & ASSESS PENDING';
                
                -- Check ASSESS status
                v_has_assess_pending := 
                    v_current_status_upper LIKE '%ASSESS%PENDING%' OR
                    v_current_status_upper = 'ASSESS PENDING' OR
                    v_current_status_upper = 'DOCS & ASSESS PENDING' OR
                    v_current_status_upper = 'DOCS VERIFIED & ASSESS PENDING';
                
                v_has_assess_verified := 
                    v_current_status_upper LIKE '%ASSESS%VERIFIED%' OR
                    v_current_status_upper = 'ASSESS VERIFIED' OR
                    v_current_status_upper = 'DOCS & ASSESS VERIFIED' OR
                    v_current_status_upper = 'DOCS PENDING & ASSESS VERIFIED';
                
                -- Initialize v_new_status with the requested status
                v_new_status := p_status;
                
                -- STATUS COMPOSITION LOGIC FOR CARD/PIN RELATED STATUSES
                -- Only apply composition logic for card/PIN related statuses
                IF UPPER(p_status) IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    
                    -- Skip PIN DISPATCH if pintype is GREEN-PIN or GREEN
                    IF UPPER(p_status) = 'PIN DISPATCH' AND 
                       (UPPER(v_pintype_from_db) = 'GREEN-PIN' OR UPPER(v_pintype_from_db) = 'GREEN') THEN
                        result_message := 'PIN DISPATCH not required for ' || v_pintype_from_db || ' pintype';
                        result_status := 'VALIDATION_ERROR';
                        RETURN;
                    END IF;
                    
                    -- Skip PIN ACK if pintype is GREEN-PIN or GREEN
                    IF UPPER(p_status) = 'PIN ACK' AND 
                       (UPPER(v_pintype_from_db) = 'GREEN-PIN' OR UPPER(v_pintype_from_db) = 'GREEN') THEN
                        result_message := 'PIN ACK not required for ' || v_pintype_from_db || ' pintype';
                        result_status := 'VALIDATION_ERROR';
                        RETURN;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                            -- Handle abbreviated forms: "CARD" means "CARD DISPATCH"
                            IF v_current_card_part = 'CARD' THEN
                                v_current_card_part := 'CARD DISPATCH';
                            END IF;
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                            -- Handle abbreviated forms: "PIN" means "PIN DISPATCH"
                            IF v_current_pin_part = 'PIN' THEN
                                v_current_pin_part := 'PIN DISPATCH';
                            END IF;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF UPPER(p_status) = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        -- Current status is not combined, need to create combination if needed
                        IF UPPER(p_status) = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF UPPER(p_status) = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    -- Special handling: When CARD DISPATCH & PIN ACK, setting CARD ACK should become CARD & PIN ACK
                    IF UPPER(p_status) = 'CARD ACK' AND v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                        v_new_status := 'CARD & PIN ACK';
                    END IF;
                    
                    -- Special handling: When CARD ACK & PIN DISPATCH, setting PIN ACK should become CARD & PIN ACK
                    IF UPPER(p_status) = 'PIN ACK' AND v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                        v_new_status := 'CARD & PIN ACK';
                    END IF;
                    
                    -- For GREEN-PIN or GREEN pintype, automatically skip PIN statuses and go directly to final state
                    IF (UPPER(v_pintype_from_db) = 'GREEN-PIN' OR UPPER(v_pintype_from_db) = 'GREEN') THEN
                        IF UPPER(p_status) = 'CARD ACK' THEN
                            -- For GREEN-PIN/GREEN, CARD ACK should be the final state
                            v_new_status := 'CARD ACK';
                        END IF;
                    END IF;
                    
                ELSIF UPPER(p_status) = 'VERIFIED' THEN
                    -- Check prerequisites based on flags
                    IF v_forwarddoc_current = '1' AND NOT v_has_docs_verified THEN
                        result_message := 'Documents not verified yet. Current status: ' || v_current_status;
                        RETURN;
                    END IF;
                    
                    IF v_forwardapproval_current = '1' AND NOT v_has_assess_verified THEN
                        result_message := 'Assessment not verified yet. Current status: ' || v_current_status;
                        RETURN;
                    END IF;
                    
                    -- If both flags are on and both are verified, we have "DOC & ASSESS VERIFIED"
                    -- In this case, we can move to "VERIFIED"
                    IF v_has_docs_verified AND v_has_assess_verified THEN
                        v_new_status := 'VERIFIED';
                    ELSE
                        -- If only one is required or none, just set to VERIFIED
                        v_new_status := 'VERIFIED';
                    END IF;
                    
                ELSIF UPPER(p_status) = 'COMPLETED' THEN
                    -- For GREEN-PIN or GREEN pintype, only need CARD ACK
                    IF UPPER(v_pintype_from_db) = 'GREEN-PIN' OR UPPER(v_pintype_from_db) = 'GREEN' THEN
                        IF v_current_status != 'CARD ACK' THEN
                            result_message := 'For ' || v_pintype_from_db || ' pintype, card must be acknowledged before completion. Current status: ' || v_current_status;
                            RETURN;
                        END IF;
                        v_new_status := 'CARD ACK';
                    ELSE
	                        -- For other pintypes, need both CARD and PIN ACK
	                        IF v_current_status != 'CARD & PIN ACK' THEN
	                            result_message := 'Both card and PIN must be acknowledged before completion. Current status: ' || v_current_status;
	                            RETURN;
	                        END IF;
							IF UPPER(p_status) = 'CARD ACK' AND v_current_status = 'CARD DISPATCH & PIN ACK' THEN
							    v_new_status := 'CARD & PIN ACK';
							END IF;
	
							-- Special handling: When CARD ACK & PIN DISPATCH, setting PIN ACK should become CARD & PIN ACK
							IF UPPER(p_status) = 'PIN ACK' AND v_current_status = 'CARD ACK & PIN DISPATCH' THEN
							    v_new_status := 'CARD & PIN ACK';
							END IF;
	                        v_new_status := 'CARD & PIN ACK';
                    END IF;
                    
                ELSIF UPPER(p_status) IN ('REJECTED', 'CANCELLED') THEN
                    -- These statuses override everything
                    v_new_status := UPPER(TRIM(p_status));
                    
                ELSE
                    	 -- ============================================
					    -- HANDLE DOCS/ASSESS STATUS TRANSITIONS
					    -- ============================================
					    IF UPPER(p_status) = 'DOCS VERIFIED' THEN
					    -- When setting DOCS VERIFIED, check what to combine with
					    IF v_current_status_upper = 'DOCS & ASSESS PENDING' THEN
					        v_new_status := 'DOCS VERIFIED & ASSESS PENDING';
					    ELSIF v_current_status_upper = 'ASSESS VERIFIED & DOCS PENDING' THEN
					        v_new_status := 'DOCS & ASSESS VERIFIED';  -- Both verified now!
					    ELSIF v_has_assess_pending THEN
					        v_new_status := 'DOCS VERIFIED & ASSESS PENDING';
					    ELSIF v_has_assess_verified THEN
					        v_new_status := 'DOCS & ASSESS VERIFIED';
					    ELSE
					        v_new_status := 'DOCS VERIFIED';
					    END IF;
					    ELSIF UPPER(p_status) = 'ASSESS VERIFIED' THEN
					    -- When setting ASSESS VERIFIED, check what to combine with
					    IF v_current_status_upper = 'DOCS & ASSESS PENDING' THEN
					        v_new_status := 'ASSESS VERIFIED & DOCS PENDING';
					    ELSIF v_current_status_upper = 'DOCS VERIFIED & ASSESS PENDING' THEN
					        v_new_status := 'DOCS & ASSESS VERIFIED';  -- Both verified now!
					    ELSIF v_has_docs_pending THEN
					        v_new_status := 'ASSESS VERIFIED & DOCS PENDING';
					    ELSIF v_has_docs_verified THEN
					        v_new_status := 'DOCS & ASSESS VERIFIED';
					    ELSE
					        v_new_status := 'ASSESS VERIFIED';
					    END IF;
					        
					    ELSIF UPPER(p_status) = 'DOCS PENDING' THEN
					        -- When setting DOCS PENDING, check what to combine with
					        IF v_has_assess_pending THEN
					            v_new_status := 'DOCS & ASSESS PENDING';
					        ELSIF v_has_assess_verified THEN
					            v_new_status := 'DOCS PENDING & ASSESS VERIFIED';
					        ELSE
					            v_new_status := 'DOCS PENDING';
					        END IF;
					        
					    ELSIF UPPER(p_status) = 'ASSESS PENDING' THEN
					        -- When setting ASSESS PENDING, check what to combine with
					        IF v_has_docs_pending THEN
					            v_new_status := 'DOCS & ASSESS PENDING';
					        ELSIF v_has_docs_verified THEN
					            v_new_status := 'DOCS VERIFIED & ASSESS PENDING';
					        ELSE
					            v_new_status := 'ASSESS PENDING';
					        END IF;
					        
					    ELSE
					        -- For any other status, use as-is
					        v_new_status := p_status;
					    END IF;
				END IF;
                
                -- Now use v_new_status (which may have been composed) for the update
                v_new_composed_status := v_new_status;
                
                -- Log status change
                IF p_debug_level >= 2 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'STATUS_CHANGE',
                        'Status updated',
                        jsonb_build_object(
                            'request_id', p_request_id,
                            'old_status', v_current_status,
                            'new_status', v_new_composed_status,
                            'forwarddoc', v_forwarddoc_current,
                            'forwardapproval', v_forwardapproval_current,
                            'pintype', v_pintype_from_db,
                            'has_docs_pending', v_has_docs_pending,
                            'has_assess_pending', v_has_assess_pending,
                            'has_docs_verified', v_has_docs_verified,
                            'has_assess_verified', v_has_assess_verified,
                            'user_id', p_userid,
                            'username', v_username
                        )
                    );
                END IF;
            END IF;
            
            -- ============================================
            -- 1. UPDATE CREDITCARDCYCLE (MAIN TABLE)
            -- ============================================
            UPDATE public.creditcardcycle 
            SET 
                full_name = COALESCE(p_full_name, full_name),
                mobile = COALESCE(p_mobile, mobile),
                account_no = COALESCE(p_account_no, account_no),
                request_type = COALESCE(p_request_type, request_type),
                card_type = COALESCE(p_card_type, card_type),
                currency_type = COALESCE(p_currency_type, currency_type),
                card_scheme = COALESCE(p_card_scheme, card_scheme),
                request_branch_id = COALESCE(p_request_branch_id, request_branch_id),
                delivery_branch_id = COALESCE(p_delivery_branch_id, delivery_branch_id),
                customer_branch_id = COALESCE(p_customer_branch_id, customer_branch_id),
                customer_branch_code = COALESCE(p_customer_branch_code, customer_branch_code),
                account_type = COALESCE(p_account_type, account_type),
                instcode = COALESCE(p_instcode, instcode),
                remarks = COALESCE(p_remarks, remarks),
                requstor_branch_code = COALESCE(p_requstor_branch_code, requstor_branch_code),
                receiver_branch_code = COALESCE(p_receiver_branch_code, receiver_branch_code),
                pintype = COALESCE(p_pintype, pintype),
                document_remarks = COALESCE(p_document_remarks, document_remarks),
                limitapproval_remarks = COALESCE(p_limitapproval_remarks, limitapproval_remarks),
                forwarddoc = COALESCE(p_forwarddoc, forwarddoc),
                forwardapproval = COALESCE(p_forwardapproval, forwardapproval),
                requested_limit = COALESCE(p_request_limit_amount, requested_limit),
                updated_at = CURRENT_TIMESTAMP,
                status = v_new_composed_status
            WHERE request_id = p_request_id;
            
            GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
            
            IF p_debug_level >= 2 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'UPDATE_CYCLE',
                    'Updated creditcardcycle record',
                    jsonb_build_object(
                        'request_id', p_request_id,
                        'rows_affected', v_rows_affected,
                        'p_request_type', p_request_type,
                        'p_status', p_status,
                        'final_status', v_new_composed_status,
                        'user_id', p_userid,
                        'username', v_username
                    )
                );
            END IF;
            
            -- ============================================
            -- 2. UPDATE DOCUMENTS (IF PROVIDED)
            -- ============================================
            IF p_documents IS NOT NULL AND jsonb_array_length(p_documents) > 0 THEN
                -- Delete existing documents and insert new ones
                DELETE FROM public.creditcard_documents WHERE request_id = p_request_id;
                
                INSERT INTO public.creditcard_documents (
                    request_id,
                    document_type,
                    url_file_name,
                    uploaded_by,
                    status
                )
                SELECT 
                    p_request_id,
                    doc->>'document_type',
                    doc->>'url_file_name',
                    COALESCE(doc->>'uploaded_by', v_username),  -- Use v_username instead of p_userid
                    COALESCE(doc->>'status', 'PENDING')
                FROM jsonb_array_elements(p_documents) AS doc;
                
                GET DIAGNOSTICS v_document_count = ROW_COUNT;
                v_rows_affected := v_rows_affected + v_document_count;
                
                IF p_debug_level >= 2 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'UPDATE_DOCUMENTS',
                        'Updated documents for request',
                        jsonb_build_object(
                            'request_id', p_request_id,
                            'document_count', v_document_count,
                            'user_id', p_userid,
                            'username', v_username
                        )
                    );
                END IF;
            END IF;
            
            -- ============================================
            -- 3. RECALCULATE CREDIT ASSESSMENT (IF FINANCIAL PARAMETERS PROVIDED)
            -- ============================================
            -- Check if financial parameters are provided for recalculation
            IF p_monthly_income IS NOT NULL AND p_calculated_by IS NOT NULL THEN
                
                -- Check if assessment exists
                IF EXISTS (SELECT 1 FROM creditcard_credit_assessment WHERE request_id = p_request_id) THEN
                    -- DELETE existing assessment first (to allow recalculation)
                    DELETE FROM public.creditcard_credit_assessment WHERE request_id = p_request_id;
                    
                    IF p_debug_level >= 2 THEN
                        PERFORM public.flog_audit_trail(
                            'CREDITCARD_MAIN',
                            'DELETE_OLD_ASSESSMENT',
                            'Deleted old assessment for recalculation',
                            jsonb_build_object(
                                'request_id', p_request_id,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        );
                    END IF;
                END IF;
                
                -- Now create NEW assessment (this will work since we deleted the old one)
                SELECT assessment_id, final_score, dbr_percentage, suggested_limit
                INTO v_assessment_id, v_final_score, v_dbr_percentage, v_suggested_limit
                FROM fcreditcard_calculate_credit_assessment(
                    p_request_id := p_request_id,
                    p_request_limit_amount := COALESCE(p_request_limit_amount, 0),
                    p_vehicle_type := COALESCE(p_vehicle_type, 'Unknown'),
                    p_residential_status := COALESCE(p_residential_status, 'Unknown'),
                    p_occupation_type := COALESCE(p_occupation_type, 'Unknown'),
                    p_monthly_income := COALESCE(p_monthly_income, 0),
                    p_monthly_expenditure := COALESCE(p_monthly_expenditure, 0),
                    p_existing_emi := COALESCE(p_existing_emi, 0),
                    p_education_level := COALESCE(p_education_level, 'Unknown'),
                    p_other_loan_count := COALESCE(p_other_loan_count, 0),
                    p_risk_category := COALESCE(p_risk_category, 'Unknown'),
                    p_employment_years := COALESCE(p_employment_years, 0),
                    p_organization_type := COALESCE(p_organization_type, 'Unknown'),
                    p_calculated_by := COALESCE(p_calculated_by, 'System'),
                    p_debug_level := p_debug_level,
                    p_limit_justification := COALESCE(p_limit_justification, 'Recalculated during update')
                );
                
                IF v_assessment_id IS NOT NULL THEN
                    v_rows_affected := v_rows_affected + 1;
                    
                    IF p_debug_level >= 2 THEN
                        PERFORM public.flog_audit_trail(
                            'CREDITCARD_MAIN',
                            'RECALCULATE_ASSESSMENT',
                            'Recalculated credit assessment',
                            jsonb_build_object(
                                'request_id', p_request_id,
                                'assessment_id', v_assessment_id,
                                'final_score', v_final_score,
                                'dbr_percentage', v_dbr_percentage,
                                'suggested_limit', v_suggested_limit,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        );
                    END IF;
                END IF;
                
            END IF;
            
            -- ============================================
            -- PREPARE SUCCESS RESPONSE
            -- ============================================
            result_status := 'SUCCESS';
            result_message := 'Application updated successfully';
            result_data := jsonb_build_object(
                'request_id', p_request_id,
                'rows_updated', v_rows_affected,
                'document_count', v_document_count,
                'assessment_id', v_assessment_id,
                'assessment_details', CASE 
                    WHEN v_assessment_id IS NOT NULL THEN
                        jsonb_build_object(
                            'final_score', v_final_score,
                            'dbr_percentage', v_dbr_percentage,
                            'suggested_limit', v_suggested_limit
                        )
                    ELSE NULL
                END,
                'status_info', jsonb_build_object(
                    'old_status', v_current_status,
                    'new_status', v_new_composed_status,
                    'status_changed', v_current_status != v_new_composed_status,
                    'pintype', v_pintype_from_db
                ),
                'application_status', v_new_composed_status,
                'updated_at', (SELECT updated_at FROM creditcardcycle WHERE request_id = p_request_id),
                'user_access_info', v_user_access_message,
                'updated_by', jsonb_build_object(
                    'user_id', p_userid,
                    'username', v_username,
                    'branch', v_user_branchcode
                )
            );
            
            IF p_debug_level >= 1 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'UPDATE_SUCCESS',
                    'Application updated successfully',
                    jsonb_build_object(
                        'request_id', p_request_id,
                        'status', result_status,
                        'assessment_id', v_assessment_id,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_access', v_user_access_message
                    )
                );
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                result_message := 'Failed to update application: ' || SQLERRM;
                
                IF p_debug_level >= 0 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'UPDATE_ERROR',
                        'Error updating application: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'error_state', SQLSTATE,
                            'parameters', jsonb_build_object(
                                'request_id', p_request_id,
                                'user_id', p_userid,
                                'username', v_username
                            )
                        )
                    );
                END IF;
                
                RETURN;
        END;
    
    -- ============================================
    -- HANDLE SEARCH ACTION (WITH BRANCH FILTERING)
    -- ============================================
       -- ============================================
    -- HANDLE SEARCH ACTION (WITH BRANCH FILTERING)
    -- ============================================
    ELSIF p_action = 'SEARCH' THEN
        -- Search logic with cross-branch access filtering
        IF p_request_id IS NOT NULL THEN
            -- 1. SEARCH BY REQUEST_ID (with branch access check)
            SELECT jsonb_build_array(
                jsonb_build_object(
                    'creditcardcycle', row_to_json(cc)::jsonb,
                    'assessment', CASE 
                        WHEN cca.assessment_id IS NOT NULL THEN row_to_json(cca)::jsonb 
                        ELSE '{}'::jsonb 
                    END,
                    'documents', COALESCE(
                        (SELECT jsonb_agg(row_to_json(cd)::jsonb)
                         FROM creditcard_documents cd 
                         WHERE cd.request_id = cc.request_id),
                        '[]'::jsonb
                    )
                )
            ) INTO result_data
            FROM creditcardcycle cc
            LEFT JOIN creditcard_credit_assessment cca ON cc.request_id = cca.request_id
            WHERE cc.request_id = p_request_id
            -- CROSS-BRANCH ACCESS FILTER
            AND (
                v_user_crossbranch = TRUE  -- Users with cross-branch access see all
                OR cc.customer_branch_code = v_user_branchcode  -- Others only see their branch
                OR (v_user_branchcode IS NULL AND cc.customer_branch_code IS NULL)  -- Handle null cases
            );
            
            IF result_data IS NOT NULL AND jsonb_array_length(result_data) > 0 THEN
                result_status := 'SUCCESS';
                result_message := 'Application found';
                result_data := jsonb_build_object(
                    'application', result_data->0,
                    'user_access_info', v_user_access_message,
                    'search_performed_by', jsonb_build_object(
                        'user_id', p_userid,
                        'username', v_username,
                        'branch', v_user_branchcode
                    )
                );
            ELSE
                result_status := 'NOT_FOUND';
                result_message := 'No application found with request_id: ' || p_request_id;
                result_data := jsonb_build_object(
                    'application', '{}'::jsonb,
                    'user_access_info', v_user_access_message,
                    'search_performed_by', jsonb_build_object(
                        'user_id', p_userid,
                        'username', v_username,
                        'branch', v_user_branchcode
                    )
                );
            END IF;
            
        ELSIF p_search_criteria IS NOT NULL THEN
            -- 2. ENHANCED SEARCH WITH MULTIPLE CRITERIA (with branch filtering)
            DECLARE
                v_status_array TEXT[];
                v_mobile_filter VARCHAR(15);
                v_name_filter VARCHAR(100);
                v_account_no_filter VARCHAR(30);
                v_from_date DATE;
                v_to_date DATE;
                v_card_type_filter VARCHAR(50);
                v_card_scheme_filter VARCHAR(50);
                v_request_type_filter VARCHAR(50);
                v_pintype_filter VARCHAR(15);
                v_currency_type_filter VARCHAR(10);
            BEGIN
                -- Extract search criteria from JSON
                IF p_search_criteria->'status' IS NOT NULL THEN
                    IF jsonb_typeof(p_search_criteria->'status') = 'array' THEN
                        SELECT array_agg(value::text) 
                        INTO v_status_array
                        FROM jsonb_array_elements_text(p_search_criteria->'status');
                    ELSE
                        v_status_array := ARRAY[p_search_criteria->>'status'];
                    END IF;
                END IF;
                
                v_mobile_filter := p_search_criteria->>'mobile';
                v_name_filter := p_search_criteria->>'full_name';
                v_account_no_filter := p_search_criteria->>'account_no';
                v_card_type_filter := p_search_criteria->>'card_type';
                v_card_scheme_filter := p_search_criteria->>'card_scheme';
                v_request_type_filter := p_search_criteria->>'request_type';
                v_pintype_filter := p_search_criteria->>'pintype';
                v_currency_type_filter := p_search_criteria->>'currency_type';
                
                -- Extract date range
                IF p_search_criteria->>'from_date' IS NOT NULL THEN
                    v_from_date := TO_DATE(p_search_criteria->>'from_date', 'YYYY-MM-DD');
                END IF;
                
                IF p_search_criteria->>'to_date' IS NOT NULL THEN
                    v_to_date := TO_DATE(p_search_criteria->>'to_date', 'YYYY-MM-DD');
                END IF;
                
                -- Build search with multiple criteria including status array AND branch filtering
                SELECT COALESCE(
                    jsonb_agg(row_to_json(cc)::jsonb ORDER BY cc.created_at DESC),
                    '[]'::jsonb
                ) INTO result_data
                FROM creditcardcycle cc
                WHERE 1=1
                -- CROSS-BRANCH ACCESS FILTER (MOST IMPORTANT)
                AND (
                    v_user_crossbranch = TRUE
                    OR cc.customer_branch_code = v_user_branchcode
                    OR (v_user_branchcode IS NULL AND cc.customer_branch_code IS NULL)
                )
                -- Original search filters - CORRECTED LOGIC
                AND (v_status_array IS NULL OR cc.status = ANY(v_status_array))
                AND (v_mobile_filter IS NULL OR cc.mobile ILIKE '%' || v_mobile_filter || '%')
                AND (v_name_filter IS NULL OR cc.full_name ILIKE '%' || v_name_filter || '%')
                AND (v_account_no_filter IS NULL OR cc.account_no = v_account_no_filter)
                AND (v_card_type_filter IS NULL OR cc.card_type = v_card_type_filter)
                -- FIXED: Changed IS NOT NULL to IS NULL
                AND (v_card_scheme_filter IS NULL OR cc.card_scheme = v_card_scheme_filter)
                AND (v_request_type_filter IS NULL OR cc.request_type = v_request_type_filter)
                AND (v_pintype_filter IS NULL OR cc.pintype = v_pintype_filter)
                AND (v_currency_type_filter IS NULL OR cc.currency_type = v_currency_type_filter)
                -- FIXED: Changed IS NOT NULL to IS NULL
                AND (v_from_date IS NULL OR cc.created_at::DATE >= v_from_date)
                AND (v_to_date IS NULL OR cc.created_at::DATE <= v_to_date);
                
                -- Set result message based on count
                IF result_data IS NOT NULL THEN
                    result_status := 'SUCCESS';
                    result_message := 'Found ' || jsonb_array_length(result_data)::text || ' application(s)';
                    result_data := jsonb_build_object(
                        'applications', result_data,
                        'user_access_info', v_user_access_message,
                        'search_summary', jsonb_build_object(
                            'total_found', jsonb_array_length(result_data),
                            'user_branch', v_user_branchcode,
                            'crossbranch_access', v_user_crossbranch
                        ),
                        'search_performed_by', jsonb_build_object(
                            'user_id', p_userid,
                            'username', v_username,
                            'branch', v_user_branchcode
                        )
                    );
                ELSE
                    result_status := 'SUCCESS';
                    result_message := 'No applications found with the specified criteria';
                    result_data := jsonb_build_object(
                        'applications', '[]'::jsonb,
                        'user_access_info', v_user_access_message,
                        'search_performed_by', jsonb_build_object(
                            'user_id', p_userid,
                            'username', v_username,
                            'branch', v_user_branchcode
                        )
                    );
                END IF;
            END;
        ELSE
            -- 3. GET ALL APPLICATIONS (with branch filtering)
            SELECT COALESCE(
                jsonb_agg(row_to_json(cc)::jsonb ORDER BY cc.created_at DESC),
                '[]'::jsonb
            ) INTO result_data
            FROM creditcardcycle cc
            -- CROSS-BRANCH ACCESS FILTER
            WHERE (
                v_user_crossbranch = TRUE
                OR cc.customer_branch_code = v_user_branchcode
                OR (v_user_branchcode IS NULL AND cc.customer_branch_code IS NULL)
            );
            
            result_status := 'SUCCESS';
            result_message := 'Found ' || COALESCE(jsonb_array_length(result_data)::text, '0') || ' application(s)';
            result_data := jsonb_build_object(
                'applications', result_data,
                'user_access_info', v_user_access_message,
                'search_summary', jsonb_build_object(
                    'total_found', COALESCE(jsonb_array_length(result_data), 0),
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch
                ),
                'search_performed_by', jsonb_build_object(
                    'user_id', p_userid,
                    'username', v_username,
                    'branch', v_user_branchcode
                )
            );
        END IF;
    
    -- ============================================
    -- HANDLE DELETE ACTION (WITH BRANCH ACCESS CHECK)
    -- ============================================
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_request_id IS NULL THEN
                result_message := 'Request ID is required for DELETE action';
                RETURN;
            END IF;
            
            -- Get application branch code first
            SELECT customer_branch_code INTO v_app_branch_code
            FROM creditcardcycle 
            WHERE request_id = p_request_id;
            
            IF v_app_branch_code IS NULL THEN
                result_message := 'Application not found for deletion';
                RETURN;
            END IF;
            
            -- ============================================
            -- CROSS-BRANCH ACCESS CHECK FOR DELETE
            -- ============================================
            v_has_access := FALSE;
            
            IF v_user_crossbranch THEN
                -- User has cross-branch access, allow delete
                v_has_access := TRUE;
            ELSIF v_user_branchcode IS NOT NULL AND v_user_branchcode = v_app_branch_code THEN
                -- User is from the same branch as the application
                v_has_access := TRUE;
            ELSE
                -- User doesn't have access
                v_has_access := FALSE;
                result_message := 'Access denied. You do not have permission to delete this application. ' ||
                                'Application belongs to branch: ' || v_app_branch_code ||
                                ', Your branch: ' || COALESCE(v_user_branchcode, 'Not assigned');
                result_status := 'ACCESS_DENIED';
                
                IF p_debug_level >= 1 THEN
                    PERFORM public.flog_audit_trail(
                        'CREDITCARD_MAIN',
                        'DELETE_ACCESS_DENIED',
                        'User denied access to delete application',
                        jsonb_build_object(
                            'request_id', p_request_id,
                            'user_id', p_userid,
                            'username', v_username,
                            'user_branch', v_user_branchcode,
                            'app_branch', v_app_branch_code,
                            'crossbranch_access', v_user_crossbranch,
                            'access_message', v_user_access_message,
                            'reason', 'Branch access mismatch'
                        )
                    );
                END IF;
                
                RETURN;
            END IF;
            
            -- Log access granted
            IF p_debug_level >= 2 THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'DELETE_ACCESS_GRANTED',
                    'User granted access to delete application',
                    jsonb_build_object(
                        'request_id', p_request_id,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_branch', v_user_branchcode,
                        'app_branch', v_app_branch_code,
                        'crossbranch_access', v_user_crossbranch,
                        'access_message', v_user_access_message
                    )
                );
            END IF;
            
            -- Get old data for logging
            SELECT to_jsonb(cc.*) INTO v_old_data
            FROM creditcardcycle cc
            WHERE cc.request_id = p_request_id;
            
            -- Delete related records first (cascade)
            DELETE FROM creditcard_credit_assessment WHERE request_id = p_request_id;
            DELETE FROM creditcard_documents WHERE request_id = p_request_id;
            DELETE FROM creditcardcycle WHERE request_id = p_request_id;
            
            GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
            
            result_status := 'SUCCESS';
            result_message := 'Application deleted successfully';
            result_data := jsonb_build_object(
                'request_id', p_request_id,
                'rows_deleted', v_rows_affected,
                'user_access_info', v_user_access_message,
                'deleted_by', jsonb_build_object(
                    'user_id', p_userid,
                    'username', v_username,
                    'branch', v_user_branchcode
                )
            );
            
            IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
                PERFORM public.flog_audit_trail(
                    'CREDITCARD_MAIN',
                    'DELETE_SUCCESS',
                    'Application deleted',
                    jsonb_build_object(
                        'request_id', p_request_id,
                        'deleted_by', v_username,
                        'user_id', p_userid,
                        'username', v_username,
                        'user_access', v_user_access_message
                    )
                );
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                result_message := 'Delete error: ' || SQLERRM;
                result_data := jsonb_build_object(
                    'error', SQLERRM,
                    'user_access_info', v_user_access_message,
                    'attempted_by', jsonb_build_object(
                        'user_id', p_userid,
                        'username', v_username,
                        'branch', v_user_branchcode
                    )
                );
        END;
    END IF;
    
    -- ============================================
    -- LOG OPERATION TO LOG TABLE
    -- ============================================
    v_execution_time := EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start_time));
    if p_action != 'SEARCH' THEN
        INSERT INTO log_credit_card_cycle (
            action_type,
            request_id,
            debug_level,
            status,
            execution_time_ms,
            rows_affected,
            documents_count,
            assessment_id,
            old_data,
            new_data,
            full_name,
            mobile,
            request_type,
            card_type,
            currency_type,
            card_scheme,
            error_message,
            user_id,
            username,  -- Added username column
            account_no,
            user_branch,
            crossbranch_access
        ) VALUES (
            p_action,
            v_request_id,
            p_debug_level,
            result_status,
            v_execution_time,
            v_rows_affected,
            v_document_count,
            v_assessment_id,
            v_old_data,
            CASE 
                WHEN p_action = 'INSERT' THEN 
                    jsonb_build_object(
                        'request_id', v_request_id,
                        'full_name', p_full_name,
                        'status', v_initial_status
                    )
                ELSE result_data
            END,
            p_full_name,
            p_mobile,
            p_request_type,
            p_card_type,
            p_currency_type,
            p_card_scheme,
            CASE WHEN result_status = 'ERROR' THEN result_message ELSE NULL END,
            p_userid,
            v_username,  -- Store username
            p_account_no,
            v_user_branchcode,
            v_user_crossbranch
        )
        RETURNING log_id INTO v_log_id;
    END IF;
    
    -- Final debug log
    IF p_debug_level >= 1 and p_action != 'SEARCH' THEN
        PERFORM public.flog_audit_trail(
            'CREDITCARD_MAIN',
            'COMPLETE_' || p_action,
            'Operation completed: ' || result_status,
            jsonb_build_object(
                'action', p_action,
                'status', result_status,
                'execution_time_ms', v_execution_time,
                'log_id', v_log_id,
                'user_id', p_userid,
                'username', v_username,
                'user_access', v_user_access_message
            )
        );
    END IF;
    
END;
$$;


ALTER FUNCTION public.fcreditcard_cycle(p_action character varying, p_debug_level integer, p_full_name character varying, p_mobile character varying, p_account_no character varying, p_request_type character varying, p_card_type character varying, p_currency_type character varying, p_card_scheme character varying, p_request_branch_id character varying, p_delivery_branch_id character varying, p_customer_branch_id character varying, p_customer_branch_code character varying, p_account_type character varying, p_instcode character varying, p_remarks text, p_requstor_branch_code character varying, p_receiver_branch_code character varying, p_pintype character varying, p_document_remarks character varying, p_limitapproval_remarks character varying, p_forwarddoc bit, p_forwardapproval bit, p_request_limit_amount numeric, p_vehicle_type character varying, p_residential_status character varying, p_occupation_type character varying, p_monthly_income numeric, p_monthly_expenditure numeric, p_existing_emi numeric, p_education_level character varying, p_other_loan_count integer, p_risk_category character varying, p_employment_years integer, p_organization_type character varying, p_calculated_by character varying, p_limit_justification text, p_documents jsonb, p_request_id character varying, p_search_criteria jsonb, p_userid integer, p_status character varying, OUT result_status character varying, OUT result_message text, OUT result_data jsonb) OWNER TO postgres;

--
-- Name: fcrud_card_cycle_log(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer, character varying, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcrud_card_cycle_log(p_action character varying, p_log_id character varying DEFAULT NULL::character varying, p_request_id character varying DEFAULT NULL::character varying, p_user_id character varying DEFAULT NULL::character varying, p_full_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_account_no character varying DEFAULT NULL::character varying, p_branch_code character varying DEFAULT NULL::character varying, p_status_old character varying DEFAULT NULL::character varying, p_status_new character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_search_term character varying DEFAULT NULL::character varying, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_log_id CHARACTER VARYING(12);
    v_count INTEGER;
    v_records JSON;
BEGIN
    -- Input validation
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'GET') THEN
        RETURN json_build_object(
            'success', FALSE,
            'message', 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, or GET'
        );
    END IF;

    -- INSERT operation
    IF p_action = 'INSERT' THEN
        -- Validate required fields for INSERT
        IF p_request_id IS NULL OR p_action IS NULL THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'request_id and action are required for INSERT'
            );
        END IF;

        -- Debug logging
        RAISE LOG 'fcrud_card_cycle_log INSERT: p_request_id=%, p_user_id=%, p_action=%', 
                  p_request_id, p_user_id, p_action;

        INSERT INTO card_request_cycle_action_log (
            action,
            request_id,
            user_id,
            full_name,
            mobile,
            account_no,
            branch_code,
            status_old,
            status_new,
            called_at
        ) VALUES (
            p_action,
            p_request_id,
            p_user_id,  -- This should be VARCHAR, matching the table column
            p_full_name,
            p_mobile,
            p_account_no,
            p_branch_code,
            p_status_old,
            p_status_new,
            CURRENT_TIMESTAMP
        )
        RETURNING log_id INTO v_log_id;
        
        RETURN json_build_object(
            'success', TRUE,
            'message', 'Record inserted successfully',
            'log_id', v_log_id
        );

    -- UPDATE operation
    ELSIF p_action = 'UPDATE' THEN
        -- Validate required fields for UPDATE
        IF p_log_id IS NULL THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'log_id is required for UPDATE'
            );
        END IF;

        UPDATE card_request_cycle_action_log
        SET 
            action = COALESCE(p_action, action),
            request_id = COALESCE(p_request_id, request_id),
            user_id = COALESCE(p_user_id, user_id),
            full_name = COALESCE(p_full_name, full_name),
            mobile = COALESCE(p_mobile, mobile),
            account_no = COALESCE(p_account_no, account_no),
            branch_code = COALESCE(p_branch_code, branch_code),
            status_old = COALESCE(p_status_old, status_old),
            status_new = COALESCE(p_status_new, status_new)
        WHERE log_id = p_log_id;
        
        IF NOT FOUND THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'Record not found for update'
            );
        END IF;
        
        RETURN json_build_object(
            'success', TRUE,
            'message', 'Record updated successfully'
        );

    -- DELETE operation
    ELSIF p_action = 'DELETE' THEN
        -- Validate required fields for DELETE
        IF p_log_id IS NULL THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'log_id is required for DELETE'
            );
        END IF;

        DELETE FROM card_request_cycle_action_log
        WHERE log_id = p_log_id;
        
        IF NOT FOUND THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'Record not found for deletion'
            );
        END IF;
        
        RETURN json_build_object(
            'success', TRUE,
            'message', 'Record deleted successfully'
        );

    -- GET single record operation
    ELSIF p_action = 'GET' THEN
        -- Validate required fields for GET
        IF p_log_id IS NULL THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'log_id is required for GET'
            );
        END IF;

        SELECT json_agg(row_to_json(t)) INTO v_records
        FROM (
            SELECT 
                log_id,
                action,
                request_id,
                user_id,
                full_name,
                mobile,
                account_no,
                branch_code,
                status_old,
                status_new,
                called_at
            FROM card_request_cycle_action_log
            WHERE log_id = p_log_id
        ) t;
        
        IF v_records IS NULL THEN
            RETURN json_build_object(
                'success', FALSE,
                'message', 'Record not found'
            );
        END IF;
        
        RETURN json_build_object(
            'success', TRUE,
            'message', 'Record retrieved successfully',
            'data', v_records
        );

    -- LIST operation (with filtering and pagination)
    ELSIF p_action = 'LIST' THEN
        -- Get filtered records
        SELECT json_agg(row_to_json(t)) INTO v_records
        FROM (
            SELECT 
                log_id,
                action,
                request_id,
                user_id,
                full_name,
                mobile,
                account_no,
                branch_code,
                status_old,
                status_new,
                called_at
            FROM card_request_cycle_action_log
            WHERE 1=1
            AND (p_request_id IS NULL OR request_id = p_request_id)
            AND (p_user_id IS NULL OR user_id = p_user_id)
            AND (p_branch_code IS NULL OR branch_code = p_branch_code)
            AND (p_status_new IS NULL OR status_new = p_status_new)
            AND (p_date_from IS NULL OR called_at >= p_date_from)
            AND (p_date_to IS NULL OR called_at <= p_date_to)
            AND (
                p_search_term IS NULL OR 
                full_name ILIKE '%' || p_search_term || '%' OR
                mobile ILIKE '%' || p_search_term || '%' OR
                account_no ILIKE '%' || p_search_term || '%'
            )
            ORDER BY called_at DESC
            LIMIT p_limit
            OFFSET p_offset
        ) t;
        
        -- Get total count for pagination
        SELECT COUNT(*) INTO v_count
        FROM card_request_cycle_action_log
        WHERE 1=1
        AND (p_request_id IS NULL OR request_id = p_request_id)
        AND (p_user_id IS NULL OR user_id = p_user_id)
        AND (p_branch_code IS NULL OR branch_code = p_branch_code)
        AND (p_status_new IS NULL OR status_new = p_status_new)
        AND (p_date_from IS NULL OR called_at >= p_date_from)
        AND (p_date_to IS NULL OR called_at <= p_date_to)
        AND (
            p_search_term IS NULL OR 
            full_name ILIKE '%' || p_search_term || '%' OR
            mobile ILIKE '%' || p_search_term || '%' OR
            account_no ILIKE '%' || p_search_term || '%'
        );
        
        RETURN json_build_object(
            'success', TRUE,
            'message', 'Records retrieved successfully',
            'data', COALESCE(v_records, '[]'::json),
            'total_count', v_count,
            'limit', p_limit,
            'offset', p_offset
        );
    END IF;
    
    -- This should never be reached, but just in case
    RETURN json_build_object(
        'success', FALSE,
        'message', 'Unknown error occurred'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', FALSE,
            'message', 'Error: ' || SQLERRM || 
                      ' | p_request_id: ' || COALESCE(p_request_id, 'NULL') ||
                      ' | p_user_id: ' || COALESCE(p_user_id, 'NULL') ||
                      ' | p_action: ' || COALESCE(p_action, 'NULL')
        );
END;
$$;


ALTER FUNCTION public.fcrud_card_cycle_log(p_action character varying, p_log_id character varying, p_request_id character varying, p_user_id character varying, p_full_name character varying, p_mobile character varying, p_account_no character varying, p_branch_code character varying, p_status_old character varying, p_status_new character varying, p_limit integer, p_offset integer, p_search_term character varying, p_date_from timestamp with time zone, p_date_to timestamp with time zone) OWNER TO postgres;

--
-- Name: fcustomer(text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, integer, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcustomer(action text, p_customercode character varying DEFAULT NULL::character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_branchcode character varying DEFAULT NULL::character varying, p_bankcode character varying DEFAULT NULL::character varying, p_accountid integer DEFAULT NULL::integer, p_accountnumber character varying DEFAULT NULL::character varying, p_cardid integer DEFAULT NULL::integer, p_schemetype character varying DEFAULT NULL::character varying, p_cardnumber character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying) RETURNS TABLE(customerid character varying, customercode character varying, fname character varying, lname character varying, middlename character varying, salutation character varying, emailid character varying, mobileno character varying, branchcode character varying, bankcode character varying, maritalstatus character, status character, dob date, address character varying, notes text, createddate timestamp without time zone, updateddate timestamp without time zone, accountid integer, accountnumber character varying, accounttype character varying, balance numeric, acc_branchcode character varying, acc_status character, acc_createddate timestamp without time zone, acc_updateddate timestamp without time zone, cardid integer, schemetype character varying, cardnumber character varying, cardtype character varying, expirydate date, issuedate date, card_status character, profileid character varying, card_createddate timestamp without time zone, card_updateddate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
BEGIN
    IF action = 'ALL_SEARCH' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,  -- customerid is VARCHAR, using customercode here
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                d.cardid, d.schemetype, d.cardnumber, d.cardtype, d.expirydate, d.issuedate, 
                d.status AS card_status, d.profileid, d.generateddate AS card_createddate, 
                d.updateddate AS card_updateddate
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card d ON a.accountid = d.accountid
            WHERE 1=1';

        IF p_mobileno IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.mobileno = %L', p_mobileno);
        END IF;
        IF p_fname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.fname = %L', p_fname);
        END IF;
        IF p_lname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.lname = %L', p_lname);
        END IF;
        IF p_middlename IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.middlename = %L', p_middlename);
        END IF;
        IF p_cardnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND d.cardnumber = %L', p_cardnumber);
        END IF;
        IF p_accountnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', p_accountnumber);
        END IF;
        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;

        RAISE NOTICE 'Dynamic query executing: %', dyn_sql;
        RETURN QUERY EXECUTE dyn_sql;

    ELSIF action = 'LIST_ACCOUNT' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                NULL::INT, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, 
                NULL::DATE, NULL::DATE, NULL::CHAR(1), NULL::VARCHAR, 
                NULL::TIMESTAMP, NULL::TIMESTAMP
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            WHERE 1=1';

        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;

        RETURN QUERY EXECUTE dyn_sql;

    ELSIF action = 'LIST_CARD' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                d.cardid, d.schemetype, d.cardnumber, d.cardtype, d.expirydate, d.issuedate, 
                d.status AS card_status, d.profileid, d.generateddate AS card_createddate, 
                d.updateddate AS card_updateddate
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card d ON a.accountid = d.accountid
            WHERE 1=1';

        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;
        IF p_accountid IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND a.accountid = %s', p_accountid);
        END IF;

        RETURN QUERY EXECUTE dyn_sql;

    ELSE
        RAISE EXCEPTION 'Invalid action: %', action;
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION public.fcustomer(action text, p_customercode character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_branchcode character varying, p_bankcode character varying, p_accountid integer, p_accountnumber character varying, p_cardid integer, p_schemetype character varying, p_cardnumber character varying, p_cardtype character varying) OWNER TO postgres;

--
-- Name: fcustomer(text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, integer, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fcustomer(action text, p_customercode character varying DEFAULT NULL::character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_branchcode character varying DEFAULT NULL::character varying, p_bankcode character varying DEFAULT NULL::character varying, p_accountid integer DEFAULT NULL::integer, p_accountnumber character varying DEFAULT NULL::character varying, p_cardid integer DEFAULT NULL::integer, p_schemetype character varying DEFAULT NULL::character varying, p_cardnumber character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer) RETURNS TABLE(customerid character varying, customercode character varying, fname character varying, lname character varying, middlename character varying, salutation character varying, emailid character varying, mobileno character varying, branchcode character varying, bankcode character varying, maritalstatus character, status character, dob date, address character varying, notes text, createddate timestamp without time zone, updateddate timestamp without time zone, accountid integer, accountnumber character varying, accounttype character varying, balance numeric, acc_branchcode character varying, acc_status character, acc_createddate timestamp without time zone, acc_updateddate timestamp without time zone, cardid integer, schemetype character varying, cardnumber character varying, cardtype character varying, expirydate date, issuedate date, card_status character, profileid character varying, card_createddate timestamp without time zone, card_updateddate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
BEGIN
    IF action = 'ALL_SEARCH' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                d.cardid, d.schemetype, d.cardnumber, d.cardtype, d.expirydate, d.issuedate, 
                d.status AS card_status, d.profileid, d.generateddate AS card_createddate, 
                d.updateddate AS card_updateddate
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card d ON a.accountid = d.accountid
            WHERE 1=1';

        IF p_mobileno IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.mobileno = %L', p_mobileno);
        END IF;
        IF p_fname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.fname = %L', p_fname);
        END IF;
        IF p_lname IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.lname = %L', p_lname);
        END IF;
        IF p_middlename IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.middlename = %L', p_middlename);
        END IF;
        IF p_cardnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND d.cardnumber = %L', p_cardnumber);
        END IF;
        IF p_accountnumber IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', p_accountnumber);
        END IF;
        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;
        IF p_userid IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND (c.createdby = %s OR a.createdby = %s OR d.createdby = %s)', p_userid, p_userid, p_userid);
        END IF;

        RAISE NOTICE 'Dynamic query executing: %', dyn_sql;
        RETURN QUERY EXECUTE dyn_sql;

    ELSIF action = 'LIST_ACCOUNT' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                NULL::INT, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, 
                NULL::DATE, NULL::DATE, NULL::CHAR(1), NULL::VARCHAR, 
                NULL::TIMESTAMP, NULL::TIMESTAMP
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            WHERE 1=1';

        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;
        IF p_userid IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND (c.createdby = %s OR a.createdby = %s)', p_userid, p_userid);
        END IF;

        RETURN QUERY EXECUTE dyn_sql;

    ELSIF action = 'LIST_CARD' THEN
        dyn_sql := '
            SELECT 
                c.customercode AS customerid,
                c.customercode, c.fname, c.lname, c.middlename, c.salutation, 
                c.emailid, c.mobileno, c.branchcode, c.bankcode, c.maritalstatus, 
                c.status, c.dob, c.address, c.notes, c.generateddate AS createddate, c.updateddate,

                a.accountid, a.accountnumber, a.accounttype, a.balance, 
                a.branchcode AS acc_branchcode, a.status AS acc_status, 
                a.generateddate AS acc_createddate, a.updateddate AS acc_updateddate,

                d.cardid, d.schemetype, d.cardnumber, d.cardtype, d.expirydate, d.issuedate, 
                d.status AS card_status, d.profileid, d.generateddate AS card_createddate, 
                d.updateddate AS card_updateddate
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card d ON a.accountid = d.accountid
            WHERE 1=1';

        IF p_customercode IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
        END IF;
        IF p_accountid IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND a.accountid = %s', p_accountid);
        END IF;
        IF p_userid IS NOT NULL THEN
            dyn_sql := dyn_sql || format(' AND (c.createdby = %s OR a.createdby = %s OR d.createdby = %s)', p_userid, p_userid, p_userid);
        END IF;

        RETURN QUERY EXECUTE dyn_sql;

    ELSE
        RAISE EXCEPTION 'Invalid action: %', action;
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION public.fcustomer(action text, p_customercode character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_branchcode character varying, p_bankcode character varying, p_accountid integer, p_accountnumber character varying, p_cardid integer, p_schemetype character varying, p_cardnumber character varying, p_cardtype character varying, p_userid integer) OWNER TO postgres;

--
-- Name: fdaemonapply_dynamic_charges(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fdaemonapply_dynamic_charges(p_debug_level integer DEFAULT 1, p_batch_size integer DEFAULT 1000, p_dry_run boolean DEFAULT false) RETURNS TABLE(operation_status character varying, records_processed integer, total_amount numeric, message text, operation_id bigint, performance_metrics jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation_id BIGINT;
    v_inserted_count INTEGER := 0;
    v_total_amount DECIMAL(12,2) := 0;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_sql_state TEXT;
    v_additional_info JSONB;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_processing_time NUMERIC;
    
    -- Configuration constants
    v_default_credit_limit CONSTANT DECIMAL := 10000;
    v_default_transaction_base CONSTANT DECIMAL := 1000;
    
    -- Charge types to process
    v_charge_types_to_process TEXT[] := ARRAY['ANNUAL_FEE', 'MONTHLY_FEE', 'SUBSCRIPTION_FEE', 'PROCESSING_FEE', 'LATE_FEE'];
    v_current_charge_type TEXT;
    v_charge_types_count INTEGER;
    v_charge_type_idx INTEGER := 0;
    
    -- Multi-currency support
    v_supported_currencies TEXT[] := ARRAY['USD', 'NPR', 'INR', 'EUR', 'CNY'];
    v_currency_default CONSTANT TEXT := 'NPR';
    
    -- Performance metrics
    v_metrics JSONB;
    v_batch_count INTEGER := 0;
    v_charge_calculation_time NUMERIC;
    v_data_retrieval_time NUMERIC;
    
    -- Currency tracking
    v_currency_summary JSONB := '{}'::JSONB;
    
    -- Variables for batch processing
    v_batch_inserted_count INTEGER;
    v_batch_total_amount DECIMAL(12,2);
    
    -- NEW: Track different counts
    v_total_cards_before_waiver INTEGER := 0;
    v_first_year_cards_count INTEGER := 0;
    v_other_excluded_cards INTEGER := 0;
    v_final_message TEXT;
    
BEGIN
    -- Start timing
    v_start_time := clock_timestamp();
    
    v_charge_types_count := array_length(v_charge_types_to_process, 1);
    
    -- Start operation logging
    v_operation_id := log_operation_start(
        'fdaemonapply_dynamic_charges',
        jsonb_build_object(
            'process', 'dynamic_charge_application',
            'version', '9.5',
            'debug_level', p_debug_level,
            'batch_size', p_batch_size,
            'dry_run', p_dry_run,
            'charge_types_to_process', v_charge_types_to_process,
            'start_time', v_start_time
        )
    );
    
    IF v_operation_id = -1 THEN
        RETURN QUERY SELECT 
            'FAILED'::VARCHAR(20),
            0,
            0::DECIMAL(15,2),
            'Failed to start operation logging',
            -1::BIGINT,
            NULL::JSONB;
        RETURN;
    END IF;

    BEGIN
        -- Set transaction characteristics
        SET LOCAL enable_nestloop = off;
        SET LOCAL work_mem = '256MB';
        
        IF p_debug_level >= 1 THEN
            RAISE NOTICE 'Starting dynamic charge application for charge types: %', 
                v_charge_types_to_process;
        END IF;

        -- First, count how many cards would be eligible WITHOUT the first-year waiver
        FOR v_charge_type_idx IN 1..v_charge_types_count LOOP
            v_current_charge_type := v_charge_types_to_process[v_charge_type_idx];
            
            -- Count cards that match all conditions EXCEPT the first-year waiver
            SELECT COUNT(DISTINCT c.cardid)
            INTO v_batch_inserted_count
            FROM card c
            INNER JOIN products p ON c.productid = p.productid
            INNER JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status='ACTIVE'
            INNER JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
            INNER JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
            INNER JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = v_current_charge_type
            INNER JOIN chargeconfig cc ON (
                cc.chargeid = (ra.action_value->>'charge_config_reference')::TEXT
                AND cc.isactive 
                AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
                AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            )
            WHERE NOT EXISTS (
                SELECT 1 FROM ruleconditions rc 
                WHERE rc.ruleid = rm.ruleid 
                AND rc.is_active
                AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
            )
            AND NOT EXISTS (
                SELECT 1 FROM card_charges ch 
                WHERE ch.cardid = c.cardid 
                AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                AND ch.charge_type = v_current_charge_type
                AND ch.status != 'CANCELLED'
            )
            AND (
                (ra.action_value->'filters'->>'schemetype' IS NULL OR p.schemetype = ra.action_value->'filters'->>'schemetype')
                AND (ra.action_value->'filters'->>'cardtype' IS NULL OR p.producttype = ra.action_value->'filters'->>'cardtype')
            );
            
            v_total_cards_before_waiver := v_total_cards_before_waiver + v_batch_inserted_count;
            
            -- Count how many of those are first-year cards
            SELECT COUNT(DISTINCT c.cardid)
            INTO v_batch_total_amount
            FROM card c
            INNER JOIN products p ON c.productid = p.productid
            INNER JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status='ACTIVE'
            INNER JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
            INNER JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
            INNER JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = v_current_charge_type
            INNER JOIN chargeconfig cc ON (
                cc.chargeid = (ra.action_value->>'charge_config_reference')::TEXT
                AND cc.isactive 
                AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
                AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            )
            WHERE NOT EXISTS (
                SELECT 1 FROM ruleconditions rc 
                WHERE rc.ruleid = rm.ruleid 
                AND rc.is_active
                AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
            )
            AND NOT EXISTS (
                SELECT 1 FROM card_charges ch 
                WHERE ch.cardid = c.cardid 
                AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                AND ch.charge_type = v_current_charge_type
                AND ch.status != 'CANCELLED'
            )
            AND (
                (ra.action_value->'filters'->>'schemetype' IS NULL OR p.schemetype = ra.action_value->'filters'->>'schemetype')
                AND (ra.action_value->'filters'->>'cardtype' IS NULL OR p.producttype = ra.action_value->'filters'->>'cardtype')
            )
            -- Cards that are in first year (issued less than 365 days ago)
            AND (c.issuedate IS NOT NULL AND (CURRENT_DATE - c.issuedate) < 365);
            
            v_first_year_cards_count := v_first_year_cards_count + v_batch_total_amount;
        END LOOP;
        
        IF p_debug_level >= 1 THEN
            RAISE NOTICE 'Total cards before waiver: %, First-year cards: %', 
                v_total_cards_before_waiver, v_first_year_cards_count;
        END IF;
        
        -- Now process charges (excluding first-year cards)
        FOR v_charge_type_idx IN 1..v_charge_types_count LOOP
            v_current_charge_type := v_charge_types_to_process[v_charge_type_idx];
            
            IF p_debug_level >= 1 THEN
                RAISE NOTICE 'Processing charge type: % (% of %)', 
                    v_current_charge_type, v_charge_type_idx, v_charge_types_count;
            END IF;
            
            -- Dry run mode: Only analyze, don't insert
            IF p_dry_run THEN
                IF p_debug_level >= 1 THEN
                    RAISE NOTICE 'Dry run completed for charge type: %', v_current_charge_type;
                END IF;
                CONTINUE;
            END IF;
            
            -- Phase 2: Batched Charge Processing (EXCLUDING first-year cards)
            v_charge_calculation_time := EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time));
            
            -- Process in batches
            v_batch_count := 0;
            
            LOOP
                v_batch_count := v_batch_count + 1;
                
                IF p_debug_level >= 3 THEN
                    RAISE NOTICE 'Processing batch % for charge type %', 
                        v_batch_count, v_current_charge_type;
                END IF;
                
                -- Reset batch variables
                v_batch_inserted_count := 0;
                v_batch_total_amount := 0;
                
                -- Insert charges using batched approach (EXCLUDING first-year cards)
                WITH eligible_cards_batch AS (
                    SELECT DISTINCT c.cardid
                    FROM card c
                    INNER JOIN products p ON c.productid = p.productid
                    INNER JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status='ACTIVE'
                    INNER JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
                    INNER JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
                    INNER JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = v_current_charge_type
                    INNER JOIN chargeconfig cc ON (
                        cc.chargeid = (ra.action_value->>'charge_config_reference')::TEXT
                        AND cc.isactive 
                        AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
                        AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
                    )
                    WHERE NOT EXISTS (
                        SELECT 1 FROM ruleconditions rc 
                        WHERE rc.ruleid = rm.ruleid 
                        AND rc.is_active
                        AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
                    )
                    AND NOT EXISTS (
                        SELECT 1 FROM card_charges ch 
                        WHERE ch.cardid = c.cardid 
                        AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                        AND ch.charge_type = v_current_charge_type
                        AND ch.status != 'CANCELLED'
                    )
                    -- Apply JSON filters
                    AND (
                        (ra.action_value->'filters'->>'schemetype' IS NULL OR p.schemetype = ra.action_value->'filters'->>'schemetype')
                        AND (ra.action_value->'filters'->>'cardtype' IS NULL OR p.producttype = ra.action_value->'filters'->>'cardtype')
                    )
                    -- EXCLUDE first-year cards
                    AND (c.issuedate IS NULL OR (CURRENT_DATE - c.issuedate) >= 365)
                    ORDER BY c.cardid
                    LIMIT p_batch_size
                ),
                calculated_charges AS (
                    SELECT 
                        c.cardid, 
                        c.cardnumber, 
                        c.accountid,
                        c.issuedate,
                        -- Determine currency
                        CASE 
                            WHEN p.currency IS NOT NULL AND p.currency != '' AND p.currency = ANY(v_supported_currencies) THEN p.currency
                            WHEN cc.currency IS NOT NULL AND cc.currency != '' AND cc.currency = ANY(v_supported_currencies) THEN cc.currency
                            ELSE v_currency_default
                        END as determined_currency,
                        v_current_charge_type as charge_type,
                        rm.rulename as charge_name,
                        -- Calculate amount based on chargeconfig
                        CASE 
                            WHEN cc.charge_type = 'FLAT' THEN cc.amount
                            WHEN cc.charge_type = 'PER' THEN 
                                (cc.percentage / 100.0) * 
                                CASE 
                                    WHEN cc.calculation_rule ILIKE '%transaction%' THEN v_default_transaction_base
                                    ELSE v_default_credit_limit
                                END
                            WHEN cc.charge_type = 'BOTH' THEN 
                                cc.amount + ((cc.percentage / 100.0) * 
                                CASE 
                                    WHEN cc.calculation_rule ILIKE '%transaction%' THEN v_default_transaction_base
                                    ELSE v_default_credit_limit
                                END)
                            ELSE cc.amount
                        END as calculated_amount,
                        CURRENT_DATE as charge_date,
                        EXTRACT(YEAR FROM CURRENT_DATE) as charge_year,
                        p.producttype,
                        p.schemetype,
                        p.productname,
                        p.productbin,
                        rm.ruleid as rule_reference,
                        cc.chargeid as config_reference,
                        ra.actionid as action_reference,
                        CURRENT_TIMESTAMP as created_at,
                        cc.chargename,
                        cc.charge_type as config_charge_type,
                        cc.percentage,
                        cc.currency as config_currency,
                        -- Calculate days since issue
                        (CURRENT_DATE - c.issuedate) as days_since_issue
                    FROM card c
                    INNER JOIN products p ON c.productid = p.productid
                    INNER JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status='ACTIVE'
                    INNER JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
                    INNER JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
                    INNER JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = v_current_charge_type
                    INNER JOIN chargeconfig cc ON (
                        cc.chargeid = (ra.action_value->>'charge_config_reference')::TEXT
                        AND cc.isactive 
                        AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
                        AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
                    )
                    INNER JOIN eligible_cards_batch ecb ON c.cardid = ecb.cardid
                    WHERE NOT EXISTS (
                        SELECT 1 FROM ruleconditions rc 
                        WHERE rc.ruleid = rm.ruleid 
                        AND rc.is_active
                        AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
                    )
                    -- Apply JSON filters
                    AND (
                        (ra.action_value->'filters'->>'schemetype' IS NULL OR p.schemetype = ra.action_value->'filters'->>'schemetype')
                        AND (ra.action_value->'filters'->>'cardtype' IS NULL OR p.producttype = ra.action_value->'filters'->>'cardtype')
                    )
                ),
                -- Use DISTINCT ON to avoid duplicates
                eligible_charges AS (
                    SELECT DISTINCT ON (cardid, rule_reference, determined_currency)
                        cardid,
                        cardnumber,
                        accountid,
                        determined_currency as currency,
                        charge_type,
                        charge_name,
                        calculated_amount,
                        charge_date,
                        charge_year,
                        -- Description with details
                        charge_name || ' - ' || chargename || 
                        CASE 
                            WHEN config_charge_type = 'PER' THEN ' (' || percentage || '%)'
                            WHEN config_charge_type = 'BOTH' THEN ' (' || percentage || '%) + Base'
                            ELSE ''
                        END || ' - Currency: ' || determined_currency as description,
                        producttype,
                        schemetype,
                        productname,
                        productbin,
                        rule_reference,
                        config_reference,
                        action_reference,
                        created_at
                    FROM calculated_charges
                    ORDER BY cardid, rule_reference, determined_currency, calculated_amount DESC
                ),
                inserted_charges AS (
                    INSERT INTO card_charges (
                        cardid, cardnumber, accountid, charge_type, 
                        amount, currency, charge_date, charge_year, description,
                        card_type, scheme_type, productname, productbin, 
                        status, created_at
                    )
                    SELECT 
                        cardid,
                        cardnumber,
                        accountid,
                        charge_type,
                        calculated_amount as amount,
                        currency,
                        charge_date,
                        charge_year,
                        description,
                        producttype,
                        schemetype,
                        productname,
                        productbin,
                        'APPLIED',
                        created_at
                    FROM eligible_charges
                    WHERE calculated_amount > 0
                    RETURNING cardid, amount, currency, charge_type
                ),
                currency_summary_batch AS (
                    SELECT 
                        currency,
                        COUNT(*) as charge_count,
                        SUM(amount) as total_amount
                    FROM inserted_charges
                    GROUP BY currency
                )
                SELECT 
                    COALESCE(SUM(csb.charge_count), 0),
                    COALESCE(SUM(csb.total_amount), 0),
                    COALESCE(jsonb_object_agg(
                        csb.currency,
                        jsonb_build_object(
                            'charge_count', csb.charge_count,
                            'total_amount', csb.total_amount
                        )
                    ), '{}'::JSONB)
                INTO 
                    v_batch_inserted_count,
                    v_batch_total_amount,
                    v_currency_summary
                FROM currency_summary_batch csb;

                -- Accumulate results
                v_inserted_count := v_inserted_count + v_batch_inserted_count;
                v_total_amount := v_total_amount + v_batch_total_amount;

                -- Exit loop if no more cards
                EXIT WHEN v_batch_inserted_count = 0;
                
                -- Small delay to prevent resource contention
                PERFORM pg_sleep(0.01);
                
            END LOOP;  -- End batch loop
            
            v_charge_calculation_time := EXTRACT(EPOCH FROM (clock_timestamp() - v_start_time)) - v_charge_calculation_time;

            IF p_debug_level >= 1 THEN
                RAISE NOTICE 'Completed %: % charges inserted', 
                    v_current_charge_type, v_inserted_count;
            END IF;
            
        END LOOP;  -- End charge type loop

        -- Calculate final metrics
        v_end_time := clock_timestamp();
        v_processing_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        v_metrics := jsonb_build_object(
            'total_processing_time', ROUND(v_processing_time, 4),
            'batches_processed', v_batch_count,
            'processed_charges', v_inserted_count,
            'total_amount', v_total_amount,
            'currency_summary', v_currency_summary,
            'cards_before_waiver', v_total_cards_before_waiver,
            'first_year_cards_waived', v_first_year_cards_count
        );

        -- Determine final message
        IF v_total_cards_before_waiver > 0 AND v_inserted_count = 0 AND v_first_year_cards_count > 0 THEN
            v_final_message := 'Charges waived for ' || v_first_year_cards_count || ' first-year cards. No charges applied.';
        ELSIF v_inserted_count > 0 THEN
            v_final_message := 'Successfully processed ' || v_inserted_count || ' charges totaling ' || v_total_amount;
        ELSE
            v_final_message := 'No eligible cards found for charge application.';
        END IF;

        -- Log successful completion
        PERFORM log_operation_completion(
            v_operation_id,
            'SUCCESS',
            v_total_cards_before_waiver,  -- Log total eligible before waiver
            v_inserted_count,
            v_total_amount,
            NULL,
            jsonb_build_object(
                'performance_metrics', v_metrics,
                'charge_types_processed', v_charge_types_to_process,
                'first_year_cards_waived', v_first_year_cards_count
            )
        );

        -- Return success results
        RETURN QUERY SELECT 
            'SUCCESS'::VARCHAR(20),
            v_inserted_count,
            v_total_amount,
            v_final_message,
            v_operation_id,
            v_metrics;

    EXCEPTION
        WHEN others THEN
            GET STACKED DIAGNOSTICS 
                v_error_message = MESSAGE_TEXT,
                v_error_detail = PG_EXCEPTION_DETAIL,
                v_sql_state = RETURNED_SQLSTATE;

            v_end_time := clock_timestamp();
            v_processing_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));

            RAISE NOTICE 'Error: %', v_error_message;

            v_metrics := jsonb_build_object(
                'total_processing_time', ROUND(v_processing_time, 4),
                'error_phase', 'charge_type_' || v_current_charge_type
            );

            PERFORM log_error(
                v_operation_id,
                'fdaemonapply_dynamic_charges',
                v_error_message,
                v_error_detail,
                v_sql_state,
                'Charge application process',
                jsonb_build_object(
                    'current_charge_type', v_current_charge_type
                )
            );

            PERFORM log_operation_completion(
                v_operation_id,
                'FAILED',
                v_total_cards_before_waiver,
                v_inserted_count,
                v_total_amount,
                v_error_message,
                jsonb_build_object('error_metrics', v_metrics)
            );

            RETURN QUERY SELECT 
                'FAILED'::VARCHAR(20),
                v_inserted_count,
                v_total_amount,
                'Failed: ' || v_error_message,
                v_operation_id,
                v_metrics;
    END;

END;
$$;


ALTER FUNCTION public.fdaemonapply_dynamic_charges(p_debug_level integer, p_batch_size integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: fdebit_getrequestdetailsbybatchidforswitch(character varying, character varying[], character varying, character varying, json, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fdebit_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying DEFAULT NULL::character varying, p_search_criteria json DEFAULT NULL::json, p_debug_level integer DEFAULT 0, p_page_number integer DEFAULT 1, p_page_size integer DEFAULT 100, p_include_data boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$

DECLARE
    v_batch_id VARCHAR(12);
    v_timestamp VARCHAR(50);
    v_record RECORD;
    v_counter INTEGER;
    v_total_records INTEGER;
    v_query TEXT;
    v_count_query TEXT;
    v_where_conditions TEXT;
    v_criteria JSON;
    v_column_name VARCHAR(100);
    v_column_value TEXT;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_result JSONB;
    v_batch_results JSONB[];
    v_batch_result JSONB;
    v_offset INTEGER;
    v_data JSONB[];
    v_row JSONB;
    v_error_context TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_execution_time_ms NUMERIC;
    v_function_name TEXT := 'fdebit_getRequestDetailsByBatchidforSwitch';
    v_json_record JSONB;
BEGIN
    -- Initialize result
    v_result := jsonb_build_object(
        'success', false,
        'timestamp', CURRENT_TIMESTAMP,
        'function_name', v_function_name,
        'action', p_action,
        'user', p_user,
        'debug_level', p_debug_level,
        'total_batches_processed', 0,
        'total_records_affected', 0,
        'execution_time_ms', 0,
        'error', NULL,
        'batches', '[]'::jsonb
    );
    
    -- Start timing
    v_start_time := clock_timestamp();
    
    -- Create timestamp for audit
    v_timestamp := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD_HH24MISS');
    
    -- Log function start at debug level 1
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'DEBIT_CARD_APPLICATIONS',
                'FUNCTION_START',
                v_function_name || ' started',
                jsonb_build_object(
                    'action', p_action,
                    'batch_ids', p_batch_ids,
                    'user', p_user,
                    'debug_level', p_debug_level,
                    'search_criteria', p_search_criteria,
                    'new_status', p_new_status,
                    'page_number', p_page_number,
                    'page_size', p_page_size,
                    'include_data', p_include_data
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    -- Calculate offset for pagination
    v_offset := (p_page_number - 1) * p_page_size;
    
    -- Initialize batch results array
    v_batch_results := ARRAY[]::JSONB[];
    
    -- Validate input parameters with error handling
    BEGIN
        IF p_action NOT IN ('SEARCH', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'Invalid action: %. Use SEARCH, UPDATE, or DELETE', p_action
            USING ERRCODE = '22000';
        END IF;
        
        IF p_batch_ids IS NULL OR array_length(p_batch_ids, 1) = 0 THEN
            RAISE EXCEPTION 'No batch IDs provided'
            USING ERRCODE = '22001';
        END IF;
        
        IF p_action = 'UPDATE' AND (p_new_status IS NULL OR p_new_status = '') THEN
            RAISE EXCEPTION 'New status is required for UPDATE action'
            USING ERRCODE = '22002';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'DEBIT_CARD_APPLICATIONS',
                'VALIDATION_ERROR',
                'Input validation failed',
                jsonb_build_object(
                    'function', v_function_name,
                    'error_message', v_error_message,
                    'error_detail', v_error_detail,
                    'error_hint', v_error_hint,
                    'sql_state', SQLSTATE
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
        
        -- Calculate execution time
        v_end_time := clock_timestamp();
        v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
        
        -- Return error result
        v_result := v_result || jsonb_build_object(
            'success', false,
            'execution_time_ms', v_execution_time_ms,
            'error', jsonb_build_object(
                'message', v_error_message,
                'detail', v_error_detail,
                'hint', v_error_hint,
                'sql_state', SQLSTATE
            )
        );
        
        RETURN v_result;
    END;
    
    -- Process each batch ID
    FOR i IN 1..array_length(p_batch_ids, 1)
    LOOP
        v_batch_id := p_batch_ids[i];
        v_counter := 0;
        v_total_records := 0;
        v_data := ARRAY[]::JSONB[];
        v_where_conditions := 'WHERE batch_id = ' || quote_literal(v_batch_id);
        
        -- Initialize batch result
        v_batch_result := jsonb_build_object(
            'batch_id', v_batch_id,
            'success', false,
            'records_affected', 0,
            'error', NULL
        );
        
        -- Log batch processing start
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'DEBIT_CARD_APPLICATIONS',
                    'BATCH_START',
                    'Processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'sequence', i
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
        
        -- Process based on action
        BEGIN
            IF p_action = 'SEARCH' THEN
                -- Build WHERE conditions for search
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        -- Handle numeric fields from debit_card_application
                        IF v_column_name IN ('dap_gros_sal1', 'dap_net_sal1', 'dap_gros_sal2', 'dap_net_sal2', 'dap_empl_age1', 'dap_empl_age2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || v_column_value;
                        -- Handle date fields
                        ELSIF v_column_name IN ('dap_date', 'dap_birt_dat1', 'dap_birt_dat2', 'dap_deci_date', 'dap_requ_effe_date', 'dap_requ_expi_date') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle boolean/character fields
                        ELSIF v_column_name IN ('dap_cus_type', 'dap_cus_old_new', 'dap_gend1', 'dap_gend2', 'dap_tit1', 'dap_tit2', 'dap_old_new_acct', 'dap_pan_gene_manu_auto', 'dap_prim_seco_card', 'dap_gree_pin_flag') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle specific identification fields
                        ELSIF v_column_name IN ('dap_cus_iden', 'dap_firs_ide1', 'dap_firs_ide2', 'dap_seco_ide1', 'dap_seco_ide2', 'dap_requ_acc_numb', 'dap_requ_card_numb') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        -- Handle other text fields with case-insensitive search
                        ELSIF v_column_name IN ('dap_firs_nam1', 'dap_last_nam1', 'dap_midd_nam1', 'dap_firs_nam2', 'dap_last_nam2', 'dap_midd_nam2', 'dap_empl_nam1', 'dap_empl_nam2', 'dap_birt_loc1', 'dap_birt_loc2', 'dap_email_adr') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' ILIKE ' || quote_literal('%' || v_column_value || '%');
                        -- Handle exact match for other fields
                        ELSE
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Get total count for pagination
                v_count_query := 'SELECT COUNT(*) FROM public.debit_card_application ' || v_where_conditions;
                EXECUTE v_count_query INTO v_total_records;
                
                -- Build search query with pagination
                v_query := 'SELECT row_to_json(dca) as row_data 
                            FROM public.debit_card_application dca ' || 
                            v_where_conditions || 
                            ' ORDER BY created_at DESC ' ||
                            ' LIMIT ' || p_page_size || 
                            ' OFFSET ' || v_offset;
                
                -- Execute query and collect data
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add to data array
                    v_data := array_append(v_data, v_json_record);
                END LOOP;
                
                -- Update batch result for SEARCH
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'SEARCH',
                    'records_found', v_counter,
                    'total_records', v_total_records,
                    'pagination', jsonb_build_object(
                        'page_number', p_page_number,
                        'page_size', p_page_size,
                        'total_pages', CASE WHEN p_page_size > 0 THEN CEIL(v_total_records::NUMERIC / p_page_size) ELSE 1 END
                    )
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'data', v_data
                    );
                END IF;
                
                -- Log successful search
                IF p_debug_level >= 1 AND v_counter > 0 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'DEBIT_CARD_APPLICATIONS',
                            'SEARCH_COMPLETED',
                            'Search completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_found', v_counter,
                                'total_records', v_total_records
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'UPDATE' THEN
                -- For UPDATE, we need to update the status-related fields
                -- Since there's no statusflag column in debit_card_application,
                -- we'll update dap_deci_auth and dap_deci_date as status indicators
                
                -- Build WHERE conditions for update
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_firs_ide1' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_firs_ide1 = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_requ_acc_numb' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_requ_acc_numb = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_deci_auth' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_deci_auth = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Execute update with RETURNING clause
                v_query := 'UPDATE public.debit_card_application 
                            SET dap_deci_auth = ' || quote_literal(p_new_status) || 
                           ', dap_deci_date = CURRENT_DATE' ||
                           ', updated_at = CURRENT_TIMESTAMP ' ||
                           v_where_conditions || 
                           ' RETURNING row_to_json(debit_card_application.*) as row_data';
                
                -- Execute update and count affected rows
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add minimal info to data array
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'dap_firs_nam1', v_json_record->>'dap_firs_nam1',
                        'dap_last_nam1', v_json_record->>'dap_last_nam1',
                        'old_decision_auth', v_json_record->>'dap_deci_auth',
                        'new_decision_auth', p_new_status,
                        'decision_date', v_json_record->>'dap_deci_date'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Update batch result for UPDATE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'UPDATE',
                    'records_affected', v_counter,
                    'new_decision_auth', p_new_status,
                    'updated_by', p_user
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'updated_records', v_data
                    );
                END IF;
                
                -- Log successful update
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'DEBIT_CARD_APPLICATIONS',
                            'UPDATE_COMPLETED',
                            'Decision update completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_updated', v_counter,
                                'new_decision_auth', p_new_status
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'DELETE' THEN
                -- Build WHERE conditions for deletion
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_deci_auth' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_deci_auth = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- First, select records to be deleted
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT dap_iden, dap_cus_iden, dap_firs_nam1, dap_last_nam1, dap_deci_auth, dap_deci_date 
                                FROM public.debit_card_application ' || 
                                v_where_conditions || 
                            ') t';
                
                FOR v_record IN EXECUTE v_query
                LOOP
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Store record info before deletion
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'dap_firs_nam1', v_json_record->>'dap_firs_nam1',
                        'dap_last_nam1', v_json_record->>'dap_last_nam1',
                        'decision_auth', v_json_record->>'dap_deci_auth',
                        'decision_date', v_json_record->>'dap_deci_date'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Execute deletion
                v_query := 'DELETE FROM public.debit_card_application ' || v_where_conditions;
                EXECUTE v_query;
                GET DIAGNOSTICS v_counter = ROW_COUNT;
                
                -- Update batch result for DELETE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'DELETE',
                    'records_deleted', v_counter
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'deleted_records', v_data
                    );
                END IF;
                
                -- Log successful deletion
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'DEBIT_CARD_APPLICATIONS',
                            'DELETE_COMPLETED',
                            'Deletion completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_deleted', v_counter
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
            END IF;
            
            -- Update batch result with success
            v_batch_result := v_batch_result || jsonb_build_object(
                'records_affected', v_counter,
                'processed_at', CURRENT_TIMESTAMP
            );
            
            -- Add to batch results array
            v_batch_results := array_append(v_batch_results, v_batch_result);
            
            -- Update total records
            v_result := v_result || jsonb_build_object(
                'total_records_affected', (v_result->>'total_records_affected')::INTEGER + v_counter
            );
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS 
                v_error_message = MESSAGE_TEXT,
                v_error_detail = PG_EXCEPTION_DETAIL,
                v_error_hint = PG_EXCEPTION_HINT,
                v_error_context = PG_EXCEPTION_CONTEXT;
            
            -- Log batch error
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'DEBIT_CARD_APPLICATIONS',
                    'BATCH_ERROR',
                    'Error processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'error_message', v_error_message,
                        'error_detail', v_error_detail,
                        'error_hint', v_error_hint,
                        'error_context', v_error_context,
                        'sql_state', SQLSTATE
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            
            -- Update batch result with error
            v_batch_result := v_batch_result || jsonb_build_object(
                'success', false,
                'error', jsonb_build_object(
                    'message', v_error_message,
                    'detail', v_error_detail,
                    'hint', v_error_hint,
                    'sql_state', SQLSTATE
                )
            );
            
            v_batch_results := array_append(v_batch_results, v_batch_result);
        END;
        
        -- Log batch completion
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'DEBIT_CARD_APPLICATIONS',
                    'BATCH_COMPLETE',
                    'Completed processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'records_affected', v_counter,
                        'success', v_batch_result->>'success'
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Prepare final result
    v_result := v_result || jsonb_build_object(
        'success', true,
        'execution_time_ms', v_execution_time_ms,
        'total_batches_processed', array_length(p_batch_ids, 1),
        'batches', to_jsonb(v_batch_results)
    );
    
    -- Log function completion
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'DEBIT_CARD_APPLICATIONS',
                'FUNCTION_COMPLETE',
                v_function_name || ' completed successfully',
                jsonb_build_object(
                    'execution_time_ms', v_execution_time_ms,
                    'total_batches', array_length(p_batch_ids, 1),
                    'total_records', v_result->>'total_records_affected'
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Global exception handler
    GET STACKED DIAGNOSTICS 
        v_error_message = MESSAGE_TEXT,
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT,
        v_error_context = PG_EXCEPTION_CONTEXT;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Log global error
    BEGIN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            created_at
        ) VALUES (
            'DEBIT_CARD_APPLICATIONS',
            'FUNCTION_ERROR',
            v_function_name || ' failed',
            jsonb_build_object(
                'error_message', v_error_message,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'error_context', v_error_context,
                'sql_state', SQLSTATE,
                'execution_time_ms', v_execution_time_ms
            ),
            p_user,
            CURRENT_TIMESTAMP
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    
    -- Return error result
    v_result := v_result || jsonb_build_object(
        'success', false,
        'execution_time_ms', v_execution_time_ms,
        'error', jsonb_build_object(
            'message', v_error_message,
            'detail', v_error_detail,
            'hint', v_error_hint,
            'context', v_error_context,
            'sql_state', SQLSTATE
        )
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fdebit_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying, p_search_criteria json, p_debug_level integer, p_page_number integer, p_page_size integer, p_include_data boolean) OWNER TO postgres;

--
-- Name: fdiag_comprehensivefunctionaltestv1_0_0(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fdiag_comprehensivefunctionaltestv1_0_0() RETURNS TABLE(test_id text, test_phase text, test_result text, details text, debug_info text, recommendation text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_test_result RECORD;
    v_success_count INTEGER := 0;
    v_total_tests INTEGER := 10;
    v_function_oid OID;
    v_return_type TEXT;
    v_param_count INTEGER;
    v_success_rate NUMERIC(5,2);
    v_skipped_tests INTEGER := 0;
    v_has_performance_metrics BOOLEAN := FALSE;
    v_has_operation_status BOOLEAN := FALSE;
    v_param_list TEXT := '';
    v_func_name TEXT := 'fdaemonapply_dynamic_charges';
    v_test_start_time TIMESTAMP;
    v_test_end_time TIMESTAMP;
    v_execution_time INTERVAL;
BEGIN
    -- Initialize result table
    CREATE TEMP TABLE IF NOT EXISTS test_results (
        test_id TEXT,
        test_phase TEXT,
        test_result TEXT,
        details TEXT,
        debug_info TEXT,
        recommendation TEXT
    );
    
    -- Clear any existing results
    DELETE FROM test_results;
    
    v_test_start_time := clock_timestamp();
    
    -- =========================================================================
    -- TEST 8.1: Function Existence Check
    -- =========================================================================
    BEGIN
        SELECT p.oid INTO v_function_oid
        FROM pg_proc p 
        JOIN pg_namespace n ON p.pronamespace = n.oid 
        WHERE p.proname = v_func_name
        AND n.nspname NOT LIKE 'pg_%' 
        AND n.nspname != 'information_schema';
        
        IF v_function_oid IS NOT NULL THEN
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.1',
                'Function Existence Check',
                'PASS',
                'Function ' || v_func_name || ' exists in database',
                'OID: ' || v_function_oid || ', Schema: public',
                'Function is properly registered in system catalog'
            );
        ELSE
            INSERT INTO test_results VALUES (
                '8.1',
                'Function Existence Check',
                'FAIL',
                'Function ' || v_func_name || ' not found',
                'Searched in user schemas excluding system schemas',
                'Check if function was created in correct schema or verify function name spelling'
            );
        END IF;
        
    EXCEPTION WHEN others THEN
        INSERT INTO test_results VALUES (
            '8.1',
            'Function Existence Check',
            'ERROR',
            'Database query failed: ' || SQLERRM,
            'Error during pg_proc catalog query',
            'Check database connectivity and user permissions'
        );
    END;
    
    -- =========================================================================
    -- TEST 8.2: Function Signature Analysis
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT format_type(p.prorettype, NULL), p.pronargs 
            INTO v_return_type, v_param_count
            FROM pg_proc p 
            WHERE p.oid = v_function_oid;
            
            -- Get parameter information
            SELECT string_agg(
                COALESCE(pa.param_name, 'param' || pa.param_index) || ' ' || 
                format_type(pa.param_type, NULL), ', ' ORDER BY pa.param_index
            ) INTO v_param_list
            FROM (
                SELECT row_number() OVER () as param_index,
                       unnest(COALESCE(p.proargnames, ARRAY[]::text[])) as param_name,
                       unnest(p.proargtypes) as param_type
                FROM pg_proc p WHERE p.oid = v_function_oid
            ) pa;
            
            IF v_param_list IS NULL THEN
                v_param_list := 'No parameters or unable to determine';
            END IF;
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.2',
                'Function Signature Analysis',
                'PASS',
                'Function signature validated',
                'Return Type: ' || COALESCE(v_return_type, 'unknown') || 
                ' | Parameters: ' || v_param_list || 
                ' | Parameter Count: ' || v_param_count,
                'Function interface matches expected signature'
            );
                         
        EXCEPTION WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.2',
                'Function Signature Analysis',
                'FAIL',
                'Cannot analyze function signature',
                'Error: ' || SQLERRM || ' | OID: ' || v_function_oid,
                'Check function definition in pg_proc system catalog'
            );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.2',
            'Function Signature Analysis',
            'SKIPPED',
            'Function not available for signature check',
            'v_function_oid is NULL from previous test',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.3: Function Privileges Check
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            PERFORM 1 FROM pg_proc p
            JOIN pg_namespace n ON p.pronamespace = n.oid
            WHERE p.oid = v_function_oid
            AND has_function_privilege(p.oid, 'execute');
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.3',
                'Function Privileges Check',
                'PASS',
                'Current user has EXECUTE privilege on function',
                'Function OID: ' || v_function_oid || ' | Privilege: EXECUTE',
                'Function permissions are properly configured'
            );
            
        EXCEPTION WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.3',
                'Function Privileges Check',
                'FAIL',
                'Privilege check failed',
                'Error: ' || SQLERRM || ' | Function: ' || v_func_name,
                'Grant EXECUTE privilege: GRANT EXECUTE ON FUNCTION ' || v_func_name || ' TO current_user'
            );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.3',
            'Function Privileges Check',
            'SKIPPED',
            'Cannot check privileges - function not found',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.4: Basic Function Execution
    -- =========================================================================
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_dry_run => true) 
            LIMIT 1;
            
            v_success_count := v_success_count + 1;
            
            -- Analyze return structure
            DECLARE
                v_field_list TEXT := '';
            BEGIN
                SELECT string_agg(attname, ', ') INTO v_field_list
                FROM pg_attribute 
                WHERE attrelid = (SELECT typrelid FROM pg_type WHERE oid = (SELECT prorettype FROM pg_proc WHERE oid = v_function_oid))
                AND attnum > 0 AND NOT attisdropped;
                
                -- Check for specific fields
                BEGIN
                    IF v_test_result.operation_status IS NOT NULL THEN
                        v_has_operation_status := TRUE;
                    END IF;
                EXCEPTION WHEN others THEN
                    v_has_operation_status := FALSE;
                END;
                
                BEGIN
                    IF v_test_result.performance_metrics IS NOT NULL THEN
                        v_has_performance_metrics := TRUE;
                    END IF;
                EXCEPTION WHEN others THEN
                    v_has_performance_metrics := FALSE;
                END;
                
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
                    'PASS',
                    'Function executed successfully in dry-run mode',
                    'Return fields detected: ' || COALESCE(v_field_list, 'unknown') || 
                    ' | operation_status: ' || v_has_operation_status || 
                    ' | performance_metrics: ' || v_has_performance_metrics,
                    'Function is operational and returning expected data structure'
                );
            EXCEPTION WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
                    'PASS',
                    'Function executed but return structure analysis failed',
                    'Execution successful | Structure analysis error: ' || SQLERRM,
                    'Verify function return type matches expected structure'
                );
            END;
                         
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.4',
                    'Basic Function Execution',
                    'FAIL',
                    'Function execution failed',
                    'Error: ' || SQLERRM || ' | Parameters: p_dry_run=true',
                    'Check function implementation, parameter types, and dependencies'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.4',
            'Basic Function Execution',
            'SKIPPED',
            'Cannot execute - function not found',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- TEST 8.5: Operation Logging Verification
    -- =========================================================================
    BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'operation_logs') THEN
            PERFORM 1 FROM operation_logs 
            WHERE function_name = 'fdaemonapply_dynamic_charges' 
            LIMIT 1;
            
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'PASS',
                'Operation logging is active and contains function records',
                'Found records in operation_logs for function: ' || v_func_name,
                'Logging system is properly capturing function executions'
            );
        ELSE
            v_skipped_tests := v_skipped_tests + 1;
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'SKIPPED',
                'operation_logs table does not exist',
                'Table operation_logs not found in current schema',
                'Create operation_logs table or check schema permissions'
            );
        END IF;
    EXCEPTION
        WHEN others THEN
            INSERT INTO test_results VALUES (
                '8.5',
                'Operation Logging Verification',
                'FAIL',
                'Operation logging check failed',
                'Error: ' || SQLERRM || ' | Table: operation_logs',
                'Check table permissions and structure'
            );
    END;
    
    -- =========================================================================
    -- TESTS 8.6-8.10: Additional Functional Tests
    -- =========================================================================
    
    -- Test 8.6: Return Structure Validation
    IF v_function_oid IS NOT NULL AND v_has_operation_status THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_dry_run => true);       
            
            IF v_test_result.operation_status IS NOT NULL THEN
                v_success_count := v_success_count + 1;
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'PASS',
                    'Return structure contains valid operation_status',
                    'operation_status: ' || v_test_result.operation_status,
                    'Function return structure meets expectations'
                );
            ELSE
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'FAIL',
                    'operation_status field is null',
                    'Expected non-null operation_status in return data',
                    'Check function logic for operation_status assignment'
                );
            END IF;
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.6',
                    'Return Structure Validation',
                    'FAIL',
                    'Structure validation failed',
                    'Error: ' || SQLERRM,
                    'Verify function return type consistency'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.6',
            'Return Structure Validation',
            'SKIPPED',
            'Cannot validate structure - function or field not available',
            'Function available: ' || (v_function_oid IS NOT NULL) || 
            ' | operation_status field: ' || v_has_operation_status,
            'Ensure function exists and returns operation_status field'
        );
    END IF;
    
    -- Test 8.7: Performance Metrics Check
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_debug_level => 1, p_dry_run => true);
            
            IF v_has_performance_metrics THEN
                IF v_test_result.performance_metrics IS NOT NULL THEN
                    v_success_count := v_success_count + 1;
                    INSERT INTO test_results VALUES (
                        '8.7',
                        'Performance Metrics Check',
                        'PASS',
                        'Performance metrics are collected',
                        'performance_metrics: ' || v_test_result.performance_metrics,
                        'Performance monitoring is active'
                    );
                ELSE
                    INSERT INTO test_results VALUES (
                        '8.7',
                        'Performance Metrics Check',
                        'FAIL',
                        'performance_metrics field is null with debug_level=1',
                        'Expected performance data with debug_level=1',
                        'Check performance metrics collection logic in function'
                    );
                END IF;
            ELSE
                v_success_count := v_success_count + 1;
                INSERT INTO test_results VALUES (
                    '8.7',
                    'Performance Metrics Check',
                    'PASS',
                    'Function executed with debug_level=1',
                    'No performance_metrics field in return type',
                    'Consider adding performance metrics to return type'
                );
            END IF;
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.7',
                    'Performance Metrics Check',
                    'FAIL',
                    'Performance test failed',
                    'Error: ' || SQLERRM || ' | Parameters: p_debug_level=1, p_dry_run=true',
                    'Check function handling of debug_level parameter'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.7',
            'Performance Metrics Check',
            'SKIPPED',
            'Cannot test performance - function not available',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- Test 8.8: Debug Level 0 Functionality
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_debug_level => 0, p_dry_run => true);
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.8',
                'Debug Level 0 Functionality',
                'PASS',
                'Function works with debug_level=0',
                'Execution successful with minimal debug level',
                'Function handles different debug levels correctly'
            );
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.8',
                    'Debug Level 0 Functionality',
                    'FAIL',
                    'Function failed with debug_level=0',
                    'Error: ' || SQLERRM || ' | Parameters: p_debug_level=0, p_dry_run=true',
                    'Check function logic for debug_level=0 handling'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.8',
            'Debug Level 0 Functionality',
            'SKIPPED',
            'Cannot test debug levels - function not available',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- Test 8.9: Batch Processing Parameter
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_batch_size => 5, p_dry_run => true);
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.9',
                'Batch Processing Parameter',
                'PASS',
                'Batch size parameter works correctly',
                'Execution successful with p_batch_size=5',
                'Batch processing functionality is operational'
            );
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.9',
                    'Batch Processing Parameter',
                    'FAIL',
                    'Batch size parameter failed',
                    'Error: ' || SQLERRM || ' | Parameters: p_batch_size=5, p_dry_run=true',
                    'Check batch size parameter validation in function'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.9',
            'Batch Processing Parameter',
            'SKIPPED',
            'Cannot test batch processing - function not available',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- Test 8.10: Actual Execution (Non-Dry Run)
    IF v_function_oid IS NOT NULL THEN
        BEGIN
            SELECT * INTO v_test_result 
            FROM fdaemonapply_dynamic_charges(p_batch_size => 1, p_dry_run => false);
            v_success_count := v_success_count + 1;
            INSERT INTO test_results VALUES (
                '8.10',
                'Actual Execution Test',
                'PASS',
                'Actual execution (non-dry-run) works',
                'Execution successful with p_dry_run=false',
                'Function is ready for production execution'
            );
        EXCEPTION
            WHEN others THEN
                INSERT INTO test_results VALUES (
                    '8.10',
                    'Actual Execution Test',
                    'FAIL',
                    'Actual execution failed',
                    'Error: ' || SQLERRM || ' | Parameters: p_batch_size=1, p_dry_run=false',
                    'Check function logic for actual execution path and data modifications'
                );
        END;
    ELSE
        v_skipped_tests := v_skipped_tests + 1;
        INSERT INTO test_results VALUES (
            '8.10',
            'Actual Execution Test',
            'SKIPPED',
            'Cannot test actual execution - function not available',
            'v_function_oid is NULL',
            'Resolve function existence issue first'
        );
    END IF;
    
    -- =========================================================================
    -- FINAL SUMMARY AND STATISTICS
    -- =========================================================================
    v_test_end_time := clock_timestamp();
    v_execution_time := v_test_end_time - v_test_start_time;
    
    v_total_tests := v_total_tests - v_skipped_tests;
    
    IF v_total_tests > 0 THEN
        v_success_rate := ROUND((v_success_count::NUMERIC / v_total_tests) * 100, 2);
    ELSE
        v_success_rate := 0;
    END IF;
    
    -- Add comprehensive summary
    INSERT INTO test_results VALUES (
        'SUMMARY',
        '=== COMPREHENSIVE TEST SUMMARY ===',
        'STATISTICS',
        'Test execution completed: ' || v_success_count || '/' || v_total_tests || ' tests passed',
        'Execution Time: ' || EXTRACT(EPOCH FROM v_execution_time) || ' seconds | ' ||
        'Success Rate: ' || v_success_rate || '% | ' ||
        'Skipped Tests: ' || v_skipped_tests || ' | ' ||
        'Failed Tests: ' || (v_total_tests - v_success_count),
        CASE 
            WHEN v_success_rate = 100 THEN '🎉 ALL TESTS PASSED! System is fully operational.'
            WHEN v_success_rate >= 80 THEN '✅ EXCELLENT: System is ready for production use.'
            WHEN v_success_rate >= 70 THEN '⚠️ GOOD: System is functional but review failed tests.'
            WHEN v_success_rate >= 50 THEN '🔶 FAIR: System has issues that need attention.'
            ELSE '❌ POOR: Multiple critical failures detected.'
        END
    );
    
    -- Return all test results - FIXED: Use proper numeric conversion
    RETURN QUERY SELECT 
        tr.test_id,
        tr.test_phase, 
        tr.test_result,
        tr.details,
        tr.debug_info,
        tr.recommendation
    FROM test_results tr
    ORDER BY 
        CASE 
            WHEN tr.test_id = 'SUMMARY' THEN 999
            ELSE REPLACE(tr.test_id, '.', '')::INTEGER  -- Remove decimal point before conversion
        END;
    
    -- Cleanup
    DROP TABLE IF EXISTS test_results;
END;
$$;


ALTER FUNCTION public.fdiag_comprehensivefunctionaltestv1_0_0() OWNER TO postgres;

--
-- Name: femail_logs(character varying, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.femail_logs(p_action character varying, p_data jsonb, p_debug_level integer DEFAULT 0, p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_record RECORD;
    v_sql TEXT;
    v_count INTEGER;
    v_email_id UUID;
    v_audit_data JSONB;
    v_debug_info JSONB;
BEGIN
    -- Initialize debug info
    v_debug_info := jsonb_build_object(
        'action', p_action,
        'debug_level', p_debug_level,
        'input_data', p_data
    );
    
    -- Validate action (logs are mostly read-only, but allow insert for logging)
    IF p_action NOT IN ('insert', 'search') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Only insert and search actions are allowed for email logs'
        );
    END IF;
    
    CASE p_action
        WHEN 'insert' THEN
            -- Validate required fields
            IF NOT (p_data ? 'email_id' AND p_data ? 'action') THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Missing required fields: email_id, action'
                );
            END IF;
            
            -- Insert log
            INSERT INTO email_logs (
                email_id,
                action,
                details,
                ip_address,
                user_agent
            ) VALUES (
                (p_data->>'email_id')::uuid,
                p_data->>'action',
                p_data->'details',
                (p_data->>'ip_address')::inet,
                p_data->>'user_agent'
            ) RETURNING id, email_id INTO v_record;
            
            -- Log audit trail (logging the log!)
            PERFORM flog_audit_trail(
                'EMAIL_LOGS',
                'INSERT',
                'Added email log for email_id: ' || v_record.email_id,
                jsonb_build_object(
                    'log_id', v_record.id,
                    'email_id', v_record.email_id,
                    'action', p_data->>'action'
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Email log added successfully',
                'data', jsonb_build_object('id', v_record.id, 'email_id', v_record.email_id)
            );
            
        WHEN 'search' THEN
            -- Build search query
            v_sql := 'SELECT * FROM email_logs WHERE 1=1';
            
            IF p_data ? 'email_id' THEN
                v_sql := v_sql || ' AND email_id = ' || quote_literal(p_data->>'email_id');
            END IF;
            IF p_data ? 'action' THEN
                v_sql := v_sql || ' AND action = ' || quote_literal(p_data->>'action');
            END IF;
            IF p_data ? 'date_from' THEN
                v_sql := v_sql || ' AND created_at >= ' || quote_literal(p_data->>'date_from');
            END IF;
            IF p_data ? 'date_to' THEN
                v_sql := v_sql || ' AND created_at <= ' || quote_literal(p_data->>'date_to');
            END IF;
            
            -- Order by creation time
            v_sql := v_sql || ' ORDER BY created_at DESC';
            
            -- Add limit if specified
            IF p_data ? 'limit' THEN
                v_sql := v_sql || ' LIMIT ' || (p_data->>'limit')::integer;
            END IF;
            
            -- Execute query and return as JSON
            EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_sql || ') t' 
            INTO v_result;
            
            -- Count results
            v_sql := 'SELECT COUNT(*) FROM email_logs WHERE 1=1';
            IF p_data ? 'email_id' THEN
                v_sql := v_sql || ' AND email_id = ' || quote_literal(p_data->>'email_id');
            END IF;
            
            EXECUTE v_sql INTO v_count;
            
            RETURN jsonb_build_object(
                'success', true,
                'data', v_result,
                'total_count', v_count
            );
            
    END CASE;
    
    -- Add debug info if requested
    IF p_debug_level >= 1 THEN
        v_result := v_result || jsonb_build_object('debug', v_debug_info);
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        PERFORM flog_audit_trail(
            'EMAIL_LOGS_FUNCTION',
            'ERROR',
            'Error in f_manage_email_logs: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'action', p_action
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Database error: ' || SQLERRM
        );
END;
$$;


ALTER FUNCTION public.femail_logs(p_action character varying, p_data jsonb, p_debug_level integer, p_id uuid) OWNER TO postgres;

--
-- Name: femail_queue(character varying, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.femail_queue(p_action character varying, p_data jsonb, p_debug_level integer DEFAULT 0, p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_record RECORD;
    v_sql TEXT;
    v_count INTEGER;
    v_recipient_email VARCHAR;
    v_audit_data JSONB;
    v_debug_info JSONB;
BEGIN
    -- Initialize debug info
    v_debug_info := jsonb_build_object(
        'action', p_action,
        'debug_level', p_debug_level,
        'input_data', p_data
    );
    
    -- Validate action
    IF p_action NOT IN ('insert', 'update', 'delete', 'search') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action'
        );
    END IF;
    
    CASE p_action
        WHEN 'insert' THEN
            -- Validate required fields
            IF NOT (p_data ? 'recipient_email' AND p_data ? 'subject' AND p_data ? 'body') THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Missing required fields: recipient_email, subject, body'
                );
            END IF;
            
            -- Insert into queue
            INSERT INTO email_queue (
                template_id,
                recipient_email,
                recipient_name,
                subject,
                body,
                variables_used,
                status,
                user_id,
                card_details,
                scheduled_for,
                sent_at
            ) VALUES (
                (p_data->>'template_id')::uuid,
                p_data->>'recipient_email',
                p_data->>'recipient_name',
                p_data->>'subject',
                p_data->>'body',
                COALESCE(p_data->'variables_used', '{}'::jsonb),
                COALESCE(p_data->>'status', 'pending'),
                (p_data->>'user_id')::integer,
                p_data->'card_details',
                COALESCE((p_data->>'scheduled_for')::timestamp, CURRENT_TIMESTAMP),
                (p_data->>'sent_at')::timestamp
            ) RETURNING id, recipient_email INTO v_record;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_QUEUE',
                'INSERT',
                'Added email to queue for: ' || v_record.recipient_email,
                jsonb_build_object(
                    'queue_id', v_record.id,
                    'recipient', v_record.recipient_email,
                    'status', COALESCE(p_data->>'status', 'pending')
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Email added to queue successfully',
                'data', jsonb_build_object('id', v_record.id, 'recipient_email', v_record.recipient_email)
            );
            
        WHEN 'update' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for update'
                );
            END IF;
            
            -- Get current recipient email
            SELECT recipient_email INTO v_recipient_email 
            FROM email_queue 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Email queue entry not found'
                );
            END IF;
            
            -- Build update statement for status and retry info
            v_sql := 'UPDATE email_queue SET';
            
            IF p_data ? 'status' THEN
                v_sql := v_sql || ' status = ' || quote_literal(p_data->>'status');
            END IF;
            IF p_data ? 'attempt_count' THEN
                v_sql := v_sql || ', attempt_count = ' || (p_data->>'attempt_count')::integer;
            END IF;
            IF p_data ? 'last_attempt_at' THEN
                v_sql := v_sql || ', last_attempt_at = ' || quote_literal(p_data->>'last_attempt_at');
            END IF;
            IF p_data ? 'error_message' THEN
                v_sql := v_sql || ', error_message = ' || quote_literal(p_data->>'error_message');
            END IF;
            IF p_data ? 'sent_at' THEN
                v_sql := v_sql || ', sent_at = ' || quote_literal(p_data->>'sent_at');
            END IF;
            
            v_sql := v_sql || ' WHERE id = ' || quote_literal(p_id::text);
            
            EXECUTE v_sql;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_QUEUE',
                'UPDATE',
                'Updated email queue entry for: ' || v_recipient_email,
                jsonb_build_object(
                    'queue_id', p_id,
                    'recipient', v_recipient_email,
                    'updates', p_data
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Email queue updated successfully',
                'rows_affected', v_count
            );
            
        WHEN 'delete' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for delete'
                );
            END IF;
            
            -- Get recipient email
            SELECT recipient_email INTO v_recipient_email 
            FROM email_queue 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Email queue entry not found'
                );
            END IF;
            
            -- Delete from queue
            DELETE FROM email_queue WHERE id = p_id;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_QUEUE',
                'DELETE',
                'Deleted email queue entry for: ' || v_recipient_email,
                jsonb_build_object(
                    'queue_id', p_id,
                    'recipient', v_recipient_email
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Email queue entry deleted successfully',
                'rows_deleted', v_count
            );
            
        WHEN 'search' THEN
            -- Build search query
            v_sql := 'SELECT * FROM email_queue WHERE 1=1';
            
            IF p_data ? 'status' THEN
                v_sql := v_sql || ' AND status = ' || quote_literal(p_data->>'status');
            END IF;
            IF p_data ? 'recipient_email' THEN
                v_sql := v_sql || ' AND recipient_email ILIKE ' || quote_literal('%' || (p_data->>'recipient_email') || '%');
            END IF;
            IF p_data ? 'user_id' THEN
                v_sql := v_sql || ' AND user_id = ' || (p_data->>'user_id')::integer;
            END IF;
            IF p_data ? 'template_id' THEN
                v_sql := v_sql || ' AND template_id = ' || quote_literal(p_data->>'template_id');
            END IF;
            IF p_data ? 'date_from' THEN
                v_sql := v_sql || ' AND created_at >= ' || quote_literal(p_data->>'date_from');
            END IF;
            IF p_data ? 'date_to' THEN
                v_sql := v_sql || ' AND created_at <= ' || quote_literal(p_data->>'date_to');
            END IF;
            
            -- Order by scheduled_for then created_at
            v_sql := v_sql || ' ORDER BY scheduled_for DESC, created_at DESC';
            
            -- Add limit if specified
            IF p_data ? 'limit' THEN
                v_sql := v_sql || ' LIMIT ' || (p_data->>'limit')::integer;
            END IF;
            
            -- Execute query and return as JSON
            EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_sql || ') t' 
            INTO v_result;
            
            -- Count results
            v_sql := 'SELECT COUNT(*) FROM email_queue WHERE 1=1';
            IF p_data ? 'status' THEN
                v_sql := v_sql || ' AND status = ' || quote_literal(p_data->>'status');
            END IF;
            IF p_data ? 'date_from' THEN
                v_sql := v_sql || ' AND created_at >= ' || quote_literal(p_data->>'date_from');
            END IF;
            
            EXECUTE v_sql INTO v_count;
            
            RETURN jsonb_build_object(
                'success', true,
                'data', v_result,
                'total_count', v_count
            );
            
    END CASE;
    
    -- Add debug info if requested
    IF p_debug_level >= 1 THEN
        v_result := v_result || jsonb_build_object('debug', v_debug_info);
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        PERFORM flog_audit_trail(
            'EMAIL_QUEUE_FUNCTION',
            'ERROR',
            'Error in f_manage_email_queue: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'action', p_action
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Database error: ' || SQLERRM
        );
END;
$$;


ALTER FUNCTION public.femail_queue(p_action character varying, p_data jsonb, p_debug_level integer, p_id uuid) OWNER TO postgres;

--
-- Name: femail_templates(character varying, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.femail_templates(p_action character varying, p_data jsonb, p_debug_level integer DEFAULT 0, p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_record RECORD;
    v_sql TEXT;
    v_where_clause TEXT := '';
    v_count INTEGER;
    v_template_name VARCHAR;
    v_description TEXT;
    v_audit_data JSONB;
    v_debug_info JSONB;
BEGIN
    -- Initialize debug info
    v_debug_info := jsonb_build_object(
        'action', p_action,
        'debug_level', p_debug_level,
        'input_data', p_data
    );
    
    -- Log function call at debug level 2+
    IF p_debug_level >= 2 THEN
        PERFORM flog_audit_trail(
            'EMAIL_TEMPLATES_FUNCTION',
            'CALL',
            'Function f_manage_email_templates called',
            v_debug_info
        );
    END IF;
    
    -- Validate action
    IF p_action NOT IN ('insert', 'update', 'delete', 'search') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be insert, update, delete, or search.'
        );
    END IF;
    
    CASE p_action
        WHEN 'insert' THEN
            -- Validate required fields
            IF NOT (p_data ? 'template_name' AND p_data ? 'subject' AND p_data ? 'body' AND p_data ? 'template_type') THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Missing required fields: template_name, subject, body, template_type'
                );
            END IF;
            
            -- Insert new template
            INSERT INTO email_templates (
                template_name,
                subject,
                body,
                template_type,
                card_type,
                event_type,
                is_active,
                created_by,
                variables
            ) VALUES (
                p_data->>'template_name',
                p_data->>'subject',
                p_data->>'body',
                p_data->>'template_type',
                p_data->>'card_type',
                p_data->>'event_type',
                COALESCE((p_data->>'is_active')::boolean, true),
                (p_data->>'created_by')::integer,
                COALESCE(p_data->'variables', '[]'::jsonb)
            ) RETURNING id, template_name INTO v_record;
            
            -- Prepare audit data
            v_audit_data := jsonb_build_object(
                'template_id', v_record.id,
                'template_name', v_record.template_name,
                'action', 'INSERT',
                'data', p_data
            );
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_TEMPLATES',
                'INSERT',
                'Created email template: ' || v_record.template_name,
                v_audit_data
            );
            
            -- Return success
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Template created successfully',
                'data', jsonb_build_object('id', v_record.id, 'template_name', v_record.template_name),
                'debug', CASE WHEN p_debug_level >= 1 THEN v_debug_info END
            );
            
        WHEN 'update' THEN
            -- Validate ID
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for update'
                );
            END IF;
            
            -- Get current template name for audit
            SELECT template_name INTO v_template_name 
            FROM email_templates 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Template not found'
                );
            END IF;
            
            -- Build update statement
            v_sql := 'UPDATE email_templates SET updated_at = CURRENT_TIMESTAMP';
            
            IF p_data ? 'template_name' THEN
                v_sql := v_sql || ', template_name = ' || quote_literal(p_data->>'template_name');
            END IF;
            IF p_data ? 'subject' THEN
                v_sql := v_sql || ', subject = ' || quote_literal(p_data->>'subject');
            END IF;
            IF p_data ? 'body' THEN
                v_sql := v_sql || ', body = ' || quote_literal(p_data->>'body');
            END IF;
            IF p_data ? 'template_type' THEN
                v_sql := v_sql || ', template_type = ' || quote_literal(p_data->>'template_type');
            END IF;
            IF p_data ? 'card_type' THEN
                v_sql := v_sql || ', card_type = ' || quote_literal(p_data->>'card_type');
            END IF;
            IF p_data ? 'event_type' THEN
                v_sql := v_sql || ', event_type = ' || quote_literal(p_data->>'event_type');
            END IF;
            IF p_data ? 'is_active' THEN
                v_sql := v_sql || ', is_active = ' || (p_data->>'is_active')::boolean;
            END IF;
            IF p_data ? 'variables' THEN
                v_sql := v_sql || ', variables = ' || quote_literal(p_data->>'variables');
            END IF;
            
            v_sql := v_sql || ' WHERE id = ' || quote_literal(p_id::text);
            
            -- Execute update
            EXECUTE v_sql;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            IF v_count = 0 THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Update failed or no changes made'
                );
            END IF;
            
            -- Log audit trail
            v_audit_data := jsonb_build_object(
                'template_id', p_id,
                'old_name', v_template_name,
                'new_data', p_data,
                'rows_affected', v_count
            );
            
            PERFORM flog_audit_trail(
                'EMAIL_TEMPLATES',
                'UPDATE',
                'Updated email template: ' || v_template_name,
                v_audit_data
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Template updated successfully',
                'rows_affected', v_count,
                'debug', CASE WHEN p_debug_level >= 1 THEN v_debug_info END
            );
            
        WHEN 'delete' THEN
            -- Validate ID
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for delete'
                );
            END IF;
            
            -- Get template name for audit
            SELECT template_name INTO v_template_name 
            FROM email_templates 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Template not found'
                );
            END IF;
            
            -- Check if template is in use
            SELECT COUNT(*) INTO v_count 
            FROM email_queue 
            WHERE template_id = p_id;
            
            IF v_count > 0 THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Cannot delete template. It is being used by ' || v_count || ' queued emails.'
                );
            END IF;
            
            -- Delete template
            DELETE FROM email_templates WHERE id = p_id;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            v_audit_data := jsonb_build_object(
                'template_id', p_id,
                'template_name', v_template_name,
                'rows_deleted', v_count
            );
            
            PERFORM flog_audit_trail(
                'EMAIL_TEMPLATES',
                'DELETE',
                'Deleted email template: ' || v_template_name,
                v_audit_data
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Template deleted successfully',
                'rows_deleted', v_count,
                'debug', CASE WHEN p_debug_level >= 1 THEN v_debug_info END
            );
            
        WHEN 'search' THEN
            -- Build search query
            v_sql := 'SELECT * FROM email_templates WHERE 1=1';
            
            IF p_data ? 'id' THEN
                v_sql := v_sql || ' AND id = ' || quote_literal(p_data->>'id');
            END IF;
            IF p_data ? 'template_name' THEN
                v_sql := v_sql || ' AND template_name ILIKE ' || quote_literal('%' || (p_data->>'template_name') || '%');
            END IF;
            IF p_data ? 'template_type' THEN
                v_sql := v_sql || ' AND template_type = ' || quote_literal(p_data->>'template_type');
            END IF;
            IF p_data ? 'card_type' THEN
                v_sql := v_sql || ' AND card_type = ' || quote_literal(p_data->>'card_type');
            END IF;
            IF p_data ? 'event_type' THEN
                v_sql := v_sql || ' AND event_type = ' || quote_literal(p_data->>'event_type');
            END IF;
            IF p_data ? 'is_active' THEN
                v_sql := v_sql || ' AND is_active = ' || (p_data->>'is_active')::boolean;
            END IF;
            IF p_data ? 'created_by' THEN
                v_sql := v_sql || ' AND created_by = ' || (p_data->>'created_by')::integer;
            END IF;
            
            -- Add ordering
            v_sql := v_sql || ' ORDER BY created_at DESC';
            
            -- Add limit if specified
            IF p_data ? 'limit' THEN
                v_sql := v_sql || ' LIMIT ' || (p_data->>'limit')::integer;
            END IF;
            
            -- Add offset if specified
            IF p_data ? 'offset' THEN
                v_sql := v_sql || ' OFFSET ' || (p_data->>'offset')::integer;
            END IF;
            
            -- Execute query
            EXECUTE v_sql INTO v_record;
            
            -- Count total records (without limit/offset for pagination)
            v_sql := 'SELECT COUNT(*) FROM email_templates WHERE 1=1';
            IF p_data ? 'template_name' THEN
                v_sql := v_sql || ' AND template_name ILIKE ' || quote_literal('%' || (p_data->>'template_name') || '%');
            END IF;
            IF p_data ? 'template_type' THEN
                v_sql := v_sql || ' AND template_type = ' || quote_literal(p_data->>'template_type');
            END IF;
            IF p_data ? 'is_active' THEN
                v_sql := v_sql || ' AND is_active = ' || (p_data->>'is_active')::boolean;
            END IF;
            
            EXECUTE v_sql INTO v_count;
            
            -- Get results as JSON array
            EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_sql || ') t' 
            INTO v_result;
            
            -- Log search audit
            IF p_debug_level >= 1 THEN
                PERFORM flog_audit_trail(
                    'EMAIL_TEMPLATES',
                    'SEARCH',
                    'Searched email templates',
                    jsonb_build_object(
                        'criteria', p_data,
                        'result_count', v_count,
                        'debug_level', p_debug_level
                    )
                );
            END IF;
            
            -- Return search results
            RETURN jsonb_build_object(
                'success', true,
                'data', v_result,
                'total_count', v_count,
                'debug', CASE WHEN p_debug_level >= 1 THEN v_debug_info END
            );
            
    END CASE;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Log error
        PERFORM flog_audit_trail(
            'EMAIL_TEMPLATES_FUNCTION',
            'ERROR',
            'Error in f_manage_email_templates: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_detail', SQLSTATE,
                'action', p_action,
                'debug_info', v_debug_info
            )
        );
        
        -- Return error
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Database error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'debug', CASE WHEN p_debug_level >= 1 THEN v_debug_info END
        );
END;
$$;


ALTER FUNCTION public.femail_templates(p_action character varying, p_data jsonb, p_debug_level integer, p_id uuid) OWNER TO postgres;

--
-- Name: femail_variables(character varying, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.femail_variables(p_action character varying, p_data jsonb, p_debug_level integer DEFAULT 0, p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_record RECORD;
    v_sql TEXT;
    v_count INTEGER;
    v_variable_key VARCHAR;
    v_description TEXT;
    v_audit_data JSONB;
    v_debug_info JSONB;
BEGIN
    -- Initialize debug info
    v_debug_info := jsonb_build_object(
        'action', p_action,
        'debug_level', p_debug_level,
        'input_data', p_data
    );
    
    -- Validate action
    IF p_action NOT IN ('insert', 'update', 'delete', 'search') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action'
        );
    END IF;
    
    CASE p_action
        WHEN 'insert' THEN
            -- Validate required fields
            IF NOT (p_data ? 'variable_key' AND p_data ? 'display_name') THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Missing required fields: variable_key, display_name'
                );
            END IF;
            
            -- Insert new variable
            INSERT INTO email_variables (
                variable_key,
                display_name,
                description,
                data_source,
                sample_value,
                category
            ) VALUES (
                p_data->>'variable_key',
                p_data->>'display_name',
                p_data->>'description',
                p_data->>'data_source',
                p_data->>'sample_value',
                COALESCE(p_data->>'category', 'general')
            ) RETURNING id, variable_key INTO v_record;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'INSERT',
                'Created email variable: ' || v_record.variable_key,
                jsonb_build_object(
                    'variable_id', v_record.id,
                    'variable_key', v_record.variable_key,
                    'action', 'INSERT'
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable created successfully',
                'data', jsonb_build_object('id', v_record.id, 'variable_key', v_record.variable_key)
            );
            
        WHEN 'update' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for update'
                );
            END IF;
            
            -- Get current variable key
            SELECT variable_key INTO v_variable_key 
            FROM email_variables 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Variable not found'
                );
            END IF;
            
            -- Build update statement
            v_sql := 'UPDATE email_variables SET';
            
            IF p_data ? 'display_name' THEN
                v_sql := v_sql || ' display_name = ' || quote_literal(p_data->>'display_name');
            END IF;
            IF p_data ? 'description' THEN
                v_sql := v_sql || ', description = ' || quote_literal(p_data->>'description');
            END IF;
            IF p_data ? 'data_source' THEN
                v_sql := v_sql || ', data_source = ' || quote_literal(p_data->>'data_source');
            END IF;
            IF p_data ? 'sample_value' THEN
                v_sql := v_sql || ', sample_value = ' || quote_literal(p_data->>'sample_value');
            END IF;
            IF p_data ? 'category' THEN
                v_sql := v_sql || ', category = ' || quote_literal(p_data->>'category');
            END IF;
            
            v_sql := v_sql || ' WHERE id = ' || quote_literal(p_id::text);
            
            EXECUTE v_sql;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'UPDATE',
                'Updated email variable: ' || v_variable_key,
                jsonb_build_object(
                    'variable_id', p_id,
                    'variable_key', v_variable_key,
                    'new_data', p_data
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable updated successfully',
                'rows_affected', v_count
            );
            
        WHEN 'delete' THEN
            IF p_id IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'ID is required for delete'
                );
            END IF;
            
            -- Get variable key
            SELECT variable_key INTO v_variable_key 
            FROM email_variables 
            WHERE id = p_id;
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'message', 'Variable not found'
                );
            END IF;
            
            -- Delete variable
            DELETE FROM email_variables WHERE id = p_id;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            
            -- Log audit trail
            PERFORM flog_audit_trail(
                'EMAIL_VARIABLES',
                'DELETE',
                'Deleted email variable: ' || v_variable_key,
                jsonb_build_object(
                    'variable_id', p_id,
                    'variable_key', v_variable_key
                )
            );
            
            v_result := jsonb_build_object(
                'success', true,
                'message', 'Variable deleted successfully',
                'rows_deleted', v_count
            );
            
        WHEN 'search' THEN
            -- Build search query
            v_sql := 'SELECT * FROM email_variables WHERE 1=1';
            
            IF p_data ? 'variable_key' THEN
                v_sql := v_sql || ' AND variable_key ILIKE ' || quote_literal('%' || (p_data->>'variable_key') || '%');
            END IF;
            IF p_data ? 'category' THEN
                v_sql := v_sql || ' AND category = ' || quote_literal(p_data->>'category');
            END IF;
            IF p_data ? 'data_source' THEN
                v_sql := v_sql || ' AND data_source = ' || quote_literal(p_data->>'data_source');
            END IF;
            
            -- Order by category then display name
            v_sql := v_sql || ' ORDER BY category, display_name';
            
            -- Execute query and return as JSON
            EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || v_sql || ') t' 
            INTO v_result;
            
            -- Count results
            v_sql := 'SELECT COUNT(*) FROM email_variables WHERE 1=1';
            IF p_data ? 'category' THEN
                v_sql := v_sql || ' AND category = ' || quote_literal(p_data->>'category');
            END IF;
            
            EXECUTE v_sql INTO v_count;
            
            RETURN jsonb_build_object(
                'success', true,
                'data', v_result,
                'total_count', v_count
            );
            
    END CASE;
    
    -- Add debug info if requested
    IF p_debug_level >= 1 THEN
        v_result := v_result || jsonb_build_object('debug', v_debug_info);
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        PERFORM flog_audit_trail(
            'EMAIL_VARIABLES_FUNCTION',
            'ERROR',
            'Error in f_manage_email_variables: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'action', p_action
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Database error: ' || SQLERRM
        );
END;
$$;


ALTER FUNCTION public.femail_variables(p_action character varying, p_data jsonb, p_debug_level integer, p_id uuid) OWNER TO postgres;

--
-- Name: fgenerate_instant_cardsrequest_from_cycle(text[], text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fgenerate_instant_cardsrequest_from_cycle(p_requestids text[] DEFAULT NULL::text[], p_status text DEFAULT 'VERIFIED'::text, p_debug_flag boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_batch_id VARCHAR(20);
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_total_processed INTEGER := 0;
    v_total_errors INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
	v_pintype VARCHAR(15)=NULL;
	v_maxloopcount INTEGER :=0;--ADDED BY ST FEB-11-2026
    
    -- Cursor for fetching records based on request IDs array and status
    cur_requests CURSOR (p_req_ids text[], p_stat text) FOR 
        SELECT 
            requestid,
            totalnumberofcard,
            currency,
            requestedbranchname,
            scheme,
            cardtype,
            requestedby,
            requestbranchcode,
            pintype,
            flags,
			approved_cards
        FROM instantcardcycle
        WHERE 
            -- If request IDs array is provided, filter by those IDs
            (p_req_ids IS NULL OR requestid = ANY(p_req_ids))
            -- Always filter by status
            AND status = p_stat;
     
    v_record RECORD;
    v_card_counter INTEGER;
    v_dap_iden VARCHAR(20);
    v_customer_id VARCHAR(20);
    v_account_number VARCHAR(20);
    v_request_processed_count INTEGER;
    v_request_error_count INTEGER;
    v_total_requests_found INTEGER := 0;
    
    -- Variables for storing generated records
    v_generated_records JSONB := '[]'::JSONB;
    v_current_record JSONB;
    v_generated_data JSONB;
    
    -- Variables for batch insertion
    v_batch_timestamp TIMESTAMP;
    
    -- Variables for aggregated batch data
    v_request_ids_array JSONB := '[]'::JSONB;
    v_schemes_array JSONB := '[]'::JSONB;
    v_card_types_array JSONB := '[]'::JSONB;
    v_flags_array JSONB := '[]'::JSONB;
    
    -- NEW: Variables for bulk insert
    v_bulk_insert_start TIMESTAMP;
    v_bulk_insert_end TIMESTAMP;
    v_temp_cards_data TEXT;
    v_insert_sql TEXT;
    
BEGIN
    -- Initialize
    v_start_time := CURRENT_TIMESTAMP;
    v_batch_id := 'BATCH' || TO_CHAR(CURRENT_TIMESTAMP, 'YYMMDDHHMISS');
    v_batch_timestamp := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Starting function with batch: %, request_ids: %, status: %', 
        v_batch_id, 
        p_requestids, 
        p_status;
    
    -- Start audit log if debug enabled
    BEGIN
        IF p_debug_flag THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_GEN',
                'START',
                'Starting bulk card generation',
                jsonb_build_object(
                    'batch_id', v_batch_id,
                    'start_time', v_start_time::TEXT,
                    'request_ids', p_requestids,
                    'status_filter', p_status,
                    'process_type', 
                        CASE 
                            WHEN p_requestids IS NOT NULL THEN 'SPECIFIC_REQUESTS'
                            ELSE 'ALL_' || p_status
                        END
                )
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Audit log error (ignored): %', SQLERRM;
    END;
    
    -- Count total requests that will be processed
    SELECT COUNT(*) INTO v_total_requests_found
    FROM instantcardcycle
    WHERE 
        (p_requestids IS NULL OR requestid = ANY(p_requestids))
        AND status = p_status;
    
    RAISE NOTICE 'Found % request(s) with status %', v_total_requests_found, p_status;
    
    -- If no records found, return early
    IF v_total_requests_found = 0 THEN
        v_result := jsonb_build_object(
            'success', TRUE,
            'message', 'No records found with the specified criteria',
            'batch_id', v_batch_id,
            'status_filter', p_status,
            'request_ids_provided', p_requestids,
            'total_requests_found', 0,
            'total_processed', 0,
            'total_errors', 0,
            'start_time', v_start_time::TEXT,
            'end_time', CURRENT_TIMESTAMP::TEXT,
            'duration_seconds', 0,
            'generated_records', '[]'::JSONB
        );
        
        -- Log the empty result
        IF p_debug_flag THEN
            BEGIN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_GEN',
                    'NO_RECORDS',
                    'No records found for processing',
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'status_filter', p_status,
                        'request_ids', p_requestids
                    )
                );
            EXCEPTION WHEN OTHERS THEN
                RAISE NOTICE 'Audit log error: %', SQLERRM;
            END;
        END IF;
        
        RETURN v_result;
    END IF;
    
    -- ========== BULK INSERT OPTIMIZATION ==========
    -- Generate and insert ALL cards in a single operation
    v_bulk_insert_start := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Starting bulk card generation...';
    
    WITH all_cards AS (
        -- Generate card series for each request
        SELECT 
            icc.requestid,
            icc.totalnumberofcard,
            icc.currency,
            icc.requestedbranchname,
            icc.scheme,
            icc.cardtype,
            icc.requestedby,
            icc.requestbranchcode,
            icc.pintype,
            icc.flags,
            gs.card_sequence,
            -- Generate unique IDs using your original logic
            icc.requestid || '_' || LPAD(gs.card_sequence::TEXT, 4, '0') as dap_iden,
            '9000' || LPAD((34456 + gs.card_sequence - 1)::TEXT, 5, '0') as customer_id,
            '900100000' || LPAD((34456 + gs.card_sequence - 1)::TEXT, 5, '0') as account_number
        FROM instantcardcycle icc
        CROSS JOIN LATERAL generate_series(1, icc.approved_cards) as gs(card_sequence)
        WHERE 
            (p_requestids IS NULL OR icc.requestid = ANY(p_requestids))
            AND icc.status = p_status
    )
    -- Bulk insert using your original column values
    INSERT INTO instant_card_applications (
        dap_iden, dap_ban_code, dap_bra_code, dap_user, dap_bat_code,
        dap_cus_type, dap_cus_old_new, dap_cus_iden, dap_date, dap_ast_code,
        dap_firs_nam1, dap_last_nam1, dap_midd_nam1, dap_tit1,
        dap_firs_ide1, dap_firs_iden_typ1, dap_gend1, dap_mst_cod1, dap_cou_cod1,
        dap_requ_acc_numb, dap_requ_acc_curr_code, dap_requ_cpr_code,
        dap_pan_gene_manu_auto, dap_requ_dpr_code,
        dap_chld_titl, dap_chld_firs_name, dap_chld_last_name, dap_chld_name,
        dap_prim_seco_card,
        dap_phon_number, dap_gree_pin_flag,
        firstaddresstype, firstaddressline1, firstadressphone1, firstcity,
        batchid, statusflag, formatid
    )
    SELECT 
        ac.dap_iden,
        '402122', '999', 'CCMSUSER', '10',
        'I', 'N', ac.customer_id, CURRENT_DATE, '1',
        'INSTANT' || ac.card_sequence, 'CARD', NULL, '1',
        '1', '1', '1', '1', COALESCE(ac.currency, '524'),
        ac.account_number, COALESCE(ac.currency, '524'), '731',
        'A', '730',
        '2', 'INSTANT' || ac.card_sequence, 'CARD', 'INSTANT CARD ' || ac.card_sequence,
        'P',
        '1111111111', 'N',
        '08', COALESCE(ac.requestedbranchname, 'Kathmandu'), '1111111111', '30608',
        v_batch_id, 'PENDING', 'AUTO_GENERATED'
    FROM all_cards ac
    ON CONFLICT (dap_iden, batchid) DO NOTHING;
    
    -- Get the total number of cards inserted
    GET DIAGNOSTICS v_total_processed = ROW_COUNT;
    v_bulk_insert_end := CURRENT_TIMESTAMP;
    
    RAISE NOTICE 'Bulk insert completed: % cards generated in % seconds', 
        v_total_processed, 
        EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start));
    
    -- ========== PROCESS INDIVIDUAL REQUESTS (KEEP YOUR ORIGINAL LOGIC) ==========
    -- Open cursor and process records for status updates, logging, and JSON building
    OPEN cur_requests(p_requestids, p_status);
    
    LOOP
        FETCH cur_requests INTO v_record;
        EXIT WHEN NOT FOUND;
        
        RAISE NOTICE 'Processing request metadata: %', v_record.requestid;
        
        -- Reset per-request counters (for tracking only)
        v_request_processed_count := 0;
        v_request_error_count := 0;
        v_generated_data := '[]'::JSONB;
        
        -- Add request ID to aggregated array
        v_request_ids_array := v_request_ids_array || to_jsonb(v_record.requestid);
        
        -- Add scheme to aggregated array (if not null and not already present)
        IF v_record.scheme IS NOT NULL THEN
            v_schemes_array := v_schemes_array || to_jsonb(v_record.scheme);
        END IF;
        
        -- Add card type to aggregated array (if not null and not already present)
        IF v_record.cardtype IS NOT NULL THEN
            v_card_types_array := v_card_types_array || to_jsonb(v_record.cardtype);
        END IF;
        
        -- Add flags to aggregated array (if not null)
        IF v_record.flags IS NOT NULL THEN
            v_flags_array := v_flags_array || to_jsonb(v_record.flags);
        END IF;
        
        -- Count cards generated for this specific request
        SELECT COUNT(*) INTO v_request_processed_count
        FROM instant_card_applications
        WHERE batchid = v_batch_id 
          AND dap_iden LIKE v_record.requestid || '_%';
		   RAISE NOTICE 'Total Count approved_cards:%',v_record.approved_cards;
           IF v_record.approved_cards>0 then
		  	   		v_maxloopcount=v_record.approved_cards;
		  ELSE
		  			v_maxloopcount=v_record.totalnumberofcard;
		  END IF;
		  RAISE NOTICE 'Value set to v_maxloopcount:%',v_maxloopcount;
        -- Build generated data for this request
        FOR v_card_counter IN 1..v_maxloopcount LOOP
            BEGIN
                -- Generate IDs using your original logic
                v_dap_iden := v_record.requestid || '_' || LPAD(v_card_counter::TEXT, 4, '0');
                v_customer_id := '9000' || LPAD((34456 + v_card_counter - 1)::TEXT, 5, '0');
                v_account_number := '900100000' || LPAD((34456 + v_card_counter - 1)::TEXT, 5, '0');
                
                -- Check if card was actually inserted
                PERFORM 1 FROM instant_card_applications 
                WHERE dap_iden = v_dap_iden AND batchid = v_batch_id;
                
                IF FOUND THEN
                    -- Create JSON object for this generated card (your original logic)
                    v_current_record := jsonb_strip_nulls(jsonb_build_object(
                        'dap_iden', v_dap_iden,
                        'dap_cus_iden', v_customer_id,
                        'dap_requ_acc_numb', v_account_number,
                        'dap_firs_nam1', 'INSTANT' || v_card_counter,
                        'dap_last_nam1', 'CARD',
                        'dap_requ_acc_curr_code', COALESCE(v_record.currency, '524'),
                        'firstaddressline1', COALESCE(v_record.requestedbranchname, 'Kathmandu'),
                        'batchid', v_batch_id,
                        'statusflag', 'PENDING',
                        'formatid', 'AUTO_GENERATED',
                        'requestid', v_record.requestid,
                        'scheme', v_record.scheme,
                        'cardtype', v_record.cardtype,
                        'pintype', v_record.pintype,
                        'flags', v_record.flags,
                        'card_sequence', v_card_counter,
                        'total_cards_for_request', v_record.totalnumberofcard,
                        'generated_at', CURRENT_TIMESTAMP::TEXT
                    ));
                    
                    -- Add to generated data array for this request
                    v_generated_data := v_generated_data || v_current_record;
                ELSE
                    -- Card insertion failed
                    v_request_error_count := v_request_error_count + 1;
                    v_total_errors := v_total_errors + 1;
                    
                    v_current_record := jsonb_build_object(
                        'error', true,
                        'requestid', v_record.requestid,
                        'card_sequence', v_card_counter,
                        'error_message', 'Card not inserted in bulk operation',
                        'error_time', CURRENT_TIMESTAMP::TEXT
                    );
                    
                    v_generated_data := v_generated_data || v_current_record;
                END IF;
                
            EXCEPTION
                WHEN OTHERS THEN
                    GET STACKED DIAGNOSTICS 
                        v_error_message = MESSAGE_TEXT,
                        v_sql_state = RETURNED_SQLSTATE;
                    
                    v_request_error_count := v_request_error_count + 1;
                    v_total_errors := v_total_errors + 1;
                    
                    v_current_record := jsonb_build_object(
                        'error', true,
                        'requestid', v_record.requestid,
                        'card_sequence', v_card_counter,
                        'error_message', v_error_message,
                        'sql_state', v_sql_state,
                        'error_time', CURRENT_TIMESTAMP::TEXT
                    );
                    
                    v_generated_data := v_generated_data || v_current_record;
            END;
        END LOOP;
        
        RAISE NOTICE 'Updating status for request % to PROCESSING', v_record.requestid;
        
        -- ✅ UPDATE STATUS FOR THIS SINGLE REQUESTID (your original logic)
        BEGIN
            UPDATE instantcardcycle
            SET status = 'PROCESSING'
            WHERE requestid = v_record.requestid;
            
            RAISE NOTICE 'Updated request % to PROCESSING (cards: %, errors: %)', 
                v_record.requestid, v_request_processed_count, v_request_error_count;
            
            -- Add request summary to generated records (your original logic)
            IF jsonb_array_length(v_generated_data) > 0 THEN
                v_current_record := jsonb_strip_nulls(jsonb_build_object(
                    'request_summary', jsonb_build_object(
                        'requestid', v_record.requestid,
                        'total_cards_requested', v_record.totalnumberofcard,
                        'cards_successfully_generated', v_request_processed_count,
                        'cards_failed', v_request_error_count,
                        'scheme', v_record.scheme,
                        'cardtype', v_record.cardtype,
                        'currency', v_record.currency,
                        'pintype', v_record.pintype,
                        'status_before', p_status,
                        'status_after', 'PROCESSING',
                        'batch_id', v_batch_id,
                        'processed_at', CURRENT_TIMESTAMP::TEXT
                    ),
                    'generated_cards', v_generated_data
                ));
                
                v_generated_records := v_generated_records || v_current_record;
            END IF;
            
            -- ✅ SEND AUDIT TRAIL FOR THIS REQUESTID (your original logic)
            IF p_debug_flag THEN
                BEGIN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_GEN',
                        'REQUEST_PROCESSED',
                        'Request processed: ' || v_record.requestid,
                        jsonb_build_object(
                            'requestid', v_record.requestid,
                            'batch_id', v_batch_id,
                            'cards_generated', v_request_processed_count,
                            'cards_failed', v_request_error_count,
                            'total_cards', v_record.totalnumberofcard,
                            'original_status', p_status,
                            'new_status', 'PROCESSING',
                            'processing_time', CURRENT_TIMESTAMP::TEXT
                        )
                    );
                    RAISE NOTICE 'Audit log sent for request %', v_record.requestid;
                EXCEPTION WHEN OTHERS THEN
                    RAISE NOTICE 'Audit log error for request %: %', v_record.requestid, SQLERRM;
                END;
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
                RAISE NOTICE 'Failed to update request %: %', v_record.requestid, v_error_message;
        END;
        
    END LOOP;
    
    CLOSE cur_requests;
    
    -- ✅ INSERT AGGREGATED BATCH RECORD (your original logic)
    BEGIN
        -- Remove duplicates from arrays using DISTINCT
        v_request_ids_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_request_ids_array)
        );
        
        v_schemes_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_schemes_array)
        );
        
        v_card_types_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_card_types_array)
        );
        
        v_flags_array := (
            SELECT jsonb_agg(DISTINCT value)
            FROM jsonb_array_elements(v_flags_array)
        );
        
        -- Insert into instant_card_generation_batches table
		SELECT DISTINCT pintype INTO v_pintype FROM instantcardcycle
    	WHERE requestid = ANY(p_requestids)AND pintype IS NOT NULL LIMIT 1;
        INSERT INTO instant_card_generation_batches (
            batch_id,
            request_ids,
            status,
            cards_generated,
            cards_failed,
            schemes,
            card_types,
            duration,
            timestamp,
            flags,
			pintype
        ) VALUES (
            v_batch_id,
            COALESCE(v_request_ids_array, '[]'::JSONB),
            'PROCESSING',
            v_total_processed,
            v_total_errors,
            COALESCE(v_schemes_array, '[]'::JSONB),
            COALESCE(v_card_types_array, '[]'::JSONB),
            NULL,
            v_batch_timestamp,
            COALESCE(v_flags_array, '[]'::JSONB),
			v_pintype
        );
        
        RAISE NOTICE 'Successfully inserted batch record % into instant_card_generation_batches', 
            v_batch_id;
        
    EXCEPTION
        WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            RAISE NOTICE 'Failed to insert into instant_card_generation_batches: %', v_error_message;
    END;
    
    -- Build final result with performance metrics
    v_end_time := CURRENT_TIMESTAMP;
    v_result := jsonb_build_object(
        'success', TRUE,
        'message', 'Bulk generation completed',
        'batch_id', v_batch_id,
        'status_filter', p_status,
        'request_ids_provided', p_requestids,
        'total_requests_found', v_total_requests_found,
        'total_processed', v_total_processed,
        'total_errors', v_total_errors,
        'start_time', v_start_time::TEXT,
        'end_time', v_end_time::TEXT,
        'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
        'performance', jsonb_strip_nulls(jsonb_build_object(
            'bulk_insert_duration', EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start)),
            'requests_per_second', 
                CASE 
                    WHEN EXTRACT(EPOCH FROM (v_end_time - v_start_time)) > 0 
                    THEN v_total_requests_found / EXTRACT(EPOCH FROM (v_end_time - v_start_time))
                END,
            'cards_per_second',
                CASE 
                    WHEN EXTRACT(EPOCH FROM (v_end_time - v_start_time)) > 0 
                    THEN v_total_processed / EXTRACT(EPOCH FROM (v_end_time - v_start_time))
                END
        )),
        'generated_records', v_generated_records,
        'batch_records_inserted', 1,
        'request_ids_in_batch', v_request_ids_array
    );
    
    -- ✅ Update duration for the batch record (your original logic)
    BEGIN
        UPDATE instant_card_generation_batches 
        SET duration = EXTRACT(EPOCH FROM (v_end_time - v_start_time)) || ' seconds'
        WHERE batch_id = v_batch_id;
        
        RAISE NOTICE 'Updated duration for batch %', v_batch_id;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Failed to update duration: %', SQLERRM;
    END;
    
    -- Final audit log if debug enabled (your original logic)
    BEGIN
        IF p_debug_flag THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_GEN',
                'COMPLETE',
                'Bulk card generation completed',
                jsonb_build_object(
                    'batch_id', v_batch_id,
                    'total_requests', v_total_requests_found,
                    'total_cards_generated', v_total_processed,
                    'total_errors', v_total_errors,
                    'status_filter', p_status,
                    'request_ids_count', 
                        CASE 
                            WHEN p_requestids IS NULL THEN 0
                            ELSE array_length(p_requestids, 1)
                        END,
                    'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
                    'start_time', v_start_time::TEXT,
                    'end_time', v_end_time::TEXT,
                    'batch_table_inserted', true,
                    'batch_request_count', jsonb_array_length(v_request_ids_array),
                    'bulk_insert_performance', EXTRACT(EPOCH FROM (v_bulk_insert_end - v_bulk_insert_start))
                )
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Final audit error: %', SQLERRM;
    END;
    
    RAISE NOTICE 'Function completed: total processed=%, total errors=%, batch record created for % request(s)', 
        v_total_processed, v_total_errors, v_total_requests_found;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        RAISE NOTICE 'CRITICAL FUNCTION ERROR: %', v_error_message;
        RAISE NOTICE 'SQL State: %', v_sql_state;
        
        -- Try to insert batch record even on error (with current state)
        BEGIN
            INSERT INTO instant_card_generation_batches (
                batch_id,
                request_ids,
                status,
                cards_generated,
                cards_failed,
                schemes,
                card_types,
                duration,
                timestamp,
                flags
            ) VALUES (
                v_batch_id,
                COALESCE(v_request_ids_array, '[]'::JSONB),
                'FAILED',
                v_total_processed,
                v_total_errors,
                COALESCE(v_schemes_array, '[]'::JSONB),
                COALESCE(v_card_types_array, '[]'::JSONB),
                EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - v_start_time)) || ' seconds',
                v_batch_timestamp,
                COALESCE(v_flags_array, '[]'::JSONB)
            );
            
            RAISE NOTICE 'Inserted FAILED batch record %', v_batch_id;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Could not insert failed batch record: %', SQLERRM;
        END;
        
        -- Build error result (still include any generated records so far)
        v_result := jsonb_build_object(
            'success', FALSE,
            'message', 'Critical error: ' || v_error_message,
            'batch_id', v_batch_id,
            'status_filter', p_status,
            'request_ids_provided', p_requestids,
            'total_processed', v_total_processed,
            'total_errors', v_total_errors,
            'sql_state', v_sql_state,
            'generated_records', COALESCE(v_generated_records, '[]'::JSONB),
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fgenerate_instant_cardsrequest_from_cycle(p_requestids text[], p_status text, p_debug_flag boolean) OWNER TO postgres;

--
-- Name: fget_batch_data_by_status(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_batch_data_by_status(p_statusflag text DEFAULT 'PENDING'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_total_count INTEGER := 0;
    v_batches JSONB;
    v_error_message TEXT;
    v_batch_record RECORD;
BEGIN
    -- Get total count of batches (not individual cards)
    SELECT COUNT(DISTINCT batchid) INTO v_total_count
    FROM instant_card_applications
    WHERE statusflag = p_statusflag;
    
    -- Initialize batches array
    v_batches := '[]'::jsonb;
    
    -- Get batch data with aggregated information
    FOR v_batch_record IN (
        SELECT 
            batchid,
            -- Extract distinct request IDs from dap_iden (format: REQUESTID_XXXX)
            jsonb_agg(DISTINCT SUBSTRING(dap_iden FROM 1 FOR 12)) as request_ids,
            -- Get status flag
            MIN(statusflag) as status,  -- All should have same status
            -- Count cards in this batch
            COUNT(*) as cards_generated,
            -- Count failed cards (if we had a failure flag)
            COUNT(*) FILTER (WHERE statusflag = 'FAILED') as cards_failed,
            -- Get distinct schemes (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'MASTERCARD'::text), '[]'::jsonb) as schemes, -- Placeholder
            -- Get distinct card types (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'INSTANT'::text), '[]'::jsonb) as card_types, -- Placeholder
            -- Placeholder for duration
            '0.000000 seconds' as duration,
            -- Get batch creation timestamp
            MIN(created_at) as timestamp,
            -- Get distinct flags (if available in data)
            COALESCE(jsonb_agg(DISTINCT 'A'::text), '[]'::jsonb) as flags, -- Placeholder
            -- Calculate success rate
            CASE 
                WHEN COUNT(*) > 0 THEN 
                    ROUND((COUNT(*) FILTER (WHERE statusflag != 'FAILED')::DECIMAL * 100.0 / COUNT(*)), 2)
                ELSE 0 
            END as success_rate,
            -- Count distinct requests
            COUNT(DISTINCT SUBSTRING(dap_iden FROM 1 FOR 12)) as request_count
        FROM instant_card_applications
        WHERE statusflag = p_statusflag
        GROUP BY batchid
        ORDER BY MIN(created_at) DESC
        LIMIT p_limit
        OFFSET p_offset
    ) LOOP
        -- Add each batch to the JSON array in your format
        v_batches := v_batches || jsonb_build_object(
            'batch_id', v_batch_record.batchid,
            'request_ids', v_batch_record.request_ids,
            'status', v_batch_record.status,
            'cards_generated', v_batch_record.cards_generated,
            'cards_failed', v_batch_record.cards_failed,
            'schemes', v_batch_record.schemes,
            'card_types', v_batch_record.card_types,
            'duration', v_batch_record.duration,
            'timestamp', v_batch_record.timestamp,
            'flags', v_batch_record.flags,
            'total_cards', v_batch_record.cards_generated + v_batch_record.cards_failed,
            'success_rate', v_batch_record.success_rate,
            'request_count', v_batch_record.request_count
        );
    END LOOP;
    
    -- Build result
    v_result := jsonb_build_object(
        'success', TRUE,
        'status_filter', p_statusflag,
        'total_batches', v_total_count,
        'returned_batches', COALESCE(jsonb_array_length(v_batches), 0),
        'limit', p_limit,
        'offset', p_offset,
        'batches', COALESCE(v_batches, '[]'::jsonb)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        v_result := jsonb_build_object(
            'success', FALSE,
            'error', v_error_message,
            'status_filter', p_statusflag
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fget_batch_data_by_status(p_statusflag text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fget_batch_summary_by_status(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_batch_summary_by_status(p_status text DEFAULT 'PROCESSING'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_total_count INTEGER := 0;
    v_batches JSONB;
    v_error_message TEXT;
BEGIN
    -- Get total count from instant_card_generation_batches
    SELECT COUNT(*) INTO v_total_count
    FROM instant_card_generation_batches
    WHERE status = p_status;
    
    -- Get batch data directly from the batch table
    SELECT jsonb_agg(
        jsonb_build_object(
            's_no', s_no,
            'batch_id', batch_id,
            'request_ids', request_ids,
            'status', status,
            'cards_generated', cards_generated,
            'cards_failed', cards_failed,
            'schemes', schemes,
            'card_types', card_types,
            'duration', duration,
            'timestamp', timestamp,
            'flags', flags,
            'total_cards', total_cards,
            'success_rate', success_rate,
            'request_count', request_count
        ) ORDER BY timestamp DESC
    ) INTO v_batches
    FROM instant_card_generation_batches
    WHERE status = p_status
    ORDER BY timestamp DESC
    LIMIT p_limit
    OFFSET p_offset;
    
    -- Build result
    v_result := jsonb_build_object(
        'success', TRUE,
        'status_filter', p_status,
        'total_batches', v_total_count,
        'returned_batches', COALESCE(jsonb_array_length(v_batches), 0),
        'limit', p_limit,
        'offset', p_offset,
        'batches', COALESCE(v_batches, '[]'::jsonb)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        v_result := jsonb_build_object(
            'success', FALSE,
            'error', v_error_message,
            'status_filter', p_status
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fget_batch_summary_by_status(p_status text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: fget_creditbatchid(character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fget_creditbatchid(p_username character varying DEFAULT NULL::character varying, p_debug_level integer DEFAULT 1) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json JSON;
    v_total_batches INTEGER;
    v_total_records INTEGER;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_execution_time NUMERIC(10,3);
    
    -- Debug level constants
    c_debug_none CONSTANT INTEGER := 0;
    c_debug_basic CONSTANT INTEGER := 1;
    c_debug_detailed CONSTANT INTEGER := 2;
    c_debug_verbose CONSTANT INTEGER := 3;
BEGIN
    -- Validate debug level
    IF p_debug_level NOT IN (0, 1, 2, 3) THEN
        p_debug_level := c_debug_basic;
    END IF;
    
    v_start_time := clock_timestamp();
    
    -- Basic logging
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Starting batch statistics function';
        RAISE NOTICE 'Username: %', COALESCE(p_username, 'SYSTEM');
        RAISE NOTICE 'Debug level: %', p_debug_level;
        RAISE NOTICE 'Start time: %', v_start_time;
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Check if table has data
    IF NOT EXISTS (SELECT 1 FROM public.credit_card_application LIMIT 1) THEN
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE 'Table credit_card_application is empty';
        END IF;
        
        v_end_time := clock_timestamp();
        v_execution_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE 'Completed in % seconds', ROUND(v_execution_time::NUMERIC, 3);
            RAISE NOTICE 'Returning empty array';
        END IF;
        
        RETURN '[]'::JSON;
    END IF;
    
    -- Get batch statistics
    IF p_debug_level >= c_debug_detailed THEN
        RAISE NOTICE 'Executing aggregation query...';
    END IF;
    
    SELECT json_agg(
        json_build_object(
            'batch_id', batch_id,
            'total_records', total_records,
            'greenpin_request_count', greenpin_count,
            'paperpin_request_count', paperpin_count
        )
    ) INTO result_json
    FROM (
        SELECT 
            batch_id,
            COUNT(*) as total_records,
            COUNT(CASE WHEN dap_gree_pin_flag = 'Y' THEN 1 END) as greenpin_count,
            COUNT(CASE WHEN dap_gree_pin_flag = 'N' OR dap_gree_pin_flag IS NULL THEN 1 END) as paperpin_count
        FROM 
            public.credit_card_application
        WHERE 
            batch_id IS NOT NULL 
            AND batch_id != ''
        GROUP BY 
            batch_id
        ORDER BY 
            batch_id
    ) as batch_stats;
    
    -- Get summary stats
    SELECT COUNT(DISTINCT batch_id), COUNT(*)
    INTO v_total_batches, v_total_records
    FROM public.credit_card_application
    WHERE batch_id IS NOT NULL AND batch_id != '';
    
    v_end_time := clock_timestamp();
    v_execution_time := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
    
    -- Completion logging
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Batch statistics function completed';
        RAISE NOTICE 'Username: %', COALESCE(p_username, 'SYSTEM');
        RAISE NOTICE 'Total batches: %', v_total_batches;
        RAISE NOTICE 'Total records: %', v_total_records;
        RAISE NOTICE 'Execution time: % seconds', ROUND(v_execution_time, 3);
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Verbose logging
    IF p_debug_level >= c_debug_verbose AND result_json IS NOT NULL THEN
        RAISE NOTICE 'Result sample: %', substring(result_json::TEXT from 1 for 200);
    END IF;
    
    RETURN COALESCE(result_json, '[]'::JSON);
END;
$$;


ALTER FUNCTION public.fget_creditbatchid(p_username character varying, p_debug_level integer) OWNER TO postgres;

