--
-- Name: fgetinstantalldatabybatchid(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fgetinstantalldatabybatchid(p_batchid character varying DEFAULT NULL::character varying) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    result_json JSON;
BEGIN
    IF p_batchid IS NULL OR p_batchid = '' THEN
        -- Return all unique batch IDs as JSON array (just batch IDs, not all columns)
        SELECT json_agg(batchid ORDER BY batchid) INTO result_json
        FROM (
            SELECT DISTINCT i.batchid
            FROM public.instantcardstock i
            WHERE i.batchid IS NOT NULL
            AND i.batchid != ''
        ) AS batch_list;
    ELSE
        -- Return ALL columns for specific batch ID as JSON array of objects
        SELECT json_agg(row_to_json(t)) INTO result_json
        FROM (
            SELECT 
                uploadid,
                batchid,
                cardnumber,
                bankcode,
                requestbranch,
                allocatedbranch,
                assingtocustomer,
                status,
                embossedname,
                opendingdate,
                expirydate,
                lastbatchprodnum,
                accountnumber,
                uploaddate,
                clientcode,
                createddate,
                createdby,
                lastupdateddate,
                lastupdatedby
            FROM public.instantcardstock i
            WHERE i.batchid = p_batchid
            ORDER BY i.createddate DESC, i.uploaddate DESC
        ) t;
    END IF;
    
    -- If no results found, return empty array
    IF result_json IS NULL THEN
        result_json = '[]'::JSON;
    END IF;
    
    RETURN result_json;
END;
$$;


ALTER FUNCTION public.fgetinstantalldatabybatchid(p_batchid character varying) OWNER TO postgres;

--
-- Name: fgetinstantuniqueuploadbatchid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fgetinstantuniqueuploadbatchid() RETURNS TABLE(batchid character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT i.batchid
    FROM public.instantcardstock i
    WHERE i.batchid IS NOT NULL
    ORDER BY i.batchid;
END;
$$;


