--
-- Name: finsert_credit_card_application(text[], integer, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finsert_credit_card_application(p_request_ids text[] DEFAULT NULL::text[], p_debug_level integer DEFAULT 1, p_batch_id text DEFAULT NULL::text, p_username character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER PARALLEL SAFE
    AS $$
DECLARE
    v_result JSONB;
    v_batch_id VARCHAR(50);
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_total_inserted INTEGER := 0;
    v_total_errors INTEGER := 0;
    v_total_duplicates INTEGER := 0;
    v_total_skipped INTEGER := 0;
    v_total_requests INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
    v_request_index INTEGER;
    v_request_id VARCHAR(50);
    
    -- Variables for data lookup
    -- From card_request_cycle
    v_full_name VARCHAR(30);
    v_mobile VARCHAR(15);
    v_account_no VARCHAR(20);
    v_request_type VARCHAR(50);
    v_card_type VARCHAR(50);
    v_currency_type VARCHAR(10);
    v_card_scheme VARCHAR(50);
    v_request_branch_id VARCHAR(100);
    v_delivery_branch_id VARCHAR(100);
    v_customer_branch_id VARCHAR(100);
    v_customer_branch_code VARCHAR(4);
    v_account_type VARCHAR(100);
    v_instcode VARCHAR(12);
    v_remarks TEXT;
    v_requstor_branch_code VARCHAR(4);
    v_receiver_branch_code VARCHAR(4);
    v_pintype VARCHAR(15);
    v_request_status VARCHAR(20);
    
    -- From account table
    v_customercode VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_accountid VARCHAR(12);
    v_balance NUMERIC(18,2);
    v_accountlimit NUMERIC(18,2);
    v_branchcode VARCHAR(10);
    v_account_status CHAR(1);
    
    -- From customer table
    v_cbs_customer_code VARCHAR(12);
    v_fname VARCHAR(50);
    v_lname VARCHAR(50);
    v_middlename VARCHAR(50);
    v_salutation VARCHAR(20);
    v_emailid VARCHAR(100);
    v_mobileno VARCHAR(15);
    v_customer_branchcode VARCHAR(10);
    v_bankcode VARCHAR(10);
    v_maritalstatus CHAR(1);
    v_customer_status CHAR(1);
    v_dob DATE;
    v_address VARCHAR(255);
    v_nationality VARCHAR(30);
    v_gender VARCHAR(10);
    v_documenttype VARCHAR(25);
    v_documentid VARCHAR(15);
    v_occupation VARCHAR(25);
    v_employment_type VARCHAR(30);
    v_annualincome NUMERIC(15,2);
    v_fathername VARCHAR(50);
    v_grandfathername VARCHAR(50);
    v_mothername VARCHAR(50);
    v_spousename VARCHAR(50);
    v_notes TEXT;
    
    -- Generated DAP_IDEN (application ID)
    v_dap_iden BIGINT;
    
    -- Error tracking
    v_error_details JSONB := '[]'::JSONB;
    v_success_details JSONB := '[]'::JSONB;
    v_skipped_details JSONB := '[]'::JSONB;
    v_duplicate_ids TEXT[] := ARRAY[]::TEXT[];
    v_error_types TEXT[] := ARRAY[]::TEXT[];
    
    -- Debug tracking
    v_temp_count INTEGER;
    
    -- Performance tracking
    v_total_duration NUMERIC(10,3) := 0;
    v_success_rate NUMERIC(5,2) := 0;
    v_error_summary JSONB := '[]'::JSONB;
    
    -- Constants for debug levels
    c_debug_none CONSTANT INTEGER := 0;
    c_debug_basic CONSTANT INTEGER := 1;
    c_debug_detailed CONSTANT INTEGER := 2;
    c_debug_verbose CONSTANT INTEGER := 3;
    
    -- Status configuration (internal constants)
    c_allowed_request_statuses CONSTANT text[] := ARRAY['Pending', 'Approved', 'PROCESSING', 'VERIFIED', 'Processed','DOCS PENDING','ASSES PENDING'];
    c_allowed_account_statuses CONSTANT text[] := ARRAY['1', 'A', 'ACTIVE', 'Y', 'a', '0'];
    
BEGIN
    -- Initialize
    v_start_time := CURRENT_TIMESTAMP;
    
    -- Validate debug level
    IF p_debug_level NOT IN (0, 1, 2, 3) THEN
        p_debug_level := 1;  -- Default to basic if invalid
    END IF;
    
    -- Generate or use provided batch ID
    IF p_batch_id IS NULL OR p_batch_id = '' THEN
        v_batch_id := 'DAP_' || TO_CHAR(CURRENT_TIMESTAMP, 'MMDDHH24MISS');
    ELSE
        v_batch_id := p_batch_id;
    END IF;
   -- v_batch_id := SUBSTR(v_batch_id, 1, 12);
    -- Validate input data
    IF p_request_ids IS NULL OR array_length(p_request_ids, 1) IS NULL THEN
        v_end_time := CURRENT_TIMESTAMP;
        v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        v_result := jsonb_build_object(
            'success', false,
            'message', 'No request IDs provided',
            'batch_id', v_batch_id,
            'total_requests', 0,
            'total_inserted', 0,
            'total_errors', 0,
            'total_duplicates', 0,
            'total_skipped', 0,
            'start_time', v_start_time::TEXT,
            'end_time', v_end_time::TEXT,
            'duration_seconds', ROUND(v_total_duration, 3),
            'debug_level', p_debug_level,
            'config', jsonb_build_object(
                'allowed_request_statuses', c_allowed_request_statuses,
                'allowed_account_statuses', c_allowed_account_statuses
            )
        );
        RETURN v_result;
    END IF;
    
    v_total_requests := array_length(p_request_ids, 1);
    
    -- Log based on debug level
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Starting debit card application insertion batch: %', v_batch_id;
        RAISE NOTICE 'Total request IDs to process: %', v_total_requests;
        RAISE NOTICE 'Debug level: %', p_debug_level;
        RAISE NOTICE 'Allowed request statuses: %', c_allowed_request_statuses;
        RAISE NOTICE 'Allowed account statuses: %', c_allowed_account_statuses;
        RAISE NOTICE 'Start time: %', v_start_time;
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Process each request ID
    FOR v_request_index IN 1..v_total_requests LOOP
        v_request_id := p_request_ids[v_request_index];
        
        -- Skip empty request IDs
        IF v_request_id IS NULL OR v_request_id = '' THEN
            v_total_errors := v_total_errors + 1;
            v_error_types := array_append(v_error_types, 'EMPTY_REQUEST_ID');
            v_error_details := v_error_details || jsonb_build_object(
                'request_index', v_request_index,
                'error_type', 'EMPTY_REQUEST_ID',
                'error_message', 'Request ID is empty or null',
                'timestamp', CURRENT_TIMESTAMP::TEXT
            );
            CONTINUE;
        END IF;
        
        IF p_debug_level >= c_debug_detailed THEN
            RAISE NOTICE '--- Processing request_id [%/%]: % ---', 
                v_request_index, v_total_requests, v_request_id;
        END IF;
        
        BEGIN
            -- ========== STEP 1: Query card_request_cycle ==========
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 1: Checking card_request_cycle for request_id: %', v_request_id;
            END IF;
            
            -- Try to get the request details
            SELECT 
                full_name, mobile, account_no, request_type, card_type, 
                currency_type, card_scheme, request_branch_id, delivery_branch_id,
                customer_branch_id, customer_branch_code, account_type, instcode,
                remarks, requstor_branch_code, receiver_branch_code, pintype, status
            INTO 
                v_full_name, v_mobile, v_account_no, v_request_type, v_card_type,
                v_currency_type, v_card_scheme, v_request_branch_id, v_delivery_branch_id,
                v_customer_branch_id, v_customer_branch_code, v_account_type, v_instcode,
                v_remarks, v_requstor_branch_code, v_receiver_branch_code, v_pintype, v_request_status
            FROM creditcardcycle 
            WHERE request_id = v_request_id;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Request ID % NOT FOUND in creditcardcycle table', v_request_id;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'REQUEST_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'REQUEST_NOT_FOUND',
                    'error_message', 'Request ID not found in creditcardcycle table',
                    'table_name', 'creditcardcycle',
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            -- Check if request is in allowed statuses
            IF v_request_status NOT IN (SELECT unnest(c_allowed_request_statuses)) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ⚠ Request found but status is "%" (allowed: %)', 
                        v_request_status, c_allowed_request_statuses;
                END IF;
                
                v_total_skipped := v_total_skipped + 1;
                v_skipped_details := v_skipped_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'reason', 'Request not in allowed statuses',
                    'current_status', v_request_status,
                    'allowed_statuses', c_allowed_request_statuses,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Request found in creditcardcycle';
                RAISE NOTICE '    Status: % (allowed)', v_request_status;
                RAISE NOTICE '    Account No: %', v_account_no;
                RAISE NOTICE '    Card Type: %', v_card_type;
                RAISE NOTICE '    Currency: %', v_currency_type;
            END IF;
            
            -- ========== STEP 2: Query account table ==========
            IF v_account_no IS NULL OR v_account_no = '' THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Account number is NULL or empty in card_request_cycle';
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'NO_ACCOUNT_NUMBER');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'NO_ACCOUNT_NUMBER',
                    'error_message', 'Account number not found for request in card_request_cycle',
                    'table_name', 'card_request_cycle',
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 2: Checking account table for account_no: %', v_account_no;
            END IF;
            
            -- Try to get account details
            SELECT 
                customercode, accountnumber, accountid, balance, 
                accountlimit, branchcode, status
            INTO 
                v_customercode, v_accountnumber, v_accountid, v_balance,
                v_accountlimit, v_branchcode, v_account_status
            FROM account 
            WHERE accountnumber = v_account_no;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Account % NOT FOUND in account table', v_account_no;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'ACCOUNT_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'ACCOUNT_NOT_FOUND',
                    'error_message', 'Account ' || v_account_no || ' not found in account table',
                    'table_name', 'account',
                    'account_number', v_account_no,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            -- Check if account is in allowed statuses
            IF v_account_status NOT IN (SELECT unnest(c_allowed_account_statuses)) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ⚠ Account found but status is "%" (allowed: %)', 
                        v_account_status, c_allowed_account_statuses;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'ACCOUNT_INACTIVE');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'ACCOUNT_INACTIVE',
                    'error_message', 'Account ' || v_account_no || ' is not in allowed statuses (status: ' || v_account_status || ')',
                    'table_name', 'account',
                    'account_number', v_account_no,
                    'account_status', v_account_status,
                    'allowed_statuses', c_allowed_account_statuses,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Account found and active';
                RAISE NOTICE '    Customer Code: %', v_customercode;
                RAISE NOTICE '    Account Status: % (allowed)', v_account_status;
                RAISE NOTICE '    Branch Code: %', v_branchcode;
            END IF;
            
            -- ========== STEP 3: Query customer table ==========
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 3: Checking customer table for customercode: %', v_customercode;
            END IF;
            IF p_debug_level >= c_debug_verbose THEN
			    RAISE NOTICE '  Nationality: "%" (Length: %)', v_nationality, length(v_nationality);
			END IF;
            -- Try to get customer details
            SELECT 
                cbs_customer_code, fname, lname, middlename, salutation, 
                emailid, mobileno, branchcode, bankcode, maritalstatus, 
                status, dob, address, nationality, gender, documenttype, 
                documentid, occupation, employment_type, annualincome,
                fathername, grandfathername, mothername, spousename, notes
            INTO 
                v_cbs_customer_code, v_fname, v_lname, v_middlename, v_salutation,
                v_emailid, v_mobileno, v_customer_branchcode, v_bankcode, v_maritalstatus,
                v_customer_status, v_dob, v_address, v_nationality, v_gender,
                v_documenttype, v_documentid, v_occupation, v_employment_type, v_annualincome,
                v_fathername, v_grandfathername, v_mothername, v_spousename, v_notes
            FROM customer 
            WHERE customercode = v_customercode;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Customer % NOT FOUND in customer table', v_customercode;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'CUSTOMER_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'CUSTOMER_NOT_FOUND',
                    'error_message', 'Customer ' || v_customercode || ' not found in customer table',
                    'table_name', 'customer',
                    'customercode', v_customercode,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Customer found';
                RAISE NOTICE '    Name: % % %', v_fname, COALESCE(v_middlename, ''), v_lname;
                RAISE NOTICE '    DOB: %', v_dob;
                RAISE NOTICE '    Mobile: %', v_mobileno;
                RAISE NOTICE '    Email: %', v_emailid;
                RAISE NOTICE '    Gender: %', v_gender;
            END IF;
            
            -- ========== STEP 4: Generate DAP_IDEN ==========
            -- Generate unique DAP_IDEN
            v_dap_iden := (EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) * 1000)::BIGINT + 
                         (v_request_index * 100) + 
                         (abs(hashtext(v_request_id || v_customercode)) % 100);
            
            -- Ensure uniqueness
            WHILE EXISTS (SELECT 1 FROM credit_card_application WHERE dap_iden = v_dap_iden) LOOP
                v_dap_iden := v_dap_iden + 1;
            END LOOP;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 4: Generated DAP_IDEN: %', v_dap_iden;
            END IF;
            
            -- ========== STEP 5: Check for Duplicate Customer ==========
            IF EXISTS (SELECT 1 FROM credit_card_application WHERE dap_cus_iden = v_customercode) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE 'STEP 5: Customer % already exists in credit_card_application', v_customercode;
                END IF;
                
                v_total_duplicates := v_total_duplicates + 1;
                v_duplicate_ids := array_append(v_duplicate_ids, v_customercode);
                
                -- Update existing record
                -- Update statement with ONLY batch_id
UPDATE credit_card_application SET
    dap_ban_code = COALESCE(v_bankcode, dap_ban_code, '402122'),
    dap_bra_code = COALESCE(v_customer_branchcode, dap_bra_code, v_branchcode, '999'),
    dap_firs_nam1 = COALESCE(v_fname, dap_firs_nam1),
    dap_last_nam1 = COALESCE(v_lname, dap_last_nam1),
    dap_midd_nam1 = COALESCE(v_middlename, dap_midd_nam1),
    dap_tit1 = CASE 
        WHEN v_salutation = 'Mr.' THEN '1'
        WHEN v_salutation = 'Mrs.' THEN '2'
        WHEN v_salutation = 'Ms.' THEN '3'
        WHEN v_salutation = 'Dr.' THEN '4'
        ELSE COALESCE(dap_tit1, '1')
    END,
    dap_birt_dat1 = COALESCE(v_dob, dap_birt_dat1),
    dap_birt_loc1 = COALESCE(v_address, dap_birt_loc1),
    dap_firs_ide1 = COALESCE(v_documentid, dap_firs_ide1),
    dap_firs_iden_typ1 = COALESCE(v_documenttype, dap_firs_iden_typ1),
    dap_gend1 = CASE 
        WHEN v_gender = 'Male' OR v_gender = 'M' THEN '1'
        WHEN v_gender = 'Female' OR v_gender = 'F' THEN '2'
        ELSE COALESCE(dap_gend1, '1')
    END,
    dap_mst_cod1 = CASE 
        WHEN v_maritalstatus = 'M' THEN '1'
        WHEN v_maritalstatus = 'S' THEN '2'
        WHEN v_maritalstatus = 'D' THEN '3'
        WHEN v_maritalstatus = 'W' THEN '4'
        ELSE COALESCE(dap_mst_cod1, '1')
    END,
    dap_cou_cod1 = CASE 
        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
        ELSE COALESCE(dap_cou_cod1, '524')
    END,
    dap_requ_acc_numb = COALESCE(v_accountnumber, dap_requ_acc_numb),
    dap_requ_acc_curr_code = COALESCE(v_currency_type, dap_requ_acc_curr_code, '524'),
    dap_phon_number = COALESCE(v_mobileno, v_mobile, dap_phon_number),
    dap_email_adr = COALESCE(v_emailid, dap_email_adr),
    firstaddressline1 = COALESCE(v_address, firstaddressline1),
    firstcity = COALESCE(v_customer_branchcode, firstcity, '30608'),
    batch_id = v_batch_id,  -- ONLY batch_id
    updated_at = CURRENT_TIMESTAMP
WHERE dap_cus_iden = v_customercode;
				
                
                
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✓ Updated existing application (DAP_IDEN: %)', v_dap_iden;
                END IF;
                
                v_success_details := v_success_details || jsonb_build_object(
                    'dap_iden', v_dap_iden,
                    'request_id', v_request_id,
                    'customercode', v_customercode,
                    'account_number', v_accountnumber,
                    'customer_name', v_fname || ' ' || v_lname,
                    'action', 'UPDATED',
                    'reason', 'Duplicate customer',
                    'request_index', v_request_index,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                
            ELSE
                -- ========== STEP 6: Insert New Record ==========
                DECLARE
                    v_dap_gend CHAR(1);
                    v_dap_tit CHAR(1);
                    v_dap_mst_cod CHAR(1);
                    v_country_code VARCHAR(10);
                    v_net_income NUMERIC(15,2);
                    v_customer_age INTEGER;
                BEGIN
                    -- Map gender
                    v_dap_gend := CASE 
                        WHEN v_gender = 'Male' OR v_gender = 'M' OR v_gender ILIKE '%male%' THEN '1'
                        WHEN v_gender = 'Female' OR v_gender = 'F' OR v_gender ILIKE '%female%' THEN '2'
                        ELSE '1'
                    END;
                    
                    -- Map title
                    v_dap_tit := CASE 
                        WHEN v_salutation = 'Mr.' THEN '1'
                        WHEN v_salutation = 'Mrs.' THEN '2'
                        WHEN v_salutation = 'Ms.' THEN '3'
                        WHEN v_salutation = 'Dr.' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map marital status
                    v_dap_mst_cod := CASE 
                        WHEN v_maritalstatus = 'M' THEN '1'
                        WHEN v_maritalstatus = 'S' THEN '2'
                        WHEN v_maritalstatus = 'D' THEN '3'
                        WHEN v_maritalstatus = 'W' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map country code
                    v_country_code := CASE 
                        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
                        ELSE '524'
                    END;
                    
                    -- Calculate net income
                    v_net_income := COALESCE(v_annualincome, 0) * 0.8;
                    
                    -- Calculate age
                    IF v_dob IS NOT NULL THEN
                        v_customer_age := EXTRACT(YEAR FROM AGE(CURRENT_DATE, v_dob))::INTEGER;
                    ELSE
                        v_customer_age := 0;
                    END IF;
             --------------------------DEBUGING ST-----------------------------------
									 IF p_debug_level >= c_debug_verbose THEN
						    RAISE NOTICE 'Checking ALL VARCHAR(10) columns before INSERT:';
						    RAISE NOTICE '1. dap_bra_code: Value="%", Length=%', 
						        COALESCE(v_customer_branchcode, v_branchcode, '999'), 
						        length(COALESCE(v_customer_branchcode, v_branchcode, '999'));
						    
						    RAISE NOTICE '2. dap_firs_iden_typ1: Value="%", Length=%', 
						        v_documenttype, length(v_documenttype);
						    
						    RAISE NOTICE '3. dap_seco_iden_typ1: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '4. dap_mst_cod1: Value="%", Length=%', 
						        v_dap_mst_cod, length(v_dap_mst_cod);
						    
						    RAISE NOTICE '5. dap_cou_cod1: Value="%", Length=%', 
						        v_country_code, length(v_country_code);
						    
						    RAISE NOTICE '6. dap_firs_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '7. dap_seco_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '8. dap_mst_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '9. dap_cou_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '10. dap_requ_acc_curr_code: Value="%", Length=%', 
						        COALESCE(v_currency_type, '524'), length(COALESCE(v_currency_type, '524'));
						    
						    RAISE NOTICE '11. dap_requ_cpr_code: Value="%", Length=%', 
						        '731', length('731');
						    
						    RAISE NOTICE '12. dap_requ_dpr_code: Value="%", Length=%', 
						        '730', length('730');
						    
						    RAISE NOTICE '13. dap_chld_titl: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '14. dap_pers_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '15. dap_memb_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '16. dap_vca_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '17. dap_pro_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '18. dap_cust_pare: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '19. firstaddresstype: Value="%", Length=%', 
						        '08', length('08');
						END IF;

			 --------------------------DEBUGGING END ST----------------------------
                    -- Insert new record
                    INSERT INTO credit_card_application (
                        dap_iden, dap_ban_code, dap_bra_code, dap_user, dap_bat_code,
                        dap_cus_type, dap_cus_old_new, dap_cus_iden, dap_date, dap_ast_code,
                        dap_firs_nam1, dap_last_nam1, dap_midd_nam1, dap_tit1,
                        dap_birt_dat1, dap_birt_loc1, dap_firs_ide1, dap_firs_iden_typ1,
                        dap_seco_ide1, dap_seco_iden_typ1, dap_gend1, dap_mst_cod1, dap_cou_cod1,
                        dap_empl_cod1, dap_empl_nam1, dap_gros_sal1, dap_net_sal1, dap_empl_age1,
                        dap_requ_acc_numb, dap_requ_acc_curr_code, dap_requ_cpr_code,
                        dap_pan_gene_manu_auto, dap_requ_dpr_code,
                        dap_requ_effe_date, dap_requ_expi_date,
                        dap_phon_number, dap_email_adr, dap_gree_pin_flag,
                        firstaddresstype, firstaddressline1, firstaddressline2, 
                        firstaddressline3, firstaddresszipcode, firstadressphone1,
                        firstadressphone2, firstcity, emailaddress,
                        created_at, updated_at, batch_id
                    ) VALUES (
                        v_dap_iden, 
                        COALESCE(v_bankcode, '402122'),
                        COALESCE(v_customer_branchcode, v_branchcode, '999'),
                        'CCMSUSER',
                        '10',
                        'I',
                        'N',
                        v_customercode,
                        CURRENT_DATE,
                        '730',
                        v_fname,
                        v_lname,
                        v_middlename,
                        v_dap_tit,
                        v_dob,
                        v_address,
                        v_documentid,
                        v_documenttype,
                        '', '',
                        v_dap_gend,
                        v_dap_mst_cod,
                        v_country_code,
                        v_employment_type,
                        v_occupation,
                        v_annualincome,
                        v_net_income,
                        v_customer_age,
                        v_accountnumber,
                        COALESCE(v_currency_type, '524'),
                        '731',
                        'A',
                        '730',
                        CURRENT_DATE,
                        CURRENT_DATE + INTERVAL '5 years',
                        COALESCE(v_mobileno, v_mobile),
                        v_emailid,
                        'Y',
                        '08',
                        v_address,
                        '', '', '',
                        COALESCE(v_mobileno, v_mobile),
                        '',
                        COALESCE(v_customer_branchcode, '30608'),
                        v_emailid,
                        CURRENT_TIMESTAMP,
                        CURRENT_TIMESTAMP,
                        v_batch_id
                    );
                    
                    v_total_inserted := v_total_inserted + 1;
                    
                    IF p_debug_level >= c_debug_verbose THEN
                        RAISE NOTICE '  ✓ Inserted new application (DAP_IDEN: %)', v_dap_iden;
                    END IF;
                    
                    v_success_details := v_success_details || jsonb_build_object(
                        'dap_iden', v_dap_iden,
                        'request_id', v_request_id,
                        'customercode', v_customercode,
                        'account_number', v_accountnumber,
                        'customer_name', v_fname || ' ' || v_lname,
                        'card_type', v_card_type,
                        'card_scheme', v_card_scheme,
                        'action', 'INSERTED',
                        'request_index', v_request_index,
                        'timestamp', CURRENT_TIMESTAMP::TEXT
                    );
                    
                END;
            END IF;
            
            -- ========== STEP 7: Update Request Status ==========
            UPDATE creditcardcycle
            SET status = 'PROCESSING', 
                updated_at = CURRENT_TIMESTAMP
            WHERE request_id = v_request_id;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 7: Updated card_request_cycle status to PROCESSING';
                RAISE NOTICE '✓ Successfully processed request %', v_request_id;
            ELSIF p_debug_level >= c_debug_basic THEN
                RAISE NOTICE '✓ Processed request %', v_request_id;
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS 
                    v_error_message = MESSAGE_TEXT,
                    v_sql_state = RETURNED_SQLSTATE;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, split_part(v_sql_state, ':', 1));
                
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'PROCESSING_ERROR',
                    'error_message', v_error_message,
                    'sql_state', v_sql_state,
                    'timestamp', CURRENT_TIMESTAMP::TEXT,
                    'debug_level', p_debug_level
                );
                
                IF p_debug_level >= c_debug_basic THEN
                    RAISE NOTICE '✗ Error processing request %: %', v_request_id, v_error_message;
                END IF;
        END;
        
        -- Log progress
        IF p_debug_level >= c_debug_basic AND v_request_index % 5 = 0 THEN
            RAISE NOTICE 'Progress: %/% requests (%✓ %✗ %⚠ %↻)',
                v_request_index, v_total_requests, 
                v_total_inserted, v_total_errors, v_total_skipped, v_total_duplicates;
        END IF;
        
    END LOOP;
    
    -- ========== BUILD FINAL RESULT ==========
    v_end_time := CURRENT_TIMESTAMP;
    v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
    
    -- Calculate success rate
    IF v_total_requests > 0 THEN
        v_success_rate := ((v_total_inserted + v_total_duplicates)::FLOAT / v_total_requests * 100)::NUMERIC(5,2);
    ELSE
        v_success_rate := 0;
    END IF;
    
    -- Build error summary
    IF array_length(v_error_types, 1) > 0 THEN
        DECLARE
            v_error_type TEXT;
            v_temp_errors TEXT[];
            v_error_count INTEGER;
        BEGIN
            FOR v_error_type IN 
                SELECT DISTINCT unnest(v_error_types)
            LOOP
                v_temp_errors := ARRAY[]::TEXT[];
                FOR i IN 1..array_length(v_error_types, 1) LOOP
                    IF v_error_types[i] = v_error_type THEN
                        v_temp_errors := array_append(v_temp_errors, v_error_types[i]);
                    END IF;
                END LOOP;
                
                v_error_count := array_length(v_temp_errors, 1);
                v_error_summary := v_error_summary || jsonb_build_object(
                    'error_type', v_error_type,
                    'count', v_error_count,
                    'percentage', ROUND((v_error_count::FLOAT / v_total_requests * 100)::NUMERIC, 2)
                );
            END LOOP;
        END;
    END IF;
    
    -- Build final result JSON
    v_result := jsonb_build_object(
        'success', v_total_inserted > 0 OR v_total_duplicates > 0,
        'message', CASE 
                    WHEN v_total_inserted > 0 OR v_total_duplicates > 0
                        THEN 'Processing completed successfully'
                    WHEN v_total_skipped > 0 
                        THEN 'Some requests were skipped (not in allowed statuses)'
                    WHEN v_total_errors = v_total_requests 
                        THEN 'All requests failed - check error details'
                    ELSE 'Processing completed with issues'
                   END,
        'batch_id', v_batch_id,
        'debug_level', p_debug_level,
        
        -- Statistics
        'statistics', jsonb_build_object(
            'total_requests', v_total_requests,
            'inserted', v_total_inserted,
            'duplicates', v_total_duplicates,
            'errors', v_total_errors,
            'skipped', v_total_skipped,
            'success_rate', v_success_rate
        ),
        
        -- Timing
        'timing', jsonb_build_object(
            'start_time', v_start_time::TEXT,
            'end_time', v_end_time::TEXT,
            'duration_seconds', ROUND(v_total_duration, 3)
        ),
        
        -- Configuration
        'config', jsonb_build_object(
            'allowed_request_statuses', c_allowed_request_statuses,
            'allowed_account_statuses', c_allowed_account_statuses
        ),
        
        -- Details
        'duplicate_customers', v_duplicate_ids,
        'error_summary', v_error_summary
    );
    
    -- Add detailed info based on debug level
    IF p_debug_level >= c_debug_detailed THEN
        v_result := v_result || jsonb_build_object(
            'success_details', v_success_details,
            'skipped_details', v_skipped_details
        );
    END IF;
    
    IF p_debug_level >= c_debug_verbose THEN
        v_result := v_result || jsonb_build_object(
            'error_details', v_error_details
        );
    END IF;
    
    -- ========== FINAL LOGGING ==========
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Batch % completed in % seconds', v_batch_id, ROUND(v_total_duration, 2);
        RAISE NOTICE 'Summary: % inserted, % duplicates, % errors, % skipped', 
            v_total_inserted, v_total_duplicates, v_total_errors, v_total_skipped;
        
        IF v_total_requests > 0 THEN
            RAISE NOTICE 'Success rate: %%%', v_success_rate;
        END IF;
        
        RAISE NOTICE 'Config: Request statuses=%, Account statuses=%', 
            c_allowed_request_statuses, c_allowed_account_statuses;
        
        RAISE NOTICE '========================================================================';
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        v_end_time := CURRENT_TIMESTAMP;
        v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE '========================================================================';
            RAISE NOTICE 'CRITICAL ERROR: %', v_error_message;
            RAISE NOTICE 'SQL State: %', v_sql_state;
            RAISE NOTICE '========================================================================';
        END IF;
        
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Critical error: ' || v_error_message,
            'batch_id', v_batch_id,
            'debug_level', p_debug_level,
            'sql_state', v_sql_state,
            'config', jsonb_build_object(
                'allowed_request_statuses', c_allowed_request_statuses,
                'allowed_account_statuses', c_allowed_account_statuses
            ),
            'statistics', jsonb_build_object(
                'total_requests_attempted', v_total_requests,
                'total_inserted', v_total_inserted,
                'total_errors', v_total_errors,
                'total_duplicates', v_total_duplicates,
                'total_skipped', v_total_skipped
            ),
            'timing', jsonb_build_object(
                'start_time', v_start_time::TEXT,
                'end_time', v_end_time::TEXT,
                'duration_seconds', ROUND(v_total_duration, 3)
            ),
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.finsert_credit_card_application(p_request_ids text[], p_debug_level integer, p_batch_id text, p_username character varying) OWNER TO postgres;

--
-- Name: finsert_debit_card_application(text[], integer, text, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finsert_debit_card_application(p_request_ids text[] DEFAULT NULL::text[], p_debug_level integer DEFAULT 1, p_batch_id text DEFAULT NULL::text, p_username character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER PARALLEL SAFE
    AS $$
DECLARE
    v_result JSONB;
    v_batch_id VARCHAR(50);
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_total_inserted INTEGER := 0;
    v_total_errors INTEGER := 0;
    v_total_duplicates INTEGER := 0;
    v_total_skipped INTEGER := 0;
    v_total_requests INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
    v_request_index INTEGER;
    v_request_id VARCHAR(50);
    
    -- Variables for data lookup
    -- From card_request_cycle
    v_full_name VARCHAR(30);
    v_mobile VARCHAR(15);
    v_account_no VARCHAR(20);
    v_request_type VARCHAR(50);
    v_card_type VARCHAR(50);
    v_currency_type VARCHAR(10);
    v_card_scheme VARCHAR(50);
    v_request_branch_id VARCHAR(100);
    v_delivery_branch_id VARCHAR(100);
    v_customer_branch_id VARCHAR(100);
    v_customer_branch_code VARCHAR(4);
    v_account_type VARCHAR(100);
    v_instcode VARCHAR(12);
    v_remarks TEXT;
    v_requstor_branch_code VARCHAR(4);
    v_receiver_branch_code VARCHAR(4);
    v_pintype VARCHAR(15);
    v_request_status VARCHAR(20);
    
    -- From account table
    v_customercode VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_accountid VARCHAR(12);
    v_balance NUMERIC(18,2);
    v_accountlimit NUMERIC(18,2);
    v_branchcode VARCHAR(10);
    v_account_status CHAR(1);
    
    -- From customer table
    v_cbs_customer_code VARCHAR(12);
    v_fname VARCHAR(50);
    v_lname VARCHAR(50);
    v_middlename VARCHAR(50);
    v_salutation VARCHAR(20);
    v_emailid VARCHAR(100);
    v_mobileno VARCHAR(15);
    v_customer_branchcode VARCHAR(10);
    v_bankcode VARCHAR(10);
    v_maritalstatus CHAR(1);
    v_customer_status CHAR(1);
    v_dob DATE;
    v_address VARCHAR(255);
    v_nationality VARCHAR(30);
    v_gender VARCHAR(10);
    v_documenttype VARCHAR(25);
    v_documentid VARCHAR(15);
    v_occupation VARCHAR(25);
    v_employment_type VARCHAR(30);
    v_annualincome NUMERIC(15,2);
    v_fathername VARCHAR(50);
    v_grandfathername VARCHAR(50);
    v_mothername VARCHAR(50);
    v_spousename VARCHAR(50);
    v_notes TEXT;
    
    -- Generated DAP_IDEN (application ID)
    v_dap_iden BIGINT;
    
    -- Error tracking
    v_error_details JSONB := '[]'::JSONB;
    v_success_details JSONB := '[]'::JSONB;
    v_skipped_details JSONB := '[]'::JSONB;
    v_duplicate_ids TEXT[] := ARRAY[]::TEXT[];
    v_error_types TEXT[] := ARRAY[]::TEXT[];
    
    -- Debug tracking
    v_temp_count INTEGER;
    
    -- Performance tracking
    v_total_duration NUMERIC(10,3) := 0;
    v_success_rate NUMERIC(5,2) := 0;
    v_error_summary JSONB := '[]'::JSONB;
    
    -- Constants for debug levels
    c_debug_none CONSTANT INTEGER := 0;
    c_debug_basic CONSTANT INTEGER := 1;
    c_debug_detailed CONSTANT INTEGER := 2;
    c_debug_verbose CONSTANT INTEGER := 3;
    
    -- Status configuration (internal constants)
    c_allowed_request_statuses CONSTANT text[] := ARRAY['Pending', 'Approved', 'PROCESSING', 'VERIFIED', 'Processed'];
    c_allowed_account_statuses CONSTANT text[] := ARRAY['1', 'A', 'ACTIVE', 'Y', 'a', '0'];
    
BEGIN
    -- Initialize
    v_start_time := CURRENT_TIMESTAMP;
    
    -- Validate debug level
    IF p_debug_level NOT IN (0, 1, 2, 3) THEN
        p_debug_level := 1;  -- Default to basic if invalid
    END IF;
    
    -- Generate or use provided batch ID
    IF p_batch_id IS NULL OR p_batch_id = '' THEN
        v_batch_id := 'DAP_' || TO_CHAR(CURRENT_TIMESTAMP, 'MMDDHH24MISS');
    ELSE
        v_batch_id := p_batch_id;
    END IF;
    
    -- Validate input data
    IF p_request_ids IS NULL OR array_length(p_request_ids, 1) IS NULL THEN
        v_end_time := CURRENT_TIMESTAMP;
        v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        v_result := jsonb_build_object(
            'success', false,
            'message', 'No request IDs provided',
            'batch_id', v_batch_id,
            'total_requests', 0,
            'total_inserted', 0,
            'total_errors', 0,
            'total_duplicates', 0,
            'total_skipped', 0,
            'start_time', v_start_time::TEXT,
            'end_time', v_end_time::TEXT,
            'duration_seconds', ROUND(v_total_duration, 3),
            'debug_level', p_debug_level,
            'config', jsonb_build_object(
                'allowed_request_statuses', c_allowed_request_statuses,
                'allowed_account_statuses', c_allowed_account_statuses
            )
        );
        RETURN v_result;
    END IF;
    
    v_total_requests := array_length(p_request_ids, 1);
    
    -- Log based on debug level
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Starting debit card application insertion batch: %', v_batch_id;
        RAISE NOTICE 'Total request IDs to process: %', v_total_requests;
        RAISE NOTICE 'Debug level: %', p_debug_level;
        RAISE NOTICE 'Allowed request statuses: %', c_allowed_request_statuses;
        RAISE NOTICE 'Allowed account statuses: %', c_allowed_account_statuses;
        RAISE NOTICE 'Start time: %', v_start_time;
        RAISE NOTICE '========================================================================';
    END IF;
    
    -- Process each request ID
    FOR v_request_index IN 1..v_total_requests LOOP
        v_request_id := p_request_ids[v_request_index];
        
        -- Skip empty request IDs
        IF v_request_id IS NULL OR v_request_id = '' THEN
            v_total_errors := v_total_errors + 1;
            v_error_types := array_append(v_error_types, 'EMPTY_REQUEST_ID');
            v_error_details := v_error_details || jsonb_build_object(
                'request_index', v_request_index,
                'error_type', 'EMPTY_REQUEST_ID',
                'error_message', 'Request ID is empty or null',
                'timestamp', CURRENT_TIMESTAMP::TEXT
            );
            CONTINUE;
        END IF;
        
        IF p_debug_level >= c_debug_detailed THEN
            RAISE NOTICE '--- Processing request_id [%/%]: % ---', 
                v_request_index, v_total_requests, v_request_id;
        END IF;
        
        BEGIN
            -- ========== STEP 1: Query card_request_cycle ==========
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 1: Checking card_request_cycle for request_id: %', v_request_id;
            END IF;
            
            -- Try to get the request details
            SELECT 
                full_name, mobile, account_no, request_type, card_type, 
                currency_type, card_scheme, request_branch_id, delivery_branch_id,
                customer_branch_id, customer_branch_code, account_type, instcode,
                remarks, requstor_branch_code, receiver_branch_code, pintype, status
            INTO 
                v_full_name, v_mobile, v_account_no, v_request_type, v_card_type,
                v_currency_type, v_card_scheme, v_request_branch_id, v_delivery_branch_id,
                v_customer_branch_id, v_customer_branch_code, v_account_type, v_instcode,
                v_remarks, v_requstor_branch_code, v_receiver_branch_code, v_pintype, v_request_status
            FROM card_request_cycle 
            WHERE request_id = v_request_id;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Request ID % NOT FOUND in card_request_cycle table', v_request_id;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'REQUEST_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'REQUEST_NOT_FOUND',
                    'error_message', 'Request ID not found in card_request_cycle table',
                    'table_name', 'card_request_cycle',
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            -- Check if request is in allowed statuses
            IF v_request_status NOT IN (SELECT unnest(c_allowed_request_statuses)) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ⚠ Request found but status is "%" (allowed: %)', 
                        v_request_status, c_allowed_request_statuses;
                END IF;
                
                v_total_skipped := v_total_skipped + 1;
                v_skipped_details := v_skipped_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'reason', 'Request not in allowed statuses',
                    'current_status', v_request_status,
                    'allowed_statuses', c_allowed_request_statuses,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Request found in card_request_cycle';
                RAISE NOTICE '    Status: % (allowed)', v_request_status;
                RAISE NOTICE '    Account No: %', v_account_no;
                RAISE NOTICE '    Card Type: %', v_card_type;
                RAISE NOTICE '    Currency: %', v_currency_type;
            END IF;
            
            -- ========== STEP 2: Query account table ==========
            IF v_account_no IS NULL OR v_account_no = '' THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Account number is NULL or empty in card_request_cycle';
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'NO_ACCOUNT_NUMBER');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'NO_ACCOUNT_NUMBER',
                    'error_message', 'Account number not found for request in card_request_cycle',
                    'table_name', 'card_request_cycle',
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 2: Checking account table for account_no: %', v_account_no;
            END IF;
            
            -- Try to get account details
            SELECT 
                customercode, accountnumber, accountid, balance, 
                accountlimit, branchcode, status
            INTO 
                v_customercode, v_accountnumber, v_accountid, v_balance,
                v_accountlimit, v_branchcode, v_account_status
            FROM account 
            WHERE accountnumber = v_account_no;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Account % NOT FOUND in account table', v_account_no;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'ACCOUNT_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'ACCOUNT_NOT_FOUND',
                    'error_message', 'Account ' || v_account_no || ' not found in account table',
                    'table_name', 'account',
                    'account_number', v_account_no,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            -- Check if account is in allowed statuses
            IF v_account_status NOT IN (SELECT unnest(c_allowed_account_statuses)) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ⚠ Account found but status is "%" (allowed: %)', 
                        v_account_status, c_allowed_account_statuses;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'ACCOUNT_INACTIVE');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'ACCOUNT_INACTIVE',
                    'error_message', 'Account ' || v_account_no || ' is not in allowed statuses (status: ' || v_account_status || ')',
                    'table_name', 'account',
                    'account_number', v_account_no,
                    'account_status', v_account_status,
                    'allowed_statuses', c_allowed_account_statuses,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Account found and active';
                RAISE NOTICE '    Customer Code: %', v_customercode;
                RAISE NOTICE '    Account Status: % (allowed)', v_account_status;
                RAISE NOTICE '    Branch Code: %', v_branchcode;
            END IF;
            
            -- ========== STEP 3: Query customer table ==========
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 3: Checking customer table for customercode: %', v_customercode;
            END IF;
            IF p_debug_level >= c_debug_verbose THEN
			    RAISE NOTICE '  Nationality: "%" (Length: %)', v_nationality, length(v_nationality);
			END IF;
            -- Try to get customer details
            SELECT 
                cbs_customer_code, fname, lname, middlename, salutation, 
                emailid, mobileno, branchcode, bankcode, maritalstatus, 
                status, dob, address, nationality, gender, documenttype, 
                documentid, occupation, employment_type, annualincome,
                fathername, grandfathername, mothername, spousename, notes
            INTO 
                v_cbs_customer_code, v_fname, v_lname, v_middlename, v_salutation,
                v_emailid, v_mobileno, v_customer_branchcode, v_bankcode, v_maritalstatus,
                v_customer_status, v_dob, v_address, v_nationality, v_gender,
                v_documenttype, v_documentid, v_occupation, v_employment_type, v_annualincome,
                v_fathername, v_grandfathername, v_mothername, v_spousename, v_notes
            FROM customer 
            WHERE customercode = v_customercode;
            
            IF NOT FOUND THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✗ Customer % NOT FOUND in customer table', v_customercode;
                END IF;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, 'CUSTOMER_NOT_FOUND');
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'CUSTOMER_NOT_FOUND',
                    'error_message', 'Customer ' || v_customercode || ' not found in customer table',
                    'table_name', 'customer',
                    'customercode', v_customercode,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                CONTINUE;
            END IF;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE '  ✓ Customer found';
                RAISE NOTICE '    Name: % % %', v_fname, COALESCE(v_middlename, ''), v_lname;
                RAISE NOTICE '    DOB: %', v_dob;
                RAISE NOTICE '    Mobile: %', v_mobileno;
                RAISE NOTICE '    Email: %', v_emailid;
                RAISE NOTICE '    Gender: %', v_gender;
            END IF;
            
            -- ========== STEP 4: Generate DAP_IDEN ==========
            -- Generate unique DAP_IDEN
            v_dap_iden := (EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) * 1000)::BIGINT + 
                         (v_request_index * 100) + 
                         (abs(hashtext(v_request_id || v_customercode)) % 100);
            
            -- Ensure uniqueness
            WHILE EXISTS (SELECT 1 FROM debit_card_application WHERE dap_iden = v_dap_iden) LOOP
                v_dap_iden := v_dap_iden + 1;
            END LOOP;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 4: Generated DAP_IDEN: %', v_dap_iden;
            END IF;
            
            -- ========== STEP 5: Check for Duplicate Customer ==========
            IF EXISTS (SELECT 1 FROM debit_card_application WHERE dap_cus_iden = v_customercode) THEN
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE 'STEP 5: Customer % already exists in debit_card_application', v_customercode;
                END IF;
                
                v_total_duplicates := v_total_duplicates + 1;
                v_duplicate_ids := array_append(v_duplicate_ids, v_customercode);
                
                -- Update existing record
                -- Update statement with ONLY batch_id
UPDATE debit_card_application SET
    dap_ban_code = COALESCE(v_bankcode, dap_ban_code, '402122'),
    dap_bra_code = COALESCE(v_customer_branchcode, dap_bra_code, v_branchcode, '999'),
    dap_firs_nam1 = COALESCE(v_fname, dap_firs_nam1),
    dap_last_nam1 = COALESCE(v_lname, dap_last_nam1),
    dap_midd_nam1 = COALESCE(v_middlename, dap_midd_nam1),
    dap_tit1 = CASE 
        WHEN v_salutation = 'Mr.' THEN '1'
        WHEN v_salutation = 'Mrs.' THEN '2'
        WHEN v_salutation = 'Ms.' THEN '3'
        WHEN v_salutation = 'Dr.' THEN '4'
        ELSE COALESCE(dap_tit1, '1')
    END,
    dap_birt_dat1 = COALESCE(v_dob, dap_birt_dat1),
    dap_birt_loc1 = COALESCE(v_address, dap_birt_loc1),
    dap_firs_ide1 = COALESCE(v_documentid, dap_firs_ide1),
    dap_firs_iden_typ1 = COALESCE(v_documenttype, dap_firs_iden_typ1),
    dap_gend1 = CASE 
        WHEN v_gender = 'Male' OR v_gender = 'M' THEN '1'
        WHEN v_gender = 'Female' OR v_gender = 'F' THEN '2'
        ELSE COALESCE(dap_gend1, '1')
    END,
    dap_mst_cod1 = CASE 
        WHEN v_maritalstatus = 'M' THEN '1'
        WHEN v_maritalstatus = 'S' THEN '2'
        WHEN v_maritalstatus = 'D' THEN '3'
        WHEN v_maritalstatus = 'W' THEN '4'
        ELSE COALESCE(dap_mst_cod1, '1')
    END,
    dap_cou_cod1 = CASE 
        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
        ELSE COALESCE(dap_cou_cod1, '524')
    END,
    dap_requ_acc_numb = COALESCE(v_accountnumber, dap_requ_acc_numb),
    dap_requ_acc_curr_code = COALESCE(v_currency_type, dap_requ_acc_curr_code, '524'),
    dap_phon_number = COALESCE(v_mobileno, v_mobile, dap_phon_number),
    dap_email_adr = COALESCE(v_emailid, dap_email_adr),
    firstaddressline1 = COALESCE(v_address, firstaddressline1),
    firstcity = COALESCE(v_customer_branchcode, firstcity, '30608'),
    batch_id = v_batch_id,  -- ONLY batch_id
    updated_at = CURRENT_TIMESTAMP
WHERE dap_cus_iden = v_customercode;
				
                
                
                IF p_debug_level >= c_debug_verbose THEN
                    RAISE NOTICE '  ✓ Updated existing application (DAP_IDEN: %)', v_dap_iden;
                END IF;
                
                v_success_details := v_success_details || jsonb_build_object(
                    'dap_iden', v_dap_iden,
                    'request_id', v_request_id,
                    'customercode', v_customercode,
                    'account_number', v_accountnumber,
                    'customer_name', v_fname || ' ' || v_lname,
                    'action', 'UPDATED',
                    'reason', 'Duplicate customer',
                    'request_index', v_request_index,
                    'timestamp', CURRENT_TIMESTAMP::TEXT
                );
                
            ELSE
                -- ========== STEP 6: Insert New Record ==========
                DECLARE
                    v_dap_gend CHAR(1);
                    v_dap_tit CHAR(1);
                    v_dap_mst_cod CHAR(1);
                    v_country_code VARCHAR(10);
                    v_net_income NUMERIC(15,2);
                    v_customer_age INTEGER;
                BEGIN
                    -- Map gender
                    v_dap_gend := CASE 
                        WHEN v_gender = 'Male' OR v_gender = 'M' OR v_gender ILIKE '%male%' THEN '1'
                        WHEN v_gender = 'Female' OR v_gender = 'F' OR v_gender ILIKE '%female%' THEN '2'
                        ELSE '1'
                    END;
                    
                    -- Map title
                    v_dap_tit := CASE 
                        WHEN v_salutation = 'Mr.' THEN '1'
                        WHEN v_salutation = 'Mrs.' THEN '2'
                        WHEN v_salutation = 'Ms.' THEN '3'
                        WHEN v_salutation = 'Dr.' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map marital status
                    v_dap_mst_cod := CASE 
                        WHEN v_maritalstatus = 'M' THEN '1'
                        WHEN v_maritalstatus = 'S' THEN '2'
                        WHEN v_maritalstatus = 'D' THEN '3'
                        WHEN v_maritalstatus = 'W' THEN '4'
                        ELSE '1'
                    END;
                    
                    -- Map country code
                    v_country_code := CASE 
                        WHEN v_nationality = 'Nepali' OR v_nationality ILIKE '%nepal%' THEN '524'
                        ELSE '524'
                    END;
                    
                    -- Calculate net income
                    v_net_income := COALESCE(v_annualincome, 0) * 0.8;
                    
                    -- Calculate age
                    IF v_dob IS NOT NULL THEN
                        v_customer_age := EXTRACT(YEAR FROM AGE(CURRENT_DATE, v_dob))::INTEGER;
                    ELSE
                        v_customer_age := 0;
                    END IF;
             --------------------------DEBUGING ST-----------------------------------
									 IF p_debug_level >= c_debug_verbose THEN
						    RAISE NOTICE 'Checking ALL VARCHAR(10) columns before INSERT:';
						    RAISE NOTICE '1. dap_bra_code: Value="%", Length=%', 
						        COALESCE(v_customer_branchcode, v_branchcode, '999'), 
						        length(COALESCE(v_customer_branchcode, v_branchcode, '999'));
						    
						    RAISE NOTICE '2. dap_firs_iden_typ1: Value="%", Length=%', 
						        v_documenttype, length(v_documenttype);
						    
						    RAISE NOTICE '3. dap_seco_iden_typ1: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '4. dap_mst_cod1: Value="%", Length=%', 
						        v_dap_mst_cod, length(v_dap_mst_cod);
						    
						    RAISE NOTICE '5. dap_cou_cod1: Value="%", Length=%', 
						        v_country_code, length(v_country_code);
						    
						    RAISE NOTICE '6. dap_firs_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '7. dap_seco_iden_typ2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '8. dap_mst_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '9. dap_cou_cod2: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '10. dap_requ_acc_curr_code: Value="%", Length=%', 
						        COALESCE(v_currency_type, '524'), length(COALESCE(v_currency_type, '524'));
						    
						    RAISE NOTICE '11. dap_requ_cpr_code: Value="%", Length=%', 
						        '731', length('731');
						    
						    RAISE NOTICE '12. dap_requ_dpr_code: Value="%", Length=%', 
						        '730', length('730');
						    
						    RAISE NOTICE '13. dap_chld_titl: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '14. dap_pers_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '15. dap_memb_fee_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '16. dap_vca_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '17. dap_pro_code: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '18. dap_cust_pare: Value="%", Length=%', 
						        '', length('');
						    
						    RAISE NOTICE '19. firstaddresstype: Value="%", Length=%', 
						        '08', length('08');
						END IF;

			 --------------------------DEBUGGING END ST----------------------------
                    -- Insert new record
                    INSERT INTO debit_card_application (
                        dap_iden, dap_ban_code, dap_bra_code, dap_user, dap_bat_code,
                        dap_cus_type, dap_cus_old_new, dap_cus_iden, dap_date, dap_ast_code,
                        dap_firs_nam1, dap_last_nam1, dap_midd_nam1, dap_tit1,
                        dap_birt_dat1, dap_birt_loc1, dap_firs_ide1, dap_firs_iden_typ1,
                        dap_seco_ide1, dap_seco_iden_typ1, dap_gend1, dap_mst_cod1, dap_cou_cod1,
                        dap_empl_cod1, dap_empl_nam1, dap_gros_sal1, dap_net_sal1, dap_empl_age1,
                        dap_requ_acc_numb, dap_requ_acc_curr_code, dap_requ_cpr_code,
                        dap_pan_gene_manu_auto, dap_requ_dpr_code,
                        dap_requ_effe_date, dap_requ_expi_date,
                        dap_phon_number, dap_email_adr, dap_gree_pin_flag,
                        firstaddresstype, firstaddressline1, firstaddressline2, 
                        firstaddressline3, firstaddresszipcode, firstadressphone1,
                        firstadressphone2, firstcity, emailaddress,
                        created_at, updated_at, batch_id
                    ) VALUES (
                        v_dap_iden, 
                        COALESCE(v_bankcode, '402122'),
                        COALESCE(v_customer_branchcode, v_branchcode, '999'),
                        'CCMSUSER',
                        '10',
                        'I',
                        'N',
                        v_customercode,
                        CURRENT_DATE,
                        '730',
                        v_fname,
                        v_lname,
                        v_middlename,
                        v_dap_tit,
                        v_dob,
                        v_address,
                        v_documentid,
                        v_documenttype,
                        '', '',
                        v_dap_gend,
                        v_dap_mst_cod,
                        v_country_code,
                        v_employment_type,
                        v_occupation,
                        v_annualincome,
                        v_net_income,
                        v_customer_age,
                        v_accountnumber,
                        COALESCE(v_currency_type, '524'),
                        '731',
                        'A',
                        '730',
                        CURRENT_DATE,
                        CURRENT_DATE + INTERVAL '5 years',
                        COALESCE(v_mobileno, v_mobile),
                        v_emailid,
                        'Y',
                        '08',
                        v_address,
                        '', '', '',
                        COALESCE(v_mobileno, v_mobile),
                        '',
                        COALESCE(v_customer_branchcode, '30608'),
                        v_emailid,
                        CURRENT_TIMESTAMP,
                        CURRENT_TIMESTAMP,
                        v_batch_id
                    );
                    
                    v_total_inserted := v_total_inserted + 1;
                    
                    IF p_debug_level >= c_debug_verbose THEN
                        RAISE NOTICE '  ✓ Inserted new application (DAP_IDEN: %)', v_dap_iden;
                    END IF;
                    
                    v_success_details := v_success_details || jsonb_build_object(
                        'dap_iden', v_dap_iden,
                        'request_id', v_request_id,
                        'customercode', v_customercode,
                        'account_number', v_accountnumber,
                        'customer_name', v_fname || ' ' || v_lname,
                        'card_type', v_card_type,
                        'card_scheme', v_card_scheme,
                        'action', 'INSERTED',
                        'request_index', v_request_index,
                        'timestamp', CURRENT_TIMESTAMP::TEXT
                    );
                    
                END;
            END IF;
            
            -- ========== STEP 7: Update Request Status ==========
            UPDATE card_request_cycle 
            SET status = 'PROCESSING', 
                updated_at = CURRENT_TIMESTAMP
            WHERE request_id = v_request_id;
            
            IF p_debug_level >= c_debug_verbose THEN
                RAISE NOTICE 'STEP 7: Updated card_request_cycle status to PROCESSING';
                RAISE NOTICE '✓ Successfully processed request %', v_request_id;
            ELSIF p_debug_level >= c_debug_basic THEN
                RAISE NOTICE '✓ Processed request %', v_request_id;
            END IF;
            
        EXCEPTION
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS 
                    v_error_message = MESSAGE_TEXT,
                    v_sql_state = RETURNED_SQLSTATE;
                
                v_total_errors := v_total_errors + 1;
                v_error_types := array_append(v_error_types, split_part(v_sql_state, ':', 1));
                
                v_error_details := v_error_details || jsonb_build_object(
                    'request_id', v_request_id,
                    'request_index', v_request_index,
                    'error_type', 'PROCESSING_ERROR',
                    'error_message', v_error_message,
                    'sql_state', v_sql_state,
                    'timestamp', CURRENT_TIMESTAMP::TEXT,
                    'debug_level', p_debug_level
                );
                
                IF p_debug_level >= c_debug_basic THEN
                    RAISE NOTICE '✗ Error processing request %: %', v_request_id, v_error_message;
                END IF;
        END;
        
        -- Log progress
        IF p_debug_level >= c_debug_basic AND v_request_index % 5 = 0 THEN
            RAISE NOTICE 'Progress: %/% requests (%✓ %✗ %⚠ %↻)',
                v_request_index, v_total_requests, 
                v_total_inserted, v_total_errors, v_total_skipped, v_total_duplicates;
        END IF;
        
    END LOOP;
    
    -- ========== BUILD FINAL RESULT ==========
    v_end_time := CURRENT_TIMESTAMP;
    v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
    
    -- Calculate success rate
    IF v_total_requests > 0 THEN
        v_success_rate := ((v_total_inserted + v_total_duplicates)::FLOAT / v_total_requests * 100)::NUMERIC(5,2);
    ELSE
        v_success_rate := 0;
    END IF;
    
    -- Build error summary
    IF array_length(v_error_types, 1) > 0 THEN
        DECLARE
            v_error_type TEXT;
            v_temp_errors TEXT[];
            v_error_count INTEGER;
        BEGIN
            FOR v_error_type IN 
                SELECT DISTINCT unnest(v_error_types)
            LOOP
                v_temp_errors := ARRAY[]::TEXT[];
                FOR i IN 1..array_length(v_error_types, 1) LOOP
                    IF v_error_types[i] = v_error_type THEN
                        v_temp_errors := array_append(v_temp_errors, v_error_types[i]);
                    END IF;
                END LOOP;
                
                v_error_count := array_length(v_temp_errors, 1);
                v_error_summary := v_error_summary || jsonb_build_object(
                    'error_type', v_error_type,
                    'count', v_error_count,
                    'percentage', ROUND((v_error_count::FLOAT / v_total_requests * 100)::NUMERIC, 2)
                );
            END LOOP;
        END;
    END IF;
    
    -- Build final result JSON
    v_result := jsonb_build_object(
        'success', v_total_inserted > 0 OR v_total_duplicates > 0,
        'message', CASE 
                    WHEN v_total_inserted > 0 OR v_total_duplicates > 0
                        THEN 'Processing completed successfully'
                    WHEN v_total_skipped > 0 
                        THEN 'Some requests were skipped (not in allowed statuses)'
                    WHEN v_total_errors = v_total_requests 
                        THEN 'All requests failed - check error details'
                    ELSE 'Processing completed with issues'
                   END,
        'batch_id', v_batch_id,
        'debug_level', p_debug_level,
        
        -- Statistics
        'statistics', jsonb_build_object(
            'total_requests', v_total_requests,
            'inserted', v_total_inserted,
            'duplicates', v_total_duplicates,
            'errors', v_total_errors,
            'skipped', v_total_skipped,
            'success_rate', v_success_rate
        ),
        
        -- Timing
        'timing', jsonb_build_object(
            'start_time', v_start_time::TEXT,
            'end_time', v_end_time::TEXT,
            'duration_seconds', ROUND(v_total_duration, 3)
        ),
        
        -- Configuration
        'config', jsonb_build_object(
            'allowed_request_statuses', c_allowed_request_statuses,
            'allowed_account_statuses', c_allowed_account_statuses
        ),
        
        -- Details
        'duplicate_customers', v_duplicate_ids,
        'error_summary', v_error_summary
    );
    
    -- Add detailed info based on debug level
    IF p_debug_level >= c_debug_detailed THEN
        v_result := v_result || jsonb_build_object(
            'success_details', v_success_details,
            'skipped_details', v_skipped_details
        );
    END IF;
    
    IF p_debug_level >= c_debug_verbose THEN
        v_result := v_result || jsonb_build_object(
            'error_details', v_error_details
        );
    END IF;
    
    -- ========== FINAL LOGGING ==========
    IF p_debug_level >= c_debug_basic THEN
        RAISE NOTICE '========================================================================';
        RAISE NOTICE 'Batch % completed in % seconds', v_batch_id, ROUND(v_total_duration, 2);
        RAISE NOTICE 'Summary: % inserted, % duplicates, % errors, % skipped', 
            v_total_inserted, v_total_duplicates, v_total_errors, v_total_skipped;
        
        IF v_total_requests > 0 THEN
            RAISE NOTICE 'Success rate: %%%', v_success_rate;
        END IF;
        
        RAISE NOTICE 'Config: Request statuses=%, Account statuses=%', 
            c_allowed_request_statuses, c_allowed_account_statuses;
        
        RAISE NOTICE '========================================================================';
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        v_end_time := CURRENT_TIMESTAMP;
        v_total_duration := EXTRACT(EPOCH FROM (v_end_time - v_start_time));
        
        IF p_debug_level >= c_debug_basic THEN
            RAISE NOTICE '========================================================================';
            RAISE NOTICE 'CRITICAL ERROR: %', v_error_message;
            RAISE NOTICE 'SQL State: %', v_sql_state;
            RAISE NOTICE '========================================================================';
        END IF;
        
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Critical error: ' || v_error_message,
            'batch_id', v_batch_id,
            'debug_level', p_debug_level,
            'sql_state', v_sql_state,
            'config', jsonb_build_object(
                'allowed_request_statuses', c_allowed_request_statuses,
                'allowed_account_statuses', c_allowed_account_statuses
            ),
            'statistics', jsonb_build_object(
                'total_requests_attempted', v_total_requests,
                'total_inserted', v_total_inserted,
                'total_errors', v_total_errors,
                'total_duplicates', v_total_duplicates,
                'total_skipped', v_total_skipped
            ),
            'timing', jsonb_build_object(
                'start_time', v_start_time::TEXT,
                'end_time', v_end_time::TEXT,
                'duration_seconds', ROUND(v_total_duration, 3)
            ),
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.finsert_debit_card_application(p_request_ids text[], p_debug_level integer, p_batch_id text, p_username character varying) OWNER TO postgres;

--
-- Name: finstant_getrequestdetailsbybatchidforswitch(character varying, character varying[], character varying, character varying, json, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstant_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying DEFAULT NULL::character varying, p_search_criteria json DEFAULT NULL::json, p_debug_level integer DEFAULT 0, p_page_number integer DEFAULT 1, p_page_size integer DEFAULT 100, p_include_data boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_batch_id VARCHAR(20);
    v_timestamp VARCHAR(50);
    v_record RECORD;
    v_counter INTEGER;
    v_total_records INTEGER;
    v_query TEXT;
    v_count_query TEXT;
    v_where_conditions TEXT;
    v_criteria JSON;
    v_column_name VARCHAR(100);
    v_column_value TEXT;
    v_audit_data JSONB;
    v_start_time TIMESTAMP;
    v_end_time TIMESTAMP;
    v_result JSONB;
    v_batch_results JSONB[];
    v_batch_result JSONB;
    v_offset INTEGER;
    v_data JSONB[];
    v_row JSONB;
    v_error_context TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_execution_time_ms NUMERIC;
    v_function_name TEXT := 'finstant_getRequestDetailsByBatchidforSwitch';
    v_json_record JSONB;
    v_row_json TEXT;
BEGIN
    -- Initialize result
    v_result := jsonb_build_object(
        'success', false,
        'timestamp', CURRENT_TIMESTAMP,
        'function_name', v_function_name,
        'action', p_action,
        'user', p_user,
        'debug_level', p_debug_level,
        'total_batches_processed', 0,
        'total_records_affected', 0,
        'execution_time_ms', 0,
        'error', NULL,
        'batches', '[]'::jsonb
    );
    
    -- Start timing
    v_start_time := clock_timestamp();
    
    -- Create timestamp for audit
    v_timestamp := TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD_HH24MISS');
    
    -- Log function start at debug level 1
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'FUNCTION_START',
                v_function_name || ' started',
                jsonb_build_object(
                    'action', p_action,
                    'batch_ids', p_batch_ids,
                    'user', p_user,
                    'debug_level', p_debug_level,
                    'search_criteria', p_search_criteria,
                    'new_status', p_new_status,
                    'page_number', p_page_number,
                    'page_size', p_page_size,
                    'include_data', p_include_data
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            -- Continue execution even if audit fails
            NULL;
        END;
    END IF;
    
    -- Calculate offset for pagination
    v_offset := (p_page_number - 1) * p_page_size;
    
    -- Initialize batch results array
    v_batch_results := ARRAY[]::JSONB[];
    
    -- Validate input parameters with error handling
    BEGIN
        IF p_action NOT IN ('SEARCH', 'UPDATE', 'DELETE') THEN
            RAISE EXCEPTION 'Invalid action: %. Use SEARCH, UPDATE, or DELETE', p_action
            USING ERRCODE = '22000';
        END IF;
        
        IF p_batch_ids IS NULL OR array_length(p_batch_ids, 1) = 0 THEN
            RAISE EXCEPTION 'No batch IDs provided'
            USING ERRCODE = '22001';
        END IF;
        
        IF p_action = 'UPDATE' AND (p_new_status IS NULL OR p_new_status = '') THEN
            RAISE EXCEPTION 'New status is required for UPDATE action'
            USING ERRCODE = '22002';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error at debug level 0 (always log errors)
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'VALIDATION_ERROR',
                'Input validation failed',
                jsonb_build_object(
                    'function', v_function_name,
                    'error_message', v_error_message,
                    'error_detail', v_error_detail,
                    'error_hint', v_error_hint,
                    'sql_state', SQLSTATE
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
        
        -- Calculate execution time
        v_end_time := clock_timestamp();
        v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
        
        -- Return error result
        v_result := v_result || jsonb_build_object(
            'success', false,
            'execution_time_ms', v_execution_time_ms,
            'error', jsonb_build_object(
                'message', v_error_message,
                'detail', v_error_detail,
                'hint', v_error_hint,
                'sql_state', SQLSTATE
            )
        );
        
        RETURN v_result;
    END;
    
    -- Process each batch ID
    FOR i IN 1..array_length(p_batch_ids, 1)
    LOOP
        v_batch_id := p_batch_ids[i];
        v_counter := 0;
        v_total_records := 0;
        v_data := ARRAY[]::JSONB[];
        v_where_conditions := 'WHERE batchid = ' || quote_literal(v_batch_id);
        
        -- Initialize batch result
        v_batch_result := jsonb_build_object(
            'batch_id', v_batch_id,
            'success', false,
            'records_affected', 0,
            'error', NULL
        );
        
        -- Log batch processing start
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_START',
                    'Processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'sequence', i
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
        
        -- Process based on action
        BEGIN
            IF p_action = 'SEARCH' THEN
                -- Build WHERE conditions for search
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name IN ('dap_gros_sal1', 'dap_net_sal1', 'dap_gros_sal2', 'dap_net_sal2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || v_column_value;
                        ELSIF v_column_name IN ('dap_date', 'dap_birt_dat1', 'dap_birt_dat2', 'dap_deci_date', 'dap_requ_effe_date', 'dap_requ_expi_date') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSIF v_column_name IN ('statusflag', 'dap_cus_type', 'dap_cus_old_new', 'dap_gend1', 'dap_gend2') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSIF v_column_name IN ('dap_cus_iden', 'dap_iden', 'dap_requ_acc_numb', 'dap_requ_card_numb') THEN
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' = ' || quote_literal(v_column_value);
                        ELSE
                            v_where_conditions := v_where_conditions || ' AND ' || v_column_name || ' ILIKE ' || quote_literal('%' || v_column_value || '%');
                        END IF;
                    END LOOP;
                END IF;
                
                -- Get total count for pagination
                v_count_query := 'SELECT COUNT(*) FROM public.instant_card_applications ' || v_where_conditions;
                EXECUTE v_count_query INTO v_total_records;
                
                -- Build search query with pagination - using row_to_json to avoid parameter limit
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT * FROM public.instant_card_applications ' || 
                                v_where_conditions || 
                                ' ORDER BY created_at DESC ' ||
                                ' LIMIT ' || p_page_size || 
                                ' OFFSET ' || v_offset || 
                            ') t';
                
                -- Execute query and collect data
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add to data array
                    v_data := array_append(v_data, v_json_record);
                END LOOP;
                
                -- Update batch result for SEARCH
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'SEARCH',
                    'records_found', v_counter,
                    'total_records', v_total_records,
                    'pagination', jsonb_build_object(
                        'page_number', p_page_number,
                        'page_size', p_page_size,
                        'total_pages', CASE WHEN p_page_size > 0 THEN CEIL(v_total_records::NUMERIC / p_page_size) ELSE 1 END
                    )
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'data', v_data
                    );
                END IF;
                
                -- Log successful search
                IF p_debug_level >= 1 AND v_counter > 0 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'SEARCH_COMPLETED',
                            'Search completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_found', v_counter,
                                'total_records', v_total_records
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'UPDATE' THEN
                -- Build WHERE conditions for update
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'statusflag' THEN
                            v_where_conditions := v_where_conditions || ' AND statusflag = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_cus_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_cus_iden = ' || quote_literal(v_column_value);
                        ELSIF v_column_name = 'dap_iden' THEN
                            v_where_conditions := v_where_conditions || ' AND dap_iden = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- Execute update with RETURNING clause - using row_to_json
                v_query := 'UPDATE public.instant_card_applications 
                            SET statusflag = ' || quote_literal(p_new_status) || 
                           ', updated_at = CURRENT_TIMESTAMP' ||
                           ', dap_deci_auth = ' || quote_literal(p_user) ||
                           ', dap_deci_date = CURRENT_DATE ' ||
                           v_where_conditions || 
                           ' RETURNING row_to_json(instant_card_applications.*) as row_data';
                
                -- Execute update and count affected rows
                FOR v_record IN EXECUTE v_query
                LOOP
                    v_counter := v_counter + 1;
                    
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Add minimal info to data array
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'old_status', v_json_record->>'statusflag',
                        'new_status', p_new_status
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Update batch result for UPDATE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'UPDATE',
                    'records_affected', v_counter,
                    'new_status', p_new_status,
                    'updated_by', p_user
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'updated_records', v_data
                    );
                END IF;
                
                -- Log successful update
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'UPDATE_COMPLETED',
                            'Status update completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_updated', v_counter,
                                'new_status', p_new_status
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
                
            ELSIF p_action = 'DELETE' THEN
                -- Additional conditions for deletion
                IF p_search_criteria IS NOT NULL THEN
                    v_criteria := p_search_criteria;
                    
                    FOR v_column_name, v_column_value IN 
                        SELECT * FROM json_each_text(v_criteria)
                    LOOP
                        IF v_column_name = 'statusflag' THEN
                            v_where_conditions := v_where_conditions || ' AND statusflag = ' || quote_literal(v_column_value);
                        END IF;
                    END LOOP;
                END IF;
                
                -- First, select records to be deleted using row_to_json
                v_query := 'SELECT row_to_json(t) as row_data 
                            FROM (
                                SELECT dap_iden, dap_cus_iden, statusflag 
                                FROM public.instant_card_applications ' || 
                                v_where_conditions || 
                            ') t';
                
                FOR v_record IN EXECUTE v_query
                LOOP
                    -- Extract the JSON from row_data column
                    v_json_record := v_record.row_data::jsonb;
                    
                    -- Store record info before deletion
                    v_row := jsonb_build_object(
                        'dap_iden', v_json_record->>'dap_iden',
                        'dap_cus_iden', v_json_record->>'dap_cus_iden',
                        'status', v_json_record->>'statusflag'
                    );
                    
                    v_data := array_append(v_data, v_row);
                END LOOP;
                
                -- Execute deletion
                v_query := 'DELETE FROM public.instant_card_applications ' || v_where_conditions;
                EXECUTE v_query;
                GET DIAGNOSTICS v_counter = ROW_COUNT;
                
                -- Update batch result for DELETE
                v_batch_result := v_batch_result || jsonb_build_object(
                    'success', true,
                    'action', 'DELETE',
                    'records_deleted', v_counter
                );
                
                IF p_include_data AND v_counter > 0 THEN
                    v_batch_result := v_batch_result || jsonb_build_object(
                        'deleted_records', v_data
                    );
                END IF;
                
                -- Log successful deletion
                IF p_debug_level >= 1 THEN
                    BEGIN
                        INSERT INTO public.audit_trail (
                            entity_type, 
                            action_type, 
                            description, 
                            data, 
                            user_id, 
                            created_at
                        ) VALUES (
                            'INSTANT_CARD_APPLICATIONS',
                            'DELETE_COMPLETED',
                            'Deletion completed for batch: ' || v_batch_id,
                            jsonb_build_object(
                                'batch_id', v_batch_id,
                                'records_deleted', v_counter
                            ),
                            p_user,
                            CURRENT_TIMESTAMP
                        );
                    EXCEPTION WHEN OTHERS THEN
                        NULL;
                    END;
                END IF;
            END IF;
            
            -- Update batch result with success
            v_batch_result := v_batch_result || jsonb_build_object(
                'records_affected', v_counter,
                'processed_at', CURRENT_TIMESTAMP
            );
            
            -- Add to batch results array
            v_batch_results := array_append(v_batch_results, v_batch_result);
            
            -- Update total records
            v_result := v_result || jsonb_build_object(
                'total_records_affected', (v_result->>'total_records_affected')::INTEGER + v_counter
            );
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS 
                v_error_message = MESSAGE_TEXT,
                v_error_detail = PG_EXCEPTION_DETAIL,
                v_error_hint = PG_EXCEPTION_HINT,
                v_error_context = PG_EXCEPTION_CONTEXT;
            
            -- Log batch error
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_ERROR',
                    'Error processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'action', p_action,
                        'error_message', v_error_message,
                        'error_detail', v_error_detail,
                        'error_hint', v_error_hint,
                        'error_context', v_error_context,
                        'sql_state', SQLSTATE
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
            
            -- Update batch result with error
            v_batch_result := v_batch_result || jsonb_build_object(
                'success', false,
                'error', jsonb_build_object(
                    'message', v_error_message,
                    'detail', v_error_detail,
                    'hint', v_error_hint,
                    'sql_state', SQLSTATE
                )
            );
            
            v_batch_results := array_append(v_batch_results, v_batch_result);
        END;
        
        -- Log batch completion
        IF p_debug_level >= 2 THEN
            BEGIN
                INSERT INTO public.audit_trail (
                    entity_type, 
                    action_type, 
                    description, 
                    data, 
                    user_id, 
                    created_at
                ) VALUES (
                    'INSTANT_CARD_APPLICATIONS',
                    'BATCH_COMPLETE',
                    'Completed processing batch: ' || v_batch_id,
                    jsonb_build_object(
                        'batch_id', v_batch_id,
                        'records_affected', v_counter,
                        'success', v_batch_result->>'success'
                    ),
                    p_user,
                    CURRENT_TIMESTAMP
                );
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Prepare final result
    v_result := v_result || jsonb_build_object(
        'success', true,
        'execution_time_ms', v_execution_time_ms,
        'total_batches_processed', array_length(p_batch_ids, 1),
        'batches', to_jsonb(v_batch_results)
    );
    
    -- Log function completion
    IF p_debug_level >= 1 THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                created_at
            ) VALUES (
                'INSTANT_CARD_APPLICATIONS',
                'FUNCTION_COMPLETE',
                v_function_name || ' completed successfully',
                jsonb_build_object(
                    'execution_time_ms', v_execution_time_ms,
                    'total_batches', array_length(p_batch_ids, 1),
                    'total_records', v_result->>'total_records_affected'
                ),
                p_user,
                CURRENT_TIMESTAMP
            );
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;
    
    RETURN v_result;
    
EXCEPTION WHEN OTHERS THEN
    -- Global exception handler
    GET STACKED DIAGNOSTICS 
        v_error_message = MESSAGE_TEXT,
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT,
        v_error_context = PG_EXCEPTION_CONTEXT;
    
    -- Calculate execution time
    v_end_time := clock_timestamp();
    v_execution_time_ms := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000;
    
    -- Log global error
    BEGIN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            created_at
        ) VALUES (
            'INSTANT_CARD_APPLICATIONS',
            'FUNCTION_ERROR',
            v_function_name || ' failed',
            jsonb_build_object(
                'error_message', v_error_message,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'error_context', v_error_context,
                'sql_state', SQLSTATE,
                'execution_time_ms', v_execution_time_ms
            ),
            p_user,
            CURRENT_TIMESTAMP
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    
    -- Return error result
    v_result := v_result || jsonb_build_object(
        'success', false,
        'execution_time_ms', v_execution_time_ms,
        'error', jsonb_build_object(
            'message', v_error_message,
            'detail', v_error_detail,
            'hint', v_error_hint,
            'context', v_error_context,
            'sql_state', SQLSTATE
        )
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.finstant_getrequestdetailsbybatchidforswitch(p_action character varying, p_batch_ids character varying[], p_user character varying, p_new_status character varying, p_search_criteria json, p_debug_level integer, p_page_number integer, p_page_size integer, p_include_data boolean) OWNER TO postgres;

--
-- Name: finstant_statusupdatebothflagtrue(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstant_statusupdatebothflagtrue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Case 1: Both booked_cards and approved_cards have records (> 0)
    -- Then we need both flags to be true
    IF NEW.booked_cards > 0 AND NEW.approved_cards > 0 THEN
        -- Check if both allocation flags are true
        IF NEW.bookedcardallocated = true AND NEW.approvedcardsallocated = true THEN
            -- Both flags are true, update status if it's 'VERIFIED' or 'PROCESSING'
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                -- Log this change
                RAISE NOTICE 'Request %: Both cards present (booked: %, approved: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.booked_cards, NEW.approved_cards;
            END IF;
        END IF;
    
    -- Case 2: Only booked_cards have records (> 0) and approved_cards are zero
    ELSIF NEW.booked_cards > 0 AND (NEW.approved_cards = 0 OR NEW.approved_cards IS NULL) THEN
        -- Check only bookedcardallocated flag
        IF NEW.bookedcardallocated = true THEN
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                RAISE NOTICE 'Request %: Only booked cards present (count: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.booked_cards;
            END IF;
        END IF;
    
    -- Case 3: Only approved_cards have records (> 0) and booked_cards are zero
    ELSIF NEW.approved_cards > 0 AND (NEW.booked_cards = 0 OR NEW.booked_cards IS NULL) THEN
        -- Check only approvedcardsallocated flag
        IF NEW.approvedcardsallocated = true THEN
            IF NEW.status IN ('VERIFIED', 'PROCESSING') THEN
                NEW.status := 'ALLOCATED';
                
                RAISE NOTICE 'Request %: Only approved cards present (count: %) - status updated to ALLOCATED', 
                    NEW.requestid, NEW.approved_cards;
            END IF;
        END IF;
    
    -- Case 4: Both are zero or NULL - no allocation needed
    ELSE
        RAISE NOTICE 'Request %: No cards to allocate (booked: %, approved: %)', 
            NEW.requestid, NEW.booked_cards, NEW.approved_cards;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.finstant_statusupdatebothflagtrue() OWNER TO postgres;

--
-- Name: finstant_update_card_flags(character varying, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstant_update_card_flags(p_requestid character varying, p_booked_flag boolean, p_approved_flag boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_booked_updated boolean := false;
    v_approved_updated boolean := false;
BEGIN
    -- Check if request exists
    IF NOT EXISTS (SELECT 1 FROM instantcardcycle WHERE requestid = p_requestid) THEN
        RETURN 'Error: Request ID not found';
    END IF;

    -- Update booked flag ONLY if parameter is TRUE
    IF p_booked_flag = true THEN
        UPDATE instantcardcycle 
        SET bookedcardallocated = true
        WHERE requestid = p_requestid;
        v_booked_updated := true;
    END IF;
    
    -- Update approved flag ONLY if parameter is TRUE
    IF p_approved_flag = true THEN
        UPDATE instantcardcycle 
        SET approvedcardsallocated = true
        WHERE requestid = p_requestid;
        v_approved_updated := true;
    END IF;
    
    -- Return appropriate message
    IF v_booked_updated AND v_approved_updated THEN
        RETURN 'Both flags updated to TRUE for request: ' || p_requestid;
    ELSIF v_booked_updated THEN
        RETURN 'Booked flag updated to TRUE for request: ' || p_requestid;
    ELSIF v_approved_updated THEN
        RETURN 'Approved flag updated to TRUE for request: ' || p_requestid;
    ELSE
        RETURN 'No flags were updated (parameters were not TRUE) for request: ' || p_requestid;
    END IF;
END;
$$;


ALTER FUNCTION public.finstant_update_card_flags(p_requestid character varying, p_booked_flag boolean, p_approved_flag boolean) OWNER TO postgres;

--
-- Name: finstantbatchidmanagement(text, text, timestamp without time zone, timestamp without time zone, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantbatchidmanagement(p_action text DEFAULT 'LOADING ALL'::text, p_batch_id text DEFAULT NULL::text, p_from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, p_status text DEFAULT NULL::text, p_debug_level integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    -- Debug level definitions (INTERNAL - no external parameters needed)
    DEBUG_ERROR_ONLY CONSTANT integer := 0;  -- Log only errors
    DEBUG_INFO CONSTANT integer := 1;       -- Log info + errors
    DEBUG_VERBOSE CONSTANT integer := 2;    -- Log everything
    
    v_result JSONB;
    v_start_time TIMESTAMP := CURRENT_TIMESTAMP;
    v_end_time TIMESTAMP;
    v_affected_rows INTEGER := 0;
    v_error_message TEXT;
    v_sql_state TEXT;
    v_count_total INTEGER := 0;
    v_log_category TEXT := 'BATCH_MGMT';
    v_current_debug_level integer;
    
    -- Dynamic SQL variables
    v_where_clause TEXT := '';
    v_sql TEXT;
    
    -- Results
    v_batch_data JSONB;
    
BEGIN
    -- Set current debug level
    v_current_debug_level := COALESCE(p_debug_level, DEBUG_ERROR_ONLY);
    
    -- Debug log: Function start
    IF v_current_debug_level >= DEBUG_INFO THEN
        PERFORM public.flog_audit_trail(
            v_log_category,
            'FUNCTION_START',
            'Starting batch management function',
            jsonb_build_object(
                'action', p_action,
                'batch_id', p_batch_id,
                'from_date', p_from_date::TEXT,
                'to_date', p_to_date::TEXT,
                'status', p_status,
                'debug_level', v_current_debug_level,
                'start_time', v_start_time::TEXT
            )
        );
    END IF;
    
    -- ========== VALIDATE INPUTS ==========
    BEGIN
        -- Validate action parameter
        IF p_action NOT IN ('LOADING ALL', 'SEARCH', 'UPDATE') THEN
            RAISE EXCEPTION 'Invalid action: %. Must be LOADING ALL, SEARCH, or UPDATE', p_action;
        END IF;
        
        -- Validate required parameters for UPDATE
        IF p_action = 'UPDATE' THEN
            IF p_batch_id IS NULL THEN
                RAISE EXCEPTION 'batch_id is required for UPDATE action';
            END IF;
            IF p_status IS NULL THEN
                RAISE EXCEPTION 'status is required for UPDATE action';
            END IF;
            -- Validate status value
            IF p_status NOT IN ('PROCESSING', 'COMPLETED', 'FAILED', 'ARCHIVED', 'CANCELLED') THEN
                RAISE EXCEPTION 'Invalid status: %. Must be PROCESSING, COMPLETED, FAILED, ARCHIVED, or CANCELLED', p_status;
            END IF;
        END IF;
        
        -- Validate date range
        IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_from_date > p_to_date THEN
            RAISE EXCEPTION 'from_date cannot be after to_date';
        END IF;
        
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
        
        IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
            PERFORM public.flog_audit_trail(
                v_log_category,
                'VALIDATION_ERROR',
                v_error_message,
                jsonb_build_object(
                    'action', p_action,
                    'batch_id', p_batch_id,
                    'error', SQLERRM
                )
            );
        END IF;
        
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Validation error: ' || v_error_message,
            'action', p_action,
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
    END;
    
    -- ========== ACTION: LOADING ALL ==========
    IF p_action = 'LOADING ALL' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing LOADING ALL action';
            END IF;
            
            -- Build WHERE clause with available filters
            IF p_from_date IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    '"timestamp" >= $1';
            END IF;
            
            IF p_to_date IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    '"timestamp" <= $2';
            END IF;
            
            IF p_status IS NOT NULL THEN
                v_where_clause := v_where_clause || 
                    CASE WHEN v_where_clause = '' THEN ' WHERE ' ELSE ' AND ' END ||
                    'status = $3';
            END IF;
            
            -- Build SQL query
            v_sql := 'SELECT jsonb_agg(row_to_json(t)) FROM (' ||
                    'SELECT batch_id, request_ids, status,pintype, cards_generated, cards_failed, ' ||
                    'schemes, card_types, duration, timestamp, flags, total_cards, ' ||
                    'success_rate, request_count, report_id ' ||
                    'FROM instant_card_generation_batches' ||
                    v_where_clause || ' ORDER BY "timestamp" DESC' ||
                    ') t';
            
            -- Execute query with parameters
            IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL AND p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_to_date;
            ELSIF p_from_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date, p_status;
            ELSIF p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_from_date;
            ELSIF p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_to_date;
            ELSIF p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_batch_data 
                USING p_status;
            ELSE
                EXECUTE v_sql INTO v_batch_data;
            END IF;
            
            -- Get total count
            v_sql := 'SELECT COUNT(*) FROM instant_card_generation_batches' || v_where_clause;
            
            IF p_from_date IS NOT NULL AND p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL AND p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_to_date;
            ELSIF p_from_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date, p_status;
            ELSIF p_to_date IS NOT NULL AND p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_to_date, p_status;
            ELSIF p_from_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_from_date;
            ELSIF p_to_date IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_to_date;
            ELSIF p_status IS NOT NULL THEN
                EXECUTE v_sql INTO v_count_total 
                USING p_status;
            ELSE
                EXECUTE v_sql INTO v_count_total;
            END IF;
            
            -- Build result
            v_result := jsonb_build_object(
                'success', TRUE,
                'action', p_action,
                'data', COALESCE(v_batch_data, '[]'::JSONB),
                'metadata', jsonb_build_object(
                    'total_records', v_count_total,
                    'filters_applied', jsonb_build_object(
                        'from_date', p_from_date::TEXT,
                        'to_date', p_to_date::TEXT,
                        'status', p_status
                    ),
                    'query_time', v_start_time::TEXT
                )
            );
            
            -- Debug log
            IF v_current_debug_level >= DEBUG_INFO THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'LOAD_SUCCESS',
                    'Successfully loaded batch data',
                    jsonb_build_object(
                        'action', p_action,
                        'records_returned', v_count_total,
                        'debug_level', v_current_debug_level
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'LOAD_ERROR',
                    'Error loading batch data',
                    jsonb_build_object(
                        'action', p_action,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error loading data: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    -- ========== ACTION: SEARCH ==========
    ELSIF p_action = 'SEARCH' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing SEARCH action for batch_id: %', p_batch_id;
            END IF;
            
            IF p_batch_id IS NULL THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'batch_id is required for SEARCH action',
                    'action', p_action
                );
                RETURN v_result;
            END IF;
            
            -- Search for specific batch
            SELECT jsonb_build_object(
                'batch_id', batch_id,
                'request_ids', request_ids,
                'status', status,
                'cards_generated', cards_generated,
                'cards_failed', cards_failed,
                'schemes', schemes,
                'card_types', card_types,
                'duration', duration,
                'timestamp', "timestamp",
                'flags', flags,
                'total_cards', total_cards,
                'success_rate', success_rate,
                'request_count', request_count,
                'report_id', report_id
            ) INTO v_batch_data
            FROM instant_card_generation_batches
            WHERE batch_id = p_batch_id;
            
            IF v_batch_data IS NULL THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'Batch not found: ' || p_batch_id,
                    'action', p_action
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'SEARCH_NOT_FOUND',
                        'Batch not found',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            ELSE
                v_result := jsonb_build_object(
                    'success', TRUE,
                    'action', p_action,
                    'data', v_batch_data,
                    'message', 'Batch found successfully'
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'SEARCH_SUCCESS',
                        'Batch found successfully',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'SEARCH_ERROR',
                    'Error searching for batch',
                    jsonb_build_object(
                        'batch_id', p_batch_id,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error searching data: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    -- ========== ACTION: UPDATE ==========
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF v_current_debug_level >= DEBUG_VERBOSE THEN
                RAISE NOTICE 'Executing UPDATE action for batch_id: % with status: %', p_batch_id, p_status;
            END IF;
            
            -- UPDATE ONLY STATUS (no other fields can be modified)
            UPDATE instant_card_generation_batches
            SET status = p_status
            WHERE batch_id = p_batch_id
            RETURNING 1 INTO v_affected_rows;
            
            IF v_affected_rows = 0 THEN
                v_result := jsonb_build_object(
                    'success', FALSE,
                    'message', 'Batch not found or no changes made: ' || p_batch_id,
                    'action', p_action
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'UPDATE_NOT_FOUND',
                        'Batch not found for update',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'action', p_action
                        )
                    );
                END IF;
            ELSE
                v_result := jsonb_build_object(
                    'success', TRUE,
                    'action', p_action,
                    'message', 'Batch status updated successfully',
                    'updated_fields', jsonb_build_object('status', p_status),
                    'batch_id', p_batch_id
                );
                
                IF v_current_debug_level >= DEBUG_INFO THEN
                    PERFORM public.flog_audit_trail(
                        v_log_category,
                        'UPDATE_SUCCESS',
                        'Batch status updated successfully',
                        jsonb_build_object(
                            'batch_id', p_batch_id,
                            'old_status', NULL, -- You might want to capture old status
                            'new_status', p_status,
                            'action', p_action,
                            'affected_rows', v_affected_rows
                        )
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT;
            
            IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
                PERFORM public.flog_audit_trail(
                    v_log_category,
                    'UPDATE_ERROR',
                    'Error updating batch status',
                    jsonb_build_object(
                        'batch_id', p_batch_id,
                        'status', p_status,
                        'error', v_error_message,
                        'sql_state', SQLSTATE
                    )
                );
            END IF;
            
            v_result := jsonb_build_object(
                'success', FALSE,
                'message', 'Error updating batch: ' || v_error_message,
                'action', p_action,
                'error_time', CURRENT_TIMESTAMP::TEXT
            );
        END;
    
    ELSE
        v_result := jsonb_build_object(
            'success', FALSE,
            'message', 'Unsupported action: ' || p_action,
            'action', p_action
        );
    END IF;
    
    -- Final debug log
    v_end_time := CURRENT_TIMESTAMP;
    
    IF v_current_debug_level >= DEBUG_INFO THEN
        PERFORM public.flog_audit_trail(
            v_log_category,
            'FUNCTION_END',
            'Batch management function completed',
            jsonb_build_object(
                'action', p_action,
                'success', v_result->>'success',
                'duration_seconds', EXTRACT(EPOCH FROM (v_end_time - v_start_time)),
                'start_time', v_start_time::TEXT,
                'end_time', v_end_time::TEXT,
                'debug_level', v_current_debug_level
            )
        );
    END IF;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_sql_state = RETURNED_SQLSTATE;
        
        IF v_current_debug_level >= DEBUG_ERROR_ONLY THEN
            PERFORM public.flog_audit_trail(
                v_log_category,
                'FUNCTION_CRITICAL_ERROR',
                'Critical error in batch management function',
                jsonb_build_object(
                    'action', p_action,
                    'error', v_error_message,
                    'sql_state', v_sql_state,
                    'error_time', CURRENT_TIMESTAMP::TEXT
                )
            );
        END IF;
        
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Critical function error: ' || v_error_message,
            'action', p_action,
            'sql_state', v_sql_state,
            'error_time', CURRENT_TIMESTAMP::TEXT
        );
END;
$_$;


ALTER FUNCTION public.finstantbatchidmanagement(p_action text, p_batch_id text, p_from_date timestamp without time zone, p_to_date timestamp without time zone, p_status text, p_debug_level integer) OWNER TO postgres;

--
-- Name: finstantcardbranchallocation(character varying, jsonb, integer, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying, p_requestid character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_isgreenpin BOOLEAN;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    
    -- Variables for flag update based on card status and type
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
    
    -- Track allocations by status, not by pin type
    v_booked_status_cards_allocated_count INTEGER := 0;
    v_approved_status_cards_allocated_count INTEGER := 0;
    v_total_booked_cards_in_request INTEGER := 0;
    v_total_approved_cards_in_request INTEGER := 0;
    
    -- Track if allocation is happening
    v_any_card_allocated BOOLEAN := FALSE;
    v_request_found BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '  p_requestid: %', p_requestid;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
		        IF p_debuglevel > 3 THEN
		            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
		                p_branchcodetoallocate, v_user_branchcode;
		        END IF;    
		        PERFORM public.flog_audit_trail(
		            'INSTANT_CARD',
		            'BRANCH_ACCESS_DENIED',
		            'User cannot allocate to branch: ' || p_branchcodetoallocate,
		            jsonb_build_object(
		                'error_message', 'User does not have permission to allocate to this branch',
		                'action', p_action,
		                'user_id', p_userid,
		                'username', v_username,
		                'user_branch', v_user_branchcode,
		                'target_branch', p_branchcodetoallocate,
		                'crossbranch_access', v_user_crossbranch,
		                'total_cards', v_total_cards,
		                'debuglevel', p_debuglevel
		            )
		        );
        
		        RETURN jsonb_build_object(
		            'success', false,
		            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
		            'error_code', 'BRANCH_ACCESS_DENIED',
		            'user_access', v_user_access_message,
		            'user_branch', v_user_branchcode,
		            'target_branch', p_branchcodetoallocate
		        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- If this is an UPDATE with requestid, pre-fetch the request details
    IF p_action = 'UPDATE' AND p_requestid IS NOT NULL THEN
        -- Get the request details from instantcardcycle
        SELECT 
            booked_cards,
            approved_cards,
            bookedcardallocated,
            approvedcardsallocated
        INTO 
            v_total_booked_cards_in_request,
            v_total_approved_cards_in_request,
            v_current_booked_allocated,
            v_current_approved_allocated
        FROM public.instantcardcycle
        WHERE requestid = p_requestid;
        
        IF FOUND THEN
            v_request_found := TRUE;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Request details found for ID %:', p_requestid;
                RAISE NOTICE '  booked_cards: %', v_total_booked_cards_in_request;
                RAISE NOTICE '  approved_cards: %', v_total_approved_cards_in_request;
                RAISE NOTICE '  bookedcardallocated: %', v_current_booked_allocated;
                RAISE NOTICE '  approvedcardsallocated: %', v_current_approved_allocated;
            END IF;
        ELSE
            RAISE NOTICE 'Warning: Request ID % not found in instantcardcycle table', p_requestid;
        END IF;
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Initialize counters
        v_booked_status_cards_allocated_count := 0;
        v_approved_status_cards_allocated_count := 0;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database including isgreenpin (for info only)
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate,
                    isgreenpin
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate,
                    v_isgreenpin
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                    RAISE NOTICE '  isgreenpin: %', v_isgreenpin;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Track if we're setting status to ALLOCATED (for flag updates)
                IF v_new_status = 'ALLOCATED' THEN
                    v_any_card_allocated := TRUE;
                END IF;
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber
                            RETURNING uploadid INTO v_uploadid;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            
                            IF v_row_count = 1 AND v_new_status = 'ALLOCATED' THEN
                                v_success_count := v_success_count + 1;
                                
                                -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                                -- This is the key fix: use v_current_status (original status) to determine which counter to increment
                                IF v_current_status = 'BOOKED' THEN
                                    -- Cards that were BOOKED should update booked_cards count
                                    v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                    END IF;
                                ELSIF v_current_status = 'AVAILABLE' THEN
                                    -- Cards that were AVAILABLE should update approved_cards count
                                    v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                    END IF;
                                ELSE
                                    -- Other statuses - for informational purposes
                                    IF p_debuglevel > 3 THEN
                                        RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                    END IF;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same (removed isgreenpin)
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'isgreenpin', v_isgreenpin,
                                'user_access', v_user_access_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same (removed isgreenpin)
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'isgreenpin', v_isgreenpin,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                        IF v_new_status = 'ALLOCATED' THEN
                            IF v_current_status = 'BOOKED' THEN
                                -- Cards that were BOOKED should update booked_cards count
                                v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                END IF;
                            ELSIF v_current_status = 'AVAILABLE' THEN
                                -- Cards that were AVAILABLE should update approved_cards count
                                v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                END IF;
                            ELSE
                                -- Other statuses - for informational purposes
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                END IF;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change (removed isgreenpin)
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'isgreenpin', v_isgreenpin,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- Count this card for flag updates based on its ORIGINAL STATUS, not pin type
                        IF v_new_status = 'ALLOCATED' THEN
                            IF v_current_status = 'BOOKED' THEN
                                -- Cards that were BOOKED should update booked_cards count
                                v_booked_status_cards_allocated_count := v_booked_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'BOOKED status card allocated (was %), booked count: %', v_current_status, v_booked_status_cards_allocated_count;
                                END IF;
                            ELSIF v_current_status = 'AVAILABLE' THEN
                                -- Cards that were AVAILABLE should update approved_cards count
                                v_approved_status_cards_allocated_count := v_approved_status_cards_allocated_count + 1;
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'AVAILABLE status card allocated (was %), approved count: %', v_current_status, v_approved_status_cards_allocated_count;
                                END IF;
                            ELSE
                                -- Other statuses - for informational purposes
                                IF p_debuglevel > 3 THEN
                                    RAISE NOTICE 'Card with status % allocated - not counted for flags', v_current_status;
                                END IF;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'isgreenpin', v_isgreenpin,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'isgreenpin', v_isgreenpin,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        -- =====================================================
        -- FLAG UPDATE LOGIC - Based on original card status, not pin type
        -- =====================================================

		-- =====================================================
-- FLAG UPDATE LOGIC - Based on original card status
-- =====================================================
			IF v_any_card_allocated AND p_requestid IS NOT NULL AND v_request_found THEN
			    BEGIN
			        RAISE NOTICE '=== FLAG UPDATE DEBUG for Request: % ===', p_requestid;
			        RAISE NOTICE 'Cards with BOOKED status allocated in this batch: %', v_booked_status_cards_allocated_count;
			        RAISE NOTICE 'Cards with AVAILABLE status allocated in this batch: %', v_approved_status_cards_allocated_count;
			        RAISE NOTICE 'Total booked cards in request: %', v_total_booked_cards_in_request;
			        RAISE NOTICE 'Total approved cards in request: %', v_total_approved_cards_in_request;
			        RAISE NOTICE 'Current booked_allocated: %, approved_allocated: %', 
			            v_current_booked_allocated, v_current_approved_allocated;
			        
			        -- =========================================
			        -- BOOKED FLAG HANDLING
			        -- =========================================
			        
			        -- Only update booked flag if there are booked cards to allocate
			        IF v_total_booked_cards_in_request > 0 THEN
			            -- Case 1: All BOOKED cards have been allocated
			            IF v_booked_status_cards_allocated_count >= v_total_booked_cards_in_request 
			               AND v_current_booked_allocated = false THEN
			                
			                UPDATE public.instantcardcycle
			                SET bookedcardallocated = true
			                WHERE requestid = p_requestid;
			                
			                v_flag_update_message := 'Booked flag updated - all BOOKED cards allocated';
			                v_flag_updated := TRUE;
			                RAISE NOTICE '✓ Updated bookedcardallocated to TRUE (all % BOOKED cards allocated)', 
			                    v_total_booked_cards_in_request;
			                
			            -- Case 2: Partial allocation of BOOKED cards
			            ELSIF v_booked_status_cards_allocated_count > 0 
			                  AND v_current_booked_allocated = false THEN
			                RAISE NOTICE 'Partial allocation of BOOKED cards: % of % allocated - flag not updated yet', 
			                    v_booked_status_cards_allocated_count, v_total_booked_cards_in_request;
			            END IF;
			        ELSE
			            -- No booked cards in request - flag should remain FALSE
			            RAISE NOTICE 'No booked cards in request - booked flag remains false';
			        END IF;
			        
			        -- =========================================
			        -- APPROVED FLAG HANDLING
			        -- =========================================
			        
			        -- Only update approved flag if there are approved cards to allocate
			        IF v_total_approved_cards_in_request > 0 THEN
			            -- Case 1: All APPROVED cards have been allocated
			            IF v_approved_status_cards_allocated_count >= v_total_approved_cards_in_request 
			               AND v_current_approved_allocated = false THEN
			                
			                UPDATE public.instantcardcycle
			                SET approvedcardsallocated = true
			                WHERE requestid = p_requestid;
			                
			                v_flag_update_message := v_flag_update_message || ' Approved flag updated - all APPROVED cards allocated';
			                v_flag_updated := TRUE;
			                RAISE NOTICE '✓ Updated approvedcardsallocated to TRUE (all % APPROVED cards allocated)', 
			                    v_total_approved_cards_in_request;
			                
			            -- Case 2: Partial allocation of APPROVED cards
			            ELSIF v_approved_status_cards_allocated_count > 0 
			                  AND v_current_approved_allocated = false THEN
			                RAISE NOTICE 'Partial allocation of APPROVED cards: % of % allocated - flag not updated yet', 
			                    v_approved_status_cards_allocated_count, v_total_approved_cards_in_request;
			            END IF;
			        ELSE
			            -- No approved cards in request - flag should remain FALSE
			            RAISE NOTICE 'No approved cards in request - approved flag remains false';
			        END IF;
			        
			        RAISE NOTICE '=== END FLAG UPDATE DEBUG ===';
			        
			    EXCEPTION WHEN OTHERS THEN
			        RAISE NOTICE 'ERROR in flag update: %', SQLERRM;
			        PERFORM public.flog_audit_trail(
			            'INSTANT_CARD_CYCLE',
			            'FLAG_UPDATE_ERROR',
			            'Error: ' || SQLERRM,
			            jsonb_build_object(
			                'requestid', p_requestid,
			                'error', SQLERRM,
			                'booked_allocated_count', v_booked_status_cards_allocated_count,
			                'approved_allocated_count', v_approved_status_cards_allocated_count,
			                'total_booked', v_total_booked_cards_in_request,
			                'total_approved', v_total_approved_cards_in_request
			            )
			        );
			    END;
			    
			ELSIF v_any_card_allocated AND p_requestid IS NULL THEN
			    RAISE NOTICE 'Warning: Cards allocated but no requestid provided - flags not updated';
			    
			ELSIF v_any_card_allocated AND NOT v_request_found THEN
			    RAISE NOTICE 'Warning: Cards allocated but request ID % not found - flags not updated', p_requestid;
			    
			END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  BOOKED status cards allocated: %', v_booked_status_cards_allocated_count;
            RAISE NOTICE '  AVAILABLE status cards allocated: %', v_approved_status_cards_allocated_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message,
                'booked_status_cards_allocated', v_booked_status_cards_allocated_count,
                'available_status_cards_allocated', v_approved_status_cards_allocated_count
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message,
                'booked_status_cards_allocated', v_booked_status_cards_allocated_count,
                'available_status_cards_allocated', v_approved_status_cards_allocated_count
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin', isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK','CARD & PIN DISPATCH')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate,
                            'isgreenpin', isgreenpin
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying, p_requestid character varying) OWNER TO postgres;

--
-- Name: finstantcardbranchallocation_feb172026_v1(character varying, jsonb, integer, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb172026_v1(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
	v_current_booked_cards INTEGER;
	v_current_approved_cards INTEGER;
	v_current_booked_allocated BOOLEAN;
	v_current_approved_allocated BOOLEAN;
	v_flag_update_message TEXT := '';
	v_flag_updated BOOLEAN := FALSE;
BEGIN
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        RAISE NOTICE 'No valid user ID provided, using limited access';
    END IF;
    
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    
    -- Only validate empty array for UPDATE and DELETE actions, not for SEARCH
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Update status validation to include all card/PIN status combinations
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel >= 1 THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate if user can allocate to target branch for UPDATE action
	RAISE NOTICE 'GOINING INSIDE Validate if user can allocate to target branch for UPDATE action-LEVEL-1';
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        RAISE NOTICE 'INSIDE LEVEL-1';
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_action = 'UPDATE' THEN
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            BEGIN
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF v_uploadid IS NULL THEN
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- ADDED: Check if user has access to modify this card
                -- Users can only modify cards in their own branch unless they have cross-branch access
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN 
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                -- Now use v_new_status (which may have been composed) for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    -- Check if card can be allocated - ALLOW ALLOCATED cards to be re-allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF v_current_status != v_new_status THEN
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username  -- Use username instead of user ID
                            WHERE cardnumber = v_cardnumber;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message
                            );
                        ELSE
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username  -- Use username instead of user ID
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
							-- =====================================================
							-- Update instantcardcycle flags when status = 'ALLOCATED' Added by ST Feb-17-2026 for updating isallocated flag instantcardcycle
							-- =====================================================
							-- =====================================================
							IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
							    BEGIN
							        -- Get the request details
							        SELECT 
							            booked_cards,
							            approved_cards,
							            bookedcardallocated,
							            approvedcardsallocated
							        INTO 
							            v_current_booked_cards,
							            v_current_approved_cards,
							            v_current_booked_allocated,
							            v_current_approved_allocated
							        FROM public.instantcardcycle
							        WHERE requestid = v_uploadid;
							        
							        -- DEBUG: Show the values retrieved
							        RAISE NOTICE '=== FLAG UPDATE DEBUG for Request: % ===', v_uploadid;
							        RAISE NOTICE 'booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
							        RAISE NOTICE 'bookedcardallocated: %, approvedcardsallocated: %', v_current_booked_allocated, v_current_approved_allocated;
							        RAISE NOTICE 'Total cards being allocated: %', v_total_cards;
							        
							        IF FOUND THEN
							            -- Check if the current allocation count matches booked_cards
							            IF v_current_booked_allocated = false 
							               AND v_current_booked_cards > 0 
							               AND v_total_cards = v_current_booked_cards THEN
							                
							                RAISE NOTICE 'CONDITION MET: Updating bookedcardallocated to TRUE for request %', v_uploadid;
							                
							                UPDATE public.instantcardcycle
							                SET bookedcardallocated = true
							                WHERE requestid = v_uploadid;
							                
							                v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
							                v_flag_updated := TRUE;
							                
							                RAISE NOTICE 'Booked flag updated successfully';
							            ELSE
							                RAISE NOTICE 'Booked flag condition NOT met:';
							                RAISE NOTICE '  - v_current_booked_allocated=false? %', (v_current_booked_allocated = false);
							                RAISE NOTICE '  - v_current_booked_cards>0? %', (v_current_booked_cards > 0);
							                RAISE NOTICE '  - v_total_cards=% = v_current_booked_cards=%? %', 
							                    v_total_cards, v_current_booked_cards, (v_total_cards = v_current_booked_cards);
							            END IF;
							            
							            -- Check if the current allocation count matches approved_cards
							            IF v_current_approved_allocated = false 
							               AND v_current_approved_cards > 0 
							               AND v_total_cards = v_current_approved_cards THEN
							                
							                RAISE NOTICE 'CONDITION MET: Updating approvedcardsallocated to TRUE for request %', v_uploadid;
							                
							                UPDATE public.instantcardcycle
							                SET approvedcardsallocated = true
							                WHERE requestid = v_uploadid;
							                
							                v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
							                v_flag_updated := TRUE;
							                
							                RAISE NOTICE 'Approved flag updated successfully';
							            ELSE
							                RAISE NOTICE 'Approved flag condition NOT met:';
							                RAISE NOTICE '  - v_current_approved_allocated=false? %', (v_current_approved_allocated = false);
							                RAISE NOTICE '  - v_current_approved_cards>0? %', (v_current_approved_cards > 0);
							                RAISE NOTICE '  - v_total_cards=% = v_current_approved_cards=%? %', 
							                    v_total_cards, v_current_approved_cards, (v_total_cards = v_current_approved_cards);
							            END IF;
							        ELSE
							            RAISE NOTICE 'Request ID % not found in instantcardcycle table', v_uploadid;
							        END IF;
							        
							        RAISE NOTICE '=== END FLAG UPDATE DEBUG ===';
							        
							    EXCEPTION WHEN OTHERS THEN
							        RAISE NOTICE 'ERROR in flag update: %', SQLERRM;
							        PERFORM public.flog_audit_trail(
							            'INSTANT_CARD_CYCLE',
							            'FLAG_UPDATE_ERROR',
							            'Error: ' || SQLERRM,
							            jsonb_build_object('requestid', v_uploadid)
							        );
							    END;
							END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF v_current_status = v_new_status THEN
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username  -- Use username instead of user ID
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message
                        );
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                
            EXCEPTION WHEN OTHERS THEN
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        -- DELETE section (simplified for brevity)
        -- Add similar branch access checks for DELETE
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- ADDED: Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
            ELSE
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        -- ADDED: Apply branch filtering based on user access
        IF v_total_cards = 0 THEN
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
					'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- ADDED: Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE  -- Users with cross-branch access see all
                OR allocatedbranch = v_user_branchcode  -- Others only see their branch
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)  -- Handle null cases
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            v_total_cards := v_success_count;
        ELSE
            -- Process specific card numbers with branch access check
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    -- ADDED: Branch access filtering
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                    END IF;
                END IF;
            END LOOP;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb172026_v1(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying) OWNER TO postgres;

--
-- Name: finstantcardbranchallocation_feb172026v2(character varying, jsonb, integer, character varying, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb172026v2(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
                p_branchcodetoallocate, v_user_branchcode;
        END IF;
            
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            v_success_count := v_success_count + 1;
                            
                            -- =====================================================
                            -- FLAG UPDATE - STATUS CHANGE WITH SAME BRANCH
                            -- =====================================================
                            IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL AND v_row_count = 1 THEN
                                RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                                
                                -- Get the request details
                                SELECT 
                                    booked_cards,
                                    approved_cards,
                                    bookedcardallocated,
                                    approvedcardsallocated
                                INTO 
                                    v_current_booked_cards,
                                    v_current_approved_cards,
                                    v_current_booked_allocated,
                                    v_current_approved_allocated
                                FROM public.instantcardcycle
                                WHERE requestid = v_uploadid;
                                RAISE NOTICE 'DEBUG - Request ID % found in instantcardcycle: %', v_uploadid, FOUND;
                                IF FOUND THEN
                                    -- Check if the current allocation count matches booked_cards
									 RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
								    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
								    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                    IF v_current_booked_allocated = false 
                                       AND v_current_booked_cards > 0 
                                       AND v_total_cards = v_current_booked_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET bookedcardallocated = true
                                        WHERE requestid = v_uploadid;
                                        
                                        v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                    
                                    -- Check if the current allocation count matches approved_cards
                                    IF v_current_approved_allocated = false 
                                       AND v_current_approved_cards > 0 
                                       AND v_total_cards = v_current_approved_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET approvedcardsallocated = true
                                        WHERE requestid = v_uploadid;
                                        
                                        v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message,
                                'flag_updated', v_flag_updated,
                                'flag_message', v_flag_update_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - BRANCH ALLOCATION
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = v_uploadid;
                            
                            IF FOUND THEN
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - STATUS ONLY CHANGE
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND v_uploadid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, v_uploadid=%', v_new_status, v_uploadid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = v_uploadid;
                            
                            IF FOUND THEN
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = v_uploadid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || v_uploadid;
                                    v_flag_updated := TRUE;
                                END IF;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb172026v2(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying) OWNER TO postgres;

--
-- Name: finstantcardbranchallocation_feb242026v3(character varying, jsonb, integer, character varying, integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardbranchallocation_feb242026v3(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying DEFAULT NULL::character varying, p_debuglevel integer DEFAULT 0, p_status character varying DEFAULT 'AVAILABLE'::character varying, p_requestid character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_start_time TIMESTAMP := clock_timestamp();
    v_execution_time INTERVAL;
    v_result JSONB;
    v_final_result JSONB;
    v_audit_data JSONB;
    
    v_card_record JSONB;
    v_cardnumber VARCHAR(19);
    v_masked_cardnumber VARCHAR(19);
    v_old_branch VARCHAR(4);
    v_uploadid VARCHAR(12);
    v_accountnumber VARCHAR(20);
    v_current_status VARCHAR(25);
    v_embossedname VARCHAR(30);
    v_expirydate DATE;
    v_row_count INTEGER;
    v_previous_values JSONB;
    
    v_total_cards INTEGER;
    v_processed_count INTEGER := 0;
    v_success_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_results_array JSONB := '[]'::JSONB;
    v_action_message TEXT;
    v_card_results JSONB := '[]'::JSONB;
    
    v_search_result JSONB;
    v_card_count INTEGER;
    v_card_data JSONB;
    
    v_status_to_use VARCHAR(25);
    v_action_detail VARCHAR(50);
    
    -- Variables for status composition
    v_new_status VARCHAR(25);
    v_status_parts VARCHAR(25)[];
    v_current_card_part VARCHAR(25);
    v_current_pin_part VARCHAR(25);
    
    -- Cross-branch access variables
    v_user_branchcode VARCHAR(10);
    v_user_instcode VARCHAR(4);
    v_user_crossbranch BOOLEAN := FALSE;
    v_user_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    v_user_access_message TEXT;
    v_current_booked_cards INTEGER;
    v_current_approved_cards INTEGER;
    v_current_booked_allocated BOOLEAN;
    v_current_approved_allocated BOOLEAN;
    v_flag_update_message TEXT := '';
    v_flag_updated BOOLEAN := FALSE;
BEGIN
    -- Debug level check for function start
    IF p_debuglevel > 3 THEN
        RAISE NOTICE '========================================';
        RAISE NOTICE 'FUNCTION STARTED at %', clock_timestamp();
        RAISE NOTICE 'Parameters:';
        RAISE NOTICE '  p_action: %', p_action;
        RAISE NOTICE '  p_cardnumbers: %', p_cardnumbers;
        RAISE NOTICE '  p_userid: %', p_userid;
        RAISE NOTICE '  p_branchcodetoallocate: %', p_branchcodetoallocate;
        RAISE NOTICE '  p_debuglevel: %', p_debuglevel;
        RAISE NOTICE '  p_status: %', p_status;
        RAISE NOTICE '  p_requestid: %', p_requestid;
        RAISE NOTICE '========================================';
    END IF;
    
    PERFORM set_config('app.debuglevel', p_debuglevel::text, false);
    PERFORM set_config('app.session_id', 
        COALESCE(current_setting('app.session_id', true), 
                'card_' || p_action || '_' || extract(epoch from now())::text), 
        false);
    PERFORM set_config('app.user_agent', 
        COALESCE(current_setting('app.user_agent', true), 'card_system'), 
        false);
    
    -- Get user branch info for access control
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 1: Getting user branch info for user_id: %', p_userid;
    END IF;
    
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name,
               al.username
          INTO v_user_branch_id, v_user_instcode, v_user_crossbranch, 
               v_user_branchcode, v_user_branchname, v_username
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        LEFT JOIN authlogin al ON al.userid = u.id
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_user_crossbranch := FALSE;
            v_user_branchcode := NULL;
            v_user_instcode := NULL;
            v_user_branchname := NULL;
            v_username := NULL;
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
            END IF;
        ELSE
            -- Clean branch code (remove any whitespace)
            v_user_branchcode := TRIM(v_user_branchcode);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'User found:';
                RAISE NOTICE '  username: %', v_username;
                RAISE NOTICE '  branchcode: %', v_user_branchcode;
                RAISE NOTICE '  branchname: %', v_user_branchname;
                RAISE NOTICE '  crossbranch: %', v_user_crossbranch;
            END IF;
            
            -- Validate branch code
            IF v_user_branchcode IS NULL OR v_user_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Set access message for audit logging
        IF v_user_crossbranch = TRUE THEN
            v_user_access_message := 'Cross-branch access enabled';
        ELSE
            v_user_access_message := 'Limited to branch: ' || v_user_branchcode;
        END IF;
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Access message: %', v_user_access_message;
        END IF;
        
    ELSE
        -- No user ID provided, use limited access
        v_user_crossbranch := FALSE;
        v_user_branchcode := NULL;
        v_username := NULL;
        v_user_access_message := 'No valid user ID provided - limited access';
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'No valid user ID provided, using limited access';
        END IF;
    END IF;
    
    -- Set status to use
    IF p_status IS NULL THEN
        v_status_to_use := 'AVAILABLE';
    ELSE
        v_status_to_use := p_status;
    END IF;
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status to use: %', v_status_to_use;
    END IF;
    
    -- Validate JSON input
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 2: Validating JSON input';
    END IF;
    
    IF jsonb_typeof(p_cardnumbers) != 'array' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: cardnumbers is not a JSON array, it is: %', jsonb_typeof(p_cardnumbers);
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'cardnumbers parameter must be a JSON array',
            jsonb_build_object(
                'error_message', 'cardnumbers parameter must be a JSON array',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'received_type', jsonb_typeof(p_cardnumbers),
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'cardnumbers parameter must be a JSON array',
            'error_code', 'INVALID_INPUT',
            'user_access', v_user_access_message
        );
    END IF;
    
    v_total_cards := jsonb_array_length(p_cardnumbers);
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Total cards in array: %', v_total_cards;
    END IF;
    
    -- Validate empty array for UPDATE/DELETE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 3: Checking for empty array (action: %)', p_action;
    END IF;
    
    IF p_action IN ('UPDATE', 'DELETE') AND v_total_cards = 0 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Empty card numbers array for UPDATE/DELETE action';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Empty card numbers array provided',
            jsonb_build_object(
                'error_message', 'Empty card numbers array provided',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel,
                'status', v_status_to_use
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'No card numbers provided',
            'error_code', 'EMPTY_ARRAY',
            'user_access', v_user_access_message
        );
    END IF;
    
    -- Validate status
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 4: Validating status: %', v_status_to_use;
    END IF;
    
    IF v_status_to_use NOT IN ('AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                               'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                               'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                               'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid status: %', v_status_to_use;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'VALIDATION_ERROR',
            'Invalid status value: ' || v_status_to_use,
            jsonb_build_object(
                'error_message', 'Invalid status value',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'provided_status', v_status_to_use,
                'valid_statuses', ARRAY['AVAILABLE', 'ALLOCATED', 'ASSIGNED', 'ACTIVE', 'BLOCKED', 'NEW', 'IN_STOCK', 'EXPIRED', 'CLOSED',
                                       'CARD DISPATCH', 'PIN DISPATCH', 'CARD & PIN DISPATCH', 
                                       'CARD ACK', 'PIN ACK', 'CARD ACK & PIN DISPATCH',
                                       'CARD DISPATCH & PIN ACK', 'CARD ACK & PIN ACK','BOOKED'],
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid status.',
            'error_code', 'INVALID_STATUS',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Status validation passed';
    END IF;
    
    -- Debug logging if debuglevel >= 1
    IF p_debuglevel >= 1 THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'Step 5: Debug logging (debuglevel >= 1)';
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            p_action || '_START',
            'Starting ' || p_action || ' action for ' || v_total_cards || ' cards with status: ' || v_status_to_use,
            jsonb_build_object(
                'action', p_action,
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'user_access_level', v_user_access_message,
                'branch_to_allocate', p_branchcodetoallocate,
                'status_to_set', v_status_to_use,
                'debuglevel', p_debuglevel,
                'start_time', v_start_time,
                'client_ip', inet_client_addr()
            )
        );
    END IF;
    
    -- Validate action
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 6: Validating action: %', p_action;
    END IF;
    
    IF p_action NOT IN ('UPDATE', 'DELETE', 'SEARCH') THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ERROR: Invalid action: %', p_action;
        END IF;
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'INVALID_ACTION',
            'Invalid action requested: ' || p_action,
            jsonb_build_object(
                'error_message', 'Invalid action requested',
                'requested_action', p_action,
                'valid_actions', ARRAY['UPDATE', 'DELETE', 'SEARCH'],
                'total_cards', v_total_cards,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Invalid action. Must be UPDATE, DELETE, or SEARCH',
            'error_code', 'INVALID_ACTION',
            'user_access', v_user_access_message
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Action validation passed';
    END IF;
    
    -- Validate branch access for UPDATE
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Step 7: Validating branch access for UPDATE action';
    END IF;
    
    IF p_action = 'UPDATE' AND p_branchcodetoallocate IS NOT NULL 
       AND v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
       AND p_branchcodetoallocate != v_user_branchcode THEN
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'ACCESS DENIED: User cannot allocate to branch % (user branch: %)', 
                p_branchcodetoallocate, v_user_branchcode;
        END IF;
            
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'BRANCH_ACCESS_DENIED',
            'User cannot allocate to branch: ' || p_branchcodetoallocate,
            jsonb_build_object(
                'error_message', 'User does not have permission to allocate to this branch',
                'action', p_action,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'target_branch', p_branchcodetoallocate,
                'crossbranch_access', v_user_crossbranch,
                'total_cards', v_total_cards,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to allocate cards to branch: ' || p_branchcodetoallocate,
            'error_code', 'BRANCH_ACCESS_DENIED',
            'user_access', v_user_access_message,
            'user_branch', v_user_branchcode,
            'target_branch', p_branchcodetoallocate
        );
    END IF;
    
    IF p_debuglevel > 3 THEN
        RAISE NOTICE 'Branch access validation passed';
    END IF;
    
    -- Main action handling
    IF p_action = 'UPDATE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING UPDATE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- Validate parameters for UPDATE
        IF p_branchcodetoallocate IS NULL AND v_status_to_use IS NULL THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'ERROR: Neither branch nor status provided for UPDATE';
            END IF;
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'UPDATE_ERROR',
                'Either branch or status must be provided for UPDATE action',
                jsonb_build_object(
                    'error_message', 'Either branch or status must be provided for UPDATE action',
                    'action', p_action,
                    'total_cards', v_total_cards,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'debuglevel', p_debuglevel
                )
            );
            
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Either branch code or status must be provided for UPDATE action',
                'error_code', 'MISSING_PARAMETER',
                'user_access', v_user_access_message
            );
        END IF;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE 'UPDATE parameters valid. Processing % cards', v_total_cards;
        END IF;
        
        -- Loop through each card
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE '----------------------------------------';
                RAISE NOTICE 'Processing card % of % (Index: %)', i+1, v_total_cards, i;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number at index %', i;
                END IF;
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Empty card number',
                    'error_code', 'EMPTY_CARD_NUMBER',
                    'user_access', v_user_access_message
                );
                CONTINUE;
            END IF;
            
            -- Create masked version for audit trail only
            v_masked_cardnumber := 'XXXX-XXXX-XXXX-' || RIGHT(v_cardnumber, 4);
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Masked card number: %', v_masked_cardnumber;
            END IF;
            
            BEGIN
                -- Get card details from database
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Fetching card details from instantcardstock';
                END IF;
                
                SELECT 
                    allocatedbranch, 
                    uploadid, 
                    accountnumber, 
                    status,
                    embossedname,
                    expirydate
                INTO 
                    v_old_branch, 
                    v_uploadid, 
                    v_accountnumber, 
                    v_current_status,
                    v_embossedname,
                    v_expirydate
                FROM public.instantcardstock 
                WHERE cardnumber = v_cardnumber;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Card details found:';
                    RAISE NOTICE '  allocatedbranch: %', v_old_branch;
                    RAISE NOTICE '  uploadid: %', v_uploadid;
                    RAISE NOTICE '  accountnumber: %', v_accountnumber;
                    RAISE NOTICE '  current status: %', v_current_status;
                    RAISE NOTICE '  embossedname: %', v_embossedname;
                END IF;
                
                IF v_uploadid IS NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ERROR: Card not found in database';
                    END IF;
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'Card not found',
                        'error_code', 'CARD_NOT_FOUND',
                        'user_access', v_user_access_message
                    );
                    CONTINUE;
                END IF;
                
                -- Check user access to modify this card
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Checking user access to modify card';
                END IF;
                
                IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
                   AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                            v_old_branch, v_user_branchcode;
                    END IF;
                        
                    v_failed_count := v_failed_count + 1;
                    v_card_results := v_card_results || jsonb_build_object(
                        'cardnumber', v_cardnumber,
                        'success', false,
                        'message', 'You do not have permission to modify this card. Card belongs to branch: ' || v_old_branch,
                        'error_code', 'CARD_ACCESS_DENIED',
                        'user_access', v_user_access_message,
                        'card_branch', v_old_branch,
                        'user_branch', v_user_branchcode
                    );
                    CONTINUE;
                END IF;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Access granted';
                END IF;
                
                -- Initialize v_new_status with the requested status
                v_new_status := v_status_to_use;
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Requested new status: %', v_new_status;
                END IF;
                
                -- STATUS COMPOSITION LOGIC
                -- Only apply composition logic for card/PIN related statuses
                IF v_status_to_use IN ('CARD DISPATCH', 'PIN DISPATCH', 'CARD ACK', 'PIN ACK') THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Applying status composition logic';
                        RAISE NOTICE 'Current status: %', v_current_status;
                    END IF;
                    
                    -- Check if current status is a combined status
                    IF v_current_status LIKE '%&%' THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is combined status';
                        END IF;
                        -- Parse the current combined status
                        v_status_parts := string_to_array(v_current_status, ' & ');
                        
                        IF array_length(v_status_parts, 1) >= 1 THEN
                            v_current_card_part := TRIM(v_status_parts[1]);
                        END IF;
                        IF array_length(v_status_parts, 1) >= 2 THEN
                            v_current_pin_part := TRIM(v_status_parts[2]);
                        END IF;
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current card part: %, current pin part: %', 
                                v_current_card_part, v_current_pin_part;
                        END IF;
                        
                        -- Apply composition logic based on requested status
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            -- Update card part to CARD DISPATCH, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD DISPATCH & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            -- Update pin part to PIN DISPATCH, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN DISPATCH';
                            ELSE
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            -- Update card part to CARD ACK, keep existing pin part
                            IF v_current_pin_part IS NOT NULL THEN
                                v_new_status := 'CARD ACK & ' || v_current_pin_part;
                            ELSE
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            -- Update pin part to PIN ACK, keep existing card part
                            IF v_current_card_part IS NOT NULL THEN
                                v_new_status := v_current_card_part || ' & PIN ACK';
                            ELSE
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Current status is simple status';
                        END IF;
                        -- Current status is not combined, need to create combination if needed
                        IF v_status_to_use = 'CARD DISPATCH' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched first, now card dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN ACK' THEN
                                -- PIN was acknowledged, now card dispatched
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Starting fresh with card dispatch
                                v_new_status := 'CARD DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN DISPATCH' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched first, now PIN dispatched
                                v_new_status := 'CARD & PIN DISPATCH';
                            ELSIF v_current_status = 'CARD ACK' THEN
                                -- Card was acknowledged, now PIN dispatched
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Starting fresh with PIN dispatch
                                v_new_status := 'PIN DISPATCH';
                            END IF;
                            
                        ELSIF v_status_to_use = 'CARD ACK' THEN
                            IF v_current_status = 'CARD DISPATCH' THEN
                                -- Card was dispatched, now acknowledged
                                v_new_status := 'CARD ACK';
                            ELSIF v_current_status = 'CARD DISPATCH & PIN ACK' THEN
                                -- Card dispatched & PIN acked, now card acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now card acknowledged
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSIF v_current_status = 'PIN DISPATCH' THEN
                                -- Only PIN dispatched, now card acknowledged (unusual)
                                v_new_status := 'CARD ACK & PIN DISPATCH';
                            ELSE
                                -- Direct card acknowledgment
                                v_new_status := 'CARD ACK';
                            END IF;
                            
                        ELSIF v_status_to_use = 'PIN ACK' THEN
                            IF v_current_status = 'PIN DISPATCH' THEN
                                -- PIN was dispatched, now acknowledged
                                v_new_status := 'PIN ACK';
                            ELSIF v_current_status = 'CARD ACK & PIN DISPATCH' THEN
                                -- Card acked & PIN dispatched, now PIN acknowledged
                                v_new_status := 'CARD ACK & PIN ACK';
                            ELSIF v_current_status = 'CARD & PIN DISPATCH' THEN
                                -- Both dispatched, now PIN acknowledged
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSIF v_current_status = 'CARD DISPATCH' THEN
                                -- Only card dispatched, now PIN acknowledged (unusual)
                                v_new_status := 'CARD DISPATCH & PIN ACK';
                            ELSE
                                -- Direct PIN acknowledgment
                                v_new_status := 'PIN ACK';
                            END IF;
                        END IF;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Composed new status: %', v_new_status;
                    END IF;
                END IF;
                -- END STATUS COMPOSITION LOGIC
                
                -- Now use v_new_status for the update   
                IF p_branchcodetoallocate IS NOT NULL THEN
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Branch allocation requested to: %', p_branchcodetoallocate;
                    END IF;
                    
                    -- Check if card can be allocated
                    IF v_current_status NOT IN ('AVAILABLE', 'NEW', 'IN_STOCK', 'ALLOCATED','BOOKED') THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Card status % does not allow allocation', v_current_status;
                        END IF;
                        v_failed_count := v_failed_count + 1;
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Card status does not allow branch allocation. Current: ' || v_current_status,
                            'error_code', 'INVALID_STATUS_FOR_BRANCH',
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Current branch: %, Target branch: %', v_old_branch, p_branchcodetoallocate;
                    END IF;
                    
                    IF v_old_branch = p_branchcodetoallocate THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Branch already matches target branch';
                        END IF;
                        
                        IF v_current_status != v_new_status THEN
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Updating status only (branch same)';
                            END IF;
                            
                            UPDATE public.instantcardstock
                            SET 
                                status = v_new_status,
                                lastupdateddate = CURRENT_TIMESTAMP,
                                lastupdatedby = v_username
                            WHERE cardnumber = v_cardnumber;
                            
                            GET DIAGNOSTICS v_row_count = ROW_COUNT;
                            v_success_count := v_success_count + 1;
                            
                            -- =====================================================
                            -- FLAG UPDATE - STATUS CHANGE WITH SAME BRANCH
                            -- =====================================================
                            IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL AND v_row_count = 1 THEN
                                RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                                
                                -- Get the request details
                                SELECT 
                                    booked_cards,
                                    approved_cards,
                                    bookedcardallocated,
                                    approvedcardsallocated
                                INTO 
                                    v_current_booked_cards,
                                    v_current_approved_cards,
                                    v_current_booked_allocated,
                                    v_current_approved_allocated
                                FROM public.instantcardcycle
                                WHERE requestid = p_requestid;
                                
                                IF FOUND THEN
                                    RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                    RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                    
                                    -- Check if the current allocation count matches booked_cards
                                    IF v_current_booked_allocated = false 
                                       AND v_current_booked_cards > 0 
                                       AND v_total_cards = v_current_booked_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET bookedcardallocated = true
                                        WHERE requestid = p_requestid;
                                        
                                        v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                    
                                    -- Check if the current allocation count matches approved_cards
                                    IF v_current_approved_allocated = false 
                                       AND v_current_approved_cards > 0 
                                       AND v_total_cards = v_current_approved_cards THEN
                                        
                                        UPDATE public.instantcardcycle
                                        SET approvedcardsallocated = true
                                        WHERE requestid = p_requestid;
                                        
                                        v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                        v_flag_updated := TRUE;
                                    END IF;
                                ELSE
                                    RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                                END IF;
                            END IF;
                            
                            -- LOGGING: Status change when branch already same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'STATUS_CHANGE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'Status updated to ' || v_new_status || ' (branch already ' || v_old_branch || ')',
                                'uploadid', v_uploadid,
                                'branch', v_old_branch,
                                'old_status', v_current_status,
                                'new_status', v_new_status,
                                'accountnumber', v_accountnumber,
                                'user_access', v_user_access_message,
                                'flag_updated', v_flag_updated,
                                'flag_message', v_flag_update_message
                            );
                            
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'Status update successful';
                            END IF;
                        ELSE
                            IF p_debuglevel > 3 THEN
                                RAISE NOTICE 'No changes required (branch and status same)';
                            END IF;
                            
                            v_success_count := v_success_count + 1;
                            
                            -- LOGGING: No change when branch same and status same
                            INSERT INTO LOG_instant_card_allocation (
                                cardnumber, operation_type,
                                from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                            ) VALUES (
                                v_cardnumber, 'UPDATE',
                                v_old_branch, p_branchcodetoallocate, v_current_status, v_current_status, v_username, p_userid
                            );
                            
                            v_card_results := v_card_results || jsonb_build_object(
                                'cardnumber', v_cardnumber,
                                'success', true,
                                'message', 'No changes required',
                                'no_change', true,
                                'current_branch', v_old_branch,
                                'current_status', v_current_status,
                                'user_access', v_user_access_message
                            );
                        END IF;
                        CONTINUE;
                    END IF;
                    
                    -- Perform the actual allocation
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Allocating card to new branch: %', p_branchcodetoallocate;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        allocatedbranch = p_branchcodetoallocate,
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - BRANCH ALLOCATION
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = p_requestid;
                            
                            IF FOUND THEN
                                RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                            ELSE
                                RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                            END IF;
                        END IF;
                        
                        -- LOGGING: Branch allocation with status change
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Branch allocated to ' || p_branchcodetoallocate || ' with status ' || v_new_status,
                            'uploadid', v_uploadid,
                            'old_branch', v_old_branch,
                            'new_branch', p_branchcodetoallocate,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Allocation successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'BRANCH_ALLOCATED',
                                'Card allocated to branch ' || p_branchcodetoallocate || ' with status ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'old_branch', v_old_branch,
                                    'new_branch', p_branchcodetoallocate,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                        
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Allocation failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'ALLOCATE',
                            v_old_branch, p_branchcodetoallocate, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Branch allocation failed - no rows affected',
                            'error_code', 'ALLOCATION_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                    
                ELSE
                    -- No branch allocation, just status update
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'No branch allocation - just status update to: %', v_new_status;
                    END IF;
                    
                    IF v_current_status = v_new_status THEN
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status already set to % - no change needed', v_new_status;
                        END IF;
                        
                        v_success_count := v_success_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'UPDATE',
                            v_old_branch, v_old_branch, v_current_status, v_current_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status already ' || v_new_status,
                            'no_change', true,
                            'current_branch', v_old_branch,
                            'current_status', v_current_status,
                            'user_access', v_user_access_message
                        );
                        CONTINUE;
                    END IF;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Updating status from % to %', v_current_status, v_new_status;
                    END IF;
                    
                    UPDATE public.instantcardstock
                    SET 
                        status = v_new_status,
                        lastupdateddate = CURRENT_TIMESTAMP,
                        lastupdatedby = v_username
                    WHERE cardnumber = v_cardnumber
                    RETURNING uploadid INTO v_uploadid;
                    
                    GET DIAGNOSTICS v_row_count = ROW_COUNT;
                    
                    IF p_debuglevel > 3 THEN
                        RAISE NOTICE 'Rows affected: %', v_row_count;
                    END IF;
                    
                    IF v_row_count = 1 THEN
                        v_success_count := v_success_count + 1;
                        
                        -- =====================================================
                        -- FLAG UPDATE - STATUS ONLY CHANGE
                        -- =====================================================
                        IF v_new_status = 'ALLOCATED' AND p_requestid IS NOT NULL THEN
                            RAISE NOTICE 'Checking flag update condition: v_new_status=%, p_requestid=%', v_new_status, p_requestid;
                            
                            -- Get the request details
                            SELECT 
                                booked_cards,
                                approved_cards,
                                bookedcardallocated,
                                approvedcardsallocated
                            INTO 
                                v_current_booked_cards,
                                v_current_approved_cards,
                                v_current_booked_allocated,
                                v_current_approved_allocated
                            FROM public.instantcardcycle
                            WHERE requestid = p_requestid;
                            
                            IF FOUND THEN
                                RAISE NOTICE 'DEBUG - booked_cards: %, approved_cards: %', v_current_booked_cards, v_current_approved_cards;
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to booked: %', v_total_cards, (v_total_cards = v_current_booked_cards);
                                RAISE NOTICE 'DEBUG - v_total_cards: %, comparing to approved: %', v_total_cards, (v_total_cards = v_current_approved_cards);
                                
                                -- Check if the current allocation count matches booked_cards
                                IF v_current_booked_allocated = false 
                                   AND v_current_booked_cards > 0 
                                   AND v_total_cards = v_current_booked_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET bookedcardallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := 'Booked flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                                
                                -- Check if the current allocation count matches approved_cards
                                IF v_current_approved_allocated = false 
                                   AND v_current_approved_cards > 0 
                                   AND v_total_cards = v_current_approved_cards THEN
                                    
                                    UPDATE public.instantcardcycle
                                    SET approvedcardsallocated = true
                                    WHERE requestid = p_requestid;
                                    
                                    v_flag_update_message := v_flag_update_message || ' Approved flag updated for request ' || p_requestid;
                                    v_flag_updated := TRUE;
                                END IF;
                            ELSE
                                RAISE NOTICE 'DEBUG - Request ID % NOT found in instantcardcycle table', p_requestid;
                            END IF;
                        END IF;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', true,
                            'message', 'Status updated to ' || v_new_status,
                            'uploadid', v_uploadid,
                            'branch', v_old_branch,
                            'old_status', v_current_status,
                            'new_status', v_new_status,
                            'accountnumber', v_accountnumber,
                            'user_access', v_user_access_message,
                            'flag_updated', v_flag_updated,
                            'flag_message', v_flag_update_message
                        );
                        
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Status update successful';
                        END IF;
                        
                        IF p_debuglevel >= 2 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD',
                                'STATUS_UPDATED',
                                'Card status updated to ' || v_new_status || ': ' || v_masked_cardnumber,
                                jsonb_build_object(
                                    'cardnumber', v_masked_cardnumber,
                                    'uploadid', v_uploadid,
                                    'branch', v_old_branch,
                                    'old_status', v_current_status,
                                    'new_status', v_new_status,
                                    'accountnumber', v_accountnumber,
                                    'user_id', p_userid,
                                    'username', v_username,
                                    'user_branch', v_user_branchcode,
                                    'crossbranch_access', v_user_crossbranch,
                                    'debuglevel', p_debuglevel
                                )
                            );
                        END IF;
                    ELSE
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'ERROR: Status update failed - no rows affected';
                        END IF;
                        
                        v_failed_count := v_failed_count + 1;
                        
                        INSERT INTO LOG_instant_card_allocation (
                            cardnumber, operation_type,
                            from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                        ) VALUES (
                            v_cardnumber, 'STATUS_CHANGE',
                            v_old_branch, v_old_branch, v_current_status, v_new_status, v_username, p_userid
                        );
                        
                        v_card_results := v_card_results || jsonb_build_object(
                            'cardnumber', v_cardnumber,
                            'success', false,
                            'message', 'Status update failed - no rows affected',
                            'error_code', 'STATUS_UPDATE_FAILED',
                            'user_access', v_user_access_message
                        );
                    END IF;
                END IF;
                  
            EXCEPTION WHEN OTHERS THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'EXCEPTION CAUGHT: %', SQLERRM;
                    RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
                END IF;
                
                v_failed_count := v_failed_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, from_status, to_status, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 
                    CASE 
                        WHEN p_branchcodetoallocate IS NOT NULL AND v_old_branch != p_branchcodetoallocate THEN 'ALLOCATE'
                        ELSE 'STATUS_CHANGE'
                    END,
                    v_old_branch, 
                    p_branchcodetoallocate, 
                    v_current_status, 
                    v_new_status, 
                    v_username, 
                    p_userid
                );
                
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'Error: ' || SQLERRM,
                    'error_code', SQLSTATE,
                    'user_access', v_user_access_message
                );
            END;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card processing complete. Success: %, Failed: %', v_success_count, v_failed_count;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('UPDATE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'UPDATE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '  Flag updated: %', v_flag_updated;
            RAISE NOTICE '  Flag message: %', v_flag_update_message;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'UPDATE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'UPDATE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch_allocated', p_branchcodetoallocate,
                'status_set', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'UPDATE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'branch', p_branchcodetoallocate,
                'status', v_new_status,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'flag_updated', v_flag_updated,
                'flag_message', v_flag_update_message
            ),
            'card_results', v_card_results
        );
    
    ELSIF p_action = 'DELETE' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING DELETE ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        -- DELETE section (with debug notices)
        FOR i IN 0..v_total_cards - 1 LOOP
            v_processed_count := v_processed_count + 1;
            v_cardnumber := p_cardnumbers->>i;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Processing card % of % for DELETE', i+1, v_total_cards;
                RAISE NOTICE 'Card number: %', v_cardnumber;
            END IF;
            
            IF v_cardnumber IS NULL OR v_cardnumber = '' THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Empty card number';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            -- Get card branch info first
            SELECT allocatedbranch INTO v_old_branch 
            FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            IF NOT FOUND THEN
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Card not found';
                END IF;
                v_failed_count := v_failed_count + 1;
                CONTINUE;
            END IF;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Card found in branch: %', v_old_branch;
            END IF;
            
            -- Check if user has access to delete this card
            IF v_user_crossbranch = FALSE AND v_user_branchcode IS NOT NULL 
               AND v_old_branch IS NOT NULL AND v_old_branch != v_user_branchcode THEN
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ACCESS DENIED: Card belongs to branch %, user is from branch %', 
                        v_old_branch, v_user_branchcode;
                END IF;
                    
                v_failed_count := v_failed_count + 1;
                v_card_results := v_card_results || jsonb_build_object(
                    'cardnumber', v_cardnumber,
                    'success', false,
                    'message', 'You do not have permission to delete this card. Card belongs to branch: ' || v_old_branch,
                    'error_code', 'CARD_ACCESS_DENIED',
                    'user_access', v_user_access_message,
                    'card_branch', v_old_branch,
                    'user_branch', v_user_branchcode
                );
                CONTINUE;
            END IF;
            
            -- Proceed with DELETE if user has access
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Deleting card';
            END IF;
            
            DELETE FROM public.instantcardstock 
            WHERE cardnumber = v_cardnumber;
            
            GET DIAGNOSTICS v_row_count = ROW_COUNT;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Rows affected: %', v_row_count;
            END IF;
            
            IF v_row_count = 1 THEN
                v_success_count := v_success_count + 1;
                
                INSERT INTO LOG_instant_card_allocation (
                    cardnumber, operation_type,
                    from_branch, to_branch, performed_by, performed_by_userid
                ) VALUES (
                    v_cardnumber, 'DELETE',
                    v_old_branch, NULL, v_username, p_userid
                );
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Delete successful';
                END IF;
            ELSE
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'ERROR: Delete failed';
                END IF;
                v_failed_count := v_failed_count + 1;
            END IF;
        END LOOP;
        
        v_execution_time := clock_timestamp() - v_start_time;
        v_action_message := format('DELETE completed: %s successful, %s failed out of %s total', 
                                 v_success_count, v_failed_count, v_total_cards);
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'DELETE SUMMARY:';
            RAISE NOTICE '  Total cards: %', v_total_cards;
            RAISE NOTICE '  Processed: %', v_processed_count;
            RAISE NOTICE '  Successful: %', v_success_count;
            RAISE NOTICE '  Failed: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'DELETE_COMPLETED',
            v_action_message,
            jsonb_build_object(
                'action', 'DELETE',
                'total_cards', v_total_cards,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'summary_message', v_action_message,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', v_success_count > 0,
            'message', v_action_message,
            'action', 'DELETE',
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'card_results', v_card_results
        );
        
    ELSIF p_action = 'SEARCH' THEN
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'PROCESSING SEARCH ACTION';
            RAISE NOTICE '========================================';
        END IF;
        
        v_search_result := '[]'::JSONB;
        
        -- If no card numbers provided, return cards with the specified status
        IF v_total_cards = 0 THEN
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for all cards with status: %', v_status_to_use;
                RAISE NOTICE 'Branch filter: user_branch=%, crossbranch=%', 
                    v_user_branchcode, v_user_crossbranch;
            END IF;
            
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'cardnumber', cardnumber,
                    'uploadid', uploadid,
                    'bankcode', bankcode,
                    'allocatedbranch', allocatedbranch,
                    'requestbranch', requestbranch,
                    'status', status,
                    'embossedname', embossedname,
                    'accountnumber', accountnumber,
                    'expirydate', expirydate,
                    'opendingdate', opendingdate,
                    'createddate', createddate,
                    'lastupdateddate', lastupdateddate,
                    'isgreenpin',isgreenpin
                )
                ORDER BY cardnumber asc
            ), '[]'::JSONB)
            INTO v_search_result
            FROM public.instantcardstock 
            WHERE CASE 
                -- When searching for PIN DISPATCH status, include multiple statuses
                WHEN v_status_to_use = 'PIN DISPATCH' THEN 
                    status IN ('ALLOCATED', 'CARD DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD DISPATCH' THEN 
                    status IN ('ALLOCATED', 'PIN DISPATCH', 'PIN ACK')
                WHEN v_status_to_use = 'PIN ACK' THEN 
                    status IN ('PIN DISPATCH', 'CARD ACK & PIN DISPATCH', 'CARD ACK')
                WHEN v_status_to_use = 'CARD ACK' THEN 
                    status IN ( 'CARD DISPATCH','CARD & PIN DISPATCH','CARD DISPATCH & PIN ACK')
                -- Otherwise use exact status match
                ELSE status = v_status_to_use
            END
            -- Branch access filtering for SEARCH
            AND (
                v_user_crossbranch = TRUE
                OR allocatedbranch = v_user_branchcode
                OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
            );
            
            v_success_count := COALESCE(jsonb_array_length(v_search_result), 0);
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Found % cards matching criteria', v_success_count;
            END IF;
            
        ELSE
            -- Process specific card numbers with branch access check
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Searching for % specific card numbers', v_total_cards;
            END IF;
            
            FOR i IN 0..v_total_cards - 1 LOOP
                v_cardnumber := p_cardnumbers->>i;
                
                IF p_debuglevel > 3 THEN
                    RAISE NOTICE 'Searching for card: %', v_cardnumber;
                END IF;
                
                IF v_cardnumber IS NOT NULL AND v_cardnumber != '' THEN
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'cardnumber', cardnumber,
                            'uploadid', uploadid,
                            'bankcode', bankcode,
                            'allocatedbranch', allocatedbranch,
                            'requestbranch', requestbranch,
                            'status', status,
                            'embossedname', embossedname,
                            'accountnumber', accountnumber,
                            'expirydate', expirydate,
                            'opendingdate', opendingdate,
                            'createddate', createddate,
                            'lastupdateddate', lastupdateddate
                        )
                    )
                    INTO v_card_data
                    FROM public.instantcardstock 
                    WHERE cardnumber = v_cardnumber
                    AND (
                        v_user_crossbranch = TRUE
                        OR allocatedbranch = v_user_branchcode
                        OR (v_user_branchcode IS NULL AND allocatedbranch IS NULL)
                    );
                    
                    IF v_card_data IS NOT NULL THEN
                        v_search_result := v_search_result || v_card_data;
                        v_success_count := v_success_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card found';
                        END IF;
                    ELSE
                        v_failed_count := v_failed_count + 1;
                        IF p_debuglevel > 3 THEN
                            RAISE NOTICE 'Card not found or access denied';
                        END IF;
                    END IF;
                END IF;
            END LOOP;
            
            IF p_debuglevel > 3 THEN
                RAISE NOTICE 'Search complete. Found: %, Not found: %', 
                    v_success_count, v_failed_count;
            END IF;
        END IF;
        
        IF p_debuglevel >= 1 THEN
            v_execution_time := clock_timestamp() - v_start_time;
            v_action_message := format('SEARCH completed: Found %s cards, %s not found', 
                                     v_success_count, v_failed_count);
            
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD',
                'SEARCH_COMPLETED',
                v_action_message,
                jsonb_build_object(
                    'action', 'SEARCH',
                    'total_cards', v_total_cards,
                    'found', v_success_count,
                    'not_found', v_failed_count,
                    'user_id', p_userid,
                    'username', v_username,
                    'user_branch', v_user_branchcode,
                    'crossbranch_access', v_user_crossbranch,
                    'status_filter', v_status_to_use,
                    'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                    'summary_message', v_action_message,
                    'debuglevel', p_debuglevel,
                    'search_criteria', CASE 
                        WHEN v_total_cards = 0 THEN format('ALL_CARDS_WITH_STATUS_%s', v_status_to_use)
                        ELSE format('SPECIFIC_CARDS(%s)', v_total_cards)
                    END
                )
            );
        END IF;
        
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'SEARCH SUMMARY:';
            RAISE NOTICE '  Total requested: %', v_total_cards;
            RAISE NOTICE '  Found: %', v_success_count;
            RAISE NOTICE '  Not found: %', v_failed_count;
            RAISE NOTICE '  Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        RETURN jsonb_build_object(
            'success', true,
            'message', format('SEARCH completed: Found %s cards, %s not found', 
                            v_success_count, v_failed_count),
            'action', 'SEARCH',
            'summary', jsonb_build_object(
                'total_requested', v_total_cards,
                'found', v_success_count,
                'not_found', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status_filter', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            ),
            'cards', v_search_result
        );
    END IF;
    
EXCEPTION
    WHEN OTHERS THEN
        v_execution_time := clock_timestamp() - v_start_time;
        
        IF p_debuglevel > 3 THEN
            RAISE NOTICE '========================================';
            RAISE NOTICE 'FATAL ERROR IN FUNCTION';
            RAISE NOTICE 'Error message: %', SQLERRM;
            RAISE NOTICE 'SQLSTATE: %', SQLSTATE;
            RAISE NOTICE 'Action: %', p_action;
            RAISE NOTICE 'Total cards: %', v_total_cards;
            RAISE NOTICE 'Processed: %', v_processed_count;
            RAISE NOTICE 'Execution time: % ms', extract(epoch from v_execution_time) * 1000;
            RAISE NOTICE '========================================';
        END IF;
        
        PERFORM public.flog_audit_trail(
            'INSTANT_CARD',
            'FUNCTION_ERROR',
            'Function error: ' || SQLERRM,
            jsonb_build_object(
                'error_message', SQLERRM,
                'error_code', SQLSTATE,
                'action', p_action,
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'status', v_status_to_use,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000,
                'debuglevel', p_debuglevel
            )
        );
        
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Function error: ' || SQLERRM,
            'error_code', SQLSTATE,
            'action', p_action,
            'summary', jsonb_build_object(
                'total_cards', v_total_cards,
                'processed', v_processed_count,
                'successful', v_success_count,
                'failed', v_failed_count,
                'user_id', p_userid,
                'username', v_username,
                'user_branch', v_user_branchcode,
                'crossbranch_access', v_user_crossbranch,
                'execution_time_ms', extract(epoch from v_execution_time) * 1000
            )
        );
END;
$$;


ALTER FUNCTION public.finstantcardbranchallocation_feb242026v3(p_action character varying, p_cardnumbers jsonb, p_userid integer, p_branchcodetoallocate character varying, p_debuglevel integer, p_status character varying, p_requestid character varying) OWNER TO postgres;

--
-- Name: finstantcardcycle(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    
    -- NEW VARIABLES for stock management
    v_headoffice_branchcode VARCHAR(4) := '0000';
    v_available_stock INTEGER;
    v_booked_cards INTEGER := 0;
    v_card_numbers TEXT[]; -- To store booked card numbers if needed
    v_temp_card_number VARCHAR(19);
    v_booked_cards_cursor REFCURSOR;
    v_stock_check_result RECORD;
	v_booked_count INTEGER DEFAULT 0;
    v_approved_count INTEGER DEFAULT 0;
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
							 'approved_cards', icc.approved_cards,        -- ADDED 13thfeb2026
            				'booked_cards', icc.booked_cards,            -- ADDED13thfeb2026
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate,
							'bookedcardallocated', icc.bookedcardallocated,     -- ADDED 13thfeb2026
            				'approvedcardsallocated', icc.approvedcardsallocated -- ADDED 13thfeb2026
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                           -- 'totalnumberofcard', icc.totalnumberofcard,
						     'totalnumberofcard', icc.totalnumberofcard, --st added feb-11-2026 to handle partial card request
                            'approved_cards', icc.approved_cards,        -- ADDED
            				'booked_cards', icc.booked_cards,            -- ADDED
							'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate,
							'bookedcardallocated', icc.bookedcardallocated,     -- ADDED
            				'approvedcardsallocated', icc.approvedcardsallocated -- ADDED
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with stock availability check)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 1 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
           
            
            -- Variable to store the status we'll insert with
            DECLARE
                v_insert_status VARCHAR(20) := COALESCE(p_status, 'PENDING');
            BEGIN
                INSERT INTO instantcardcycle (
                    scheme, cardtype, currency, totalnumberofcard, 
                    flags, pintype, requestedby, requestedbranchname, 
                    requestbranchcode, status
                ) VALUES (
                    p_scheme,
                    p_cardtype,
                    UPPER(p_currency),
                    p_totalnumberofcard,
                    p_flags,
                    p_pintype,
                    p_requestedby,
                    p_requestedbranchname,
                    p_requestbranchcode,
                    v_insert_status  -- Use the determined status
                )
                RETURNING requestid, jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'status', status,
                    'requesteddate', requesteddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname,
                    'cards_available', v_available_stock,
                    'cards_requested', p_totalnumberofcard,
                    'cards_booked', v_booked_cards,
                    'stock_check_performed', CASE WHEN p_requestbranchcode != v_headoffice_branchcode THEN TRUE ELSE FALSE END,
                    'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                ) INTO v_new_requestid, p_result_data;
                
                p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode || ' with status: ' || v_insert_status;
                
                -- Add stock info to message if applicable
                IF p_requestbranchcode != v_headoffice_branchcode THEN
                    IF v_insert_status = 'BOOKED' THEN
                        p_result_message := p_result_message || ' - Sufficient stock available';
                    ELSE
                        p_result_message := p_result_message || ' - Insufficient stock (Available: ' || v_available_stock || ' cards)';
                    END IF;
                END IF;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_SUCCESS',
                        'Instant card cycle created: ' || v_new_requestid || ' with status: ' || v_insert_status,
                        jsonb_build_object(
                            'requestid', v_new_requestid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'status', v_insert_status,
                            'branch', p_requestbranchcode,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'stock_available', v_available_stock,
                            'cards_requested', p_totalnumberofcard,
                            'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                        )
                    );
                END IF;
            END;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                RAISE NOTICE 'Setting v_update_type as %',v_update_type;
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 1 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                 RAISE NOTICE 'Setting v_update_type as %',v_update_type;
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Attempt to update completed cycle',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'current_status', v_current_record.status,
                                'requested_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If approving, require approvedby if not already set
                IF p_status = 'APPROVED' AND p_approvedby IS NULL AND v_current_record.approvedby IS NULL THEN
                    p_result_message := 'ERROR: approvedby is required when approving a request';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Missing approver for approval',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'error', p_result_message,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If verifying, require verifiedby AND verifiedbranchcode if not already set
                IF p_status = 'VERIFIED' THEN
                    IF p_verifiedby IS NULL AND v_current_record.verifiedby IS NULL THEN
                        p_result_message := 'ERROR: verifiedby is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verifier for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_verifiedbranchcode IS NULL AND v_current_record.verifiedbranchcode IS NULL THEN
                        p_result_message := 'ERROR: verifiedbranchcode is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verification branch for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
            END IF;
            -- =======================================================================================================
                    -- NEW CODE: STOCK CHECK FOR VERIFICATION DATE:FEB-11-2026 ONLY CHEC IF NOT HEAD OFFICE CODE!=0000
            -- ========================================================================================================
			-- Replace your stock check section (around line 460) with this:

					IF p_status = 'VERIFIED' THEN
					    v_booked_count := 0;
					    v_approved_count := 0;
					    
					    IF v_current_record.requestbranchcode != '0000' THEN
					        DECLARE
					            v_isgreenpin CHAR(1);
					        BEGIN
					            -- Determine isgreenpin based on pintype
					            IF v_current_record.pintype = 'GREEN-PIN' THEN
					                v_isgreenpin := 'Y';
					            ELSIF v_current_record.pintype = 'PAPER-PIN' THEN
					                v_isgreenpin := 'N';
					            ELSE
					                v_isgreenpin := NULL;
					            END IF;	
					            
					            -- Check available stock
					            SELECT COUNT(*) INTO v_available_stock
					            FROM instantcardstock
					            WHERE status = 'AVAILABLE'
					              AND (v_isgreenpin IS NULL OR isgreenpin = v_isgreenpin);
					            
					            RAISE NOTICE 'Verification stock check: Available=% cards, Requested=% cards', 
					                v_available_stock, v_current_record.totalnumberofcard;
					            
					            -- Calculate allocations based on stock
					            IF v_available_stock >= v_current_record.totalnumberofcard THEN
					                -- Case 1: Full stock available
					                v_booked_count := v_current_record.totalnumberofcard;
					                v_approved_count := 0;
					                -- ✅ CYCLE STATUS REMAINS VERIFIED
					                -- Do NOT change p_status - keep it as 'VERIFIED'
					                RAISE NOTICE 'Full stock: Booking % cards in stock table, cycle status stays VERIFIED', v_booked_count;
					                
					            ELSIF v_available_stock > 0 THEN
					                -- Case 2: Partial stock available
					                v_booked_count := v_available_stock;
					                v_approved_count := v_current_record.totalnumberofcard - v_available_stock;
					                -- ✅ CYCLE STATUS REMAINS VERIFIED
					                RAISE NOTICE 'Partial stock: Booking % cards, % cards remain VERIFIED for switch', 
					                    v_booked_count, v_approved_count;
					                    
					            ELSE
					                -- Case 3: No stock available
					                v_booked_count := 0;
					                v_approved_count := v_current_record.totalnumberofcard;
					                -- ✅ CYCLE STATUS REMAINS VERIFIED
					                RAISE NOTICE 'No stock: All % cards VERIFIED for switch', v_approved_count;
					            END IF;
					            
					            -- IMPORTANT: Do NOT change p_status - keep it as 'VERIFIED'
					            -- p_status remains what was passed in ('VERIFIED')
					            
					            -- Store allocation info for audit
					            IF v_debug_flag = 1 THEN
					                v_audit_data := jsonb_set(v_audit_data, '{stock_allocation}', 
					                    jsonb_build_object(
					                        'available_stock', v_available_stock,
					                        'booked_cards', v_booked_count,
					                        'approved_cards', v_approved_count,
					                        'cycle_status', 'VERIFIED'  -- Always VERIFIED for the cycle
					                    ));
					            END IF;
					        END;
					    ELSE -- Head office branch (0000)
					        -- Head office: all cards go to switch (no stock check)
					        v_booked_count := 0;
					        v_approved_count := v_current_record.totalnumberofcard;
					        -- p_status remains 'VERIFIED'
					        RAISE NOTICE 'Head office: All % cards VERIFIED for switch', v_approved_count;
					        
					        IF v_debug_flag = 1 THEN
					            v_audit_data := jsonb_set(v_audit_data, '{stock_allocation}', 
					                jsonb_build_object(
					                    'available_stock', 0,
					                    'booked_cards', 0,
					                    'approved_cards', v_approved_count,
					                    'cycle_status', 'VERIFIED',
					                    'head_office', TRUE
					                ));
					        END IF;
					    END IF; -- Branch check 0000 end
					END IF; -- VERIFIED status end
			-- =======================================================================================================
                    -- NEW CODE: STOCK CHECK FOR VERIFICATION END
            -- ========================================================================================================
                   -- DEBUG: Show parameter values
					    RAISE NOTICE '========== ALL UPDATE DEBUG ==========';
					    RAISE NOTICE 'p_requestid: %', p_requestid;
					    RAISE NOTICE 'p_status raw: "%"', p_status;
					    RAISE NOTICE 'v_booked_count: %', v_booked_count;
					    RAISE NOTICE 'v_approved_count: %', v_approved_count;
	          -- Perform update based on type
	        IF v_update_type = 'ALL' THEN
			    -- Update all fields including allocation columns
			   		UPDATE instantcardcycle
				    SET 
				        scheme = COALESCE(p_scheme, scheme),
				        cardtype = COALESCE(p_cardtype, cardtype),
				        currency = CASE 
				            WHEN p_currency IS NOT NULL THEN UPPER(p_currency) 
				            ELSE currency 
				        END,
				        totalnumberofcard = COALESCE(p_totalnumberofcard, totalnumberofcard),
				        flags = COALESCE(p_flags, flags),
				        pintype = COALESCE(p_pintype, pintype),
				        requestedby = COALESCE(p_requestedby, requestedby),
				        requestedbranchname = COALESCE(p_requestedbranchname, requestedbranchname),
				        requestbranchcode = COALESCE(p_requestbranchcode, requestbranchcode),
				        approvedby = COALESCE(p_approvedby, approvedby),
				        approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
				        approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
				        verifiedby = COALESCE(p_verifiedby, verifiedby),
				        verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
				        verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
				        status = COALESCE(p_status, status),
				
				        -- SAFE ALLOCATION COLUMNS UPDATE:
				        -- Only modifies values when status is APPROVED/BOOKED
				        -- Otherwise, keeps existing values
				        booked_cards = CASE 
				            WHEN p_status IN ('APPROVED', 'BOOKED') THEN v_booked_count
				            ELSE booked_cards  -- Keep existing value for other statuses
				        END,
				        
				        approved_cards = CASE 
				            WHEN p_status IN ('APPROVED', 'BOOKED') THEN v_approved_count
				            ELSE approved_cards  -- Keep existing value for other statuses
				        END,
				        
				        bookedcardallocated = CASE 
				            WHEN p_status IN ('APPROVED', 'BOOKED') AND v_booked_count > 0 THEN TRUE
				            WHEN p_status IN ('APPROVED', 'BOOKED') AND v_booked_count = 0 THEN FALSE
				            ELSE bookedcardallocated  -- Keep existing value for other statuses
				        END,
				  
				        
				        approvedate = CASE 
				            WHEN p_status IN ('APPROVED', 'REJECTED', 'BOOKED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
				            ELSE approvedate
				        END,
				        
				        verifieddate = CASE 
				            WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
				            ELSE verifieddate
				        END
				        
					    WHERE requestid = p_requestid
					    RETURNING jsonb_build_object(
					        'requestid', requestid,
					        'scheme', scheme,
					        'cardtype', cardtype,
					        'currency', currency,
					        'totalnumberofcard', totalnumberofcard,
					        'booked_cards', booked_cards,
					        'approved_cards', approved_cards,
					        'flags', flags,
					        'pintype', pintype,
					        'status', status,
					        'approvedby', approvedby,
					        'approvedbranchcode', approvedbranchcode,
					        'approvedbranchname', approvedbranchname,
					        'verifiedby', verifiedby,
					        'verifiedbranchname', verifiedbranchname,
					        'verifiedbranchcode', verifiedbranchcode,
					        'approvedate', approvedate,
					        'verifieddate', verifieddate,
					        'requestbranchcode', requestbranchcode,
					        'requestedbranchname', requestedbranchname
					    ) INTO p_result_data;
                RAISE NOTICE 'UPDATE completed. Result: %', p_result_data;
                p_result_message := 'SUCCESS: All fields updated';
				RAISE NOTICE 'EXECUTION END';	
				-- ST ADDED NOW UPDATING CARD AT INSTANTCARDSTOCK AS BOOKED AS WELL DATE:11-FEB-2026
				RAISE NOTICE 'status : %', p_status;							                    
                -- STOCK UPDATE - ONLY for BOOKED status
				RAISE NOTICE 'AT SETP 1 :p_status % v_booked_count%', p_status,v_booked_count;
			    IF p_status = 'BOOKED' AND v_booked_count > 0 THEN
			        UPDATE instantcardstock 
			        SET STATUS = 'BOOKED'
			        WHERE CARDNUMBER IN (
			            SELECT CARDNUMBER 
			            FROM instantcardstock 
			            WHERE STATUS = 'AVAILABLE'
			            ORDER BY CARDNUMBER
			            LIMIT v_booked_count
			        );
					RAISE NOTICE 'status updated successfully at cardcycle: %', v_booked_count;
			    END IF;
                -- Update audit data with changes for ALL fields update
                IF v_debug_flag = 1 THEN
                    IF p_scheme IS NOT NULL AND p_scheme != v_current_record.scheme THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,scheme}', 
                            jsonb_build_object('from', v_current_record.scheme, 'to', p_scheme));
                    END IF;
                    
                    IF p_totalnumberofcard IS NOT NULL AND p_totalnumberofcard != v_current_record.totalnumberofcard THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,totalnumberofcard}', 
                            jsonb_build_object('from', v_current_record.totalnumberofcard, 'to', p_totalnumberofcard));
                    END IF;
                    
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_current_record.requestbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,requestbranchcode}', 
                            jsonb_build_object('from', v_current_record.requestbranchcode, 'to', p_requestbranchcode));
                    END IF;
                    
                    v_audit_description := 'All fields updated for request: ' || p_requestid;
                END IF;
                
            ELSIF v_update_type = 'APPROVAL' THEN
                -- Update only approval/verification fields and status
				RAISE NOTICE 'UDATE AT APPROVAL----DEBUG';
                UPDATE instantcardcycle
                SET 
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
					booked_cards = CASE 
				            WHEN p_status IN ('VERIFIED', 'BOOKED') THEN v_booked_count
				            ELSE booked_cards  -- Keep existing value for other statuses
				        END,
				        
				        approved_cards = CASE 
				            WHEN p_status IN ('VERIFIED', 'BOOKED') THEN v_approved_count
				            ELSE approved_cards  -- Keep existing value for other statuses
				        END,
					-- ✓ FIXED: Use correct column names with 's'
			        
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: Approval/Verification fields updated';
                RAISE NOTICE 'UPDATING CARDCYCLESTOCK % status%',v_booked_count,p_status;
                p_result_message := 'SUCCESS: All fields updated';	
				-- ST ADDED NOW UPDATING CARD AT INSTANTCARDSTOCK AS BOOKED AS WELL DATE:11-FEB-2026
				RAISE NOTICE 'status : %', p_status;							                    
                -- STOCK UPDATE - ONLY for BOOKED status
				RAISE NOTICE 'AT SETP 2 :p_status % v_booked_count%', p_status,v_booked_count;
			  --  IF p_status = 'VERIFIED' AND v_booked_count > 0 THEN
			  IF v_booked_count > 0 THEN
					DECLARE
					 v_pin_filter CHAR(1);
        			 v_updated_rows INTEGER;
    				BEGIN
							 -- Set PIN filter based on request
					        IF v_current_record.pintype = 'GREEN-PIN' THEN
					            v_pin_filter := 'Y';
					        ELSIF v_current_record.pintype = 'PAPER-PIN' THEN
					            v_pin_filter := 'N';
					        ELSE
					            v_pin_filter := NULL;
					        END IF;
					        UPDATE instantcardstock 
					        SET STATUS = 'BOOKED'
					        WHERE CARDNUMBER IN (
					            SELECT CARDNUMBER 
					            FROM instantcardstock 
					            WHERE STATUS = 'AVAILABLE'
								AND isgreenpin = v_pin_filter  -- ✅ ONLY book correct PIN type
					            ORDER BY CARDNUMBER
					            LIMIT v_booked_count
					        );
							GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
					        RAISE NOTICE 'Actual cards updated: % out of % requested (filter: isgreenpin=%)', 
					            v_updated_rows, v_booked_count, v_pin_filter;
										END;
										RAISE NOTICE 'status updated successfully at cardcycle: %', v_booked_count;
			    END IF;
                -- Update audit data for APPROVAL/VERIFICATION update
                IF v_debug_flag = 1 THEN
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_approvedby IS NOT NULL AND p_approvedby != v_current_record.approvedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,approvedby}', 
                            jsonb_build_object('from', v_current_record.approvedby, 'to', p_approvedby));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    v_audit_description := 'Status updated to ' || COALESCE(p_status, v_current_record.status) || 
                                          ' for request: ' || p_requestid;
                END IF;
                
            END IF;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                p_result_data := '{}'::JSONB;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;-- END OF UPDATE PART
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
   			 	END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- Name: finstantcardcycle_backup_mar26(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle_backup_mar26(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables (ADDED)
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
	v_headoffice_branchcode VARCHAR(4)='0000';
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control (ADDED - Similar to reference function)
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH (UPDATED with cross-branch access control)
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with branch validation)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 10 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Insert record
            INSERT INTO instantcardcycle (
                scheme, cardtype, currency, totalnumberofcard, 
                flags, pintype, requestedby, requestedbranchname, 
                requestbranchcode, status
            ) VALUES (
                p_scheme,
                p_cardtype,
                UPPER(p_currency),
                p_totalnumberofcard,
                p_flags,
                p_pintype,
                p_requestedby,
                p_requestedbranchname,
                p_requestbranchcode,
                COALESCE(p_status, 'PENDING')
            )
            RETURNING requestid, jsonb_build_object(
                'requestid', requestid,
                'scheme', scheme,
                'cardtype', cardtype,
                'currency', currency,
                'totalnumberofcard', totalnumberofcard,
                'status', status,
                'requesteddate', requesteddate,
                'requestbranchcode', requestbranchcode,
                'requestedbranchname', requestedbranchname
            ) INTO v_new_requestid, p_result_data;
            
            p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'INSERT_SUCCESS',
                    'Instant card cycle created: ' || v_new_requestid,
                    jsonb_build_object(
                        'requestid', v_new_requestid,
                        'scheme', p_scheme,
                        'cardtype', p_cardtype,
                        'total_cards', p_totalnumberofcard,
                        'status', COALESCE(p_status, 'PENDING'),
                        'branch', p_requestbranchcode,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'user_branch', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 10 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Attempt to update completed cycle',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'current_status', v_current_record.status,
                                'requested_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If approving, require approvedby if not already set
                IF p_status = 'APPROVED' AND p_approvedby IS NULL AND v_current_record.approvedby IS NULL THEN
                    p_result_message := 'ERROR: approvedby is required when approving a request';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Missing approver for approval',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'error', p_result_message,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If verifying, require verifiedby AND verifiedbranchcode if not already set
                IF p_status = 'VERIFIED' THEN
                    IF p_verifiedby IS NULL AND v_current_record.verifiedby IS NULL THEN
                        p_result_message := 'ERROR: verifiedby is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verifier for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_verifiedbranchcode IS NULL AND v_current_record.verifiedbranchcode IS NULL THEN
                        p_result_message := 'ERROR: verifiedbranchcode is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verification branch for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
            END IF;
            
            -- Perform update based on type
            IF v_update_type = 'ALL' THEN
                -- Update all fields
                UPDATE instantcardcycle
                SET 
                    scheme = COALESCE(p_scheme, scheme),
                    cardtype = COALESCE(p_cardtype, cardtype),
                    currency = CASE 
                        WHEN p_currency IS NOT NULL THEN UPPER(p_currency) 
                        ELSE currency 
                    END,
                    totalnumberofcard = COALESCE(p_totalnumberofcard, totalnumberofcard),
                    flags = COALESCE(p_flags, flags),
                    pintype = COALESCE(p_pintype, pintype),
                    requestedby = COALESCE(p_requestedby, requestedby),
                    requestedbranchname = COALESCE(p_requestedbranchname, requestedbranchname),
                    requestbranchcode = COALESCE(p_requestbranchcode, requestbranchcode),
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'flags', flags,
                    'pintype', pintype,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: All fields updated';
                
                -- Update audit data with changes for ALL fields update
                IF v_debug_flag = 1 THEN
                    IF p_scheme IS NOT NULL AND p_scheme != v_current_record.scheme THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,scheme}', 
                            jsonb_build_object('from', v_current_record.scheme, 'to', p_scheme));
                    END IF;
                    
                    IF p_totalnumberofcard IS NOT NULL AND p_totalnumberofcard != v_current_record.totalnumberofcard THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,totalnumberofcard}', 
                            jsonb_build_object('from', v_current_record.totalnumberofcard, 'to', p_totalnumberofcard));
                    END IF;
                    
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_current_record.requestbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,requestbranchcode}', 
                            jsonb_build_object('from', v_current_record.requestbranchcode, 'to', p_requestbranchcode));
                    END IF;
                    
                    v_audit_description := 'All fields updated for request: ' || p_requestid;
                END IF;
                
            ELSIF v_update_type = 'APPROVAL' THEN
                -- Update only approval/verification fields and status
                UPDATE instantcardcycle
                SET 
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: Approval/Verification fields updated';
                
                -- Update audit data for APPROVAL/VERIFICATION update
                IF v_debug_flag = 1 THEN
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_approvedby IS NOT NULL AND p_approvedby != v_current_record.approvedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,approvedby}', 
                            jsonb_build_object('from', v_current_record.approvedby, 'to', p_approvedby));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    v_audit_description := 'Status updated to ' || COALESCE(p_status, v_current_record.status) || 
                                          ' for request: ' || p_requestid;
                END IF;
                
            END IF;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                p_result_data := '{}'::JSONB;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle_backup_mar26(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- Name: finstantcardcycle_feb112026(character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantcardcycle_feb112026(p_action character varying, p_requestid character varying DEFAULT NULL::character varying, p_scheme character varying DEFAULT NULL::character varying, p_cardtype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_totalnumberofcard integer DEFAULT NULL::integer, p_flags character varying DEFAULT NULL::character varying, p_pintype character varying DEFAULT NULL::character varying, p_requestedby character varying DEFAULT NULL::character varying, p_requestedbranchname character varying DEFAULT NULL::character varying, p_requestbranchcode character varying DEFAULT NULL::character varying, p_approvedby character varying DEFAULT NULL::character varying, p_approvedbranchcode character varying DEFAULT NULL::character varying, p_approvedbranchname character varying DEFAULT NULL::character varying, p_verifiedby character varying DEFAULT NULL::character varying, p_verifiedbranchname character varying DEFAULT NULL::character varying, p_verifiedbranchcode character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_userid integer DEFAULT 0, OUT p_result_message character varying, OUT p_result_data jsonb) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_requestid VARCHAR(12);
    v_current_record RECORD;
    v_update_type VARCHAR(20); -- 'ALL', 'APPROVAL', 'STATUS_ONLY'
    v_debug_flag INTEGER := 1; -- 1 = Enable audit logging for CRUD, 0 = Disable audit logging
    v_search_debug_flag INTEGER := 1; -- 1 = Enable audit logging for SEARCH, 0 = Disable (default off for production)
    v_audit_user VARCHAR(100);
    v_audit_data JSONB;
    v_audit_description TEXT;
    
    -- SEARCH variables
    v_search_records JSONB;
    v_total_count INTEGER;
    v_filtered_count INTEGER;
    v_search_criteria JSONB;
    
    -- Cross-branch access variables
    v_branchcode VARCHAR(10);
    v_instcode VARCHAR(4);
    v_crossbranch BOOLEAN := FALSE;
    v_branchname VARCHAR(100);
    v_username VARCHAR(30);
    v_user_branch_id INTEGER;
    
    -- NEW VARIABLES for stock management
    v_headoffice_branchcode VARCHAR(4) := '0000';
    v_available_stock INTEGER;
    v_booked_cards INTEGER := 0;
    v_card_numbers TEXT[]; -- To store booked card numbers if needed
    v_temp_card_number VARCHAR(19);
    v_booked_cards_cursor REFCURSOR;
    v_stock_check_result RECORD;
BEGIN
    -- Initialize outputs
    p_result_message := '';
    p_result_data := '{}'::JSONB;
    
    -- Determine audit user (priority: approvedby > requestedby > current user)
    v_audit_user := COALESCE(p_approvedby, p_requestedby, CURRENT_USER);
    
    -- Get user branch info for access control
    IF p_userid IS NOT NULL AND p_userid > 0 THEN
        RAISE NOTICE 'USER REQUESTING ID: %', p_userid;
        
        -- Get user info with explicit handling - JOIN with branch table to get branch_no
        SELECT u.branchid,
               LEFT(u.institutionid::TEXT, 4),
               u.crossbranch,
               b.branch_no,
               b.branch_name
          INTO v_user_branch_id, v_instcode, v_crossbranch, v_branchcode, v_branchname
        FROM users u
        LEFT JOIN branch b ON b.id = u.branchid
        WHERE u.id = p_userid;
        
        -- If user not found, use defaults
        IF NOT FOUND THEN
            v_crossbranch := FALSE;
            v_branchcode := NULL;
            v_instcode := NULL;
            v_branchname := NULL;
            RAISE NOTICE 'User ID % not found in users table, using limited access', p_userid;
        ELSE
            RAISE NOTICE 'User branch: % (code: %), Cross-branch: %', v_branchname, v_branchcode, v_crossbranch;
            
            -- Clean branch code (remove any whitespace)
            v_branchcode := TRIM(v_branchcode);
            
            -- Validate branch code
            IF v_branchcode IS NULL OR v_branchcode = '' THEN
                RAISE EXCEPTION 'User % has NULL or empty branch code. Please update user branch information.', p_userid;
            END IF;
        END IF;
        
        -- Get username for audit purposes
        SELECT username INTO v_username FROM authlogin WHERE userid = p_userid LIMIT 1;
        IF FOUND THEN
            v_audit_user := COALESCE(v_audit_user, v_username);
        END IF;
    ELSE
        -- No user ID provided, use limited access
        v_crossbranch := FALSE;
        v_branchcode := NULL;
        RAISE NOTICE 'No user ID provided, using limited access';
    END IF;
    
    -- Validate action (UPDATED to include SEARCH)
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'SEARCH') THEN
        p_result_message := 'ERROR: Invalid action. Use INSERT, UPDATE, DELETE, or SEARCH';
        
        -- Audit log for invalid action if debug flag is 1
        IF v_debug_flag = 1 THEN
            PERFORM public.flog_audit_trail(
                'INSTANT_CARD_CYCLE',
                'INVALID_ACTION',
                'Invalid action attempted: ' || p_action,
                jsonb_build_object(
                    'action', p_action,
                    'error', p_result_message,
                    'user', v_audit_user,
                    'user_id', p_userid
                )
            );
        END IF;
        RETURN;
    END IF;
    
    -- ACTION: SEARCH
    IF p_action = 'SEARCH' THEN
        BEGIN
            -- Build search criteria for audit logging (if enabled)
            v_search_criteria := jsonb_build_object(
                'requestid', p_requestid,
                'scheme', p_scheme,
                'cardtype', p_cardtype,
                'requestedby', p_requestedby,
                'approvedby', p_approvedby,
                'verifiedby', p_verifiedby,
                'requestbranchcode', p_requestbranchcode,
                'approvedbranchcode', p_approvedbranchcode,
                'verifiedbranchcode', p_verifiedbranchcode,
                'status', p_status,
                'start_date', p_start_date,
                'end_date', p_end_date,
                'user_id', p_userid,
                'user_branch', v_branchcode,
                'crossbranch_access', v_crossbranch
            );
            
            -- Get total count of all records
            SELECT COUNT(*) INTO v_total_count FROM instantcardcycle;
            
            -- Build dynamic query for search with branch access control
            IF p_requestid IS NOT NULL THEN
                -- EXCLUSIVE SEARCH: When requestid is provided, search ONLY by ID
                -- But check branch access if user doesn't have cross-branch privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                    )
                    FROM instantcardcycle icc
                    WHERE icc.requestid = p_requestid
                    -- ADDED: Branch access check
                    AND (v_crossbranch = TRUE OR icc.requestbranchcode = v_branchcode 
                         OR (p_userid IS NULL OR p_userid = 0)) -- Allow if no user ID provided
                );
            ELSE
                -- NORMAL SEARCH: When no requestid provided, use all other filters
                -- ADDED: Apply branch filtering based on user privileges
                v_search_records := (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'requestid', icc.requestid,
                            'scheme', icc.scheme,
                            'cardtype', icc.cardtype,
                            'currency', icc.currency,
                            'totalnumberofcard', icc.totalnumberofcard,
                            'flags', icc.flags,
                            'pintype', icc.pintype,
                            'requestedby', icc.requestedby,
                            'requestedbranchname', icc.requestedbranchname,
                            'requestbranchcode', icc.requestbranchcode,
                            'approvedby', icc.approvedby,
                            'approvedbranchcode', icc.approvedbranchcode,
                            'approvedbranchname', icc.approvedbranchname,
                            'verifiedby', icc.verifiedby,
                            'verifiedbranchname', icc.verifiedbranchname,
                            'verifiedbranchcode', icc.verifiedbranchcode,
                            'status', icc.status,
                            'requesteddate', icc.requesteddate,
                            'approvedate', icc.approvedate,
                            'verifieddate', icc.verifieddate
                        )
                        ORDER BY icc.requesteddate DESC
                    )
                    FROM instantcardcycle icc
                    WHERE 
                        (p_scheme IS NULL OR icc.scheme = p_scheme)
                        AND (p_cardtype IS NULL OR icc.cardtype = p_cardtype)
                        AND (p_requestedby IS NULL OR icc.requestedby = p_requestedby)
                        AND (p_approvedby IS NULL OR icc.approvedby = p_approvedby)
                        AND (p_verifiedby IS NULL OR icc.verifiedby = p_verifiedby)
                        AND (p_requestbranchcode IS NULL OR icc.requestbranchcode = p_requestbranchcode)
                        AND (p_approvedbranchcode IS NULL OR icc.approvedbranchcode = p_approvedbranchcode)
                        AND (p_verifiedbranchcode IS NULL OR icc.verifiedbranchcode = p_verifiedbranchcode)
                        AND (p_status IS NULL OR icc.status = p_status)
                        AND (p_start_date IS NULL OR DATE(icc.requesteddate) >= p_start_date)
                        AND (p_end_date IS NULL OR DATE(icc.requesteddate) <= p_end_date)
                        -- ADDED: Branch access control
                        AND (
                            v_crossbranch = TRUE 
                            OR icc.requestbranchcode = v_branchcode 
                            OR (p_userid IS NULL OR p_userid = 0) -- Allow if no user ID provided
                        )
                );
            END IF;
            
            -- Get filtered count
            IF v_search_records IS NULL THEN
                v_filtered_count := 0;
            ELSE
                v_filtered_count := jsonb_array_length(v_search_records);
            END IF;
            
            -- Prepare result data with access info
            p_result_data := jsonb_build_object(
                'search_criteria', v_search_criteria,
                'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                'total_records', v_total_count,
                'filtered_records', v_filtered_count,
                'user_access', jsonb_build_object(
                    'user_id', p_userid,
                    'branch_code', v_branchcode,
                    'crossbranch_access', v_crossbranch,
                    'branch_name', v_branchname
                ),
                'records', COALESCE(v_search_records, '[]'::jsonb)
            );
            
            IF p_requestid IS NOT NULL THEN
                p_result_message := 'SUCCESS: ID exclusive search completed. Found ' || v_filtered_count || ' record(s)';
            ELSE
                p_result_message := 'SUCCESS: Search completed. Found ' || v_filtered_count || ' records';
            END IF;
            
            -- Add access info to message if not cross-branch
            IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                p_result_message := p_result_message || ' (Filtered by branch: ' || v_branchcode || ')';
            ELSIF v_crossbranch = TRUE THEN
                p_result_message := p_result_message || ' (Cross-branch access enabled)';
            END IF;
            
            -- Audit log for SEARCH only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    CASE WHEN p_requestid IS NOT NULL THEN 'SEARCH_ID_EXCLUSIVE' ELSE 'SEARCH_SUCCESS' END,
                    'Search performed: ' || v_filtered_count || ' records found',
                    jsonb_build_object(
                        'search_criteria', v_search_criteria,
                        'total_records', v_total_count,
                        'filtered_records', v_filtered_count,
                        'search_type', CASE WHEN p_requestid IS NOT NULL THEN 'ID_EXCLUSIVE' ELSE 'NORMAL' END,
                        'user', v_audit_user,
                        'user_id', p_userid,
                        'branch_access', v_branchcode,
                        'crossbranch', v_crossbranch
                    )
                );
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: Search failed - ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            -- Audit log for SEARCH error only if search debug flag is enabled
            IF v_search_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'SEARCH_ERROR',
                    'Search failed: ' || SQLERRM,
                    jsonb_build_object(
                        'error', SQLERRM,
                        'search_criteria', v_search_criteria,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
        -- Return after SEARCH action
        RETURN;
    END IF;
    
    -- ACTION: INSERT (UPDATED with stock availability check)
    IF p_action = 'INSERT' THEN
        BEGIN
            -- Check for NULL required fields
            IF p_scheme IS NULL THEN
                p_result_message := 'ERROR: scheme is required';
                RETURN;
            END IF;
            IF p_cardtype IS NULL THEN
                p_result_message := 'ERROR: cardtype is required';
                RETURN;
            END IF;
            IF p_currency IS NULL THEN
                p_result_message := 'ERROR: currency is required';
                RETURN;
            END IF;
            IF p_totalnumberofcard IS NULL THEN
                p_result_message := 'ERROR: totalnumberofcard is required';
                RETURN;
            END IF;
            IF p_requestedby IS NULL THEN
                p_result_message := 'ERROR: requestedby is required';
                RETURN;
            END IF;
            
            -- ADDED: Use user's branch info if not provided
            IF p_requestedbranchname IS NULL AND v_branchname IS NOT NULL THEN
                p_requestedbranchname := v_branchname;
            END IF;
            
            IF p_requestbranchcode IS NULL THEN
                IF v_branchcode IS NOT NULL THEN
                    p_requestbranchcode := v_branchcode;
                ELSE
                    p_result_message := 'ERROR: requestbranchcode is required';
                    RETURN;
                END IF;
            END IF;
            
            -- ADDED: Validate user can create for this branch if branch code is provided
            IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
               AND p_requestbranchcode != v_branchcode AND v_crossbranch = FALSE THEN
                p_result_message := 'ERROR: You do not have permission to create records for branch: ' || 
                                   p_requestbranchcode || '. Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ACCESS_DENIED',
                        'Branch access denied for INSERT',
                        jsonb_build_object(
                            'user_branch', v_branchcode,
                            'requested_branch', p_requestbranchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate card count
            IF p_totalnumberofcard < 10 THEN
                p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'minimum_required', 10,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            IF p_totalnumberofcard > 10000 THEN
                p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_VALIDATION_ERROR',
                        'Card count validation failed: ' || p_totalnumberofcard,
                        jsonb_build_object(
                            'provided_cards', p_totalnumberofcard,
                            'maximum_allowed', 10000,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- NEW LOGIC: Check stock availability for non-head office branches
            v_available_stock := 0;
            v_booked_cards := 0;
            
            -- Variable to store the status we'll insert with
            DECLARE
                v_insert_status VARCHAR(20);
                v_is_greenpin CHAR(1);
            BEGIN
                -- Determine isgreenpin value based on pintype
                IF p_pintype = 'GREEN-PIN' THEN
                    v_is_greenpin := 'Y';
                ELSIF p_pintype = 'PAPER-PIN' THEN
                    v_is_greenpin := 'N';
                ELSE
                    v_is_greenpin := NULL; -- If pintype is null or unknown, don't filter by it
                END IF;
                
                -- Only check stock if branch is NOT head office
                IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_headoffice_branchcode THEN
                    
                    -- Check available stock count
                    SELECT COUNT(*) INTO v_available_stock
                    FROM instantcardstock
                    WHERE status = 'AVAILABLE'
                      --AND allocatedbranch = p_requestbranchcode
                      AND (v_is_greenpin IS NULL OR isgreenpin = v_is_greenpin);
                    
                    RAISE NOTICE 'Available stock for branch % (pintype: %, isgreenpin: %): % cards, Requested: % cards', 
                        p_requestbranchcode, p_pintype, v_is_greenpin, v_available_stock, p_totalnumberofcard;
                    
                    -- Determine status based on stock availability
                    IF v_available_stock >= p_totalnumberofcard THEN
                        v_insert_status := 'BOOKED';
                        v_booked_cards := p_totalnumberofcard; -- All requested cards can be booked
                        RAISE NOTICE 'Sufficient stock. Inserting with status: BOOKED';
                    ELSE
                        v_insert_status := 'PENDING';
                        v_booked_cards := 0; -- No cards booked yet
                        RAISE NOTICE 'Insufficient stock. Inserting with status: PENDING';
                    END IF;
                ELSE
                    -- Head office or branch not specified - default to PENDING
                    v_insert_status := COALESCE(p_status, 'PENDING');
                    v_booked_cards := 0;
                    RAISE NOTICE 'Head office branch or branch not specified. Inserting with status: %', v_insert_status;
                END IF;
                
                -- Insert record with determined status
                INSERT INTO instantcardcycle (
                    scheme, cardtype, currency, totalnumberofcard, 
                    flags, pintype, requestedby, requestedbranchname, 
                    requestbranchcode, status
                ) VALUES (
                    p_scheme,
                    p_cardtype,
                    UPPER(p_currency),
                    p_totalnumberofcard,
                    p_flags,
                    p_pintype,
                    p_requestedby,
                    p_requestedbranchname,
                    p_requestbranchcode,
                    v_insert_status  -- Use the determined status
                )
                RETURNING requestid, jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'status', status,
                    'requesteddate', requesteddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname,
                    'cards_available', v_available_stock,
                    'cards_requested', p_totalnumberofcard,
                    'cards_booked', v_booked_cards,
                    'stock_check_performed', CASE WHEN p_requestbranchcode != v_headoffice_branchcode THEN TRUE ELSE FALSE END,
                    'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                ) INTO v_new_requestid, p_result_data;
                
                p_result_message := 'SUCCESS: Record inserted for branch: ' || p_requestbranchcode || ' with status: ' || v_insert_status;
                
                -- Add stock info to message if applicable
                IF p_requestbranchcode != v_headoffice_branchcode THEN
                    IF v_insert_status = 'BOOKED' THEN
                        p_result_message := p_result_message || ' - Sufficient stock available';
                    ELSE
                        p_result_message := p_result_message || ' - Insufficient stock (Available: ' || v_available_stock || ' cards)';
                    END IF;
                END IF;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_SUCCESS',
                        'Instant card cycle created: ' || v_new_requestid || ' with status: ' || v_insert_status,
                        jsonb_build_object(
                            'requestid', v_new_requestid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'status', v_insert_status,
                            'branch', p_requestbranchcode,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'stock_available', v_available_stock,
                            'cards_requested', p_totalnumberofcard,
                            'is_head_office', CASE WHEN p_requestbranchcode = v_headoffice_branchcode THEN TRUE ELSE FALSE END
                        )
                    );
                END IF;
            END;
            
        EXCEPTION 
            WHEN not_null_violation THEN
                p_result_message := 'ERROR: Required field is missing';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Not null constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN check_violation THEN
                p_result_message := 'ERROR: Data validation failed';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_CONSTRAINT_ERROR',
                        'Check constraint violation',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
                
            WHEN OTHERS THEN
                p_result_message := 'ERROR: ' || SQLERRM;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'INSERT_ERROR',
                        'Insert failed: ' || SQLERRM,
                        jsonb_build_object(
                            'error', SQLERRM,
                            'user', v_audit_user,
                            'user_id', p_userid,
                            'scheme', p_scheme,
                            'cardtype', p_cardtype,
                            'total_cards', p_totalnumberofcard,
                            'branch', p_requestbranchcode
                        )
                    );
                END IF;
        END;
        
    -- ACTION: UPDATE (UPDATED with branch access control)
    ELSIF p_action = 'UPDATE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for UPDATE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'Missing requestid for UPDATE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get current record
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found with requestid: ' || p_requestid;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_NOT_FOUND',
                        'Record not found: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to update this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ACCESS_DENIED',
                        'Branch access denied for UPDATE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for UPDATE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'old_status', v_current_record.status,
                    'new_status', p_status,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch,
                    'old_approvedby', v_current_record.approvedby,
                    'new_approvedby', p_approvedby,
                    'old_verifiedby', v_current_record.verifiedby,
                    'new_verifiedby', p_verifiedby,
                    'old_verifiedbranchcode', v_current_record.verifiedbranchcode,
                    'new_verifiedbranchcode', p_verifiedbranchcode,
                    'changes', jsonb_build_object()
                );
            END IF;
            
            -- Determine update type based on provided parameters
            IF p_scheme IS NOT NULL OR p_cardtype IS NOT NULL OR p_currency IS NOT NULL OR
               p_totalnumberofcard IS NOT NULL OR p_flags IS NOT NULL OR p_pintype IS NOT NULL OR
               p_requestedby IS NOT NULL OR p_requestedbranchname IS NOT NULL OR p_requestbranchcode IS NOT NULL THEN
                -- Type 1: Update all fields (if any non-approval field is provided)
                v_update_type := 'ALL';
                
                -- ADDED: Check if user can change branch if requestbranchcode is being updated
                IF p_requestbranchcode IS NOT NULL AND v_branchcode IS NOT NULL 
                   AND p_requestbranchcode != v_current_record.requestbranchcode 
                   AND v_crossbranch = FALSE THEN
                    p_result_message := 'ERROR: You do not have permission to change record branch. ' ||
                                       'Current branch: ' || v_current_record.requestbranchcode || 
                                       ', New branch: ' || p_requestbranchcode;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_ACCESS_DENIED',
                            'Branch change denied for UPDATE',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'old_branch', v_current_record.requestbranchcode,
                                'new_branch', p_requestbranchcode,
                                'user_branch', v_branchcode,
                                'crossbranch', v_crossbranch,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- Validate card count if provided
                IF p_totalnumberofcard IS NOT NULL THEN
                    IF p_totalnumberofcard < 10 THEN
                        p_result_message := 'ERROR: Minimum 10 cards required. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'minimum_required', 10,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_totalnumberofcard > 10000 THEN
                        p_result_message := 'ERROR: Maximum 10000 cards allowed. Provided: ' || p_totalnumberofcard::text;
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Card count validation failed: ' || p_totalnumberofcard,
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'provided_cards', p_totalnumberofcard,
                                    'maximum_allowed', 10000,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_cards', v_current_record.totalnumberofcard
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
                
            ELSIF p_approvedby IS NOT NULL OR p_approvedbranchcode IS NOT NULL OR 
                  p_approvedbranchname IS NOT NULL OR p_verifiedby IS NOT NULL OR
                  p_verifiedbranchname IS NOT NULL OR p_verifiedbranchcode IS NOT NULL OR 
                  p_status IS NOT NULL THEN
                -- Type 2: Update approval/verification fields + status
                v_update_type := 'APPROVAL';
                
                -- Validate status if provided
                IF p_status IS NOT NULL AND p_status NOT IN ('PENDING', 'APPROVED', 'REJECTED', 'PROCESSING', 'COMPLETED', 'VERIFIED') THEN
                    p_result_message := 'ERROR: Invalid status value: ' || p_status;
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Invalid status value: ' || p_status,
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'invalid_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
            ELSE
                -- Type 3: No fields to update
                p_result_message := 'ERROR: No fields provided for update';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_VALIDATION_ERROR',
                        'No fields provided for update',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Validate status transitions
            IF p_status IS NOT NULL THEN
                -- Cannot update COMPLETED records
                IF v_current_record.status = 'COMPLETED' THEN
                    p_result_message := 'ERROR: Cannot update completed cycle';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Attempt to update completed cycle',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'current_status', v_current_record.status,
                                'requested_status', p_status,
                                'user', v_audit_user,
                                'user_id', p_userid
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If approving, require approvedby if not already set
                IF p_status = 'APPROVED' AND p_approvedby IS NULL AND v_current_record.approvedby IS NULL THEN
                    p_result_message := 'ERROR: approvedby is required when approving a request';
                    
                    IF v_debug_flag = 1 THEN
                        PERFORM public.flog_audit_trail(
                            'INSTANT_CARD_CYCLE',
                            'UPDATE_VALIDATION_ERROR',
                            'Missing approver for approval',
                            jsonb_build_object(
                                'requestid', p_requestid,
                                'error', p_result_message,
                                'user', v_audit_user,
                                'user_id', p_userid,
                                'current_status', v_current_record.status
                            )
                        );
                    END IF;
                    RETURN;
                END IF;
                
                -- If verifying, require verifiedby AND verifiedbranchcode if not already set
                IF p_status = 'VERIFIED' THEN
                    IF p_verifiedby IS NULL AND v_current_record.verifiedby IS NULL THEN
                        p_result_message := 'ERROR: verifiedby is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verifier for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                    
                    IF p_verifiedbranchcode IS NULL AND v_current_record.verifiedbranchcode IS NULL THEN
                        p_result_message := 'ERROR: verifiedbranchcode is required when verifying a request';
                        
                        IF v_debug_flag = 1 THEN
                            PERFORM public.flog_audit_trail(
                                'INSTANT_CARD_CYCLE',
                                'UPDATE_VALIDATION_ERROR',
                                'Missing verification branch for verification',
                                jsonb_build_object(
                                    'requestid', p_requestid,
                                    'error', p_result_message,
                                    'user', v_audit_user,
                                    'user_id', p_userid,
                                    'current_status', v_current_record.status
                                )
                            );
                        END IF;
                        RETURN;
                    END IF;
                END IF;
            END IF;
            
            -- Perform update based on type
            IF v_update_type = 'ALL' THEN
                -- Update all fields
                UPDATE instantcardcycle
                SET 
                    scheme = COALESCE(p_scheme, scheme),
                    cardtype = COALESCE(p_cardtype, cardtype),
                    currency = CASE 
                        WHEN p_currency IS NOT NULL THEN UPPER(p_currency) 
                        ELSE currency 
                    END,
                    totalnumberofcard = COALESCE(p_totalnumberofcard, totalnumberofcard),
                    flags = COALESCE(p_flags, flags),
                    pintype = COALESCE(p_pintype, pintype),
                    requestedby = COALESCE(p_requestedby, requestedby),
                    requestedbranchname = COALESCE(p_requestedbranchname, requestedbranchname),
                    requestbranchcode = COALESCE(p_requestbranchcode, requestbranchcode),
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'scheme', scheme,
                    'cardtype', cardtype,
                    'currency', currency,
                    'totalnumberofcard', totalnumberofcard,
                    'flags', flags,
                    'pintype', pintype,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate,
                    'requestbranchcode', requestbranchcode,
                    'requestedbranchname', requestedbranchname
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: All fields updated';
                
                -- Update audit data with changes for ALL fields update
                IF v_debug_flag = 1 THEN
                    IF p_scheme IS NOT NULL AND p_scheme != v_current_record.scheme THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,scheme}', 
                            jsonb_build_object('from', v_current_record.scheme, 'to', p_scheme));
                    END IF;
                    
                    IF p_totalnumberofcard IS NOT NULL AND p_totalnumberofcard != v_current_record.totalnumberofcard THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,totalnumberofcard}', 
                            jsonb_build_object('from', v_current_record.totalnumberofcard, 'to', p_totalnumberofcard));
                    END IF;
                    
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    IF p_requestbranchcode IS NOT NULL AND p_requestbranchcode != v_current_record.requestbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,requestbranchcode}', 
                            jsonb_build_object('from', v_current_record.requestbranchcode, 'to', p_requestbranchcode));
                    END IF;
                    
                    v_audit_description := 'All fields updated for request: ' || p_requestid;
                END IF;
                
            ELSIF v_update_type = 'APPROVAL' THEN
                -- Update only approval/verification fields and status
                UPDATE instantcardcycle
                SET 
                    approvedby = COALESCE(p_approvedby, approvedby),
                    approvedbranchcode = COALESCE(p_approvedbranchcode, approvedbranchcode),
                    approvedbranchname = COALESCE(p_approvedbranchname, approvedbranchname),
                    verifiedby = COALESCE(p_verifiedby, verifiedby),
                    verifiedbranchname = COALESCE(p_verifiedbranchname, verifiedbranchname),
                    verifiedbranchcode = COALESCE(p_verifiedbranchcode, verifiedbranchcode),
                    status = COALESCE(p_status, status),
                    approvedate = CASE 
                        WHEN p_status IN ('APPROVED', 'REJECTED') AND approvedate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status IN ('APPROVED', 'REJECTED') THEN approvedate
                        ELSE approvedate
                    END,
                    verifieddate = CASE 
                        WHEN p_status = 'VERIFIED' AND verifieddate IS NULL THEN CURRENT_TIMESTAMP
                        WHEN p_status = 'VERIFIED' THEN verifieddate
                        ELSE verifieddate
                    END
                WHERE requestid = p_requestid
                RETURNING jsonb_build_object(
                    'requestid', requestid,
                    'status', status,
                    'approvedby', approvedby,
                    'approvedbranchcode', approvedbranchcode,
                    'approvedbranchname', approvedbranchname,
                    'verifiedby', verifiedby,
                    'verifiedbranchname', verifiedbranchname,
                    'verifiedbranchcode', verifiedbranchcode,
                    'approvedate', approvedate,
                    'verifieddate', verifieddate
                ) INTO p_result_data;
                
                p_result_message := 'SUCCESS: Approval/Verification fields updated';
                
                -- Update audit data for APPROVAL/VERIFICATION update
                IF v_debug_flag = 1 THEN
                    IF p_status IS NOT NULL AND p_status != v_current_record.status THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,status}', 
                            jsonb_build_object('from', v_current_record.status, 'to', p_status));
                    END IF;
                    
                    IF p_approvedby IS NOT NULL AND p_approvedby != v_current_record.approvedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,approvedby}', 
                            jsonb_build_object('from', v_current_record.approvedby, 'to', p_approvedby));
                    END IF;
                    
                    IF p_verifiedby IS NOT NULL AND p_verifiedby != v_current_record.verifiedby THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedby}', 
                            jsonb_build_object('from', v_current_record.verifiedby, 'to', p_verifiedby));
                    END IF;
                    
                    IF p_verifiedbranchcode IS NOT NULL AND p_verifiedbranchcode != v_current_record.verifiedbranchcode THEN
                        v_audit_data = jsonb_set(v_audit_data, '{changes,verifiedbranchcode}', 
                            jsonb_build_object('from', v_current_record.verifiedbranchcode, 'to', p_verifiedbranchcode));
                    END IF;
                    
                    v_audit_description := 'Status updated to ' || COALESCE(p_status, v_current_record.status) || 
                                          ' for request: ' || p_requestid;
                END IF;
                
            END IF;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                p_result_data := '{}'::JSONB;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_ERROR',
                        'Record not found during update: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                -- ADDED: Include user access info in success message
                IF v_crossbranch = FALSE AND v_branchcode IS NOT NULL THEN
                    p_result_message := p_result_message || ' (User branch: ' || v_branchcode || ')';
                END IF;
                
                IF v_debug_flag = 1 AND v_audit_description IS NOT NULL THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'UPDATE_SUCCESS',
                        v_audit_description,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            p_result_data := '{}'::JSONB;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'UPDATE_ERROR',
                    'Update failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    -- ACTION: DELETE (UPDATED with branch access control)
    ELSIF p_action = 'DELETE' THEN
        BEGIN
            IF p_requestid IS NULL THEN
                p_result_message := 'ERROR: requestid is required for DELETE';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Missing requestid for DELETE',
                        jsonb_build_object(
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Get record before deletion for audit logging
            SELECT * INTO v_current_record 
            FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_NOT_FOUND',
                        'Record not found for deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- ADDED: Check if user has access to this record's branch
            IF v_branchcode IS NOT NULL AND v_crossbranch = FALSE 
               AND v_current_record.requestbranchcode != v_branchcode THEN
                p_result_message := 'ERROR: You do not have permission to delete this record. ' ||
                                   'Record belongs to branch: ' || v_current_record.requestbranchcode || 
                                   ', Your branch: ' || v_branchcode;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ACCESS_DENIED',
                        'Branch access denied for DELETE',
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'record_branch', v_current_record.requestbranchcode,
                            'user_branch', v_branchcode,
                            'crossbranch', v_crossbranch,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Only allow deletion of PENDING or REJECTED records
            IF v_current_record.status NOT IN ('PENDING', 'REJECTED') THEN
                p_result_message := 'ERROR: Cannot delete record with status: ' || v_current_record.status;
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_VALIDATION_ERROR',
                        'Delete failed - invalid status: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'status', v_current_record.status,
                            'allowed_statuses', 'PENDING, REJECTED',
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
                RETURN;
            END IF;
            
            -- Prepare audit data for DELETE if debug flag is 1
            IF v_debug_flag = 1 THEN
                v_audit_data := jsonb_build_object(
                    'requestid', p_requestid,
                    'scheme', v_current_record.scheme,
                    'cardtype', v_current_record.cardtype,
                    'total_cards', v_current_record.totalnumberofcard,
                    'status', v_current_record.status,
                    'branch', v_current_record.requestbranchcode,
                    'requested_by', v_current_record.requestedby,
                    'approved_by', v_current_record.approvedby,
                    'verified_by', v_current_record.verifiedby,
                    'user', v_audit_user,
                    'user_id', p_userid,
                    'user_branch', v_branchcode,
                    'record_branch', v_current_record.requestbranchcode,
                    'crossbranch', v_crossbranch
                );
            END IF;
            
            -- Delete record
            DELETE FROM instantcardcycle 
            WHERE requestid = p_requestid;
            
            IF NOT FOUND THEN
                p_result_message := 'ERROR: Record not found';
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_ERROR',
                        'Record not found during deletion: ' || p_requestid,
                        jsonb_build_object(
                            'requestid', p_requestid,
                            'error', p_result_message,
                            'user', v_audit_user,
                            'user_id', p_userid
                        )
                    );
                END IF;
            ELSE
                p_result_message := 'SUCCESS: Record deleted from branch: ' || v_current_record.requestbranchcode;
                p_result_data := jsonb_build_object(
                    'deleted_requestid', p_requestid,
                    'deleted_branch', v_current_record.requestbranchcode,
                    'user_branch', v_branchcode
                );
                
                IF v_debug_flag = 1 THEN
                    PERFORM public.flog_audit_trail(
                        'INSTANT_CARD_CYCLE',
                        'DELETE_SUCCESS',
                        'Instant card cycle deleted: ' || p_requestid,
                        v_audit_data
                    );
                END IF;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            p_result_message := 'ERROR: ' || SQLERRM;
            
            IF v_debug_flag = 1 THEN
                PERFORM public.flog_audit_trail(
                    'INSTANT_CARD_CYCLE',
                    'DELETE_ERROR',
                    'Delete failed: ' || p_requestid || ' - ' || SQLERRM,
                    jsonb_build_object(
                        'requestid', p_requestid,
                        'error', SQLERRM,
                        'user', v_audit_user,
                        'user_id', p_userid
                    )
                );
            END IF;
        END;
        
    END IF;
    
END;
$$;


ALTER FUNCTION public.finstantcardcycle_feb112026(p_action character varying, p_requestid character varying, p_scheme character varying, p_cardtype character varying, p_currency character varying, p_totalnumberofcard integer, p_flags character varying, p_pintype character varying, p_requestedby character varying, p_requestedbranchname character varying, p_requestbranchcode character varying, p_approvedby character varying, p_approvedbranchcode character varying, p_approvedbranchname character varying, p_verifiedby character varying, p_verifiedbranchname character varying, p_verifiedbranchcode character varying, p_status character varying, p_start_date date, p_end_date date, p_userid integer, OUT p_result_message character varying, OUT p_result_data jsonb) OWNER TO postgres;

--
-- Name: finstantgetrequestcountbooedapproved(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantgetrequestcountbooedapproved(p_branchname character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Return all records as a JSON array
    SELECT jsonb_agg(
        jsonb_build_object(
            'requestid', requestid,
            'totalnumberofcards', totalnumberofcard,
            'bookedcards', booked_cards,
            'approved_cards', approved_cards,
            'bookedcardallocated', bookedcardallocated,
            'approvedcardallocated', approvedcardsallocated,
            'status', status,
            'requestedbranchname', requestedbranchname,
            'requestbranchcode', requestbranchcode,
			'pintype',pintype
        )
    ) INTO v_result
    FROM instantcardcycle
    WHERE requestedbranchname = p_branchname;
    
    -- Check if any records found
    IF v_result IS NULL THEN
        RETURN jsonb_build_array(); -- Return empty array if no records
    END IF;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.finstantgetrequestcountbooedapproved(p_branchname character varying) OWNER TO postgres;

--
-- Name: finstantgetrequestcountbooedapproved_backfeb16(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finstantgetrequestcountbooedapproved_backfeb16(p_branchname character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
    v_record instantcardcycle%ROWTYPE;
BEGIN
    -- Get the first record for the requested branch name
    SELECT * INTO v_record
    FROM instantcardcycle
    WHERE requestedbranchname = p_branchname
    LIMIT 1;
    
    -- Check if record exists
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'error', 'No record found for branch',
            'branchname', p_branchname
        );
    END IF;
    
    -- Build JSON result with the actual column values from the record
    v_result := jsonb_build_object(
        'requestid', v_record.requestid,
        'totalnumberofcards', v_record.totalnumberofcard,
        'bookedcards', v_record.booked_cards,
        'approved_cards', v_record.approved_cards,
        'bookedcardallocated', v_record.bookedcardallocated,
        'approvedcardallocated', v_record.approvedcardsallocated,
        'status', v_record.status,
        'requestedbranchname', v_record.requestedbranchname,
        'requestbranchcode', v_record.requestbranchcode
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.finstantgetrequestcountbooedapproved_backfeb16(p_branchname character varying) OWNER TO postgres;

--
-- Name: fiso_transaction(character varying, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, character, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fiso_transaction(p_action character varying DEFAULT NULL::character varying, p_mti character DEFAULT NULL::bpchar, p_pan_2 character DEFAULT NULL::bpchar, p_pcode_3 character DEFAULT NULL::bpchar, p_tran_amount_4 character DEFAULT NULL::bpchar, p_tran_datetime_7 character DEFAULT NULL::bpchar, p_trace_11 character DEFAULT NULL::bpchar, p_local_time_12 character DEFAULT NULL::bpchar, p_local_date_13 character DEFAULT NULL::bpchar, p_expiry_date_14 character DEFAULT NULL::bpchar, p_settlement_date_15 character DEFAULT NULL::bpchar, p_merchant_category_code_18 character DEFAULT NULL::bpchar, p_acquiring_institution_country_code_19 character DEFAULT NULL::bpchar, p_point_of_service_entry_mode_22 character DEFAULT NULL::bpchar, p_point_of_service_conditon_mode_25 character DEFAULT NULL::bpchar, p_acquirer_id_32 character DEFAULT NULL::bpchar, p_track_ii_35 character DEFAULT NULL::bpchar, p_rrn_37 character DEFAULT NULL::bpchar, p_auth_id_38 character DEFAULT NULL::bpchar, p_resp_code_39 character DEFAULT NULL::bpchar, p_authorization_number character DEFAULT NULL::bpchar, p_card_acceptor_terminal_id_41 character DEFAULT NULL::bpchar, p_card_acceptor_identification_code_42 character DEFAULT NULL::bpchar, p_card_acceptor_name_location_43 character DEFAULT NULL::bpchar, p_additional_response_data_44 character DEFAULT NULL::bpchar, p_additional_data_iso_46 character DEFAULT NULL::bpchar, p_additional_data_private_48 character DEFAULT NULL::bpchar, p_currency_code_49 character DEFAULT NULL::bpchar, p_account_103 character DEFAULT NULL::bpchar, p_account_102 character DEFAULT NULL::bpchar, p_additional_amount_54 character DEFAULT NULL::bpchar, p_original_data_90 character DEFAULT NULL::bpchar, p_settlement_inst_identification_code_99 character DEFAULT NULL::bpchar, p_reserved_private_111 character DEFAULT NULL::bpchar, p_reserved_private_116 character DEFAULT NULL::bpchar, p_field_123 character DEFAULT NULL::bpchar, p_field_124 text DEFAULT NULL::text, p_debuglevel integer DEFAULT 2) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_audit_data jsonb;
    v_description text;
BEGIN
    -- Prepare audit data (only key fields for audit)
    v_audit_data = jsonb_build_object(
        'mti', p_mti,
        'pan_2', p_pan_2,
        'transaction_amount', p_tran_amount_4,
        'tran_datetime_7', p_tran_datetime_7,
        'rrn_37', p_rrn_37,
        'account_102', p_account_102,
        'account_103', p_account_103,
        'resp_code_39', p_resp_code_39,
        'auth_id_38', p_auth_id_38
    );

    -- Perform INSERT or UPDATE
    IF UPPER(p_action) = 'INSERT' THEN
        INSERT INTO public.iso_transaction (
            mti, pan_2, pcode_3, tran_amount_4, tran_datetime_7, trace_11, 
            local_time_12, local_date_13, expiry_date_14, settlement_date_15, 
            merchant_category_code_18, acquiring_institution_country_code_19, 
            point_of_service_entry_mode_22, point_of_service_conditon_mode_25, 
            acquirer_id_32, track_ii_35, rrn_37, auth_id_38, resp_code_39, 
            authorization_number, card_acceptor_terminal_id_41, 
            card_acceptor_identification_code_42, card_acceptor_name_location_43, 
            additional_response_data_44, additional_data_iso_46, 
            additional_data_private_48, currency_code_49, account_103, 
            account_102, additional_amount_54, original_data_90, 
            settlement_inst_identification_code_99, reserved_private_111, 
            reserved_private_116, field_123, field_124
        ) VALUES (
            p_mti, p_pan_2, p_pcode_3, p_tran_amount_4, p_tran_datetime_7, p_trace_11, 
            p_local_time_12, p_local_date_13, p_expiry_date_14, p_settlement_date_15, 
            p_merchant_category_code_18, p_acquiring_institution_country_code_19, 
            p_point_of_service_entry_mode_22, p_point_of_service_conditon_mode_25, 
            p_acquirer_id_32, p_track_ii_35, p_rrn_37, p_auth_id_38, p_resp_code_39, 
            p_authorization_number, p_card_acceptor_terminal_id_41, 
            p_card_acceptor_identification_code_42, p_card_acceptor_name_location_43, 
            p_additional_response_data_44, p_additional_data_iso_46, 
            p_additional_data_private_48, p_currency_code_49, p_account_103, 
            p_account_102, p_additional_amount_54, p_original_data_90, 
            p_settlement_inst_identification_code_99, p_reserved_private_111, 
            p_reserved_private_116, p_field_123, p_field_124
        );
        
        v_description = 'INSERT into iso_transaction';
        
    ELSIF UPPER(p_action) = 'UPDATE' THEN
        -- UPDATE using RRN and account_102 as WHERE condition
        UPDATE public.iso_transaction
        SET mti = COALESCE(p_mti, mti),
            resp_code_39 = COALESCE(p_resp_code_39, resp_code_39),
            auth_id_38 = COALESCE(p_auth_id_38, auth_id_38),
            authorization_number = COALESCE(p_authorization_number, authorization_number)
        WHERE rrn_37 = p_rrn_37 
          AND account_102 = p_account_102;
        
        v_description = 'UPDATE iso_transaction - updated MTI, RESP_CODE_39, AUTH_ID_38, AUTHORIZATION_NUMBER using RRN and account_102';
    END IF;

    -- Log to audit trail if debuglevel = 2
    IF p_debuglevel = 2 THEN
        PERFORM public.flog_audit_trail(
            'ISO_TRANSACTION',
            UPPER(p_action),
            v_description,
            v_audit_data
        );
    END IF;
END;
$$;


ALTER FUNCTION public.fiso_transaction(p_action character varying, p_mti character, p_pan_2 character, p_pcode_3 character, p_tran_amount_4 character, p_tran_datetime_7 character, p_trace_11 character, p_local_time_12 character, p_local_date_13 character, p_expiry_date_14 character, p_settlement_date_15 character, p_merchant_category_code_18 character, p_acquiring_institution_country_code_19 character, p_point_of_service_entry_mode_22 character, p_point_of_service_conditon_mode_25 character, p_acquirer_id_32 character, p_track_ii_35 character, p_rrn_37 character, p_auth_id_38 character, p_resp_code_39 character, p_authorization_number character, p_card_acceptor_terminal_id_41 character, p_card_acceptor_identification_code_42 character, p_card_acceptor_name_location_43 character, p_additional_response_data_44 character, p_additional_data_iso_46 character, p_additional_data_private_48 character, p_currency_code_49 character, p_account_103 character, p_account_102 character, p_additional_amount_54 character, p_original_data_90 character, p_settlement_inst_identification_code_99 character, p_reserved_private_111 character, p_reserved_private_116 character, p_field_123 character, p_field_124 text, p_debuglevel integer) OWNER TO postgres;

--
-- Name: fixed_apply_charges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fixed_apply_charges() RETURNS TABLE(status text, processed integer, amount numeric, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_processed INTEGER := 0;
    v_total DECIMAL(12,2) := 0;
    v_card RECORD;
BEGIN
    -- Loop through eligible cards one by one (simpler logic)
    FOR v_card IN (
        SELECT DISTINCT
            c.cardid,
            c.cardnumber,
            c.accountid,
            c.cardtype,
            c.schemetype,
            p.productname,
            p.productbin,
            p.currency,
            ra.action_value->>'charge_config_reference' as charge_ref,
            cc.amount as charge_amount,
            cc.percentage as charge_percentage,
            cc.charge_type as config_type
        FROM card c
        JOIN products p ON c.productid = p.productid
        JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status = 'ACTIVE'
        JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
        JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
        JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = 'ANNUAL_FEE'
        JOIN chargeconfig cc ON cc.chargeid = ra.action_value->>'charge_config_reference'
        WHERE c.status = 'A'
        AND c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
        AND rm.ruleid = 'R0109'
        -- Check conditions
        AND NOT EXISTS (
            SELECT 1 FROM ruleconditions rc 
            WHERE rc.ruleid = 'R0109'
            AND rc.is_active
            AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
        )
        -- Check existing charges
        AND NOT EXISTS (
            SELECT 1 FROM card_charges ch 
            WHERE ch.cardid = c.cardid 
            AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
            AND ch.charge_type = 'ANNUAL_FEE'
            AND ch.status != 'CANCELLED'
        )
        -- Check filters
        AND (ra.action_value->'filters'->>'scheme' IS NULL OR c.schemetype = ra.action_value->'filters'->>'scheme')
        AND (ra.action_value->'filters'->>'card_type' IS NULL OR c.cardtype = ra.action_value->'filters'->>'card_type')
        -- Charge config active
        AND cc.isactive 
        AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
        AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
    ) LOOP
        
        -- Calculate charge amount
        DECLARE
            v_calculated_amount DECIMAL(12,2);
        BEGIN
            IF v_card.config_type = 'FLAT' THEN
                v_calculated_amount := COALESCE(v_card.charge_amount, 0);
            ELSIF v_card.config_type = 'PER' THEN
                v_calculated_amount := (COALESCE(v_card.charge_percentage, 0) / 100.0) * 1000;  -- Using 1000 as base
            ELSIF v_card.config_type = 'BOTH' THEN
                v_calculated_amount := COALESCE(v_card.charge_amount, 0) + 
                                     ((COALESCE(v_card.charge_percentage, 0) / 100.0) * 1000);
            ELSE
                v_calculated_amount := COALESCE(v_card.charge_amount, 0);
            END IF;
            
            -- Insert charge
            INSERT INTO card_charges (
                charge_id, cardid, cardnumber, accountid, charge_type, 
                amount, currency, charge_date, charge_year, description,
                card_type, scheme_type, productname, productbin, status
            ) VALUES (
                fcreatefeesidanual(),
                v_card.cardid,
                v_card.cardnumber,
                v_card.accountid,
                'ANNUAL_FEE',
                v_calculated_amount,
                v_card.currency,
                CURRENT_DATE,
                EXTRACT(YEAR FROM CURRENT_DATE),
                'Annual fee - Fixed function',
                v_card.cardtype,
                v_card.schemetype,
                v_card.productname,
                v_card.productbin,
                'APPLIED'
            );
            
            v_processed := v_processed + 1;
            v_total := v_total + v_calculated_amount;
            
        EXCEPTION WHEN others THEN
            RAISE NOTICE 'Error processing card %: %', v_card.cardid, SQLERRM;
        END;
    END LOOP;
    
    status := 'SUCCESS';
    processed := v_processed;
    amount := v_total;
    message := 'Processed ' || v_processed || ' cards';
    
    RETURN NEXT;
    
EXCEPTION WHEN others THEN
    status := 'ERROR';
    processed := 0;
    amount := 0;
    message := SQLERRM;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fixed_apply_charges() OWNER TO postgres;

--
-- Name: flog_audit_trail(character varying, character varying, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.flog_audit_trail(p_entity_type character varying, p_action_type character varying, p_description text, p_data jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO audit_trail (
        entity_type,
        action_type,
        description,
        data,
        user_id,
        ip_address,
        user_agent
    ) VALUES (
        p_entity_type,
        p_action_type,
        p_description,
        p_data,
        CURRENT_USER,
        inet_client_addr(),
        current_setting('application_name', true)
    );
END;
$$;


ALTER FUNCTION public.flog_audit_trail(p_entity_type character varying, p_action_type character varying, p_description text, p_data jsonb) OWNER TO postgres;

--
-- Name: foperationlogdump(character varying, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.foperationlogdump(p_function_name character varying, p_additional_info text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation_id BIGINT;
BEGIN
    INSERT INTO operation_log (
        function_name,
        start_time,
        execution_status,
        username,
        additional_info
    ) VALUES (
        p_function_name,
        CURRENT_TIMESTAMP,
        'STARTED',
        CURRENT_USER,
        p_additional_info
    ) RETURNING operation_id INTO v_operation_id;
    
    RETURN v_operation_id;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Failed to log operation start: %', SQLERRM;
        RETURN -1; -- Return -1 on failure
END;
$$;


ALTER FUNCTION public.foperationlogdump(p_function_name character varying, p_additional_info text) OWNER TO postgres;

--
-- Name: fproductcrud(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fproductcrud(p_action character varying, p_productid character varying DEFAULT NULL::character varying, p_productname character varying DEFAULT NULL::character varying, p_productdescription character varying DEFAULT NULL::character varying, p_producttype character varying DEFAULT NULL::character varying, p_schemetype character varying DEFAULT NULL::character varying, p_currency character varying DEFAULT NULL::character varying, p_productbin character varying DEFAULT NULL::character varying, p_status character varying DEFAULT NULL::character varying, p_search_term character varying DEFAULT NULL::character varying, p_page_size integer DEFAULT 10, p_page_number integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_count INT;
    v_total_pages INT;
    v_offset INT;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_message TEXT;
    v_deleted_count INT;
BEGIN
    -- Input validation
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'GET') THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', 'Invalid action. Use INSERT, UPDATE, DELETE, LIST, or GET.',
            'timestamp', CURRENT_TIMESTAMP
        );
    END IF;

    -- For INSERT, UPDATE, DELETE actions, require basic validation
    IF p_action IN ('INSERT', 'UPDATE') THEN
        IF p_productname IS NULL OR p_productname = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Product name is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_producttype IS NULL OR p_producttype = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Product type is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_schemetype IS NULL OR p_schemetype = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Scheme type is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_currency IS NULL OR p_currency = '' THEN
            RETURN jsonb_build_object(
                'status', 'ERROR',
                'message', 'Currency is required.',
                'timestamp', CURRENT_TIMESTAMP
            );
        END IF;
        
        IF p_status IS NULL THEN
            p_status := 'ACTIVE';
        END IF;
    END IF;

    -- Perform the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Check for duplicate combination (unique constraint)
            BEGIN
                INSERT INTO products (
                    productname,
                    productdescription,
                    producttype,
                    schemetype,
                    currency,
                    productbin,
                    status
                ) VALUES (
                    p_productname,
                    p_productdescription,
                    p_producttype,
                    p_schemetype,
                    p_currency,
                    p_productbin,
                    p_status
                )
                RETURNING productid INTO p_productid;
                
                -- Get the inserted record
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                ) INTO v_result
                FROM products
                WHERE productid = p_productid;
                
                -- Log audit trail
                v_audit_message := 'Product created: ' || p_productname || ' (' || p_productid || ')';
                PERFORM flog_audit_trail('PRODUCT', 'INSERT', v_audit_message, v_result);
                
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product created successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
                
            EXCEPTION 
                WHEN unique_violation THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'A product with same type, scheme, currency and BIN already exists.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                WHEN OTHERS THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', SQLERRM,
                        'detail', SQLSTATE,
                        'timestamp', CURRENT_TIMESTAMP
                    );
            END;
            
        WHEN 'UPDATE' THEN
            -- Check if product exists
            IF NOT EXISTS (SELECT 1 FROM products WHERE productid = p_productid) THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            -- Get old record for audit
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status
            ) INTO v_old_record
            FROM products
            WHERE productid = p_productid;
            
            BEGIN
                UPDATE products
                SET 
                    productname = COALESCE(p_productname, productname),
                    productdescription = COALESCE(p_productdescription, productdescription),
                    producttype = COALESCE(p_producttype, producttype),
                    schemetype = COALESCE(p_schemetype, schemetype),
                    currency = COALESCE(p_currency, currency),
                    productbin = COALESCE(p_productbin, productbin),
                    status = COALESCE(p_status, status),
                    updateddate = CURRENT_TIMESTAMP
                WHERE productid = p_productid;
                
                -- Get the updated record
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                ) INTO v_result
                FROM products
                WHERE productid = p_productid;
                
                -- Get new record for audit
                SELECT jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status
                ) INTO v_new_record
                FROM products
                WHERE productid = p_productid;
                
                -- Log audit trail with changes
                v_audit_message := 'Product updated: ' || p_productid;
                PERFORM flog_audit_trail('PRODUCT', 'UPDATE', v_audit_message, 
                    jsonb_build_object('old', v_old_record, 'new', v_new_record));
                
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product updated successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
                
            EXCEPTION 
                WHEN unique_violation THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'A product with same type, scheme, currency and BIN already exists.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                WHEN OTHERS THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', SQLERRM,
                        'detail', SQLSTATE,
                        'timestamp', CURRENT_TIMESTAMP
                    );
            END;
            
        WHEN 'DELETE' THEN
            -- Check if product exists
            IF NOT EXISTS (SELECT 1 FROM products WHERE productid = p_productid) THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            -- Get record for audit before deletion
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status,
                'createddate', createddate,
                'updateddate', updateddate
            ) INTO v_old_record
            FROM products
            WHERE productid = p_productid;
            
            -- Check dependencies with detailed error messages
            DECLARE
                v_card_count INT;
                v_chargeconfig_count INT;
                v_error_details TEXT;
            BEGIN
                -- Count active cards
                SELECT COUNT(*) INTO v_card_count
                FROM card 
                WHERE productid = p_productid AND status = 'A';
                
                -- Count active charge configurations
                SELECT COUNT(*) INTO v_chargeconfig_count
                FROM chargeconfig 
                WHERE productid = p_productid AND isactive = true;
                
                -- Build detailed error message if dependencies exist
                v_error_details := '';
                IF v_card_count > 0 THEN
                    v_error_details := v_error_details || ' Associated with ' || v_card_count || ' active card(s).';
                END IF;
                IF v_chargeconfig_count > 0 THEN
                    v_error_details := v_error_details || ' Has ' || v_chargeconfig_count || ' active charge configuration(s).';
                END IF;
                
                -- If dependencies exist, return error
                IF v_card_count > 0 OR v_chargeconfig_count > 0 THEN
                    RETURN jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'Cannot delete product due to existing dependencies.' || v_error_details,
                        'dependencies', jsonb_build_object(
                            'active_cards', v_card_count,
                            'active_charge_configs', v_chargeconfig_count
                        ),
                        'timestamp', CURRENT_TIMESTAMP
                    );
                END IF;
                
                -- Perform HARD DELETE
                DELETE FROM products
                WHERE productid = p_productid;
                
                GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
                
                IF v_deleted_count = 0 THEN
                    v_result := jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'Product deletion failed.',
                        'timestamp', CURRENT_TIMESTAMP
                    );
                ELSE
                    -- Log audit trail
                    v_audit_message := 'Product HARD DELETED: ' || p_productid;
                    PERFORM flog_audit_trail('PRODUCT', 'DELETE', v_audit_message, v_old_record);
                    
                    v_result := jsonb_build_object(
                        'status', 'SUCCESS',
                        'message', 'Product permanently deleted successfully.',
                        'deleted_data', v_old_record,
                        'deleted_count', v_deleted_count,
                        'timestamp', CURRENT_TIMESTAMP
                    );
                END IF;
            END;
            
        WHEN 'GET' THEN
            -- Get single product by ID
            IF p_productid IS NULL THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product ID is required for GET action.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
            SELECT jsonb_build_object(
                'productid', productid,
                'productname', productname,
                'productdescription', productdescription,
                'producttype', producttype,
                'schemetype', schemetype,
                'currency', currency,
                'productbin', productbin,
                'status', status,
                'createddate', createddate,
                'updateddate', updateddate
            ) INTO v_result
            FROM products
            WHERE productid = p_productid;
            
            IF v_result IS NULL THEN
                v_result := jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Product not found.',
                    'timestamp', CURRENT_TIMESTAMP
                );
            ELSE
                v_result := jsonb_build_object(
                    'status', 'SUCCESS',
                    'message', 'Product retrieved successfully.',
                    'data', v_result,
                    'timestamp', CURRENT_TIMESTAMP
                );
            END IF;
            
        WHEN 'LIST' THEN
            -- Calculate pagination
            v_offset := (p_page_number - 1) * p_page_size;
            
            -- Get total count for pagination
            SELECT COUNT(*) INTO v_count
            FROM products
            WHERE 1=1
            AND (
                p_search_term IS NULL OR
                productid ILIKE '%' || p_search_term || '%' OR
                productname ILIKE '%' || p_search_term || '%' OR
                productdescription ILIKE '%' || p_search_term || '%' OR
                producttype ILIKE '%' || p_search_term || '%'
            );
            
            v_total_pages := CEIL(v_count::DECIMAL / p_page_size);
            
            -- Get paginated results
            SELECT jsonb_agg(
                jsonb_build_object(
                    'productid', productid,
                    'productname', productname,
                    'productdescription', productdescription,
                    'producttype', producttype,
                    'schemetype', schemetype,
                    'currency', currency,
                    'productbin', productbin,
                    'status', status,
                    'createddate', createddate,
                    'updateddate', updateddate
                )
            ) INTO v_result
            FROM products
            WHERE 1=1
            AND (
                p_search_term IS NULL OR
                productid ILIKE '%' || p_search_term || '%' OR
                productname ILIKE '%' || p_search_term || '%' OR
                productdescription ILIKE '%' || p_search_term || '%' OR
                producttype ILIKE '%' || p_search_term || '%'
            )
            ORDER BY createddate DESC
            LIMIT p_page_size
            OFFSET v_offset;
            
            -- Handle empty result
            IF v_result IS NULL THEN
                v_result := '[]'::JSONB;
            END IF;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'message', 'Products listed successfully.',
                'data', v_result,
                'pagination', jsonb_build_object(
                    'total_records', v_count,
                    'total_pages', v_total_pages,
                    'current_page', p_page_number,
                    'page_size', p_page_size,
                    'has_next', p_page_number < v_total_pages,
                    'has_previous', p_page_number > 1
                ),
                'timestamp', CURRENT_TIMESTAMP
            );
            
    END CASE;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', 'Unexpected error: ' || SQLERRM,
            'detail', SQLSTATE,
            'timestamp', CURRENT_TIMESTAMP
        );
END;
$$;


ALTER FUNCTION public.fproductcrud(p_action character varying, p_productid character varying, p_productname character varying, p_productdescription character varying, p_producttype character varying, p_schemetype character varying, p_currency character varying, p_productbin character varying, p_status character varying, p_search_term character varying, p_page_size integer, p_page_number integer) OWNER TO postgres;

--
-- Name: fprofilemastercurd(character varying, character varying, character varying, text, character varying, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fprofilemastercurd(p_action character varying, p_profileid character varying DEFAULT NULL::character varying, p_profilename character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_status character varying DEFAULT NULL::character varying, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_profileid VARCHAR(10);
    v_profile_count INTEGER;
    v_return_message TEXT;
    v_generated_profileid VARCHAR(10);
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Debug: Log input parameters
    RAISE NOTICE 'Input parameters: action=%, profilename=%, status=%', p_action, p_profilename, p_status;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_profileid := TRIM(p_profileid);
    p_profilename := TRIM(p_profilename);
    p_description := TRIM(p_description);
    p_status := UPPER(TRIM(p_status));
    
    RAISE NOTICE 'After trim: action=%, profilename=%, status=%', p_action, p_profilename, p_status;
    
    -- Check if table exists
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables 
                   WHERE table_schema = 'public' 
                   AND table_name = 'profilemaster') THEN
        RAISE EXCEPTION 'Table profilemaster does not exist';
    END IF;
    
    -- Log function call for debugging
    BEGIN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'FUNCTION_CALL',
            'EXECUTE',
            'fprofilemasterCURD called with action: ' || p_action,
            jsonb_build_object(
                'profileid', p_profileid,
                'profilename', p_profilename,
                'action', p_action
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Could not log to audit_trail: %', SQLERRM;
    END;
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, or SELECT';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate INSERT parameters
            IF p_profilename IS NULL OR p_profilename = '' THEN
                RAISE EXCEPTION 'profilename is required for INSERT';
            END IF;
            
            IF p_status IS NULL OR p_status = '' THEN
                RAISE EXCEPTION 'status is required for INSERT';
            END IF;
            
            -- Check for duplicate profilename (case-insensitive)
            SELECT COUNT(*) INTO v_profile_count
            FROM public.profilemaster
            WHERE LOWER(profilename) = LOWER(p_profilename);
            
            RAISE NOTICE 'Duplicate check: count=% for profilename=%', v_profile_count, p_profilename;
            
            IF v_profile_count > 0 THEN
                RAISE EXCEPTION 'profilename "%" already exists', p_profilename;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_profileid IS NULL OR p_profileid = '' THEN
                RAISE EXCEPTION 'profileid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_profile_count
            FROM public.profilemaster
            WHERE profileid = p_profileid;
            
            IF v_profile_count = 0 THEN
                RAISE EXCEPTION 'profileid "%" not found', p_profileid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(pm) INTO v_old_record
            FROM public.profilemaster pm
            WHERE profileid = p_profileid;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_profileid IS NULL OR p_profileid = '' THEN
                RAISE EXCEPTION 'profileid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_profile_count
            FROM public.profilemaster
            WHERE profileid = p_profileid;
            
            IF v_profile_count = 0 THEN
                RAISE EXCEPTION 'profileid "%" not found', p_profileid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(pm) INTO v_old_record
            FROM public.profilemaster pm
            WHERE profileid = p_profileid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_profileid IS NULL OR p_profileid = '' THEN
                RAISE EXCEPTION 'profileid is required for SELECT';
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            RAISE NOTICE 'Attempting INSERT with: profilename=%, description=%, status=%', 
                         p_profilename, p_description, p_status;
            
            -- Generate profileid using default function
            INSERT INTO public.profilemaster (
                profilename,
                description,
                status
            ) VALUES (
                p_profilename,
                p_description,
                p_status
            )
            RETURNING profileid INTO v_existing_profileid;
            
            RAISE NOTICE 'INSERT successful, generated profileid: %', v_existing_profileid;
            
            -- Get the newly inserted record
            SELECT row_to_json(pm) INTO v_new_record
            FROM public.profilemaster pm
            WHERE profileid = v_existing_profileid;
            
            v_return_message := 'Profile created successfully';
            v_audit_description := 'Created new profile: ' || p_profilename;
            
        WHEN 'UPDATE' THEN
            UPDATE public.profilemaster
            SET 
                profilename = COALESCE(p_profilename, profilename),
                description = COALESCE(p_description, description),
                status = COALESCE(p_status, status),
                updated_at = CURRENT_TIMESTAMP
            WHERE profileid = p_profileid
            RETURNING profileid INTO v_existing_profileid;
            
            -- Get the updated record
            SELECT row_to_json(pm) INTO v_new_record
            FROM public.profilemaster pm
            WHERE profileid = p_profileid;
            
            v_return_message := 'Profile updated successfully';
            v_audit_description := 'Updated profile: ' || p_profileid;
            
        WHEN 'DELETE' THEN
            DELETE FROM public.profilemaster
            WHERE profileid = p_profileid;
            
            v_return_message := 'Profile deleted successfully';
            v_audit_description := 'Deleted profile: ' || p_profileid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            SELECT row_to_json(pm) INTO v_new_record
            FROM public.profilemaster pm
            WHERE profileid = p_profileid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Profile with ID "%" not found', p_profileid;
            END IF;
            
            v_return_message := 'Profile retrieved successfully';
            v_audit_description := 'Retrieved profile: ' || p_profileid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all profiles
            SELECT jsonb_agg(
                jsonb_build_object(
                    'profileid', pm.profileid,
                    'profilename', pm.profilename,
                    'description', pm.description,
                    'status', pm.status,
                    'created_at', pm.created_at,
                    'updated_at', pm.updated_at
                )
            ) INTO v_new_record
            FROM public.profilemaster pm
            ORDER BY pm.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Profiles listed successfully';
            v_audit_description := 'Listed all profiles';
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST which could return many records)
    IF p_action != 'LIST' THEN
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                ip_address, 
                user_agent
            ) VALUES (
                'PROFILEMASTER',
                p_action,
                v_audit_description,
                jsonb_build_object(
                    'old_record', v_old_record,
                    'new_record', v_new_record,
                    'profileid', COALESCE(p_profileid, v_existing_profileid)
                ),
                p_user_id,
                p_ip_address,
                p_user_agent
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Could not log to audit_trail for action: %', SQLERRM;
        END;
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action = 'LIST' THEN v_new_record
            ELSE jsonb_build_object('profile', v_new_record)
        END,
        'profileid', COALESCE(p_profileid, v_existing_profileid)
    );
    
    RAISE NOTICE 'Function returning: %', v_result;
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        RAISE NOTICE 'Exception occurred: %', v_error_message;
        RAISE NOTICE 'Error detail: %', v_error_detail;
        
        -- Log error to audit trail
        BEGIN
            INSERT INTO public.audit_trail (
                entity_type, 
                action_type, 
                description, 
                data, 
                user_id, 
                ip_address, 
                user_agent
            ) VALUES (
                'PROFILEMASTER',
                'ERROR',
                'Error in fprofilemasterCURD: ' || v_error_message,
                jsonb_build_object(
                    'action', p_action,
                    'error_detail', v_error_detail,
                    'error_hint', v_error_hint,
                    'profileid', p_profileid
                ),
                p_user_id,
                p_ip_address,
                p_user_agent
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Could not log error to audit_trail: %', SQLERRM;
        END;
        
        -- Build error response
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Operation failed: ' || v_error_message,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'data', null
        );
        
        RETURN v_result;
END;
$$;


ALTER FUNCTION public.fprofilemastercurd(p_action character varying, p_profileid character varying, p_profilename character varying, p_description text, p_status character varying, p_user_id character varying, p_ip_address inet, p_user_agent text) OWNER TO postgres;

--
-- Name: fprofilerulemappingcrud(character varying, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fprofilerulemappingcrud(p_action character varying, p_profile_rule_id character varying DEFAULT NULL::character varying, p_profileid character varying DEFAULT NULL::character varying, p_ruleid character varying DEFAULT NULL::character varying, p_is_active boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSONB;
    v_count INTEGER;
    v_new_profile_rule_id VARCHAR;
BEGIN
    -- Input validation
    IF p_action IS NULL THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', 'Action parameter is required'
        );
    END IF;

    p_action := UPPER(p_action);
    
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate required parameters for INSERT
            IF p_profileid IS NULL OR p_ruleid IS NULL THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'profileid and ruleid are required for INSERT'
                );
            END IF;
            
            -- Check if the combination already exists
            SELECT COUNT(*) INTO v_count
            FROM public.profilerulemapping
            WHERE profileid = p_profileid AND ruleid = p_ruleid;
            
            IF v_count > 0 THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Profile-Rule combination already exists'
                );
            END IF;
            
            -- Insert new record (profile_rule_id will be auto-generated by fcreateprofilerulemappingid())
            INSERT INTO public.profilerulemapping (
                profileid,
                ruleid,
                is_active
            ) VALUES (
                p_profileid,
                p_ruleid,
                COALESCE(p_is_active, true)
            )
            RETURNING profile_rule_id INTO v_new_profile_rule_id;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'message', 'Record inserted successfully',
                'profile_rule_id', v_new_profile_rule_id
            );

        WHEN 'UPDATE' THEN
            -- Validate required parameters for UPDATE
            IF p_profile_rule_id IS NULL THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'profile_rule_id is required for UPDATE'
                );
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_count
            FROM public.profilerulemapping
            WHERE profile_rule_id = p_profile_rule_id;
            
            IF v_count = 0 THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Record not found'
                );
            END IF;
            
            -- If profileid and ruleid are being updated, check for duplicates
            IF p_profileid IS NOT NULL AND p_ruleid IS NOT NULL THEN
                SELECT COUNT(*) INTO v_count
                FROM public.profilerulemapping
                WHERE profileid = p_profileid 
                  AND ruleid = p_ruleid 
                  AND profile_rule_id != p_profile_rule_id;
                
                IF v_count > 0 THEN
                    RETURN jsonb_build_object(
                        'status', 'ERROR',
                        'message', 'Profile-Rule combination already exists'
                    );
                END IF;
            END IF;
            
            -- Update record
            UPDATE public.profilerulemapping
            SET 
                profileid = COALESCE(p_profileid, profileid),
                ruleid = COALESCE(p_ruleid, ruleid),
                is_active = COALESCE(p_is_active, is_active),
                updated_at = CURRENT_TIMESTAMP
            WHERE profile_rule_id = p_profile_rule_id;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'message', 'Record updated successfully',
                'profile_rule_id', p_profile_rule_id
            );

        WHEN 'DELETE' THEN
            -- Validate required parameters for DELETE
            IF p_profile_rule_id IS NULL THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'profile_rule_id is required for DELETE'
                );
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_count
            FROM public.profilerulemapping
            WHERE profile_rule_id = p_profile_rule_id;
            
            IF v_count = 0 THEN
                RETURN jsonb_build_object(
                    'status', 'ERROR',
                    'message', 'Record not found'
                );
            END IF;
            
            -- Delete record
            DELETE FROM public.profilerulemapping
            WHERE profile_rule_id = p_profile_rule_id;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'message', 'Record deleted successfully',
                'profile_rule_id', p_profile_rule_id
            );

        WHEN 'LIST' THEN
            -- Return all records or filter by profileid/ruleid
            IF p_profileid IS NOT NULL AND p_ruleid IS NOT NULL THEN
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'profile_rule_id', prm.profile_rule_id,
                        'profileid', prm.profileid,
                        'ruleid', prm.ruleid,
                        'is_active', prm.is_active,
                        'created_at', prm.created_at,
                        'updated_at', prm.updated_at
                    )
                ) INTO v_result
                FROM public.profilerulemapping prm
                WHERE prm.profileid = p_profileid AND prm.ruleid = p_ruleid;
            ELSIF p_profileid IS NOT NULL THEN
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'profile_rule_id', prm.profile_rule_id,
                        'profileid', prm.profileid,
                        'ruleid', prm.ruleid,
                        'is_active', prm.is_active,
                        'created_at', prm.created_at,
                        'updated_at', prm.updated_at
                    )
                ) INTO v_result
                FROM public.profilerulemapping prm
                WHERE prm.profileid = p_profileid;
            ELSIF p_ruleid IS NOT NULL THEN
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'profile_rule_id', prm.profile_rule_id,
                        'profileid', prm.profileid,
                        'ruleid', prm.ruleid,
                        'is_active', prm.is_active,
                        'created_at', prm.created_at,
                        'updated_at', prm.updated_at
                    )
                ) INTO v_result
                FROM public.profilerulemapping prm
                WHERE prm.ruleid = p_ruleid;
            ELSE
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'profile_rule_id', prm.profile_rule_id,
                        'profileid', prm.profileid,
                        'ruleid', prm.ruleid,
                        'is_active', prm.is_active,
                        'created_at', prm.created_at,
                        'updated_at', prm.updated_at
                    )
                ) INTO v_result
                FROM public.profilerulemapping prm;
            END IF;
            
            -- Handle case when no records found
            IF v_result IS NULL THEN
                v_result := jsonb_build_array();
            END IF;
            
            v_result := jsonb_build_object(
                'status', 'SUCCESS',
                'data', v_result
            );

        ELSE
            v_result := jsonb_build_object(
                'status', 'ERROR',
                'message', 'Invalid action. Use INSERT, UPDATE, DELETE, or LIST'
            );
    END CASE;

    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'status', 'ERROR',
            'message', SQLERRM
        );
END;
$$;


ALTER FUNCTION public.fprofilerulemappingcrud(p_action character varying, p_profile_rule_id character varying, p_profileid character varying, p_ruleid character varying, p_is_active boolean) OWNER TO postgres;

--
-- Name: frpt_analyze_search_criteria_v1_0_0_3(json); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frpt_analyze_search_criteria_v1_0_0_3(p_table_names json) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_result JSON;
    v_table_array TEXT[];
    v_column_info RECORD;
    v_criteria JSONB := '[]'::jsonb;
    v_criteria_json JSONB;
    v_grouped_criteria JSON;
BEGIN
    -- Parse table names
    IF p_table_names IS NOT NULL AND p_table_names::text != 'null' THEN
        SELECT array_agg(value::text) 
        INTO v_table_array
        FROM json_array_elements_text(p_table_names);
    ELSE
        v_table_array := NULL;
    END IF;
    
    -- Analyze each table and column to determine appropriate search criteria
    FOR v_column_info IN (
        SELECT 
            c.table_schema,
            c.table_name,
            c.column_name,
            c.data_type,
            c.is_nullable,
            tc.constraint_type,
            ccu.table_name as referenced_table,
            ccu.column_name as referenced_column
        FROM information_schema.columns c
        LEFT JOIN information_schema.key_column_usage kcu
            ON c.table_schema = kcu.table_schema
            AND c.table_name = kcu.table_name 
            AND c.column_name = kcu.column_name
        LEFT JOIN information_schema.table_constraints tc
            ON kcu.constraint_schema = tc.constraint_schema
            AND kcu.constraint_name = tc.constraint_name
        LEFT JOIN information_schema.constraint_column_usage ccu
            ON kcu.constraint_schema = ccu.constraint_schema
            AND kcu.constraint_name = ccu.constraint_name
        WHERE c.table_schema NOT IN ('pg_catalog', 'information_schema')
          AND (v_table_array IS NULL OR c.table_name = ANY(v_table_array))
        ORDER BY c.table_name, c.ordinal_position
    ) LOOP
        
        -- Initialize criteria object for this column
        v_criteria_json := NULL;
        
        -- Determine search criteria type based on column properties
        IF v_column_info.data_type IN ('date', 'timestamp', 'timestamp without time zone', 'timestamp with time zone', 'time', 'time without time zone', 'time with time zone') THEN
            -- Date/Time columns
            v_criteria_json := jsonb_build_object(
                'table', v_column_info.table_name,
                'column', v_column_info.column_name,
                'data_type', v_column_info.data_type,
                'search_type', 'DATE_RANGE',
                'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(replace(v_column_info.column_name, 'date', '')) || '_date',
                'description', 'Filter by ' || v_column_info.column_name || ' range',
                'operators', '["BETWEEN", "GREATER_THAN", "LESS_THAN"]'
            );
        
        ELSIF v_column_info.data_type IN ('integer', 'bigint', 'smallint', 'numeric', 'decimal', 'double precision', 'real', 'money') THEN
            -- Numeric columns
            v_criteria_json := jsonb_build_object(
                'table', v_column_info.table_name,
                'column', v_column_info.column_name,
                'data_type', v_column_info.data_type,
                'search_type', 'NUMERIC_RANGE',
                'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                'description', 'Filter by ' || v_column_info.column_name,
                'operators', '["EQUALS", "BETWEEN", "GREATER_THAN", "LESS_THAN"]'
            );
        
        ELSIF v_column_info.data_type IN ('character varying', 'varchar', 'text', 'char', 'character', 'bpchar') THEN
            -- Text columns
            IF v_column_info.column_name ~* '(id|code|number|num|no|ref|key)$' THEN
                -- Code/ID field
                v_criteria_json := jsonb_build_object(
                    'table', v_column_info.table_name,
                    'column', v_column_info.column_name,
                    'data_type', v_column_info.data_type,
                    'search_type', 'EXACT_MATCH',
                    'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                    'description', 'Filter by exact ' || v_column_info.column_name,
                    'operators', '["EQUALS", "IN_LIST"]'
                );
            ELSIF v_column_info.column_name ~* '(name|title|description|type|status|label|subject|topic|category)$' THEN
                -- Name/description field
                v_criteria_json := jsonb_build_object(
                    'table', v_column_info.table_name,
                    'column', v_column_info.column_name,
                    'data_type', v_column_info.data_type,
                    'search_type', 'TEXT_SEARCH',
                    'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                    'description', 'Search in ' || v_column_info.column_name,
                    'operators', '["CONTAINS", "STARTS_WITH", "EQUALS", "IN_LIST"]'
                );
            ELSE
                -- Generic text field
                v_criteria_json := jsonb_build_object(
                    'table', v_column_info.table_name,
                    'column', v_column_info.column_name,
                    'data_type', v_column_info.data_type,
                    'search_type', 'TEXT_SEARCH',
                    'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                    'description', 'Search in ' || v_column_info.column_name,
                    'operators', '["CONTAINS", "EQUALS"]'
                );
            END IF;
        
        ELSIF v_column_info.data_type = 'boolean' OR v_column_info.data_type = 'bool' THEN
            -- Boolean columns
            v_criteria_json := jsonb_build_object(
                'table', v_column_info.table_name,
                'column', v_column_info.column_name,
                'data_type', v_column_info.data_type,
                'search_type', 'BOOLEAN',
                'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                'description', 'Filter by ' || v_column_info.column_name,
                'operators', '["EQUALS"]'
            );
        
        ELSIF v_column_info.constraint_type = 'FOREIGN KEY' AND v_column_info.referenced_table IS NOT NULL THEN
            -- Foreign key columns
            v_criteria_json := jsonb_build_object(
                'table', v_column_info.table_name,
                'column', v_column_info.column_name,
                'data_type', v_column_info.data_type,
                'search_type', 'FOREIGN_KEY',
                'parameter_name', 'p_' || lower(v_column_info.referenced_table) || '_' || lower(replace(v_column_info.column_name, '_id', '')),
                'description', 'Filter by related ' || v_column_info.referenced_table,
                'referenced_table', v_column_info.referenced_table,
                'referenced_column', v_column_info.referenced_column,
                'operators', '["EQUALS", "IN_LIST"]'
            );
        
        ELSE
            -- Handle other data types (enum, json, jsonb, xml, uuid, etc.)
            -- For now, provide basic equality search
            v_criteria_json := jsonb_build_object(
                'table', v_column_info.table_name,
                'column', v_column_info.column_name,
                'data_type', v_column_info.data_type,
                'search_type', 'EXACT_MATCH',
                'parameter_name', 'p_' || lower(v_column_info.table_name) || '_' || lower(v_column_info.column_name),
                'description', 'Filter by ' || v_column_info.column_name,
                'operators', '["EQUALS", "IN_LIST"]'
            );
        END IF;
        
        -- Add to criteria array if we have a valid criteria object
        IF v_criteria_json IS NOT NULL THEN
            v_criteria := v_criteria || v_criteria_json;
        END IF;
    END LOOP;
    
    -- Group criteria by table using a two-step approach
    -- First, aggregate criteria by table in a temporary table/CTE
    WITH table_criteria AS (
        SELECT 
            (value->>'table') as table_name,
            json_agg(value ORDER BY (value->>'column')) as table_criteria_array
        FROM jsonb_array_elements(v_criteria)
        GROUP BY (value->>'table')
        ORDER BY (value->>'table')
    )
    SELECT json_agg(
        json_build_object(
            'table_name', tc.table_name,
            'search_criteria', tc.table_criteria_array
        )
        ORDER BY tc.table_name
    )
    INTO v_result
    FROM table_criteria tc;
    
    RETURN COALESCE(v_result, '[]'::json);
END;
$_$;


ALTER FUNCTION public.frpt_analyze_search_criteria_v1_0_0_3(p_table_names json) OWNER TO postgres;

--
-- Name: frpt_generate_dynamic_report_v1_0_0(json, json, json, json, json, json, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frpt_generate_dynamic_report_v1_0_0(p_tables json, p_filters json DEFAULT NULL::json, p_columns json DEFAULT NULL::json, p_joins json DEFAULT NULL::json, p_group_by json DEFAULT NULL::json, p_order_by json DEFAULT NULL::json, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_include_metadata boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_table_array TEXT[];
    v_select_clause TEXT := '';
    v_from_clause TEXT := '';
    v_where_clause TEXT := '';
    v_join_clause TEXT := '';
    v_group_clause TEXT := '';
    v_order_clause TEXT := '';
    v_main_query TEXT;
    v_count_query TEXT;
    v_count INTEGER := 0;
    v_temp_text TEXT;
    v_temp_value TEXT;
    v_table_name TEXT;
    v_column_name TEXT;
    v_filter_key TEXT;
    v_filter_value TEXT;
    v_filter_operator TEXT;
    v_filter_item JSONB;
    v_column_info JSON;
    v_metadata JSON;
    v_pagination_info JSON;
    v_json_type TEXT;
    i INTEGER;
    v_clean_table_name TEXT;
    v_tables_in_columns TEXT[] := ARRAY[]::TEXT[];
    v_table_in_column TEXT;
    v_column_list TEXT[];
    v_main_table TEXT;
    v_related_table TEXT;
    v_fk_column TEXT;
    v_pk_column TEXT;
    v_auto_joins TEXT := '';
    v_all_tables TEXT[];
    v_joined_tables TEXT[];
    v_table_without_schema TEXT;
    v_schema_name TEXT;
    v_table_only TEXT;
    v_condition TEXT;
BEGIN
    -- Step 1: Validate and parse input tables
    IF p_tables IS NULL OR p_tables::text = 'null' OR p_tables::text = '' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Tables parameter is required and must be a JSON array or string',
            'query', NULL,
            'data', '[]'::json
        );
    END IF;
    
    -- Check if p_tables is a JSON array
    BEGIN
        SELECT json_typeof(p_tables) INTO v_json_type;
        
        IF v_json_type != 'array' THEN
            v_temp_value := REPLACE(p_tables::text, '"', '');
            v_table_array := ARRAY[v_temp_value];
        ELSE
            SELECT array_agg(REPLACE(value::text, '"', '')) 
            INTO v_table_array
            FROM json_array_elements_text(p_tables);
        END IF;
    EXCEPTION WHEN OTHERS THEN
        v_temp_value := REPLACE(p_tables::text, '"', '');
        v_table_array := ARRAY[v_temp_value];
    END;
    
    -- Validate table array
    IF v_table_array IS NULL OR array_length(v_table_array, 1) IS NULL OR array_length(v_table_array, 1) = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'No valid tables specified',
            'query', NULL,
            'data', '[]'::json
        );
    END IF;
    
    -- Step 2: Generate SELECT clause and extract tables from columns
    IF p_columns IS NOT NULL AND p_columns::text != 'null' AND p_columns::text != '' THEN
        BEGIN
            SELECT json_typeof(p_columns) INTO v_json_type;
            
            IF v_json_type = 'array' THEN
                FOR v_temp_value IN SELECT REPLACE(value::text, '"', '') FROM json_array_elements_text(p_columns)
                LOOP
                    IF v_select_clause != '' THEN
                        v_select_clause := v_select_clause || ', ';
                    END IF;
                    v_select_clause := v_select_clause || v_temp_value;
                    
                    -- Extract table name from column if it's in table.column format
                    IF v_temp_value LIKE '%.%' THEN
                        -- Handle schema.table.column format
                        IF (SELECT COUNT(*) FROM regexp_matches(v_temp_value, '\.', 'g')) = 2 THEN
                            -- schema.table.column format
                            v_table_in_column := split_part(v_temp_value, '.', 1) || '.' || split_part(v_temp_value, '.', 2);
                        ELSE
                            -- table.column format
                            v_table_in_column := split_part(v_temp_value, '.', 1);
                        END IF;
                        
                        -- Add to tables list if not already present
                        IF NOT v_table_in_column = ANY(v_tables_in_columns) THEN
                            v_tables_in_columns := array_append(v_tables_in_columns, v_table_in_column);
                        END IF;
                    END IF;
                END LOOP;
            ELSE
                -- Treat as comma-separated string
                v_select_clause := REPLACE(p_columns::text, '"', '');
                
                -- Also extract tables from comma-separated columns
                v_column_list := string_to_array(REPLACE(p_columns::text, '"', ''), ',');
                FOR i IN 1..array_length(v_column_list, 1)
                LOOP
                    v_temp_value := TRIM(v_column_list[i]);
                    IF v_temp_value LIKE '%.%' THEN
                        -- Handle schema.table.column format
                        IF (SELECT COUNT(*) FROM regexp_matches(v_temp_value, '\.', 'g')) = 2 THEN
                            v_table_in_column := split_part(v_temp_value, '.', 1) || '.' || split_part(v_temp_value, '.', 2);
                        ELSE
                            v_table_in_column := split_part(v_temp_value, '.', 1);
                        END IF;
                        
                        IF NOT v_table_in_column = ANY(v_tables_in_columns) THEN
                            v_tables_in_columns := array_append(v_tables_in_columns, v_table_in_column);
                        END IF;
                    END IF;
                END LOOP;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_select_clause := REPLACE(p_columns::text, '"', '');
        END;
    ELSE
        -- Select all columns from specified tables
        IF array_length(v_table_array, 1) = 1 THEN
            v_select_clause := v_table_array[1] || '.*';
            v_tables_in_columns := ARRAY[v_table_array[1]];
        ELSE
            FOR i IN 1..array_length(v_table_array, 1)
            LOOP
                IF v_select_clause != '' THEN
                    v_select_clause := v_select_clause || ', ';
                END IF;
                v_select_clause := v_select_clause || v_table_array[i] || '.*';
                
                IF NOT v_table_array[i] = ANY(v_tables_in_columns) THEN
                    v_tables_in_columns := array_append(v_tables_in_columns, v_table_array[i]);
                END IF;
            END LOOP;
        END IF;
    END IF;
    
    -- Step 3: Generate FROM clause
    v_from_clause := v_table_array[1];
    
    -- Extract just the table name without schema for FK detection
    IF v_table_array[1] LIKE '%.%' THEN
        v_schema_name := split_part(v_table_array[1], '.', 1);
        v_table_only := split_part(v_table_array[1], '.', 2);
    ELSE
        v_schema_name := 'public';
        v_table_only := v_table_array[1];
    END IF;
    v_main_table := v_table_only;
    
    -- Step 4: AUTO-GENERATE JOINs based on database schema
    v_all_tables := v_tables_in_columns;
    v_joined_tables := ARRAY[v_table_array[1]];
    
    -- Function to find foreign key relationship
    FOR i IN 1..array_length(v_all_tables, 1)
    LOOP
        v_related_table := v_all_tables[i];
        
        -- Skip if already in joined tables or is main table
        IF v_related_table = v_table_array[1] OR v_related_table = ANY(v_joined_tables) THEN
            CONTINUE;
        END IF;
        
        -- Extract table name without schema for FK detection
        IF v_related_table LIKE '%.%' THEN
            v_schema_name := split_part(v_related_table, '.', 1);
            v_table_only := split_part(v_related_table, '.', 2);
        ELSE
            v_schema_name := 'public';
            v_table_only := v_related_table;
        END IF;
        
        -- Try to find a foreign key relationship
        BEGIN
            -- Look for foreign key relationship between the tables
            -- Method 1: Check if card has customer_id or customer_code
            IF v_table_only = 'card' AND v_main_table = 'customer' THEN
                -- Check for common foreign key patterns
                IF EXISTS(
                    SELECT 1 FROM information_schema.columns 
                    WHERE table_schema = 'public' 
                    AND table_name = 'card' 
                    AND column_name IN ('customer_id', 'customercode', 'customer_code')
                ) THEN
                    -- Find the actual column name
                    SELECT column_name INTO v_fk_column
                    FROM information_schema.columns 
                    WHERE table_schema = 'public' 
                    AND table_name = 'card' 
                    AND column_name IN ('customer_id', 'customercode', 'customer_code')
                    LIMIT 1;
                    
                    -- Use the actual column name found
                    v_auto_joins := v_auto_joins || ' LEFT JOIN public.card ON public.card.' || v_fk_column || ' = public.customer.customercode';
                    v_joined_tables := array_append(v_joined_tables, v_related_table);
                    CONTINUE;
                END IF;
            END IF;
            
            -- Method 2: General foreign key detection
            SELECT kcu.column_name, ccu.column_name
            INTO v_fk_column, v_pk_column
            FROM information_schema.table_constraints tc
            JOIN information_schema.key_column_usage kcu 
                ON tc.constraint_schema = kcu.constraint_schema
                AND tc.constraint_name = kcu.constraint_name
            JOIN information_schema.constraint_column_usage ccu
                ON tc.constraint_schema = ccu.constraint_schema
                AND tc.constraint_name = ccu.constraint_name
            WHERE tc.constraint_type = 'FOREIGN KEY'
              AND tc.table_schema = 'public'
              AND tc.table_name = v_main_table
              AND ccu.table_name = v_table_only
            LIMIT 1;
            
            IF FOUND THEN
                v_auto_joins := v_auto_joins || ' LEFT JOIN ' || v_related_table || 
                              ' ON ' || v_table_array[1] || '.' || v_fk_column || ' = ' || 
                              v_related_table || '.' || v_pk_column;
                v_joined_tables := array_append(v_joined_tables, v_related_table);
                CONTINUE;
            END IF;
            
            -- Check reverse relationship
            SELECT kcu.column_name, ccu.column_name
            INTO v_fk_column, v_pk_column
            FROM information_schema.table_constraints tc
            JOIN information_schema.key_column_usage kcu 
                ON tc.constraint_schema = kcu.constraint_schema
                AND tc.constraint_name = kcu.constraint_name
            JOIN information_schema.constraint_column_usage ccu
                ON tc.constraint_schema = ccu.constraint_schema
                AND tc.constraint_name = ccu.constraint_name
            WHERE tc.constraint_type = 'FOREIGN KEY'
              AND tc.table_schema = 'public'
              AND tc.table_name = v_table_only
              AND ccu.table_name = v_main_table
            LIMIT 1;
            
            IF FOUND THEN
                v_auto_joins := v_auto_joins || ' LEFT JOIN ' || v_related_table || 
                              ' ON ' || v_related_table || '.' || v_fk_column || ' = ' || 
                              v_table_array[1] || '.' || v_pk_column;
                v_joined_tables := array_append(v_joined_tables, v_related_table);
                CONTINUE;
            END IF;
            
            -- Method 3: Manual join for customer-card relationship
            IF (v_main_table = 'customer' AND v_table_only = 'card') OR 
               (v_main_table = 'card' AND v_table_only = 'customer') THEN
                v_auto_joins := v_auto_joins || ' LEFT JOIN public.card ON public.card.customercode = public.customer.customercode';
                v_joined_tables := array_append(v_joined_tables, v_related_table);
                CONTINUE;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            CONTINUE;
        END;
    END LOOP;
    
    -- Step 5: Add user-provided JOINs if any
    IF p_joins IS NOT NULL AND p_joins::text != 'null' AND p_joins::text != '' THEN
        BEGIN
            SELECT json_typeof(p_joins) INTO v_json_type;
            
            IF v_json_type = 'array' THEN
                FOR v_temp_value IN SELECT REPLACE(value::text, '"', '') FROM json_array_elements_text(p_joins)
                LOOP
                    v_join_clause := v_join_clause || ' ' || v_temp_value;
                END LOOP;
            ELSE
                v_join_clause := REPLACE(p_joins::text, '"', '');
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_join_clause := REPLACE(p_joins::text, '"', '');
        END;
    END IF;
    
    -- Combine auto-generated joins with user-provided joins
    v_join_clause := v_auto_joins || ' ' || v_join_clause;
    
    -- Step 6: Generate WHERE clause from filters using build_where_condition function
    IF p_filters IS NOT NULL AND p_filters::text != 'null' AND p_filters::text != '' THEN
        v_where_clause := ' WHERE 1=1';
        
        BEGIN
            SELECT json_typeof(p_filters) INTO v_json_type;
            
            IF v_json_type = 'array' THEN
                -- Parse as array of filter objects
                FOR v_filter_item IN SELECT * FROM jsonb_array_elements(p_filters::jsonb)
                LOOP
                    v_column_name := COALESCE(v_filter_item->>'column', v_filter_item->>'field');
                    v_filter_operator := COALESCE(v_filter_item->>'operator', 'EQUALS');
                    v_filter_value := v_filter_item->>'value';
                    
                    IF v_column_name IS NOT NULL AND v_filter_value IS NOT NULL THEN
                        -- Use the build_where_condition function for all filters
                        v_condition := public.build_where_condition(v_column_name, v_filter_operator, v_filter_value);
                        
                        IF v_condition IS NOT NULL AND v_condition != '' THEN
                            v_where_clause := v_where_clause || v_condition;
                        END IF;
                    END IF;
                END LOOP;
            ELSE
                -- Parse as key-value object (old format)
                FOR v_filter_key, v_filter_value IN 
                    SELECT key, value::text 
                    FROM json_each(p_filters)
                LOOP
                    -- Parse filter key (format: "column|operator")
                    IF v_filter_key LIKE '%|%' THEN
                        v_column_name := split_part(v_filter_key, '|', 1);
                        v_filter_operator := split_part(v_filter_key, '|', 2);
                    ELSE
                        v_column_name := v_filter_key;
                        v_filter_operator := 'EQUALS';
                    END IF;
                    
                    -- Use the build_where_condition function for all filters
                    v_condition := public.build_where_condition(v_column_name, v_filter_operator, v_filter_value);
                    
                    IF v_condition IS NOT NULL AND v_condition != '' THEN
                        v_where_clause := v_where_clause || v_condition;
                    END IF;
                END LOOP;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- If JSON parsing fails, skip filters
            v_where_clause := '';
            RAISE NOTICE 'Filter parsing error: %', SQLERRM;
        END;
    END IF;
    
    -- Step 7: Generate GROUP BY clause
    IF p_group_by IS NOT NULL AND p_group_by::text != 'null' AND p_group_by::text != '' THEN
        BEGIN
            SELECT json_typeof(p_group_by) INTO v_json_type;
            
            IF v_json_type = 'array' THEN
                v_group_clause := ' GROUP BY ';
                FOR v_temp_value IN SELECT REPLACE(value::text, '"', '') FROM json_array_elements_text(p_group_by)
                LOOP
                    IF v_group_clause != ' GROUP BY ' THEN
                        v_group_clause := v_group_clause || ', ';
                    END IF;
                    v_group_clause := v_group_clause || v_temp_value;
                END LOOP;
            ELSE
                v_group_clause := ' GROUP BY ' || REPLACE(p_group_by::text, '"', '');
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_group_clause := ' GROUP BY ' || REPLACE(p_group_by::text, '"', '');
        END;
    END IF;
    
    -- Step 8: Generate ORDER BY clause
    IF p_order_by IS NOT NULL AND p_order_by::text != 'null' AND p_order_by::text != '' THEN
        BEGIN
            SELECT json_typeof(p_order_by) INTO v_json_type;
            
            IF v_json_type = 'array' THEN
                v_order_clause := ' ORDER BY ';
                FOR v_temp_value IN SELECT REPLACE(value::text, '"', '') FROM json_array_elements_text(p_order_by)
                LOOP
                    IF v_order_clause != ' ORDER BY ' THEN
                        v_order_clause := v_order_clause || ', ';
                    END IF;
                    v_order_clause := v_order_clause || v_temp_value;
                END LOOP;
            ELSE
                v_order_clause := ' ORDER BY ' || REPLACE(p_order_by::text, '"', '');
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_order_clause := ' ORDER BY ' || REPLACE(p_order_by::text, '"', '');
        END;
    ELSE
        v_order_clause := ' ORDER BY 1';
    END IF;
    
    -- Step 9: Build main query
    v_main_query := 'SELECT ' || v_select_clause || 
                    ' FROM ' || v_from_clause || 
                    v_join_clause || 
                    v_where_clause || 
                    v_group_clause ||
                    v_order_clause ||
                    ' LIMIT ' || p_limit || 
                    ' OFFSET ' || p_offset;
    
    -- Step 10: Build count query
    v_count_query := 'SELECT COUNT(*) FROM (' ||
                     'SELECT 1 FROM ' || v_from_clause || 
                     v_join_clause || v_where_clause || v_group_clause ||
                     ') as count_query';
    
    -- Step 11: Execute count query
    BEGIN
        EXECUTE v_count_query INTO v_count;
    EXCEPTION WHEN OTHERS THEN
        v_count := 0;
        RAISE NOTICE 'Count query error: %', SQLERRM;
    END;
    
    -- Step 12: Execute main query
    BEGIN
        EXECUTE '
            SELECT COALESCE(json_agg(row_to_json(report_data)), ''[]''::json)
            FROM (' || v_main_query || ') report_data'
        INTO v_result;
    EXCEPTION WHEN OTHERS THEN
        v_result := '[]'::json;
        RAISE NOTICE 'Query execution error: %', SQLERRM;
        RAISE NOTICE 'Query was: %', v_main_query;
    END;
    
    -- Step 13: Build pagination info
    v_pagination_info := json_build_object(
        'total_records', v_count,
        'limit', p_limit,
        'offset', p_offset,
        'current_page', CASE WHEN p_limit > 0 THEN (p_offset / p_limit) + 1 ELSE 1 END,
        'total_pages', CASE WHEN p_limit > 0 THEN CEIL(v_count::DECIMAL / p_limit) ELSE 1 END,
        'has_more', (v_count - p_offset) > p_limit
    );
    
    -- Step 14: Build metadata if requested
    IF p_include_metadata THEN
        -- Get column information for metadata (simplified)
        v_column_info := '[]'::json;
        
        v_metadata := json_build_object(
            'tables', v_all_tables,
            'columns', v_column_info,
            'auto_joins_generated', v_auto_joins != '',
            'joins_used', v_join_clause,
            'filters_applied', p_filters,
            'query_generated', v_main_query,
            'generated_at', CURRENT_TIMESTAMP
        );
    ELSE
        v_metadata := '{}'::json;
    END IF;
    
    -- Step 15: Return final result
    RETURN json_build_object(
        'success', true,
        'pagination', v_pagination_info,
        'metadata', v_metadata,
        'data', COALESCE(v_result, '[]'::json)
    );
END;
$$;


ALTER FUNCTION public.frpt_generate_dynamic_report_v1_0_0(p_tables json, p_filters json, p_columns json, p_joins json, p_group_by json, p_order_by json, p_limit integer, p_offset integer, p_include_metadata boolean) OWNER TO postgres;

--
-- Name: frpt_get_database_tables_info_1_0_0(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frpt_get_database_tables_info_1_0_0() RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_sql TEXT;
    v_row_count BIGINT;
    rec RECORD;
	 v_exclusion_list text[] := ARRAY['v_eligible_count','usertype','session'];
BEGIN
    v_result := '[]'::json;
    
    FOR rec IN (
        SELECT 
	    t.table_schema,
	    t.table_name,
	    t.table_type
	FROM information_schema.tables t
	LEFT JOIN excluded_tables e ON e.table_name = t.table_name
	WHERE t.table_schema NOT IN ('pg_catalog', 'information_schema')
	  AND t.table_type = 'BASE TABLE'
	  AND e.id IS NULL  -- This excludes tables found in excluded_tables
	ORDER BY t.table_schema, t.table_name
    )
    LOOP
        -- Safely get row count for each table
        BEGIN
            EXECUTE format('SELECT COUNT(*) FROM %I.%I', 
                          rec.table_schema, rec.table_name)
            INTO v_row_count;
        EXCEPTION WHEN OTHERS THEN
            v_row_count := NULL; -- or -1 to indicate error
        END;
        
        -- Append to result array
        v_result := jsonb_insert(
            v_result::jsonb,
            '{0}',
            jsonb_build_object(
                'table_schema', rec.table_schema,
                'table_name', rec.table_name,
                'table_type', rec.table_type,
                'row_count', v_row_count
            ),
            true
        );
    END LOOP;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.frpt_get_database_tables_info_1_0_0() OWNER TO postgres;

--
-- Name: frpt_getcolumnuniquevalues(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frpt_getcolumnuniquevalues(p_table_name text, p_column_name text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_search_pattern text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_sql text;
    v_count_sql text;
    v_total_count bigint;
    v_column_type text;
    v_result jsonb;
BEGIN
    -- Get column data type for better formatting
    SELECT data_type INTO v_column_type
    FROM information_schema.columns 
    WHERE table_name = p_table_name 
    AND column_name = p_column_name
    AND table_schema = 'public';
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Table "%s" or column "%s" does not exist', p_table_name, p_column_name),
            'timestamp', now()
        );
    END IF;
    
    -- Build count query for DISTINCT values
    v_count_sql := format(
        'SELECT COUNT(DISTINCT %I) FROM public.%I',
        p_column_name, p_table_name
    );
    
    IF p_search_pattern IS NOT NULL THEN
        v_count_sql := v_count_sql || format(
            ' WHERE CAST(%I AS text) ILIKE ''%%%s%%''',
            p_column_name, REPLACE(p_search_pattern, '''', '''''')
        );
    END IF;
    
    EXECUTE v_count_sql INTO v_total_count;
    
    -- Build main query: First get distinct values, then apply row_number
    v_sql := format(
        'WITH distinct_values AS (' ||
            'SELECT DISTINCT %I as value ' ||
            'FROM public.%I ',
        p_column_name, p_table_name
    );
    
    IF p_search_pattern IS NOT NULL THEN
        v_sql := v_sql || format(
            'WHERE CAST(%I AS text) ILIKE ''%%%s%%'' ',
            p_column_name, REPLACE(p_search_pattern, '''', '''''')
        );
    END IF;
    
    v_sql := v_sql || format(
        '), ' ||
        'numbered_values AS (' ||
            'SELECT value, ROW_NUMBER() OVER (ORDER BY value) as rn ' ||
            'FROM distinct_values ' ||
            'ORDER BY value ' ||
        '), ' ||
        'paginated_values AS (' ||
            'SELECT value, rn ' ||
            'FROM numbered_values ' ||
            'LIMIT %s OFFSET %s' ||
        ') ' ||
        'SELECT jsonb_agg(jsonb_build_object(' ||
            '''id'', rn, ' ||
            '''value'', value, ' ||
            '''label'', CAST(value AS text)' ||
        ') ORDER BY rn) FROM paginated_values',
        p_limit, p_offset
    );
    
    EXECUTE v_sql INTO v_result;
    
    -- If no results, return empty array
    IF v_result IS NULL THEN
        v_result := '[]'::jsonb;
    END IF;
    
    -- Return final JSON structure
    RETURN jsonb_build_object(
        'success', true,
        'data', v_result,
        'pagination', jsonb_build_object(
            'total', v_total_count,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total_count,
            'total_pages', CASE 
                WHEN p_limit > 0 THEN CEIL(v_total_count::float / p_limit)
                ELSE 0 
            END
        ),
        'metadata', jsonb_build_object(
            'table', p_table_name,
            'column', p_column_name,
            'column_type', v_column_type,
            'search_used', p_search_pattern IS NOT NULL,
            'search_pattern', p_search_pattern,
            'retrieved_at', now()
        )
    );
END;
$$;


ALTER FUNCTION public.frpt_getcolumnuniquevalues(p_table_name text, p_column_name text, p_limit integer, p_offset integer, p_search_pattern text) OWNER TO postgres;

--
-- Name: frpt_table_columns_info_v1_0_1(json); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frpt_table_columns_info_v1_0_1(p_table_names json DEFAULT NULL::json) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_table_array TEXT[];
    v_temp_result JSON;
BEGIN
    -- Parse table names from JSON array
    IF p_table_names IS NOT NULL AND p_table_names::text != 'null' THEN
        SELECT array_agg(value::text) 
        INTO v_table_array
        FROM json_array_elements_text(p_table_names);
    END IF;
    
    -- Build the result using a CTE (Common Table Expression) for clarity
    WITH table_list AS (
        SELECT 
            c.table_schema,
            c.table_name
        FROM information_schema.tables c
        WHERE c.table_schema NOT IN ('pg_catalog', 'information_schema')
          AND c.table_type = 'BASE TABLE'
          AND (v_table_array IS NULL OR c.table_name = ANY(v_table_array))
        ORDER BY c.table_name
    )
    SELECT json_agg(
        json_build_object(
            'table_name', tl.table_name,
            'table_schema', tl.table_schema,
            'columns', COALESCE(
                (
                    SELECT json_agg(
                        json_build_object(
                            'column_name', col.column_name,
                            'data_type', col.data_type,
                            'is_nullable', col.is_nullable,
                            'is_primary_key', CASE 
                                WHEN kcu.column_name IS NOT NULL THEN true 
                                ELSE false 
                            END,
                            'is_foreign_key', CASE 
                                WHEN tc.constraint_type = 'FOREIGN KEY' THEN true 
                                ELSE false 
                            END,
                            'foreign_table', ccu.table_name,
                            'foreign_column', ccu.column_name
                        )
                        ORDER BY col.ordinal_position
                    )
                    FROM information_schema.columns col
                    LEFT JOIN information_schema.key_column_usage kcu 
                        ON col.table_schema = kcu.table_schema
                        AND col.table_name = kcu.table_name 
                        AND col.column_name = kcu.column_name
                    LEFT JOIN information_schema.table_constraints tc
                        ON kcu.constraint_schema = tc.constraint_schema
                        AND kcu.constraint_name = tc.constraint_name
                        AND tc.constraint_type IN ('PRIMARY KEY', 'FOREIGN KEY')
                    LEFT JOIN information_schema.constraint_column_usage ccu
                        ON tc.constraint_schema = ccu.constraint_schema
                        AND tc.constraint_name = ccu.constraint_name
                    WHERE col.table_schema = tl.table_schema
                    AND col.table_name = tl.table_name
                    GROUP BY col.table_schema, col.table_name
                ),
                '[]'::json
            )
        )
        ORDER BY tl.table_name
    )
    INTO v_result
    FROM table_list tl;
    
    RETURN COALESCE(v_result, '[]'::json);
END;
$$;


ALTER FUNCTION public.frpt_table_columns_info_v1_0_1(p_table_names json) OWNER TO postgres;

--
-- Name: fruleactionscurd(character varying, character varying, character varying, character varying, jsonb, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fruleactionscurd(p_action character varying, p_actionid character varying DEFAULT NULL::character varying, p_ruleid character varying DEFAULT NULL::character varying, p_action_type character varying DEFAULT NULL::character varying, p_action_value jsonb DEFAULT NULL::jsonb, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_actionid VARCHAR(5);
    v_action_count INTEGER;
    v_rule_count INTEGER;
    v_return_message TEXT;
    v_action_value_text TEXT;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_actionid := TRIM(p_actionid);
    p_ruleid := TRIM(p_ruleid);
    p_action_type := TRIM(p_action_type);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'fruleactionsCURD called with action: ' || p_action,
        jsonb_build_object(
            'actionid', p_actionid,
            'ruleid', p_ruleid,
            'action_type', p_action_type,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT', 'LIST_BY_RULE') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, SELECT, or LIST_BY_RULE';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for INSERT';
            END IF;
            
            IF p_action_type IS NULL OR p_action_type = '' THEN
                RAISE EXCEPTION 'action_type is required for INSERT';
            END IF;
            
            IF p_action_value IS NULL THEN
                RAISE EXCEPTION 'action_value (JSONB) is required for INSERT';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
            -- Validate action_value is valid JSONB
            BEGIN
                v_action_value_text := p_action_value::TEXT;
            EXCEPTION WHEN OTHERS THEN
                RAISE EXCEPTION 'Invalid JSONB format for action_value';
            END;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_action_count
            FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            IF v_action_count = 0 THEN
                RAISE EXCEPTION 'actionid "%" not found', p_actionid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(ra) INTO v_old_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            -- Check if new ruleid exists (if provided)
            IF p_ruleid IS NOT NULL AND p_ruleid != '' THEN
                SELECT COUNT(*) INTO v_rule_count
                FROM public.rulesmaster
                WHERE ruleid = p_ruleid;
                
                IF v_rule_count = 0 THEN
                    RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
                END IF;
            END IF;
            
            -- Validate action_value if provided
            IF p_action_value IS NOT NULL THEN
                BEGIN
                    v_action_value_text := p_action_value::TEXT;
                EXCEPTION WHEN OTHERS THEN
                    RAISE EXCEPTION 'Invalid JSONB format for action_value';
                END;
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_action_count
            FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            IF v_action_count = 0 THEN
                RAISE EXCEPTION 'actionid "%" not found', p_actionid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(ra) INTO v_old_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_actionid IS NULL OR p_actionid = '' THEN
                RAISE EXCEPTION 'actionid is required for SELECT';
            END IF;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Validate LIST_BY_RULE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for LIST_BY_RULE';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new rule action
            INSERT INTO public.ruleactions (
                ruleid,
                action_type,
                action_value
            ) VALUES (
                p_ruleid,
                p_action_type,
                p_action_value
            )
            RETURNING actionid INTO v_existing_actionid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = v_existing_actionid;
            
            v_return_message := 'Rule action created successfully';
            v_audit_description := 'Created new rule action for rule: ' || p_ruleid;
            
        WHEN 'UPDATE' THEN
            -- Update existing rule action
            UPDATE public.ruleactions
            SET 
                ruleid = COALESCE(NULLIF(p_ruleid, ''), ruleid),
                action_type = COALESCE(NULLIF(p_action_type, ''), action_type),
                action_value = COALESCE(p_action_value, action_value),
                updated_at = CURRENT_TIMESTAMP
            WHERE actionid = p_actionid
            RETURNING actionid INTO v_existing_actionid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            v_return_message := 'Rule action updated successfully';
            v_audit_description := 'Updated rule action: ' || p_actionid;
            
        WHEN 'DELETE' THEN
            -- Delete rule action
            DELETE FROM public.ruleactions
            WHERE actionid = p_actionid;
            
            v_return_message := 'Rule action deleted successfully';
            v_audit_description := 'Deleted rule action: ' || p_actionid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific rule action
            SELECT jsonb_build_object(
                'actionid', ra.actionid,
                'ruleid', ra.ruleid,
                'action_type', ra.action_type,
                'action_value', ra.action_value,
                'created_at', ra.created_at,
                'updated_at', ra.updated_at
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE actionid = p_actionid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Rule action with ID "%" not found', p_actionid;
            END IF;
            
            v_return_message := 'Rule action retrieved successfully';
            v_audit_description := 'Retrieved rule action: ' || p_actionid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all rule actions
            SELECT jsonb_agg(
                jsonb_build_object(
                    'actionid', ra.actionid,
                    'ruleid', ra.ruleid,
                    'action_type', ra.action_type,
                    'action_value', ra.action_value,
                    'created_at', ra.created_at,
                    'updated_at', ra.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleactions ra
            ORDER BY ra.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule actions listed successfully';
            v_audit_description := 'Listed all rule actions';
            v_old_record := NULL;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Get all actions for a specific rule
            SELECT jsonb_agg(
                jsonb_build_object(
                    'actionid', ra.actionid,
                    'ruleid', ra.ruleid,
                    'action_type', ra.action_type,
                    'action_value', ra.action_value,
                    'created_at', ra.created_at,
                    'updated_at', ra.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleactions ra
            WHERE ra.ruleid = p_ruleid
            ORDER BY ra.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule actions listed for rule: ' || p_ruleid;
            v_audit_description := 'Listed actions for rule: ' || p_ruleid;
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST operations)
    IF p_action NOT IN ('LIST', 'LIST_BY_RULE') THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULEACTIONS',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'actionid', COALESCE(p_actionid, v_existing_actionid),
                'ruleid', p_ruleid
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action IN ('LIST', 'LIST_BY_RULE') THEN v_new_record
            ELSE jsonb_build_object('ruleaction', v_new_record)
        END,
        'actionid', COALESCE(p_actionid, v_existing_actionid),
        'ruleid', CASE 
            WHEN p_action = 'LIST_BY_RULE' THEN p_ruleid
            WHEN p_action IN ('INSERT', 'UPDATE') THEN COALESCE(p_ruleid, 
                (v_new_record->>'ruleid')::VARCHAR)
            ELSE NULL
        END
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN foreign_key_violation THEN
        v_error_message := 'Foreign key violation. The referenced rule does not exist.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Ensure the ruleid exists in rulesmaster table.';
        
    WHEN invalid_text_representation THEN
        v_error_message := 'Invalid JSONB format for action_value.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Provide valid JSON format for action_value.';
        
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
    -- Log error to audit trail
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'RULEACTIONS',
        'ERROR',
        'Error in fruleactionsCURD: ' || v_error_message,
        jsonb_build_object(
            'action', p_action,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'actionid', p_actionid,
            'ruleid', p_ruleid
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Build error response
    v_result := jsonb_build_object(
        'success', false,
        'message', 'Operation failed: ' || v_error_message,
        'error_detail', v_error_detail,
        'error_hint', v_error_hint,
        'data', null
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fruleactionscurd(p_action character varying, p_actionid character varying, p_ruleid character varying, p_action_type character varying, p_action_value jsonb, p_user_id character varying, p_ip_address inet, p_user_agent text) OWNER TO postgres;

--
-- Name: FUNCTION fruleactionscurd(p_action character varying, p_actionid character varying, p_ruleid character varying, p_action_type character varying, p_action_value jsonb, p_user_id character varying, p_ip_address inet, p_user_agent text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fruleactionscurd(p_action character varying, p_actionid character varying, p_ruleid character varying, p_action_type character varying, p_action_value jsonb, p_user_id character varying, p_ip_address inet, p_user_agent text) IS 'CRUD operations for ruleactions table with audit logging';


--
-- Name: fruleconditionscurd(character varying, character varying, character varying, character varying, character varying, text, character varying, text, integer, boolean, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fruleconditionscurd(p_action character varying, p_conditionid character varying DEFAULT NULL::character varying, p_ruleid character varying DEFAULT NULL::character varying, p_field_name character varying DEFAULT NULL::character varying, p_operator character varying DEFAULT NULL::character varying, p_value text DEFAULT NULL::text, p_data_type character varying DEFAULT NULL::character varying, p_validation_message text DEFAULT NULL::text, p_condition_order integer DEFAULT NULL::integer, p_is_active boolean DEFAULT NULL::boolean, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_conditionid VARCHAR(11);
    v_condition_count INTEGER;
    v_rule_count INTEGER;
    v_return_message TEXT;
    v_validated_value TEXT;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := UPPER(TRIM(p_action));
    p_conditionid := TRIM(p_conditionid);
    p_ruleid := TRIM(p_ruleid);
    p_field_name := TRIM(p_field_name);
    p_operator := UPPER(TRIM(p_operator));
    p_value := TRIM(p_value);
    p_data_type := LOWER(TRIM(p_data_type));
    p_validation_message := TRIM(p_validation_message);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'fruleconditionsCURD called with action: ' || p_action,
        jsonb_build_object(
            'conditionid', p_conditionid,
            'ruleid', p_ruleid,
            'field_name', p_field_name,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT', 'LIST_BY_RULE', 'VALIDATE') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, SELECT, LIST_BY_RULE, or VALIDATE';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for INSERT';
            END IF;
            
            IF p_field_name IS NULL OR p_field_name = '' THEN
                RAISE EXCEPTION 'field_name is required for INSERT';
            END IF;
            
            IF p_operator IS NULL OR p_operator = '' THEN
                RAISE EXCEPTION 'operator is required for INSERT';
            END IF;
            
            IF p_value IS NULL OR p_value = '' THEN
                RAISE EXCEPTION 'value is required for INSERT';
            END IF;
            
            IF p_data_type IS NULL OR p_data_type = '' THEN
                RAISE EXCEPTION 'data_type is required for INSERT';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
            -- Validate operator against allowed values
            IF p_operator NOT IN ('EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 
                                  'GREATER_EQUAL', 'LESS_EQUAL', 'BETWEEN', 'IN', 
                                  'CONTAINS', 'STARTS_WITH', 'ENDS_WITH', 'REGEX') THEN
                RAISE EXCEPTION 'Invalid operator. Must be one of: EQUALS, NOT_EQUALS, GREATER_THAN, LESS_THAN, GREATER_EQUAL, LESS_EQUAL, BETWEEN, IN, CONTAINS, STARTS_WITH, ENDS_WITH, REGEX';
            END IF;
            
            -- Validate data_type against allowed values
            IF p_data_type NOT IN ('string', 'integer', 'boolean', 'date', 'decimal', 'timestamp') THEN
                RAISE EXCEPTION 'Invalid data_type. Must be one of: string, integer, boolean, date, decimal, timestamp';
            END IF;
            
            -- Validate value based on data_type - WITH PROPER ERROR HANDLING
            BEGIN
                v_validated_value := public.fRuleCondtionValidate_condition_value(p_value, p_data_type, p_operator);
            EXCEPTION
                WHEN undefined_function THEN
                    RAISE EXCEPTION 'Validation function fRuleCondtionValidate_condition_value not found. Please create this function first.';
            END;
            
            IF v_validated_value IS NULL THEN
                RAISE EXCEPTION 'Invalid value for data_type "%". Value: "%"', p_data_type, p_value;
            END IF;
            
            -- Set default condition_order if not provided
            IF p_condition_order IS NULL THEN
                SELECT COALESCE(MAX(condition_order), 0) + 1 
                INTO p_condition_order
                FROM public.ruleconditions 
                WHERE ruleid = p_ruleid;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_conditionid IS NULL OR p_conditionid = '' THEN
                RAISE EXCEPTION 'conditionid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_condition_count
            FROM public.ruleconditions
            WHERE conditionid = p_conditionid;
            
            IF v_condition_count = 0 THEN
                RAISE EXCEPTION 'conditionid "%" not found', p_conditionid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(rc) INTO v_old_record
            FROM public.ruleconditions rc
            WHERE conditionid = p_conditionid;
            
            -- Check if new ruleid exists (if provided)
            IF p_ruleid IS NOT NULL AND p_ruleid != '' THEN
                SELECT COUNT(*) INTO v_rule_count
                FROM public.rulesmaster
                WHERE ruleid = p_ruleid;
                
                IF v_rule_count = 0 THEN
                    RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
                END IF;
            END IF;
            
            -- Validate operator if provided
            IF p_operator IS NOT NULL AND p_operator != '' THEN
                IF p_operator NOT IN ('EQUALS', 'NOT_EQUALS', 'GREATER_THAN', 'LESS_THAN', 
                                      'GREATER_EQUAL', 'LESS_EQUAL', 'BETWEEN', 'IN', 
                                      'CONTAINS', 'STARTS_WITH', 'ENDS_WITH', 'REGEX') THEN
                    RAISE EXCEPTION 'Invalid operator. Must be one of: EQUALS, NOT_EQUALS, GREATER_THAN, LESS_THAN, GREATER_EQUAL, LESS_EQUAL, BETWEEN, IN, CONTAINS, STARTS_WITH, ENDS_WITH, REGEX';
                END IF;
            END IF;
            
            -- Validate data_type if provided
            IF p_data_type IS NOT NULL AND p_data_type != '' THEN
                IF p_data_type NOT IN ('string', 'integer', 'boolean', 'date', 'decimal', 'timestamp') THEN
                    RAISE EXCEPTION 'Invalid data_type. Must be one of: string, integer, boolean, date, decimal, timestamp';
                END IF;
            END IF;
            
            -- Validate value if provided - WITH PROPER ERROR HANDLING
            IF p_value IS NOT NULL AND p_value != '' THEN
                BEGIN
                    v_validated_value := public.fRuleCondtionValidate_condition_value(
                        p_value, 
                        COALESCE(p_data_type, (v_old_record->>'data_type')),
                        COALESCE(p_operator, (v_old_record->>'operator'))
                    );
                EXCEPTION
                    WHEN undefined_function THEN
                        RAISE EXCEPTION 'Validation function fRuleCondtionValidate_condition_value not found. Please create this function first.';
                END;
                
                IF v_validated_value IS NULL THEN
                    RAISE EXCEPTION 'Invalid value for the specified data_type';
                END IF;
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_conditionid IS NULL OR p_conditionid = '' THEN
                RAISE EXCEPTION 'conditionid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_condition_count
            FROM public.ruleconditions
            WHERE conditionid = p_conditionid;
            
            IF v_condition_count = 0 THEN
                RAISE EXCEPTION 'conditionid "%" not found', p_conditionid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(rc) INTO v_old_record
            FROM public.ruleconditions rc
            WHERE conditionid = p_conditionid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_conditionid IS NULL OR p_conditionid = '' THEN
                RAISE EXCEPTION 'conditionid is required for SELECT';
            END IF;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Validate LIST_BY_RULE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for LIST_BY_RULE';
            END IF;
            
            -- Check if parent rule exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'Parent rule with ruleid "%" does not exist', p_ruleid;
            END IF;
            
        WHEN 'VALIDATE' THEN
            -- Validate parameters for validation
            IF p_operator IS NULL OR p_operator = '' THEN
                RAISE EXCEPTION 'operator is required for VALIDATE';
            END IF;
            
            IF p_value IS NULL OR p_value = '' THEN
                RAISE EXCEPTION 'value is required for VALIDATE';
            END IF;
            
            IF p_data_type IS NULL OR p_data_type = '' THEN
                RAISE EXCEPTION 'data_type is required for VALIDATE';
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new rule condition
            INSERT INTO public.ruleconditions (
                ruleid,
                field_name,
                operator,
                value,
                data_type,
                validation_message,
                condition_order,
                is_active
            ) VALUES (
                p_ruleid,
                p_field_name,
                p_operator,
                v_validated_value,
                p_data_type,
                p_validation_message,
                COALESCE(p_condition_order, 0),
                COALESCE(p_is_active, true)
            )
            RETURNING conditionid INTO v_existing_conditionid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'conditionid', rc.conditionid,
                'ruleid', rc.ruleid,
                'field_name', rc.field_name,
                'operator', rc.operator,
                'value', rc.value,
                'data_type', rc.data_type,
                'validation_message', rc.validation_message,
                'condition_order', rc.condition_order,
                'is_active', rc.is_active,
                'created_at', rc.created_at,
                'updated_at', rc.updated_at
            ) INTO v_new_record
            FROM public.ruleconditions rc
            WHERE conditionid = v_existing_conditionid;
            
            v_return_message := 'Rule condition created successfully';
            v_audit_description := 'Created new condition for rule: ' || p_ruleid;
            
        WHEN 'UPDATE' THEN
            -- Update existing rule condition
            UPDATE public.ruleconditions
            SET 
                ruleid = COALESCE(NULLIF(p_ruleid, ''), ruleid),
                field_name = COALESCE(NULLIF(p_field_name, ''), field_name),
                operator = COALESCE(NULLIF(p_operator, ''), operator),
                value = COALESCE(v_validated_value, value),
                data_type = COALESCE(NULLIF(p_data_type, ''), data_type),
                validation_message = COALESCE(p_validation_message, validation_message),
                condition_order = COALESCE(p_condition_order, condition_order),
                is_active = COALESCE(p_is_active, is_active),
                updated_at = CURRENT_TIMESTAMP
            WHERE conditionid = p_conditionid
            RETURNING conditionid INTO v_existing_conditionid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'conditionid', rc.conditionid,
                'ruleid', rc.ruleid,
                'field_name', rc.field_name,
                'operator', rc.operator,
                'value', rc.value,
                'data_type', rc.data_type,
                'validation_message', rc.validation_message,
                'condition_order', rc.condition_order,
                'is_active', rc.is_active,
                'created_at', rc.created_at,
                'updated_at', rc.updated_at
            ) INTO v_new_record
            FROM public.ruleconditions rc
            WHERE conditionid = p_conditionid;
            
            v_return_message := 'Rule condition updated successfully';
            v_audit_description := 'Updated rule condition: ' || p_conditionid;
            
        WHEN 'DELETE' THEN
            -- Delete rule condition
            DELETE FROM public.ruleconditions
            WHERE conditionid = p_conditionid;
            
            v_return_message := 'Rule condition deleted successfully';
            v_audit_description := 'Deleted rule condition: ' || p_conditionid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific rule condition
            SELECT jsonb_build_object(
                'conditionid', rc.conditionid,
                'ruleid', rc.ruleid,
                'field_name', rc.field_name,
                'operator', rc.operator,
                'value', rc.value,
                'data_type', rc.data_type,
                'validation_message', rc.validation_message,
                'condition_order', rc.condition_order,
                'is_active', rc.is_active,
                'created_at', rc.created_at,
                'updated_at', rc.updated_at
            ) INTO v_new_record
            FROM public.ruleconditions rc
            WHERE conditionid = p_conditionid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Rule condition with ID "%" not found', p_conditionid;
            END IF;
            
            v_return_message := 'Rule condition retrieved successfully';
            v_audit_description := 'Retrieved rule condition: ' || p_conditionid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all rule conditions
            SELECT jsonb_agg(
                jsonb_build_object(
                    'conditionid', rc.conditionid,
                    'ruleid', rc.ruleid,
                    'field_name', rc.field_name,
                    'operator', rc.operator,
                    'value', rc.value,
                    'data_type', rc.data_type,
                    'validation_message', rc.validation_message,
                    'condition_order', rc.condition_order,
                    'is_active', rc.is_active,
                    'created_at', rc.created_at,
                    'updated_at', rc.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleconditions rc
            WHERE (p_is_active IS NULL OR rc.is_active = p_is_active)
            ORDER BY rc.ruleid, rc.condition_order, rc.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule conditions listed successfully';
            v_audit_description := 'Listed all rule conditions';
            v_old_record := NULL;
            
        WHEN 'LIST_BY_RULE' THEN
            -- Get all conditions for a specific rule
            SELECT jsonb_agg(
                jsonb_build_object(
                    'conditionid', rc.conditionid,
                    'ruleid', rc.ruleid,
                    'field_name', rc.field_name,
                    'operator', rc.operator,
                    'value', rc.value,
                    'data_type', rc.data_type,
                    'validation_message', rc.validation_message,
                    'condition_order', rc.condition_order,
                    'is_active', rc.is_active,
                    'created_at', rc.created_at,
                    'updated_at', rc.updated_at
                )
            ) INTO v_new_record
            FROM public.ruleconditions rc
            WHERE rc.ruleid = p_ruleid
            AND (p_is_active IS NULL OR rc.is_active = p_is_active)
            ORDER BY rc.condition_order, rc.created_at;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rule conditions listed for rule: ' || p_ruleid;
            v_audit_description := 'Listed conditions for rule: ' || p_ruleid;
            v_old_record := NULL;
            
        WHEN 'VALIDATE' THEN
            -- Validate condition value - WITH PROPER ERROR HANDLING
            BEGIN
                v_validated_value := public.fRuleCondtionValidate_condition_value(p_value, p_data_type, p_operator);
            EXCEPTION
                WHEN undefined_function THEN
                    v_result := jsonb_build_object(
                        'success', false,
                        'message', 'Validation function not found',
                        'data', jsonb_build_object(
                            'value', p_value,
                            'data_type', p_data_type,
                            'operator', p_operator,
                            'is_valid', false,
                            'error', 'Validation function fRuleCondtionValidate_condition_value not found'
                        )
                    );
                    RETURN v_result;
            END;
            
            IF v_validated_value IS NULL THEN
                v_result := jsonb_build_object(
                    'success', false,
                    'message', 'Validation failed',
                    'data', jsonb_build_object(
                        'value', p_value,
                        'data_type', p_data_type,
                        'operator', p_operator,
                        'is_valid', false,
                        'error', 'Invalid value for the specified data_type and operator'
                    )
                );
            ELSE
                v_result := jsonb_build_object(
                    'success', true,
                    'message', 'Validation successful',
                    'data', jsonb_build_object(
                        'original_value', p_value,
                        'validated_value', v_validated_value,
                        'data_type', p_data_type,
                        'operator', p_operator,
                        'is_valid', true
                    )
                );
            END IF;
            
            RETURN v_result;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST operations)
    IF p_action NOT IN ('LIST', 'LIST_BY_RULE', 'VALIDATE') THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULECONDITIONS',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'conditionid', COALESCE(p_conditionid, v_existing_conditionid),
                'ruleid', p_ruleid
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action IN ('LIST', 'LIST_BY_RULE') THEN v_new_record
            ELSE jsonb_build_object('condition', v_new_record)
        END,
        'conditionid', COALESCE(p_conditionid, v_existing_conditionid),
        'ruleid', CASE 
            WHEN p_action = 'LIST_BY_RULE' THEN p_ruleid
            WHEN p_action IN ('INSERT', 'UPDATE') THEN COALESCE(p_ruleid, 
                (v_new_record->>'ruleid')::VARCHAR)
            ELSE NULL
        END
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN foreign_key_violation THEN
        v_error_message := 'Foreign key violation. The referenced rule does not exist.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Ensure the ruleid exists in rulesmaster table.';
        
    WHEN check_violation THEN
        v_error_message := 'Check constraint violation. Invalid operator or data_type.';
        v_error_detail := SQLERRM;
        v_error_hint := 'Check allowed values for operator and data_type.';
        
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
    -- Log error to audit trail
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'RULECONDITIONS',
        'ERROR',
        'Error in fruleconditionsCURD: ' || v_error_message,
        jsonb_build_object(
            'action', p_action,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'conditionid', p_conditionid,
            'ruleid', p_ruleid
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Build error response
    v_result := jsonb_build_object(
        'success', false,
        'message', 'Operation failed: ' || v_error_message,
        'error_detail', v_error_detail,
        'error_hint', v_error_hint,
        'data', null
    );
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION public.fruleconditionscurd(p_action character varying, p_conditionid character varying, p_ruleid character varying, p_field_name character varying, p_operator character varying, p_value text, p_data_type character varying, p_validation_message text, p_condition_order integer, p_is_active boolean, p_user_id character varying, p_ip_address inet, p_user_agent text) OWNER TO postgres;

--
-- Name: FUNCTION fruleconditionscurd(p_action character varying, p_conditionid character varying, p_ruleid character varying, p_field_name character varying, p_operator character varying, p_value text, p_data_type character varying, p_validation_message text, p_condition_order integer, p_is_active boolean, p_user_id character varying, p_ip_address inet, p_user_agent text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fruleconditionscurd(p_action character varying, p_conditionid character varying, p_ruleid character varying, p_field_name character varying, p_operator character varying, p_value text, p_data_type character varying, p_validation_message text, p_condition_order integer, p_is_active boolean, p_user_id character varying, p_ip_address inet, p_user_agent text) IS 'CRUD operations for ruleconditions table with audit logging';


--
-- Name: frulecondtionvalidate_condition_value(text, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frulecondtionvalidate_condition_value(p_value text, p_data_type character varying, p_operator character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_validated_value TEXT;
    v_array_values TEXT[];
    v_min_value NUMERIC;
    v_max_value NUMERIC;
BEGIN
    -- Handle empty values
    IF p_value IS NULL OR p_value = '' THEN
        RETURN NULL;
    END IF;
    
    -- Validate based on data_type
    CASE p_data_type
        WHEN 'string' THEN
            -- String validation
            v_validated_value := p_value;
            
        WHEN 'integer' THEN
            -- Integer validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        v_min_value := v_array_values[1]::INTEGER;
                        v_max_value := v_array_values[2]::INTEGER;
                        IF v_min_value <= v_max_value THEN
                            v_validated_value := p_value;
                        END IF;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::INTEGER::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single integer value
                    v_validated_value := p_value::INTEGER::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'decimal' THEN
            -- Decimal validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        v_min_value := v_array_values[1]::NUMERIC;
                        v_max_value := v_array_values[2]::NUMERIC;
                        IF v_min_value <= v_max_value THEN
                            v_validated_value := p_value;
                        END IF;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::NUMERIC::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single decimal value
                    v_validated_value := p_value::NUMERIC::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'boolean' THEN
            -- Boolean validation
            IF p_value IN ('true', 'false', 'TRUE', 'FALSE', '1', '0') THEN
                v_validated_value := LOWER(p_value);
            ELSE
                RETURN NULL;
            END IF;
            
        WHEN 'date' THEN
            -- Date validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        -- Validate both dates
                        v_validated_value := 
                            v_array_values[1]::DATE::TEXT || ',' || 
                            v_array_values[2]::DATE::TEXT;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::DATE::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single date value
                    v_validated_value := p_value::DATE::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        WHEN 'timestamp' THEN
            -- Timestamp validation
            BEGIN
                IF p_operator = 'BETWEEN' THEN
                    -- Parse range for BETWEEN operator
                    v_array_values := string_to_array(p_value, ',');
                    IF array_length(v_array_values, 1) = 2 THEN
                        -- Validate both timestamps
                        v_validated_value := 
                            v_array_values[1]::TIMESTAMP::TEXT || ',' || 
                            v_array_values[2]::TIMESTAMP::TEXT;
                    END IF;
                ELSIF p_operator = 'IN' THEN
                    -- Parse list for IN operator
                    v_array_values := string_to_array(p_value, ',');
                    FOR i IN 1..array_length(v_array_values, 1) LOOP
                        BEGIN
                            v_array_values[i] := v_array_values[i]::TIMESTAMP::TEXT;
                        EXCEPTION WHEN OTHERS THEN
                            RETURN NULL;
                        END;
                    END LOOP;
                    v_validated_value := array_to_string(v_array_values, ',');
                ELSE
                    -- Single timestamp value
                    v_validated_value := p_value::TIMESTAMP::TEXT;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                RETURN NULL;
            END;
            
        ELSE
            RETURN NULL;
    END CASE;
    
    RETURN v_validated_value;
END;
$$;


ALTER FUNCTION public.frulecondtionvalidate_condition_value(p_value text, p_data_type character varying, p_operator character varying) OWNER TO postgres;

--
-- Name: frulesmastercurd(character varying, character varying, character varying, character varying, character varying, text, integer, boolean, date, date, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.frulesmastercurd(p_action character varying, p_ruleid character varying DEFAULT NULL::character varying, p_rulename character varying DEFAULT NULL::character varying, p_ruletype character varying DEFAULT NULL::character varying, p_appliesto character varying DEFAULT NULL::character varying, p_description text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_isactive boolean DEFAULT NULL::boolean, p_startdate date DEFAULT NULL::date, p_enddate date DEFAULT NULL::date, p_user_id character varying DEFAULT NULL::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_result JSONB;
    v_old_record JSONB;
    v_new_record JSONB;
    v_audit_description TEXT;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_hint TEXT;
    v_existing_ruleid VARCHAR(5);
    v_rule_count INTEGER;
    v_return_message TEXT;
    v_allowed_ruletypes TEXT[] := ARRAY['VALIDATION', 'CALCULATION', 'BUSINESS', 'SECURITY', 'WORKFLOW', 'OTHER'];
    v_valid_ruletype BOOLEAN;
BEGIN
    -- Initialize result
    v_result := '{"success": false, "message": "Unknown error", "data": null}'::JSONB;
    
    -- Trim and validate inputs
    p_action := TRIM(p_action);
    p_ruleid := TRIM(p_ruleid);
    p_rulename := TRIM(p_rulename);
    p_ruletype := TRIM(p_ruletype);
    p_appliesto := TRIM(p_appliesto);
    p_description := TRIM(p_description);
    
    -- Log function call for debugging
    INSERT INTO public.audit_trail (
        entity_type, 
        action_type, 
        description, 
        data, 
        user_id, 
        ip_address, 
        user_agent
    ) VALUES (
        'FUNCTION_CALL',
        'EXECUTE',
        'frulesmasterCURD called with action: ' || p_action,
        jsonb_build_object(
            'ruleid', p_ruleid,
            'rulename', p_rulename,
            'ruletype', p_ruletype,
            'action', p_action
        ),
        p_user_id,
        p_ip_address,
        p_user_agent
    );
    
    -- Validate action parameter
    IF p_action NOT IN ('INSERT', 'UPDATE', 'DELETE', 'LIST', 'SELECT') THEN
        RAISE EXCEPTION 'Invalid action. Must be INSERT, UPDATE, DELETE, LIST, or SELECT';
    END IF;
    
    -- Validate required parameters based on action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Validate mandatory fields for INSERT
            IF p_rulename IS NULL OR p_rulename = '' THEN
                RAISE EXCEPTION 'rulename is required for INSERT';
            END IF;
            
            IF p_ruletype IS NULL OR p_ruletype = '' THEN
                RAISE EXCEPTION 'ruletype is required for INSERT';
            END IF;
            
            IF p_appliesto IS NULL OR p_appliesto = '' THEN
                RAISE EXCEPTION 'appliesto is required for INSERT';
            END IF;
            
            IF p_priority IS NULL THEN
                RAISE EXCEPTION 'priority is required for INSERT';
            END IF;
            
            IF p_startdate IS NULL THEN
                RAISE EXCEPTION 'startdate is required for INSERT';
            END IF;
            
            -- Validate ruletype - either in allowed list or pass through
            -- Comment out strict validation if you want to allow any ruletype
            /*
            IF NOT (p_ruletype = ANY(v_allowed_ruletypes)) THEN
                RAISE EXCEPTION 'ruletype must be one of: %, %, %, %, %, or %', 
                    v_allowed_ruletypes[1], v_allowed_ruletypes[2], v_allowed_ruletypes[3],
                    v_allowed_ruletypes[4], v_allowed_ruletypes[5], v_allowed_ruletypes[6];
            END IF;
            */
            
            -- Validate priority range
            IF p_priority < 1 OR p_priority > 999 THEN
                RAISE EXCEPTION 'priority must be between 1 and 999';
            END IF;
            
            -- Validate date range
            IF p_enddate IS NOT NULL AND p_startdate > p_enddate THEN
                RAISE EXCEPTION 'startdate cannot be after enddate';
            END IF;
            
            -- Check for duplicate rulename
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE LOWER(rulename) = LOWER(p_rulename);
            
            IF v_rule_count > 0 THEN
                RAISE EXCEPTION 'rulename "%" already exists', p_rulename;
            END IF;
            
        WHEN 'UPDATE' THEN
            -- Validate UPDATE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for UPDATE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'ruleid "%" not found', p_ruleid;
            END IF;
            
            -- Get old record for audit
            SELECT row_to_json(rm) INTO v_old_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            -- Validate ruletype if provided (commented out for flexibility)
            /*
            IF p_ruletype IS NOT NULL AND p_ruletype != '' THEN
                IF NOT (p_ruletype = ANY(v_allowed_ruletypes)) THEN
                    RAISE EXCEPTION 'ruletype must be one of: %, %, %, %, %, or %', 
                        v_allowed_ruletypes[1], v_allowed_ruletypes[2], v_allowed_ruletypes[3],
                        v_allowed_ruletypes[4], v_allowed_ruletypes[5], v_allowed_ruletypes[6];
                END IF;
            END IF;
            */
            
            -- Validate priority range if provided
            IF p_priority IS NOT NULL THEN
                IF p_priority < 1 OR p_priority > 999 THEN
                    RAISE EXCEPTION 'priority must be between 1 and 999';
                END IF;
            END IF;
            
            -- Validate date logic
            IF (p_startdate IS NOT NULL AND p_enddate IS NOT NULL) AND (p_startdate > p_enddate) THEN
                RAISE EXCEPTION 'startdate cannot be after enddate';
            END IF;
            
        WHEN 'DELETE' THEN
            -- Validate DELETE parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for DELETE';
            END IF;
            
            -- Check if record exists
            SELECT COUNT(*) INTO v_rule_count
            FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            IF v_rule_count = 0 THEN
                RAISE EXCEPTION 'ruleid "%" not found', p_ruleid;
            END IF;
            
            -- Get record for audit
            SELECT row_to_json(rm) INTO v_old_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
        WHEN 'SELECT' THEN
            -- Validate SELECT parameters
            IF p_ruleid IS NULL OR p_ruleid = '' THEN
                RAISE EXCEPTION 'ruleid is required for SELECT';
            END IF;
            
    END CASE;
    
    -- Execute the requested action
    CASE p_action
        WHEN 'INSERT' THEN
            -- Insert new rule
            INSERT INTO public.rulesmaster (
                rulename,
                ruletype,
                appliesto,
                description,
                priority,
                isactive,
                startdate,
                enddate
            ) VALUES (
                p_rulename,
                p_ruletype,
                p_appliesto,
                p_description,
                p_priority,
                COALESCE(p_isactive, true),
                p_startdate,
                p_enddate
            )
            RETURNING ruleid INTO v_existing_ruleid;
            
            -- Get the newly inserted record
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = v_existing_ruleid;
            
            v_return_message := 'Rule created successfully';
            v_audit_description := 'Created new rule: ' || p_rulename;
            
        WHEN 'UPDATE' THEN
            -- Update existing rule
            UPDATE public.rulesmaster
            SET 
                rulename = COALESCE(p_rulename, rulename),
                ruletype = COALESCE(NULLIF(p_ruletype, ''), ruletype),
                appliesto = COALESCE(NULLIF(p_appliesto, ''), appliesto),
                description = COALESCE(p_description, description),
                priority = COALESCE(p_priority, priority),
                isactive = COALESCE(p_isactive, isactive),
                startdate = COALESCE(p_startdate, startdate),
                enddate = p_enddate, -- Allow NULL enddate
                updated_at = CURRENT_TIMESTAMP
            WHERE ruleid = p_ruleid
            RETURNING ruleid INTO v_existing_ruleid;
            
            -- Get the updated record
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            v_return_message := 'Rule updated successfully';
            v_audit_description := 'Updated rule: ' || p_ruleid;
            
        WHEN 'DELETE' THEN
            -- Delete rule
            DELETE FROM public.rulesmaster
            WHERE ruleid = p_ruleid;
            
            v_return_message := 'Rule deleted successfully';
            v_audit_description := 'Deleted rule: ' || p_ruleid;
            v_new_record := NULL;
            
        WHEN 'SELECT' THEN
            -- Select specific rule
            SELECT jsonb_build_object(
                'ruleid', rm.ruleid,
                'rulename', rm.rulename,
                'ruletype', rm.ruletype,
                'appliesto', rm.appliesto,
                'description', rm.description,
                'priority', rm.priority,
                'isactive', rm.isactive,
                'startdate', rm.startdate,
                'enddate', rm.enddate,
                'created_at', rm.created_at,
                'updated_at', rm.updated_at
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE ruleid = p_ruleid;
            
            IF v_new_record IS NULL THEN
                RAISE EXCEPTION 'Rule with ID "%" not found', p_ruleid;
            END IF;
            
            v_return_message := 'Rule retrieved successfully';
            v_audit_description := 'Retrieved rule: ' || p_ruleid;
            v_old_record := NULL;
            
        WHEN 'LIST' THEN
            -- Get all rules with optional filtering
            SELECT jsonb_agg(
                jsonb_build_object(
                    'ruleid', rm.ruleid,
                    'rulename', rm.rulename,
                    'ruletype', rm.ruletype,
                    'appliesto', rm.appliesto,
                    'description', rm.description,
                    'priority', rm.priority,
                    'isactive', rm.isactive,
                    'startdate', rm.startdate,
                    'enddate', rm.enddate,
                    'created_at', rm.created_at,
                    'updated_at', rm.updated_at
                )
            ) INTO v_new_record
            FROM public.rulesmaster rm
            WHERE 
                (p_isactive IS NULL OR rm.isactive = p_isactive)
                AND (p_ruletype IS NULL OR rm.ruletype = p_ruletype)
                AND (p_appliesto IS NULL OR rm.appliesto = p_appliesto)
            ORDER BY rm.priority, rm.created_at DESC;
            
            IF v_new_record IS NULL THEN
                v_new_record := '[]'::JSONB;
            END IF;
            
            v_return_message := 'Rules listed successfully';
            v_audit_description := 'Listed rules';
            v_old_record := NULL;
            
    END CASE;
    
    -- Log the action to audit trail (except for LIST which could return many records)
    IF p_action != 'LIST' THEN
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULESMASTER',
            p_action,
            v_audit_description,
            jsonb_build_object(
                'old_record', v_old_record,
                'new_record', v_new_record,
                'ruleid', COALESCE(p_ruleid, v_existing_ruleid)
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
    END IF;
    
    -- Build success response
    v_result := jsonb_build_object(
        'success', true,
        'message', v_return_message,
        'data', CASE 
            WHEN p_action = 'LIST' THEN v_new_record
            ELSE jsonb_build_object('rule', v_new_record)
        END,
        'ruleid', COALESCE(p_ruleid, v_existing_ruleid)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Get error details
        GET STACKED DIAGNOSTICS 
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_hint = PG_EXCEPTION_HINT;
        
        -- Log error to audit trail
        INSERT INTO public.audit_trail (
            entity_type, 
            action_type, 
            description, 
            data, 
            user_id, 
            ip_address, 
            user_agent
        ) VALUES (
            'RULESMASTER',
            'ERROR',
            'Error in frulesmasterCURD: ' || v_error_message,
            jsonb_build_object(
                'action', p_action,
                'error_detail', v_error_detail,
                'error_hint', v_error_hint,
                'ruleid', p_ruleid
            ),
            p_user_id,
            p_ip_address,
            p_user_agent
        );
        
        -- Build error response
        v_result := jsonb_build_object(
            'success', false,
            'message', 'Operation failed: ' || v_error_message,
            'error_detail', v_error_detail,
            'error_hint', v_error_hint,
            'data', null
        );
        
        RETURN v_result;
END;
$$;


