--
-- Name: log_operation_start(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_operation_start(p_function_name text, p_parameters jsonb DEFAULT NULL::jsonb) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation_id BIGINT;
BEGIN
    -- Create operation_logs table if it doesn't exist
    CREATE TABLE IF NOT EXISTS operation_logs (
        operation_id BIGSERIAL PRIMARY KEY,
        function_name TEXT NOT NULL,
        start_time TIMESTAMP NOT NULL,
        end_time TIMESTAMP,
        status TEXT NOT NULL,
        eligible_count INTEGER DEFAULT 0,
        processed_count INTEGER DEFAULT 0,
        total_amount DECIMAL(15,2) DEFAULT 0,
        error_message TEXT,
        additional_info JSONB,
        duration_ms DECIMAL(10,2),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );

    INSERT INTO operation_logs (
        function_name,
        start_time,
        status,
        additional_info
    ) VALUES (
        p_function_name,
        CURRENT_TIMESTAMP,
        'STARTED',
        p_parameters
    ) RETURNING operation_id INTO v_operation_id;
    
    RETURN v_operation_id;
EXCEPTION
    WHEN others THEN
        RETURN -1;
END;
$$;


ALTER FUNCTION public.log_operation_start(p_function_name text, p_parameters jsonb) OWNER TO postgres;

--
-- Name: log_operation_start(character varying, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_operation_start(p_function_name character varying, p_additional_info text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation_id BIGINT;
    v_error_text TEXT;
BEGIN
    RAISE NOTICE 'Attempting to insert into operation_log with function_name: %, additional_info: %', 
        p_function_name, p_additional_info;
    
    BEGIN
        INSERT INTO operation_log (
            function_name,
            execution_status,
            additional_info
        ) VALUES (
            p_function_name,
            'STARTED',
            p_additional_info
        ) RETURNING operation_id INTO v_operation_id;
        
        RAISE NOTICE 'Successfully inserted operation log with ID: %', v_operation_id;
        RETURN v_operation_id;
        
    EXCEPTION 
        WHEN others THEN
            GET STACKED DIAGNOSTICS v_error_text = MESSAGE_TEXT;
            RAISE NOTICE 'Insert failed with error: %', v_error_text;
            RETURN -1;
    END;
    
EXCEPTION
    WHEN others THEN
        GET STACKED DIAGNOSTICS v_error_text = MESSAGE_TEXT;
        RAISE NOTICE 'Function failed with error: %', v_error_text;
        RETURN -1;
END;
$$;


ALTER FUNCTION public.log_operation_start(p_function_name character varying, p_additional_info text) OWNER TO postgres;

--
-- Name: log_warning(bigint, character varying, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_warning(p_operation_id bigint, p_function_name character varying, p_warning_message text, p_additional_info text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_error_id BIGINT;
BEGIN
    PERFORM log_error(
        p_operation_id,
        p_function_name,
        p_warning_message,
        p_additional_info,
        NULL, -- sql_state
        NULL, -- failed_query
        jsonb_build_object('warning_type', 'WARNING', 'additional_info', p_additional_info)
    );
    
    RETURN v_error_id;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Failed to log warning: %', SQLERRM;
        RETURN -1;
END;
$$;


ALTER FUNCTION public.log_warning(p_operation_id bigint, p_function_name character varying, p_warning_message text, p_additional_info text) OWNER TO postgres;

--
-- Name: manage_dispatch(character varying, character varying, character varying, character varying, character varying, character varying, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.manage_dispatch(p_action character varying, p_request_id character varying DEFAULT NULL::character varying, p_username character varying DEFAULT NULL::character varying, p_receivername character varying DEFAULT NULL::character varying, p_idtype character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_address text DEFAULT NULL::text, p_urldoclink text DEFAULT NULL::text, p_deliverydate date DEFAULT NULL::date) RETURNS TABLE(request_id character varying, username character varying, receivername character varying, idtype character varying, mobileno character varying, address text, urldoclink text, deliverydate date, created_at timestamp without time zone, updated_at timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- INSERT action
    IF UPPER(p_action) = 'INSERT' THEN
        RETURN QUERY
        INSERT INTO dispatch(
            request_id, username, receivername, idtype, mobileno, address, urldoclink, deliverydate
        ) VALUES (
            p_request_id, p_username, p_receivername, p_idtype, p_mobileno, p_address, p_urldoclink, p_deliverydate
        )
        RETURNING *;

    -- UPDATE action
    ELSIF UPPER(p_action) = 'UPDATE' THEN
        IF p_request_id IS NULL THEN
            RAISE EXCEPTION 'request_id is required for UPDATE';
        END IF;

        RETURN QUERY
        UPDATE dispatch
        SET 
            username = COALESCE(p_username, username),
            receivername = COALESCE(p_receivername, receivername),
            idtype = COALESCE(p_idtype, idtype),
            mobileno = COALESCE(p_mobileno, mobileno),
            address = COALESCE(p_address, address),
            urldoclink = COALESCE(p_urldoclink, urldoclink),
            deliverydate = COALESCE(p_deliverydate, deliverydate),
            updated_at = NOW()
        WHERE request_id = p_request_id
        RETURNING *;

    -- DELETE action
    ELSIF UPPER(p_action) = 'DELETE' THEN
        IF p_request_id IS NULL THEN
            RAISE EXCEPTION 'request_id is required for DELETE';
        END IF;

        RETURN QUERY
        DELETE FROM dispatch
        WHERE request_id = p_request_id
        RETURNING *;

    -- LIST action
    ELSIF UPPER(p_action) = 'LIST' THEN
        RETURN QUERY
        SELECT * FROM dispatch;

    ELSE
        RAISE EXCEPTION 'Invalid action: %, allowed actions are INSERT, UPDATE, DELETE, LIST', p_action;
    END IF;
END;
$$;


ALTER FUNCTION public.manage_dispatch(p_action character varying, p_request_id character varying, p_username character varying, p_receivername character varying, p_idtype character varying, p_mobileno character varying, p_address text, p_urldoclink text, p_deliverydate date) OWNER TO postgres;

--
-- Name: mark_error_resolved(bigint, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_error_resolved(p_error_id bigint, p_resolved_by character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE error_log 
    SET 
        resolved = true,
        resolved_at = CURRENT_TIMESTAMP,
        resolved_by = COALESCE(p_resolved_by, CURRENT_USER)
    WHERE error_id = p_error_id;
    
    RETURN FOUND;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Failed to mark error as resolved: %', SQLERRM;
        RETURN FALSE;
END;
$$;


ALTER FUNCTION public.mark_error_resolved(p_error_id bigint, p_resolved_by character varying) OWNER TO postgres;

--
-- Name: pcustomer(text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character, character, date, character varying, character varying, character varying, character varying, character varying, character varying, character varying, numeric, character varying, character varying, character varying, character varying, text, character varying, character varying, character varying, numeric, numeric, character, character varying, character varying, character varying, character varying, date, date, character, character varying, boolean, character varying, character varying, date, date, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.pcustomer(IN action text, INOUT p_customercode character varying DEFAULT NULL::character varying, IN p_cbs_customer_code character varying DEFAULT NULL::character varying, IN p_fname character varying DEFAULT NULL::character varying, IN p_middlename character varying DEFAULT NULL::character varying, IN p_lname character varying DEFAULT NULL::character varying, IN p_salutation character varying DEFAULT NULL::character varying, IN p_emailid character varying DEFAULT NULL::character varying, IN p_mobileno character varying DEFAULT NULL::character varying, IN p_branchcode character varying DEFAULT NULL::character varying, IN p_bankcode character varying DEFAULT NULL::character varying, IN p_maritalstatus character DEFAULT NULL::bpchar, IN p_customer_status character DEFAULT NULL::bpchar, IN p_dob date DEFAULT NULL::date, IN p_address character varying DEFAULT NULL::character varying, IN p_nationality character varying DEFAULT NULL::character varying, IN p_gender character varying DEFAULT NULL::character varying, IN p_documenttype character varying DEFAULT NULL::character varying, IN p_documentid character varying DEFAULT NULL::character varying, IN p_occupation character varying DEFAULT NULL::character varying, IN p_employment_type character varying DEFAULT NULL::character varying, IN p_annualincome numeric DEFAULT NULL::numeric, IN p_fathername character varying DEFAULT NULL::character varying, IN p_mothername character varying DEFAULT NULL::character varying, IN p_spousename character varying DEFAULT NULL::character varying, IN p_grandfathername character varying DEFAULT NULL::character varying, IN p_notes text DEFAULT NULL::text, INOUT p_accountid character varying DEFAULT NULL::character varying, IN p_accountnumber character varying DEFAULT NULL::character varying, IN p_accounttype character varying DEFAULT NULL::character varying, IN p_balance numeric DEFAULT NULL::numeric, IN p_accountlimit numeric DEFAULT NULL::numeric, IN p_account_status character DEFAULT NULL::bpchar, INOUT p_cardid character varying DEFAULT NULL::character varying, IN p_schemetype character varying DEFAULT NULL::character varying, IN p_cardnumber character varying DEFAULT NULL::character varying, IN p_cardtype character varying DEFAULT NULL::character varying, IN p_expirydate date DEFAULT NULL::date, IN p_issuedate date DEFAULT NULL::date, IN p_card_status character DEFAULT NULL::bpchar, IN p_productid character varying DEFAULT NULL::character varying, IN p_autorenewal boolean DEFAULT false, IN p_profileid character varying DEFAULT NULL::character varying, IN p_profile_mapping_status character varying DEFAULT 'ACTIVE'::character varying, IN p_effective_date date DEFAULT NULL::date, IN p_expiry_date date DEFAULT NULL::date, IN p_assigned_by character varying DEFAULT 'SYSTEM'::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result JSON;
    v_card_profile_id VARCHAR(12);
    v_generated_customercode VARCHAR(12);
    v_generated_accountid VARCHAR(12);
    v_generated_cardid VARCHAR(12);
    v_affected_rows INT;
    v_temp_cardid VARCHAR(12);
    v_debug_expiry_date DATE; -- Temporary variable for expiry date
BEGIN
    -- ===============================
    -- ACTION: ALL (Insert Customer → Account → Card → Card Profile Mapping)
    -- ===============================
    IF action = 'ALL' THEN
        -- Insert Customer - customercode will be auto-generated by default fCreateCustomerCode()
        INSERT INTO CUSTOMER (
            cbs_customer_code, fname, lname, middlename, salutation, 
            emailid, mobileno, branchcode, bankcode, maritalstatus, status, 
            dob, address, nationality, gender, documenttype, documentid, 
            occupation, employment_type, annualincome, fathername, 
            mothername, spousename, grandfathername, notes
        ) VALUES (
            p_cbs_customer_code, p_fname, p_lname, p_middlename, 
            p_salutation, p_emailid, p_mobileno, p_branchcode, p_bankcode, 
            p_maritalstatus, p_customer_status, p_dob, p_address, p_nationality, 
            p_gender, p_documenttype, p_documentid, p_occupation, p_employment_type, 
            p_annualincome, p_fathername, p_mothername, p_spousename, 
            p_grandfathername, p_notes
        ) RETURNING customercode INTO v_generated_customercode;
        
        -- Set the output parameter
        p_customercode := v_generated_customercode;
        RAISE NOTICE 'Generated Customer Code: %', p_customercode;

        -- Insert Account - accountid will be auto-generated by default fCreateAccountCode()
        INSERT INTO ACCOUNT (
            customercode, accountnumber, accounttype, balance, accountlimit, 
            branchcode, status
        ) VALUES (
            p_customercode, p_accountnumber, p_accounttype, p_balance, 
            p_accountlimit, p_branchcode, p_account_status
        ) RETURNING accountid INTO v_generated_accountid;
        
        -- Set the output parameter
        p_accountid := v_generated_accountid;
        RAISE NOTICE 'Generated Account ID: %', p_accountid;

        -- Insert Card - cardid will be auto-generated by default fCreateCardCode()
        INSERT INTO CARD (
            accountid, customercode, schemetype, cardnumber, cardtype, 
            expirydate, issuedate, status, productid, autorenewal
        ) VALUES (
            p_accountid, p_customercode, p_schemetype, p_cardnumber, p_cardtype, 
            p_expirydate, p_issuedate, p_card_status, p_productid, p_autorenewal
        ) RETURNING cardid INTO v_generated_cardid;
        
        -- Set the output parameter
        p_cardid := v_generated_cardid;
        RAISE NOTICE 'Generated Card ID: %', p_cardid;

        -- Insert Card Profile Mapping using the function
        IF p_profileid IS NOT NULL AND p_cardid IS NOT NULL THEN
            -- Set default effective_date to card's issuedate if not provided
            IF p_effective_date IS NULL THEN
                p_effective_date := p_issuedate;
            END IF;
            
            -- Set default assigned_by if not provided
            IF p_assigned_by IS NULL THEN
                p_assigned_by := 'SYSTEM';
            END IF;
            
            -- Set default status if not provided
            IF p_profile_mapping_status IS NULL THEN
                p_profile_mapping_status := 'ACTIVE';
            END IF;
            
            -- FIX: Use a temporary variable to handle expiry_date properly
            v_debug_expiry_date := p_expiry_date;
            
            -- DEBUG: Log the values before calling the function
            RAISE NOTICE 'DEBUG [ALL] - Parameters for card profile mapping:';
            RAISE NOTICE '  p_cardid: % (type: %)', p_cardid, pg_typeof(p_cardid);
            RAISE NOTICE '  p_profileid: % (type: %)', p_profileid, pg_typeof(p_profileid);
            RAISE NOTICE '  p_profile_mapping_status: %', p_profile_mapping_status;
            RAISE NOTICE '  p_effective_date: % (type: %)', p_effective_date, pg_typeof(p_effective_date);
            RAISE NOTICE '  p_expiry_date: % (type: %)', v_debug_expiry_date, pg_typeof(v_debug_expiry_date);
            RAISE NOTICE '  p_assigned_by: %', p_assigned_by;
            
            -- Call the card profile mapping function with the SAME parameters as INSERT_CARD
            -- Remove redundant casting since parameters already have correct types
            v_result := fcardprofilemappingCRUD(
                'INSERT',                    -- action
                NULL,                        -- p_card_profile_id (will be auto-generated)
                p_cardid,                    -- p_cardid (already VARCHAR)
                p_profileid,                 -- p_profileid (already VARCHAR)
                p_profile_mapping_status,    -- p_status (already VARCHAR)
                p_effective_date,            -- p_effective_date (already DATE or NULL)
                v_debug_expiry_date,         -- p_expiry_date (using temporary variable)
                p_assigned_by                -- p_assigned_by (already VARCHAR)
            );
            
            -- Check if the insert was successful
            IF v_result IS NOT NULL AND (v_result->>'success')::BOOLEAN = true THEN
                -- Extract the generated card_profile_id from the result
                v_card_profile_id := v_result->>'card_profile_id';
                RAISE NOTICE 'Card profile mapping created successfully. ID: %', v_card_profile_id;
            ELSE
                RAISE WARNING 'Card profile mapping failed: %', 
                    CASE 
                        WHEN v_result IS NULL THEN 'Function returned NULL'
                        ELSE COALESCE(v_result->>'message', 'Unknown error')
                    END;
            END IF;
        ELSE
            IF p_profileid IS NULL THEN
                RAISE NOTICE 'Skipping card profile mapping: profileid is NULL';
            END IF;
            IF p_cardid IS NULL THEN
                RAISE NOTICE 'Skipping card profile mapping: cardid is NULL';
            END IF;
        END IF;

    -- ===============================
    -- INSERT_CUSTOMER Operation
    -- ===============================
    ELSIF action = 'INSERT_CUSTOMER' THEN
        -- Insert Customer - customercode will be auto-generated
        INSERT INTO CUSTOMER (
            cbs_customer_code, fname, lname, middlename, salutation, 
            emailid, mobileno, branchcode, bankcode, maritalstatus, status, 
            dob, address, nationality, gender, documenttype, documentid, 
            occupation, employment_type, annualincome, fathername, 
            mothername, spousename, grandfathername, notes
        ) VALUES (
            p_cbs_customer_code, p_fname, p_lname, p_middlename, 
            p_salutation, p_emailid, p_mobileno, p_branchcode, p_bankcode, 
            p_maritalstatus, p_customer_status, p_dob, p_address, p_nationality, 
            p_gender, p_documenttype, p_documentid, p_occupation, p_employment_type, 
            p_annualincome, p_fathername, p_mothername, p_spousename, 
            p_grandfathername, p_notes
        ) RETURNING customercode INTO p_customercode;
        
        RAISE NOTICE 'Generated Customer Code: %', p_customercode;

    -- ===============================
    -- UPDATE_CUSTOMER Operation
    -- ===============================
    ELSIF action = 'UPDATE_CUSTOMER' THEN
        -- Check if customer exists
        IF NOT EXISTS (SELECT 1 FROM customer WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Customer with code % does not exist', p_customercode;
        END IF;
        
        -- Update Customer
        UPDATE CUSTOMER SET
            cbs_customer_code = COALESCE(p_cbs_customer_code, cbs_customer_code),
            fname = COALESCE(p_fname, fname),
            lname = COALESCE(p_lname, lname),
            middlename = COALESCE(p_middlename, middlename),
            salutation = COALESCE(p_salutation, salutation),
            emailid = COALESCE(p_emailid, emailid),
            mobileno = COALESCE(p_mobileno, mobileno),
            branchcode = COALESCE(p_branchcode, branchcode),
            bankcode = COALESCE(p_bankcode, bankcode),
            maritalstatus = COALESCE(p_maritalstatus, maritalstatus),
            status = COALESCE(p_customer_status, status),
            dob = COALESCE(p_dob, dob),
            address = COALESCE(p_address, address),
            nationality = COALESCE(p_nationality, nationality),
            gender = COALESCE(p_gender, gender),
            documenttype = COALESCE(p_documenttype, documenttype),
            documentid = COALESCE(p_documentid, documentid),
            occupation = COALESCE(p_occupation, occupation),
            employment_type = COALESCE(p_employment_type, employment_type),
            annualincome = COALESCE(p_annualincome, annualincome),
            fathername = COALESCE(p_fathername, fathername),
            mothername = COALESCE(p_mothername, mothername),
            spousename = COALESCE(p_spousename, spousename),
            grandfathername = COALESCE(p_grandfathername, grandfathername),
            notes = COALESCE(p_notes, notes),
            updateddate = CURRENT_TIMESTAMP
        WHERE customercode = p_customercode;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Customer updated: %, Rows affected: %', p_customercode, v_affected_rows;

    -- ===============================
    -- DELETE_CUSTOMER Operation (HARD DELETE)
    -- ===============================
    ELSIF action = 'DELETE_CUSTOMER' THEN
        -- Check if customer exists
        IF NOT EXISTS (SELECT 1 FROM customer WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Customer with code % does not exist', p_customercode;
        END IF;
        
        -- Check if customer has accounts
        IF EXISTS (SELECT 1 FROM account WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Cannot delete customer with existing accounts. Delete accounts first.';
        END IF;
        
        -- Check if customer has cards
        IF EXISTS (SELECT 1 FROM card WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Cannot delete customer with existing cards. Delete cards first.';
        END IF;
        
        -- HARD DELETE customer
        DELETE FROM CUSTOMER WHERE customercode = p_customercode;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Customer HARD DELETED: %, Rows affected: %', p_customercode, v_affected_rows;

    -- ===============================
    -- INSERT_ACCOUNT Operation
    -- ===============================
    ELSIF action = 'INSERT_ACCOUNT' THEN
        -- Check if customer exists
        IF NOT EXISTS (SELECT 1 FROM customer WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Customer with code % does not exist', p_customercode;
        END IF;
        
        -- Insert Account - accountid will be auto-generated
        INSERT INTO ACCOUNT (
            customercode, accountnumber, accounttype, balance, accountlimit, 
            branchcode, status
        ) VALUES (
            p_customercode, p_accountnumber, p_accounttype, p_balance, 
            p_accountlimit, p_branchcode, p_account_status
        ) RETURNING accountid INTO p_accountid;
        
        RAISE NOTICE 'Generated Account ID: %', p_accountid;

    -- ===============================
    -- UPDATE_ACCOUNT Operation
    -- ===============================
    ELSIF action = 'UPDATE_ACCOUNT' THEN
        -- Check if account exists
        IF NOT EXISTS (SELECT 1 FROM account WHERE accountid = p_accountid) THEN
            RAISE EXCEPTION 'Account with ID % does not exist', p_accountid;
        END IF;
        
        -- Check if account belongs to customer (if customer code provided)
        IF p_customercode IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM account 
            WHERE accountid = p_accountid AND customercode = p_customercode
        ) THEN
            RAISE EXCEPTION 'Account % does not belong to customer %', p_accountid, p_customercode;
        END IF;
        
        -- Update Account
        UPDATE ACCOUNT SET
            accountnumber = COALESCE(p_accountnumber, accountnumber),
            accounttype = COALESCE(p_accounttype, accounttype),
            balance = COALESCE(p_balance, balance),
            accountlimit = COALESCE(p_accountlimit, accountlimit),
            branchcode = COALESCE(p_branchcode, branchcode),
            status = COALESCE(p_account_status, status),
            updateddate = CURRENT_TIMESTAMP
        WHERE accountid = p_accountid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Account updated: %, Rows affected: %', p_accountid, v_affected_rows;

    -- ===============================
    -- DELETE_ACCOUNT Operation (HARD DELETE)
    -- ===============================
    ELSIF action = 'DELETE_ACCOUNT' THEN
        -- Check if account exists
        IF NOT EXISTS (SELECT 1 FROM account WHERE accountid = p_accountid) THEN
            RAISE EXCEPTION 'Account with ID % does not exist', p_accountid;
        END IF;
        
        -- Check if account has balance
        IF (SELECT balance FROM account WHERE accountid = p_accountid) > 0 THEN
            RAISE EXCEPTION 'Cannot delete account with balance. Zero out balance first.';
        END IF;
        
        -- Check if account has cards
        IF EXISTS (SELECT 1 FROM card WHERE accountid = p_accountid) THEN
            RAISE EXCEPTION 'Cannot delete account with existing cards. Delete cards first.';
        END IF;
        
        -- HARD DELETE account
        DELETE FROM ACCOUNT WHERE accountid = p_accountid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Account HARD DELETED: %, Rows affected: %', p_accountid, v_affected_rows;

    -- ===============================
    -- INSERT_CARD Operation
    -- ===============================
    ELSIF action = 'INSERT_CARD' THEN
        -- Validate required parameters
        IF p_customercode IS NULL THEN
            RAISE EXCEPTION 'Cannot insert card: customercode must be provided';
        END IF;
        
        IF p_accountid IS NULL AND p_accountnumber IS NOT NULL THEN
            -- Try to find accountid from accountnumber
            SELECT accountid INTO p_accountid
            FROM account
            WHERE accountnumber = p_accountnumber
              AND customercode = p_customercode
            LIMIT 1;
            
            IF p_accountid IS NULL THEN
                RAISE EXCEPTION 'Cannot insert card: No account found with accountnumber % for customer %', 
                    p_accountnumber, p_customercode;
            END IF;
        ELSIF p_accountid IS NULL THEN
            RAISE EXCEPTION 'Cannot insert card: accountid or accountnumber must be provided';
        END IF;
        
        -- Check if account exists and belongs to customer
        IF NOT EXISTS (SELECT 1 FROM account WHERE accountid = p_accountid AND customercode = p_customercode) THEN
            RAISE EXCEPTION 'Account % does not belong to customer %', p_accountid, p_customercode;
        END IF;

        -- Insert Card - cardid will be auto-generated
        INSERT INTO CARD (
            accountid, customercode, schemetype, cardnumber, cardtype, 
            expirydate, issuedate, status, productid, autorenewal
        ) VALUES (
            p_accountid, p_customercode, p_schemetype, p_cardnumber, p_cardtype, 
            p_expirydate, p_issuedate, p_card_status, p_productid, p_autorenewal
        ) RETURNING cardid INTO v_generated_cardid;
        
        -- Set the output parameter
        p_cardid := v_generated_cardid;
        RAISE NOTICE 'Generated Card ID: %', p_cardid;

        -- Insert Card Profile Mapping using the function
        IF p_profileid IS NOT NULL AND p_cardid IS NOT NULL THEN
            -- Set default effective_date to card's issuedate if not provided
            IF p_effective_date IS NULL THEN
                p_effective_date := p_issuedate;
            END IF;
            
            -- Set default assigned_by if not provided
            IF p_assigned_by IS NULL THEN
                p_assigned_by := 'SYSTEM';
            END IF;
            
            -- Set default status if not provided
            IF p_profile_mapping_status IS NULL THEN
                p_profile_mapping_status := 'ACTIVE';
            END IF;
            
            -- DEBUG: Log the values before calling the function
            RAISE NOTICE 'DEBUG [INSERT_CARD] - Parameters for card profile mapping:';
            RAISE NOTICE '  p_cardid: % (type: %)', p_cardid, pg_typeof(p_cardid);
            RAISE NOTICE '  p_profileid: % (type: %)', p_profileid, pg_typeof(p_profileid);
            RAISE NOTICE '  p_profile_mapping_status: %', p_profile_mapping_status;
            RAISE NOTICE '  p_effective_date: % (type: %)', p_effective_date, pg_typeof(p_effective_date);
            RAISE NOTICE '  p_expiry_date: % (type: %)', p_expiry_date, pg_typeof(p_expiry_date);
            RAISE NOTICE '  p_assigned_by: %', p_assigned_by;
            
            -- Call the card profile mapping function
            v_result := fcardprofilemappingCRUD(
                'INSERT'::VARCHAR,
                NULL::VARCHAR,  -- p_card_profile_id
                p_cardid::VARCHAR,  -- p_cardid
                p_profileid::VARCHAR,  -- p_profileid
                p_profile_mapping_status::VARCHAR,  -- p_status
                p_effective_date::DATE,  -- p_effective_date
                p_expiry_date::DATE,  -- p_expiry_date
                p_assigned_by::VARCHAR  -- p_assigned_by
            );
            
            -- Check if the insert was successful
            IF v_result IS NOT NULL AND (v_result->>'success')::BOOLEAN = true THEN
                -- Extract the generated card_profile_id from the result
                v_card_profile_id := v_result->>'card_profile_id';
                RAISE NOTICE 'Card profile mapping created successfully. ID: %', v_card_profile_id;
            ELSE
                RAISE WARNING 'Card profile mapping failed: %', 
                    CASE 
                        WHEN v_result IS NULL THEN 'Function returned NULL'
                        ELSE COALESCE(v_result->>'message', 'Unknown error')
                    END;
            END IF;
        ELSE
            IF p_profileid IS NULL THEN
                RAISE NOTICE 'Skipping card profile mapping: profileid is NULL';
            END IF;
            IF p_cardid IS NULL THEN
                RAISE NOTICE 'Skipping card profile mapping: cardid is NULL';
            END IF;
        END IF;

    -- ===============================
    -- UPDATE_CARD Operation
    -- ===============================
    ELSIF action = 'UPDATE_CARD' THEN
        -- Check if card exists
        IF NOT EXISTS (SELECT 1 FROM card WHERE cardid = p_cardid) THEN
            RAISE EXCEPTION 'Card with ID % does not exist', p_cardid;
        END IF;
        
        -- Check if card belongs to customer (if customer code provided)
        IF p_customercode IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM card 
            WHERE cardid = p_cardid AND customercode = p_customercode
        ) THEN
            RAISE EXCEPTION 'Card % does not belong to customer %', p_cardid, p_customercode;
        END IF;
        
        -- Check if card belongs to account (if accountid provided)
        IF p_accountid IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM card 
            WHERE cardid = p_cardid AND accountid = p_accountid
        ) THEN
            RAISE EXCEPTION 'Card % does not belong to account %', p_cardid, p_accountid;
        END IF;
        
        -- Update Card
        UPDATE CARD SET
            schemetype = COALESCE(p_schemetype, schemetype),
            cardnumber = COALESCE(p_cardnumber, cardnumber),
            cardtype = COALESCE(p_cardtype, cardtype),
            expirydate = COALESCE(p_expirydate, expirydate),
            issuedate = COALESCE(p_issuedate, issuedate),
            status = COALESCE(p_card_status, status),
            productid = COALESCE(p_productid, productid),
            autorenewal = COALESCE(p_autorenewal, autorenewal),
            updateddate = CURRENT_TIMESTAMP
        WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Card updated: %, Rows affected: %', p_cardid, v_affected_rows;

    -- ===============================
    -- DELETE_CARD Operation (HARD DELETE)
    -- ===============================
    ELSIF action = 'DELETE_CARD' THEN
        -- Check if card exists
        IF NOT EXISTS (SELECT 1 FROM card WHERE cardid = p_cardid) THEN
            RAISE EXCEPTION 'Card with ID % does not exist', p_cardid;
        END IF;
        
        -- Delete card profile mappings first (if they exist)
        DELETE FROM cardprofilemapping WHERE cardid = p_cardid;
        
        -- HARD DELETE card
        DELETE FROM CARD WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Card HARD DELETED: %, Rows affected: %', p_cardid, v_affected_rows;

    -- ===============================
    -- ACTIVATE_CUSTOMER Operation
    -- ===============================
    ELSIF action = 'ACTIVATE_CUSTOMER' THEN
        -- Check if customer exists
        IF NOT EXISTS (SELECT 1 FROM customer WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Customer with code % does not exist', p_customercode;
        END IF;
        
        -- Activate customer
        UPDATE CUSTOMER SET
            status = 'A',
            updateddate = CURRENT_TIMESTAMP
        WHERE customercode = p_customercode;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Customer activated: %, Rows affected: %', p_customercode, v_affected_rows;

    -- ===============================
    -- DEACTIVATE_CUSTOMER Operation
    -- ===============================
    ELSIF action = 'DEACTIVATE_CUSTOMER' THEN
        -- Check if customer exists
        IF NOT EXISTS (SELECT 1 FROM customer WHERE customercode = p_customercode) THEN
            RAISE EXCEPTION 'Customer with code % does not exist', p_customercode;
        END IF;
        
        -- Deactivate customer
        UPDATE CUSTOMER SET
            status = 'I',
            updateddate = CURRENT_TIMESTAMP
        WHERE customercode = p_customercode;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Customer deactivated: %, Rows affected: %', p_customercode, v_affected_rows;

    -- ===============================
    -- ACTIVATE_ACCOUNT Operation
    -- ===============================
    ELSIF action = 'ACTIVATE_ACCOUNT' THEN
        -- Check if account exists
        IF NOT EXISTS (SELECT 1 FROM account WHERE accountid = p_accountid) THEN
            RAISE EXCEPTION 'Account with ID % does not exist', p_accountid;
        END IF;
        
        -- Activate account
        UPDATE ACCOUNT SET
            status = 'A',
            updateddate = CURRENT_TIMESTAMP
        WHERE accountid = p_accountid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Account activated: %, Rows affected: %', p_accountid, v_affected_rows;

    -- ===============================
    -- DEACTIVATE_ACCOUNT Operation
    -- ===============================
    ELSIF action = 'DEACTIVATE_ACCOUNT' THEN
        -- Check if account exists
        IF NOT EXISTS (SELECT 1 FROM account WHERE accountid = p_accountid) THEN
            RAISE EXCEPTION 'Account with ID % does not exist', p_accountid;
        END IF;
        
        -- Deactivate account
        UPDATE ACCOUNT SET
            status = 'I',
            updateddate = CURRENT_TIMESTAMP
        WHERE accountid = p_accountid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Account deactivated: %, Rows affected: %', p_accountid, v_affected_rows;

    -- ===============================
    -- ACTIVATE_CARD Operation
    -- ===============================
    ELSIF action = 'ACTIVATE_CARD' THEN
        -- Check if card exists
        IF NOT EXISTS (SELECT 1 FROM card WHERE cardid = p_cardid) THEN
            RAISE EXCEPTION 'Card with ID % does not exist', p_cardid;
        END IF;
        
        -- Activate card
        UPDATE CARD SET
            status = 'A',
            updateddate = CURRENT_TIMESTAMP
        WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Card activated: %, Rows affected: %', p_cardid, v_affected_rows;

    -- ===============================
    -- DEACTIVATE_CARD Operation
    -- ===============================
    ELSIF action = 'DEACTIVATE_CARD' THEN
        -- Check if card exists
        IF NOT EXISTS (SELECT 1 FROM card WHERE cardid = p_cardid) THEN
            RAISE EXCEPTION 'Card with ID % does not exist', p_cardid;
        END IF;
        
        -- Deactivate card
        UPDATE CARD SET
            status = 'I',
            updateddate = CURRENT_TIMESTAMP
        WHERE cardid = p_cardid;
        
        GET DIAGNOSTICS v_affected_rows = ROW_COUNT;
        RAISE NOTICE 'Card deactivated: %, Rows affected: %', p_cardid, v_affected_rows;

    ELSE
        RAISE EXCEPTION 'Invalid action parameter: %', action;
    END IF;
END;
$$;


ALTER PROCEDURE public.pcustomer(IN action text, INOUT p_customercode character varying, IN p_cbs_customer_code character varying, IN p_fname character varying, IN p_middlename character varying, IN p_lname character varying, IN p_salutation character varying, IN p_emailid character varying, IN p_mobileno character varying, IN p_branchcode character varying, IN p_bankcode character varying, IN p_maritalstatus character, IN p_customer_status character, IN p_dob date, IN p_address character varying, IN p_nationality character varying, IN p_gender character varying, IN p_documenttype character varying, IN p_documentid character varying, IN p_occupation character varying, IN p_employment_type character varying, IN p_annualincome numeric, IN p_fathername character varying, IN p_mothername character varying, IN p_spousename character varying, IN p_grandfathername character varying, IN p_notes text, INOUT p_accountid character varying, IN p_accountnumber character varying, IN p_accounttype character varying, IN p_balance numeric, IN p_accountlimit numeric, IN p_account_status character, INOUT p_cardid character varying, IN p_schemetype character varying, IN p_cardnumber character varying, IN p_cardtype character varying, IN p_expirydate date, IN p_issuedate date, IN p_card_status character, IN p_productid character varying, IN p_autorenewal boolean, IN p_profileid character varying, IN p_profile_mapping_status character varying, IN p_effective_date date, IN p_expiry_date date, IN p_assigned_by character varying) OWNER TO postgres;

--
-- Name: procinsert_branch(character varying, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.procinsert_branch(IN p_bankcode character varying, IN p_branchname character varying, IN p_branchid character varying, IN p_managername character varying, IN p_phone character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO kmana_branch (bankcode, branchname, branchid, managername, phone)
    VALUES (p_bankcode, p_branchname, p_branchid, p_managername, p_phone);
EXCEPTION
    WHEN unique_violation THEN
        RAISE NOTICE 'Branch with bankcode % and branchid % already exists.', p_bankcode, p_branchid;
        RAISE; -- Re-raise error so caller sees it
    WHEN others THEN
        RAISE NOTICE 'An error occurred: %', SQLERRM;
        RAISE; -- Re-raise error
END;
$$;


ALTER PROCEDURE public.procinsert_branch(IN p_bankcode character varying, IN p_branchname character varying, IN p_branchid character varying, IN p_managername character varying, IN p_phone character varying) OWNER TO postgres;

--
-- Name: rulesmonitor(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.rulesmonitor()
    LANGUAGE plpgsql
    AS $$
DECLARE
    r_rule RECORD;
    r_condition RECORD;
    r_action RECORD;
    all_conditions_passed BOOLEAN;
    eval_result BOOLEAN;

    -- Dummy input context - replace with parameters or dynamic input if needed
    input_transaction_amount INTEGER := 1200;
    input_card_status TEXT := 'active';
    input_kyc_level TEXT := 'full';

    executed_actions_json JSONB := '[]'::JSONB;
BEGIN
    -- Loop through all active rules within effective date range, ordered by priority
    FOR r_rule IN
        SELECT * FROM rulesmaster
        WHERE isactive = TRUE
          AND startdate <= CURRENT_DATE
          AND (enddate IS NULL OR enddate >= CURRENT_DATE)
        ORDER BY priority ASC
    LOOP
        all_conditions_passed := TRUE;
        executed_actions_json := '[]'::JSONB;

        -- Evaluate all conditions for this rule
        FOR r_condition IN
            SELECT * FROM ruleconditions WHERE ruleid = r_rule.ruleid
        LOOP
            -- Basic condition checks (expand with more operators/fields as needed)
            IF r_condition.field_name = 'transaction_amount' AND r_condition.operator = '>' THEN
                eval_result := input_transaction_amount > r_condition.value::INTEGER;

            ELSIF r_condition.field_name = 'card_status' AND r_condition.operator = '=' THEN
                eval_result := input_card_status = r_condition.value;

            ELSIF r_condition.field_name = 'kyc_level' AND r_condition.operator = '=' THEN
                eval_result := input_kyc_level = r_condition.value;

            ELSE
                -- Unsupported condition/operator results in failed evaluation
                eval_result := FALSE;
            END IF;

            IF NOT eval_result THEN
                all_conditions_passed := FALSE;
                EXIT; -- Stop checking further conditions
            END IF;
        END LOOP;

        -- If all conditions passed, collect all actions for the rule
        IF all_conditions_passed THEN
            FOR r_action IN
                SELECT * FROM ruleactions WHERE ruleid = r_rule.ruleid
            LOOP
                -- Append action_value JSONB objects to the actions array
                executed_actions_json := executed_actions_json || jsonb_build_array(r_action.action_value);
                -- Here you could implement action execution logic
            END LOOP;
        END IF;

        -- Insert the evaluation result into rulelogs
        INSERT INTO rulelogs (
            ruleid,
            rule_name,
            conditions_met,
            input_context,
            executed_actions,
            evaluation_time,
            remarks
        ) VALUES (
            r_rule.ruleid,
            r_rule.rulename,
            all_conditions_passed,
            jsonb_build_object(
                'transaction_amount', input_transaction_amount,
                'card_status', input_card_status,
                'kyc_level', input_kyc_level
            ),
            executed_actions_json,
            CURRENT_TIMESTAMP,
            CASE
                WHEN all_conditions_passed THEN 'Rule triggered and actions logged.'
                ELSE 'Conditions not met or unsupported.'
            END
        );
    END LOOP;
END;
$$;


ALTER PROCEDURE public.rulesmonitor() OWNER TO postgres;

--
-- Name: search_customer_dynamic(character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_customer_dynamic(p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_customercode character varying DEFAULT NULL::character varying, p_accountno character varying DEFAULT NULL::character varying, p_cardno character varying DEFAULT NULL::character varying) RETURNS TABLE(customercode character varying, fname character varying, lname character varying, middlename character varying, mobileno character varying, accountid character varying, accountnumber character varying, accounttype character varying, balance numeric, cardid character varying, cardnumber character varying, cardtype character varying, schemetype character varying, status character)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
BEGIN
    -- Base query
    dyn_sql := 'SELECT 
                    c.customercode,
                    c.fname,
                    c.lname,
                    c.middlename,
                    c.mobileno,
                    a.accountid,
                    a.accountnumber,
                    a.accounttype,
                    a.balance,
                    cd.cardid,
                    cd.cardnumber,
                    cd.cardtype,
                    cd.schemetype,
                    cd.status
                FROM customer c
                LEFT JOIN account a ON c.customercode = a.customercode
                LEFT JOIN card cd ON a.accountid = cd.accountid
                WHERE 1=1';

    -- Add filters only if parameter is NOT NULL and NOT empty
    IF p_fname IS NOT NULL AND p_fname <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.fname ILIKE %L', p_fname || '%');
    END IF;

    IF p_lname IS NOT NULL AND p_lname <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.lname ILIKE %L', p_lname || '%');
    END IF;

    IF p_middlename IS NOT NULL AND p_middlename <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.middlename ILIKE %L', p_middlename || '%');
    END IF;

    IF p_mobileno IS NOT NULL AND p_mobileno <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.mobileno = %L', p_mobileno);
    END IF;

    IF p_customercode IS NOT NULL AND p_customercode <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.customercode = %L', p_customercode);
    END IF;

    IF p_accountno IS NOT NULL AND p_accountno <> '' THEN
        dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', p_accountno);
    END IF;

    IF p_cardno IS NOT NULL AND p_cardno <> '' THEN
        dyn_sql := dyn_sql || format(' AND cd.cardnumber = %L', p_cardno);
    END IF;

    -- Debug: show the dynamic query
    RAISE NOTICE 'Dynamic query executing: %', dyn_sql;

    -- Execute the query
    RETURN QUERY EXECUTE dyn_sql;

END;
$$;


ALTER FUNCTION public.search_customer_dynamic(p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_customercode character varying, p_accountno character varying, p_cardno character varying) OWNER TO postgres;

--
-- Name: search_customer_dynamic(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_customer_dynamic(p_action character varying DEFAULT NULL::character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_customercode character varying DEFAULT NULL::character varying, p_accountno character varying DEFAULT NULL::character varying, p_cardno character varying DEFAULT NULL::character varying) RETURNS TABLE(customercode character varying, fname character varying, lname character varying, middlename character varying, mobileno character varying, accountid character varying, accountnumber character varying, accounttype character varying, balance numeric, cardid character varying, cardnumber character varying, cardtype character varying, schemetype character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
BEGIN
    -- Base query based on action
    IF p_action = 'CUST' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            WHERE 1=1';

    ELSIF p_action = 'ACC' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            WHERE 1=1';

    ELSIF p_action = 'CARD' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSIF p_action = 'ALL' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSE
        RAISE EXCEPTION 'Invalid action: %', p_action;
    END IF;

    -- Apply filters only if values are provided
    IF p_fname IS NOT NULL AND trim(p_fname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.fname ILIKE %L', '%' || trim(p_fname) || '%');
    END IF;

    IF p_lname IS NOT NULL AND trim(p_lname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.lname ILIKE %L', '%' || trim(p_lname) || '%');
    END IF;

    IF p_middlename IS NOT NULL AND trim(p_middlename) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.middlename ILIKE %L', '%' || trim(p_middlename) || '%');
    END IF;

    IF p_mobileno IS NOT NULL AND trim(p_mobileno) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.mobileno = %L', trim(p_mobileno));
    END IF;

    IF p_customercode IS NOT NULL AND trim(p_customercode) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.customercode = %L', trim(p_customercode));
    END IF;

    IF p_accountno IS NOT NULL AND trim(p_accountno) <> '' AND p_action IN ('ACC','CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', trim(p_accountno));
    END IF;

    IF p_cardno IS NOT NULL AND trim(p_cardno) <> '' AND p_action IN ('CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND cd.cardnumber = %L', trim(p_cardno));
    END IF;

    -- Debug: show the final query
    RAISE NOTICE 'Executing query: %', dyn_sql;

    -- Execute dynamic query
    RETURN QUERY EXECUTE dyn_sql;
END;
$$;


ALTER FUNCTION public.search_customer_dynamic(p_action character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_customercode character varying, p_accountno character varying, p_cardno character varying) OWNER TO postgres;

--
-- Name: search_customer_dynamic(character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_customer_dynamic(p_action character varying DEFAULT NULL::character varying, p_fname character varying DEFAULT NULL::character varying, p_lname character varying DEFAULT NULL::character varying, p_middlename character varying DEFAULT NULL::character varying, p_mobileno character varying DEFAULT NULL::character varying, p_customercode character varying DEFAULT NULL::character varying, p_accountno character varying DEFAULT NULL::character varying, p_cardno character varying DEFAULT NULL::character varying, p_userid integer DEFAULT NULL::integer) RETURNS TABLE(customercode character varying, fname character varying, lname character varying, middlename character varying, mobileno character varying, accountid character varying, accountnumber character varying, accounttype character varying, balance numeric, cardid character varying, cardnumber character varying, cardtype character varying, schemetype character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    dyn_sql TEXT;
    v_branchcode VARCHAR;
    v_institutionid VARCHAR;
    v_crossbranch BOOLEAN;
BEGIN
    -- Get user's branchcode, institutionid, and crossbranch flag
    SELECT lpad(branchid::text, 4, '0'), institutionid, crossbranch
    INTO v_branchcode, v_institutionid, v_crossbranch
    FROM users
    WHERE id = p_userid;

    -- Debug notice
    RAISE NOTICE 'User branchcode=% | institutionid=% | crossbranch=%', v_branchcode, v_institutionid, v_crossbranch;

    -- Base query based on action
    IF p_action = 'CUST' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            WHERE 1=1';

    ELSIF p_action = 'ACC' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   NULL::VARCHAR AS cardid,
                   NULL::VARCHAR AS cardnumber,
                   NULL::VARCHAR AS cardtype,
                   NULL::VARCHAR AS schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            WHERE 1=1';

    ELSIF p_action = 'CARD' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   NULL::VARCHAR AS accountid,
                   NULL::VARCHAR AS accountnumber,
                   NULL::VARCHAR AS accounttype,
                   NULL::NUMERIC AS balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            JOIN account a ON c.customercode = a.customercode
            JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSIF p_action = 'ALL' THEN
        dyn_sql := '
            SELECT c.customercode,
                   c.fname,
                   c.lname,
                   c.middlename,
                   c.mobileno,
                   a.accountid,
                   a.accountnumber,
                   a.accounttype,
                   a.balance,
                   cd.cardid,
                   cd.cardnumber,
                   cd.cardtype,
                   cd.schemetype
            FROM customer c
            LEFT JOIN account a ON c.customercode = a.customercode
            LEFT JOIN card cd ON a.accountid = cd.accountid
            WHERE 1=1';

    ELSE
        RAISE EXCEPTION 'Invalid action: %', p_action;
    END IF;

    -- Apply branch filter if crossbranch is false
    IF NOT v_crossbranch THEN
        dyn_sql := dyn_sql || format(' AND c.branchcode = %L', v_branchcode);
    END IF;

    -- Apply other filters if provided
    IF p_fname IS NOT NULL AND trim(p_fname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.fname ILIKE %L', '%' || trim(p_fname) || '%');
    END IF;

    IF p_lname IS NOT NULL AND trim(p_lname) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.lname ILIKE %L', '%' || trim(p_lname) || '%');
    END IF;

    IF p_middlename IS NOT NULL AND trim(p_middlename) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.middlename ILIKE %L', '%' || trim(p_middlename) || '%');
    END IF;

    IF p_mobileno IS NOT NULL AND trim(p_mobileno) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.mobileno = %L', trim(p_mobileno));
    END IF;

    IF p_customercode IS NOT NULL AND trim(p_customercode) <> '' THEN
        dyn_sql := dyn_sql || format(' AND c.customercode = %L', trim(p_customercode));
    END IF;

    IF p_accountno IS NOT NULL AND trim(p_accountno) <> '' AND p_action IN ('ACC','CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND a.accountnumber = %L', trim(p_accountno));
    END IF;

    IF p_cardno IS NOT NULL AND trim(p_cardno) <> '' AND p_action IN ('CARD','ALL') THEN
        dyn_sql := dyn_sql || format(' AND cd.cardnumber = %L', trim(p_cardno));
    END IF;

    -- Debug final SQL
    RAISE NOTICE 'Executing SQL: %', dyn_sql;

    -- Execute dynamic query
    RETURN QUERY EXECUTE dyn_sql;
END;
$$;


ALTER FUNCTION public.search_customer_dynamic(p_action character varying, p_fname character varying, p_lname character varying, p_middlename character varying, p_mobileno character varying, p_customercode character varying, p_accountno character varying, p_cardno character varying, p_userid integer) OWNER TO postgres;

--
-- Name: simple_apply_charges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simple_apply_charges() RETURNS TABLE(status text, records integer, amount numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_records INTEGER := 0;
    v_total DECIMAL(12,2) := 0;
BEGIN
    -- Simple direct insert without all the complex logic
    INSERT INTO card_charges (
        charge_id, cardid, cardnumber, accountid, charge_type, 
        amount, currency, charge_date, charge_year, description,
        card_type, scheme_type, productname, productbin, status
    )
    SELECT 
        fcreatefeesidanual(),  -- Generate charge ID
        c.cardid,
        c.cardnumber,
        c.accountid,
        'ANNUAL_FEE',
        500.00,  -- Fixed amount
        'USD',
        CURRENT_DATE,
        EXTRACT(YEAR FROM CURRENT_DATE),
        'Simple test charge',
        c.cardtype,
        c.schemetype,
        p.productname,
        p.productbin,
        'APPLIED'
    FROM card c
    JOIN products p ON c.productid = p.productid
    WHERE c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
    AND c.status = 'A'
    AND NOT EXISTS (
        SELECT 1 FROM card_charges cc 
        WHERE cc.cardid = c.cardid 
        AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
        AND cc.charge_type = 'ANNUAL_FEE'
    )
    RETURNING cardid, amount
    INTO v_records, v_total;
    
    status := 'SUCCESS';
    records := v_records;
    amount := v_total;
    
    RETURN NEXT;
    
EXCEPTION WHEN others THEN
    status := 'ERROR: ' || SQLERRM;
    records := 0;
    amount := 0;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.simple_apply_charges() OWNER TO postgres;

--
-- Name: simple_apply_to_all(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simple_apply_to_all() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER := 0;
BEGIN
    -- Apply charges to ALL active VISA DEBIT cards regardless of profiles
    INSERT INTO card_charges (
        charge_id, cardid, cardnumber, accountid, charge_type, 
        amount, currency, charge_date, charge_year, description,
        card_type, scheme_type, productname, productbin, status
    )
    SELECT 
        fcreatefeesidanual(),
        c.cardid,
        c.cardnumber,
        c.accountid,
        'ANNUAL_FEE',
        500.00,
        'USD',
        CURRENT_DATE,
        EXTRACT(YEAR FROM CURRENT_DATE),
        'Simple annual fee',
        c.cardtype,
        c.schemetype,
        p.productname,
        p.productbin,
        'APPLIED'
    FROM card c
    JOIN products p ON c.productid = p.productid
    WHERE c.status = 'A'
    AND c.cardtype = 'DEBIT'
    AND c.schemetype = 'VISA'
    AND c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
    AND NOT EXISTS (
        SELECT 1 FROM card_charges cc 
        WHERE cc.cardid = c.cardid 
        AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
        AND cc.charge_type = 'ANNUAL_FEE'
    );
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN 'Applied charges to ' || v_count || ' cards';
    
EXCEPTION WHEN others THEN
    RETURN 'Error: ' || SQLERRM;
END;
$$;


ALTER FUNCTION public.simple_apply_to_all() OWNER TO postgres;

--
-- Name: simple_wrapper_for_your_function(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.simple_wrapper_for_your_function() RETURNS TABLE(operation_status character varying, records_processed integer, total_amount numeric, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_processed INTEGER := 0;
    v_total DECIMAL(12,2) := 0;
BEGIN
    -- Use the working SQL from above
    INSERT INTO card_charges (
        cardid, cardnumber, accountid, charge_type, 
        amount, currency, charge_date, charge_year, description,
        card_type, scheme_type, productname, productbin, 
        status, created_at
    )
    SELECT 
        cardid,
        cardnumber,
        accountid,
        charge_type,
        calculated_amount as amount,
        currency,
        charge_date,
        charge_year,
        description,
        producttype,
        schemetype,
        productname,
        productbin,
        'APPLIED',
        created_at
    FROM (
        SELECT DISTINCT ON (cc.cardid, cc.rule_reference, cc.determined_currency)
            cc.cardid,
            cc.cardnumber,
            cc.accountid,
            cc.determined_currency as currency,
            cc.charge_type,
            cc.calculated_amount,
            cc.charge_date,
            cc.charge_year,
            cc.charge_name || ' - ' || cc.chargename || 
            CASE 
                WHEN cc.config_charge_type = 'PER' THEN ' (' || cc.percentage || '%)'
                WHEN cc.config_charge_type = 'BOTH' THEN ' (' || cc.percentage || '%) + Base'
                ELSE ''
            END || ' - Currency: ' || cc.determined_currency as description,
            cc.producttype,
            cc.schemetype,
            cc.productname,
            cc.productbin,
            cc.created_at
        FROM (
            SELECT 
                c.cardid, 
                c.cardnumber, 
                c.accountid,
                CASE 
                    WHEN p.currency IS NOT NULL AND p.currency != '' AND p.currency = ANY(ARRAY['USD', 'NPR', 'INR', 'EUR', 'CNY']) THEN p.currency
                    WHEN cc.currency IS NOT NULL AND cc.currency != '' AND cc.currency = ANY(ARRAY['USD', 'NPR', 'INR', 'EUR', 'CNY']) THEN cc.currency
                    ELSE 'NPR'
                END as determined_currency,
                'ANNUAL_FEE' as charge_type,
                rm.rulename as charge_name,
                CASE 
                    WHEN cc.charge_type = 'FLAT' THEN cc.amount
                    WHEN cc.charge_type = 'PER' THEN 
                        (cc.percentage / 100.0) * 1000
                    WHEN cc.charge_type = 'BOTH' THEN 
                        cc.amount + ((cc.percentage / 100.0) * 1000)
                    ELSE cc.amount
                END as calculated_amount,
                CURRENT_DATE as charge_date,
                EXTRACT(YEAR FROM CURRENT_DATE) as charge_year,
                p.producttype,
                p.schemetype,
                p.productname,
                p.productbin,
                rm.ruleid as rule_reference,
                cc.chargeid as config_reference,
                ra.actionid as action_reference,
                CURRENT_TIMESTAMP as created_at,
                cc.chargename,
                cc.charge_type as config_charge_type,
                cc.percentage,
                cc.currency as config_currency
            FROM card c
            INNER JOIN products p ON c.productid = p.productid
            INNER JOIN cardprofilemapping cpm ON c.cardid = cpm.cardid AND cpm.status='ACTIVE'
            INNER JOIN profilerulemapping prm ON cpm.profileid = prm.profileid AND prm.is_active
            INNER JOIN rulesmaster rm ON prm.ruleid = rm.ruleid AND rm.isactive
            INNER JOIN ruleactions ra ON rm.ruleid = ra.ruleid AND ra.action_type = 'ANNUAL_FEE'
            INNER JOIN chargeconfig cc ON (
                cc.chargeid = (ra.action_value->>'charge_config_reference')::TEXT
                AND cc.isactive 
                AND (cc.effectivedate IS NULL OR cc.effectivedate <= CURRENT_DATE)
                AND (cc.expirydate IS NULL OR cc.expirydate >= CURRENT_DATE)
            )
            WHERE NOT EXISTS (
                SELECT 1 FROM ruleconditions rc 
                WHERE rc.ruleid = rm.ruleid 
                AND rc.is_active
                AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
            )
            AND NOT EXISTS (
                SELECT 1 FROM card_charges ch 
                WHERE ch.cardid = c.cardid 
                AND ch.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                AND ch.charge_type = 'ANNUAL_FEE'
                AND ch.status != 'CANCELLED'
            )
            AND (
                ((ra.action_value->'filters'->>'scheme') IS NULL OR p.schemetype = (ra.action_value->'filters'->>'scheme'))
                AND ((ra.action_value->'filters'->>'card_type') IS NULL OR p.producttype = (ra.action_value->'filters'->>'card_type'))
            )
            AND c.status = 'A'
        ) cc
        WHERE cc.calculated_amount > 0
        ORDER BY cc.cardid, cc.rule_reference, cc.determined_currency, cc.calculated_amount DESC
    ) final_charges;
    
    GET DIAGNOSTICS v_processed = ROW_COUNT;
    
    SELECT SUM(amount) INTO v_total
    FROM card_charges 
    WHERE charge_date = CURRENT_DATE
    AND description LIKE '%Annual Card Subscription Fee%';
    
    operation_status := 'SUCCESS';
    records_processed := v_processed;
    total_amount := v_total;
    message := 'Processed ' || v_processed || ' charges';
    
    RETURN NEXT;
    
EXCEPTION WHEN others THEN
    operation_status := 'ERROR';
    records_processed := 0;
    total_amount := 0;
    message := SQLERRM;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.simple_wrapper_for_your_function() OWNER TO postgres;

--
-- Name: test_charge_application(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.test_charge_application() RETURNS TABLE(test_cardid character varying, status text, reason text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_test_card RECORD;
    v_card_id VARCHAR;
BEGIN
    FOR v_test_card IN 
        SELECT DISTINCT c.cardid, c.cardnumber, c.accountid, c.cardtype, c.schemetype, c.status
        FROM card c
        WHERE c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000050', 'CAR00000055')
        AND c.status = 'A'
    LOOP
        v_card_id := v_test_card.cardid;
        
        -- Check rule conditions manually
        IF NOT EXISTS (
            SELECT 1 FROM ruleconditions rc 
            WHERE rc.ruleid = 'R0109'
            AND rc.is_active
            AND NOT evaluate_card_condition(
                v_card_id, 
                (SELECT productid FROM card WHERE cardid = v_card_id),
                rc.field_name, 
                rc.operator, 
                rc.value, 
                rc.data_type
            )
        ) THEN
            -- Check existing charges
            IF NOT EXISTS (
                SELECT 1 FROM card_charges cc 
                WHERE cc.cardid = v_card_id 
                AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
                AND cc.charge_type = 'ANNUAL_FEE'
                AND cc.status != 'CANCELLED'
            ) THEN
                -- Check rule actions
                IF EXISTS (
                    SELECT 1 FROM ruleactions ra
                    WHERE ra.ruleid = 'R0109'
                    AND ra.action_type = 'ANNUAL_FEE'
                    AND (ra.action_value->'filters'->>'card_type' IS NULL 
                         OR ra.action_value->'filters'->>'card_type' = v_test_card.cardtype)
                    AND (ra.action_value->'filters'->>'scheme' IS NULL 
                         OR ra.action_value->'filters'->>'scheme' = v_test_card.schemetype)
                ) THEN
                    test_cardid := v_card_id;
                    status := 'ELIGIBLE';
                    reason := 'All checks passed';
                    RETURN NEXT;
                ELSE
                    test_cardid := v_card_id;
                    status := 'NOT ELIGIBLE';
                    reason := 'No matching rule action';
                    RETURN NEXT;
                END IF;
            ELSE
                test_cardid := v_card_id;
                status := 'NOT ELIGIBLE';
                reason := 'Already charged this year';
                RETURN NEXT;
            END IF;
        ELSE
            test_cardid := v_card_id;
            status := 'NOT ELIGIBLE';
            reason := 'Failed rule conditions';
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;


