--
-- Name: update_updatedate_column(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_updatedate_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Set approvedate when status changes to APPROVED or REJECTED
    IF (OLD.status IS DISTINCT FROM NEW.status) THEN
        IF (NEW.status = 'APPROVED' OR NEW.status = 'REJECTED') THEN
            -- Only set if not already set (allows manual override if needed)
            IF NEW.approvedate IS NULL THEN
                NEW.approvedate = CURRENT_TIMESTAMP;
            END IF;
        END IF;
        
        -- Set verifieddate when status changes to VERIFIED
        IF (NEW.status = 'VERIFIED') THEN
            -- Only set if not already set (allows manual override if needed)
            IF NEW.verifieddate IS NULL THEN
                NEW.verifieddate = CURRENT_TIMESTAMP;
            END IF;
        END IF;
        
        -- Reset verification fields if status changes away from VERIFIED
        IF (OLD.status = 'VERIFIED' AND NEW.status != 'VERIFIED') THEN
            NEW.verifieddate = NULL;
            NEW.verifiedby = NULL;
            NEW.verifiedbranchname = NULL;
            NEW.verifiedbranchcode = NULL;
        END IF;
        
        -- Reset approval fields if status changes away from APPROVED/REJECTED to earlier status
        IF ((OLD.status = 'APPROVED' OR OLD.status = 'REJECTED') AND 
            (NEW.status = 'PENDING' OR NEW.status = 'PROCESSING')) THEN
            NEW.approvedate = NULL;
            NEW.approvedby = NULL;
            NEW.approvedbranchcode = NULL;
            NEW.approvedbranchname = NULL;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


