--
-- Name: working_apply_charges(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.working_apply_charges() RETURNS TABLE(status character varying, records_processed integer, total_amount numeric, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_processed INTEGER := 0;
    v_total DECIMAL(12,2) := 0;
    v_card RECORD;
BEGIN
    -- Get eligible cards with SIMPLE logic
    FOR v_card IN (
        SELECT DISTINCT
            c.cardid,
            c.cardnumber,
            c.accountid,
            c.cardtype,
            c.schemetype,
            p.productname,
            p.productbin,
            p.currency,
            -- Get matching charge config
            ra.action_value->>'charge_config_reference' as charge_ref
        FROM card c
        JOIN products p ON c.productid = p.productid
        -- Check if card has ANY active profile (not necessarily PRO109)
        WHERE EXISTS (
            SELECT 1 FROM cardprofilemapping cpm 
            WHERE cpm.cardid = c.cardid 
            AND cpm.status = 'ACTIVE'
        )
        -- Check if that profile has ANY active rule
        AND EXISTS (
            SELECT 1 FROM cardprofilemapping cpm2
            JOIN profilerulemapping prm ON cpm2.profileid = prm.profileid
            WHERE cpm2.cardid = c.cardid
            AND cpm2.status = 'ACTIVE'
            AND prm.is_active = true
        )
        -- Check if there's a matching rule action
        AND EXISTS (
            SELECT 1 FROM ruleactions ra
            WHERE ra.ruleid IN (
                SELECT prm2.ruleid 
                FROM cardprofilemapping cpm3
                JOIN profilerulemapping prm2 ON cpm3.profileid = prm2.profileid
                WHERE cpm3.cardid = c.cardid
                AND cpm3.status = 'ACTIVE'
                AND prm2.is_active = true
            )
            AND ra.action_type = 'ANNUAL_FEE'
            AND (ra.action_value->'filters'->>'card_type' IS NULL 
                 OR ra.action_value->'filters'->>'card_type' = c.cardtype)
            AND (ra.action_value->'filters'->>'scheme' IS NULL 
                 OR ra.action_value->'filters'->>'scheme' = c.schemetype)
        )
        -- Check rule conditions
        AND NOT EXISTS (
            SELECT 1 FROM ruleconditions rc 
            WHERE rc.ruleid IN (
                SELECT prm3.ruleid 
                FROM cardprofilemapping cpm4
                JOIN profilerulemapping prm3 ON cpm4.profileid = prm3.profileid
                WHERE cpm4.cardid = c.cardid
                AND cpm4.status = 'ACTIVE'
                AND prm3.is_active = true
            )
            AND rc.is_active
            AND NOT evaluate_card_condition(c.cardid, p.productid, rc.field_name, rc.operator, rc.value, rc.data_type)
        )
        -- No existing charge this year
        AND NOT EXISTS (
            SELECT 1 FROM card_charges cc 
            WHERE cc.cardid = c.cardid 
            AND cc.charge_year = EXTRACT(YEAR FROM CURRENT_DATE)
            AND cc.charge_type = 'ANNUAL_FEE'
            AND cc.status != 'CANCELLED'
        )
        -- Basic card criteria
        AND c.status = 'A'
        AND c.cardid IN ('CAR00000012', 'CAR00000013', 'CAR00000055')
    ) 
    LOOP
        BEGIN
            -- Get charge amount from config
            DECLARE
                v_charge_amount DECIMAL(12,2);
            BEGIN
                SELECT cc.amount INTO v_charge_amount
                FROM ruleactions ra
                JOIN chargeconfig cc ON cc.chargeid = ra.action_value->>'charge_config_reference'
                WHERE ra.ruleid IN (
                    SELECT prm.ruleid 
                    FROM cardprofilemapping cpm
                    JOIN profilerulemapping prm ON cpm.profileid = prm.profileid
                    WHERE cpm.cardid = v_card.cardid
                    AND cpm.status = 'ACTIVE'
                    AND prm.is_active = true
                )
                AND ra.action_type = 'ANNUAL_FEE'
                AND (ra.action_value->'filters'->>'card_type' IS NULL 
                     OR ra.action_value->'filters'->>'card_type' = v_card.cardtype)
                AND (ra.action_value->'filters'->>'scheme' IS NULL 
                     OR ra.action_value->'filters'->>'scheme' = v_card.schemetype)
                AND cc.isactive = true
                LIMIT 1;
                
                IF v_charge_amount IS NULL THEN
                    v_charge_amount := 500.00;  -- Default amount
                END IF;
                
                -- Insert the charge
                INSERT INTO card_charges (
                    charge_id, cardid, cardnumber, accountid, charge_type, 
                    amount, currency, charge_date, charge_year, description,
                    card_type, scheme_type, productname, productbin, status
                ) VALUES (
                    fcreatefeesidanual(),
                    v_card.cardid,
                    v_card.cardnumber,
                    v_card.accountid,
                    'ANNUAL_FEE',
                    v_charge_amount,
                    v_card.currency,
                    CURRENT_DATE,
                    EXTRACT(YEAR FROM CURRENT_DATE),
                    'Annual fee - Working function',
                    v_card.cardtype,
                    v_card.schemetype,
                    v_card.productname,
                    v_card.productbin,
                    'APPLIED'
                );
                
                v_processed := v_processed + 1;
                v_total := v_total + v_charge_amount;
                
            EXCEPTION WHEN others THEN
                RAISE NOTICE 'Error getting charge amount for card %: %', v_card.cardid, SQLERRM;
                CONTINUE;
            END;
            
        EXCEPTION WHEN others THEN
            RAISE NOTICE 'Error processing card %: %', v_card.cardid, SQLERRM;
            CONTINUE;
        END;
    END LOOP;
    
    status := 'SUCCESS';
    records_processed := v_processed;
    total_amount := v_total;
    message := 'Processed ' || v_processed || ' cards';
    
    RETURN NEXT;
    
EXCEPTION WHEN others THEN
    status := 'ERROR';
    records_processed := 0;
    total_amount := 0;
    message := SQLERRM;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.working_apply_charges() OWNER TO postgres;

